      // Newer Android app: the tablet app sends the pieces itself (steady timing, off the page's thread).\n            if (typeof B.writePaced === 'function') {\n              return Promise.resolve(B.writePaced(uint8ToBase64(data), pace.chunk, pace.delay)).then(check);\n            }\n            // Older app: the page sends the pieces.\n            var offB = 0;\n            var stepB = function () {\n              if (offB >= data.length) return Promise.resolve();\n              var piece = data.subarray(offB, offB + pace.chunk);\n              offB += pace.chunk;\n              return Promise.resolve(B.write(uint8ToBase64(piece))).then(check).then(function () {\n                if (offB < data.length) return new Promise(function (r) { setTimeout(r, pace.delay); }).then(stepB);\n              });\n            };\n            return stepB();\n          }\n          return Promise.resolve(B.write(uint8ToBase64(data))).then(check);\n        }\n\n        var self = this;\n        var CHUNK = this._mode === 'le' ? 100 : 512;\n        var off = 0;\n\n        function next() {\n          if (off >= data.length) return Promise.resolve();\n          var chunk = data.subarray(off, off + CHUNK);\n          off += CHUNK;\n          var p = self._char.properties.writeWithoutResponse\n            ? self._char.writeValueWithoutResponse(chunk)\n            : self._char.writeValue(chunk);\n          return p.then(function () {\n            if (off < data.length) {\n              return new Promise(function (r) { setTimeout(r, 12); }).then(next);\n            }\n          });\n        }\n        return next();\n      };\n\n      BtThermal.prototype.printCanvas = function (canvas, opts) {\n        opts = opts || {};\n        var cut = opts.cut !== false;\n        var feed = opts.feed != null ? opts.feed : 3;\n        if (!this._mode) return Promise.reject(new Error('Printer not connected'));\n\n        var prof = btProfile(), pace = opts.pace || btPaceFor(this);   // opts.pace: the smooth-print test strip\n        var mono = toReceiptCanvas(canvas, this._paperWidth, opts.brightness, opts.quality);\n        var enc = new EscPosEncoder(this._paperWidth);\n        enc.initialize();\n        if (pace.slow) enc.slowPrint();\n        if (prof.cmd === 'star') enc.imageStar(mono); else enc.image(mono, pace.band);\n        enc.feed(feed);\n        // 58mm mobile printers have no cutter: skip the cut command (some read it as text) and leave room to tear.\n        if (cut && this._paperWidth > 384) enc.cut(); else if (cut) enc.feed(2);\n        return this.write(enc.getBuffer(), pace);\n      };\n\n      // Step 1 of the printer check: plain text only. If this prints, the link and the printer are fine.\n      BtThermal.prototype.testText = function () {\n        if (!this._mode) return Promise.reject(new Error('Printer not connected'));\n        var enc = new EscPosEncoder(this._paperWidth);\n        enc.initialize().text('PHOTOBOOTH4U\\nText test OK\\n' + (this._name || 'Bluetooth printer') + '\\n').feed(3);\n        return this.write(enc.getBuffer(), btPaceFor(this));\n      };\n\n      // Step 2: a short picture (64 rows). If text works but this garbles, the printer needs the Compatibility image mode.\n      BtThermal.prototype.testSmall = function () {\n        var dotW = this._paperWidth || 576;\n        var cvs = document.createElement('canvas');\n        cvs.width = dotW; cvs.height = 64;\n        var ctx = cvs.getContext('2d');\n        ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, dotW, 64);\n        ctx.fillStyle = '#000000';\n        for (var x = -64; x < dotW; x += 16) { ctx.beginPath(); ctx.moveTo(x, 64); ctx.lineTo(x + 8, 64); ctx.lineTo(x + 72, 0); ctx.lineTo(x + 64, 0); ctx.fill(); }\n        ctx.fillStyle = '#ffffff'; ctx.fillRect(dotW / 2 - 110, 18, 220, 28);\n        ctx.fillStyle = '#000000'; ctx.textAlign = 'center'; ctx.font = 'bold 20px sans-serif';\n        ctx.fillText('SMALL PICTURE OK', dotW / 2, 40);\n        return this.printCanvas(cvs, { feed: 3, cut: true, quality: 'normal' });\n      };\n\n      BtThermal.prototype.testPrint = function (paper) {\n        var dotW = PAPER_WIDTHS[paper || '80mm'] || 576;\n        this._paperWidth = dotW;          // the job must be as wide as this paper (a 58mm printer fed 80mm rows prints garbage)\n        var cvs = document.createElement('canvas');\n        cvs.width = dotW;\n        cvs.height = 360;\n        var ctx = cvs.getContext('2d');\n\n        ctx.fillStyle = '#ffffff';\n        ctx.fillRect(0, 0, cvs.width, cvs.height);\n        ctx.fillStyle = '#000000';\n        ctx.textAlign = 'center';\n\n        ctx.font = 'bold 30px sans-serif';\n        ctx.fillText('*** PHOTOBOOTH4U ***', dotW / 2, 50);\n\n        ctx.font = 'bold 22px sans-serif';\n        ctx.fillText('THERMAL RECEIPT TEST', dotW / 2, 95);\n\n        ctx.font = '16px sans-serif';\n        ctx.fillText(new Date().toLocaleString(), dotW / 2, 130);\n        ctx.fillText('Printer: ' + (this._name || 'Bluetooth Printer'), dotW / 2, 160);\n        ctx.fillText('Paper: ' + (paper || '80mm') + ' (' + dotW + ' printable dots)', dotW / 2, 190);\n\n        ctx.fillRect(30, 220, dotW - 60, 3);\n\n        ctx.font = 'italic 20px sans-serif';\n        ctx.fillText('Bluetooth thermal printing is working!', dotW / 2, 260);\n\n        ctx.font = '15px monospace';\n        ctx.fillText('--------------------------------', dotW / 2, 300);\n\n        return this.printCanvas(cvs, { feed: 4, cut: true });\n      };\n\n      var btPrinter = new BtThermal({ paperWidth: 576 });\n\n      function isBtAvailable() { return BtThermal.available() !== null; }\n      function isNativeAndroid() { return !!(global.__BTBridge && global.__BTBridge.connect); }\n      function isBtEnabled() {\n        if (global.__BTBridge && typeof global.__BTBridge.isEnabled === 'function') {\n          try { return global.__BTBridge.isEnabled(); } catch (_) { return true; }\n        }\n        return true;\n      }\n      function openBtSettings() {\n        if (global.__BTBridge && typeof global.__BTBridge.openBluetoothSettings === 'function') {\n          return global.__BTBridge.openBluetoothSettings();\n        }\n        return false;\n      }\n\n      // Prints one page. Not linked: links to the remembered printer quietly (the picker only when none was chosen yet).\n      // The send fails (a stale link after the printer was switched off and on): links again once and sends it again.\n      function printViaBluetooth(canvas, paper, opts) {\n        btPrinter._paperWidth = PAPER_WIDTHS[paper || '80mm'] || 576;\n        var link = function () {\n          if (btPrinter.connected) return Promise.resolve();\n          if (btPrinter.canReconnect()) return btPrinter.reconnect().catch(function (e) { if (e && e.none) return btPrinter.connect(); throw e; });\n          return btPrinter.connect();\n        };\n        return link().then(function () {\n          return btPrinter.printCanvas(canvas, opts).catch(function (err) {\n            if (!btPrinter.canReconnect()) throw err;\n            try { btPrinter.disconnect(true); } catch (_) { }\n            return btPrinter.reconnect().then(function () { return btPrinter.printCanvas(canvas, opts); });\n          });\n        });\n      }\n\n      global._btThermal = {\n        BtThermal: BtThermal,\n        EscPosEncoder: EscPosEncoder,\n        PAPER_WIDTHS: PAPER_WIDTHS,\n        toReceiptCanvas: toReceiptCanvas,\n        btPrinter: btPrinter,\n        isBtAvailable: isBtAvailable,\n        isNativeAndroid: isNativeAndroid,\n        btProfile: btProfile,\n        btSetProfile: btSetProfile,\n        tuneGet: tuneGet,\n        tuneSet: tuneSet,\n        TUNE_NAMES: TUNE_NAMES,\n        btTunePacing: btTunePacing,\n        rawTuneBand: rawTuneBand,\n        isBtEnabled: isBtEnabled,\n        openBtSettings: openBtSettings,\n        printViaBluetooth: printViaBluetooth,\n      };\n\n    }(typeof globalThis !== 'undefined' ? globalThis : window));\n  </script>\n</head>\n\n<body>\n  <svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n    <symbol id=\"i-camera\" viewBox=\"0 0 24 24\">\n      <path d=\"M4 8h3l2-3h6l2 3h3a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1z\" />\n      <circle cx=\"12\" cy=\"13\" r=\"3.5\" />\n    </symbol>\n    <symbol id=\"i-printer\" viewBox=\"0 0 24 24\">\n      <path d=\"M7 9V3h10v6\" />\n      <rect x=\"3\" y=\"9\" width=\"18\" height=\"8\" rx=\"2\" />\n      <path d=\"M7 14h10v7H7z\" />\n    </symbol>\n    <symbol id=\"i-palette\" viewBox=\"0 0 24 24\">\n      <path\n        d=\"M12 3a9 9 0 1 0 0 18c1.1 0 1.8-.8 1.8-1.7 0-.5-.2-.9-.5-1.2-.3-.4-.5-.8-.5-1.2 0-1 .8-1.8 1.8-1.8H17a4 4 0 0 0 4-4c0-4.4-4-8.1-9-8.1z\" />\n      <circle cx=\"7.5\" cy=\"11\" r=\"1\" />\n      <circle cx=\"10\" cy=\"7\" r=\"1\" />\n      <circle cx=\"15\" cy=\"7.5\" r=\"1\" />\n    </symbol>\n    <symbol id=\"i-eye\" viewBox=\"0 0 24 24\">\n      <path d=\"M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z\" />\n      <circle cx=\"12\" cy=\"12\" r=\"3\" />\n    </symbol>\n    <symbol id=\"i-monitor\" viewBox=\"0 0 24 24\">\n      <rect x=\"3\" y=\"4\" width=\"18\" height=\"12\" rx=\"2\" />\n      <path d=\"M8 20h8M12 16v4\" />\n    </symbol>\n    <symbol id=\"i-lock\" viewBox=\"0 0 24 24\">\n      <rect x=\"4\" y=\"11\" width=\"16\" height=\"10\" rx=\"2\" />\n      <path d=\"M8 11V7a4 4 0 0 1 8 0v4\" />\n    </symbol>\n    <symbol id=\"i-tap\" viewBox=\"0 0 24 24\">\n      <path\n        d=\"M9 11V5.5a1.5 1.5 0 0 1 3 0V11m0-1.5a1.5 1.5 0 0 1 3 0V11m0-.5a1.5 1.5 0 0 1 3 0V15a6 6 0 0 1-6 6h-1a6 6 0 0 1-5-2.7L3.6 15a1.5 1.5 0 0 1 2.4-1.8L9 16\" />\n    </symbol>\n    <symbol id=\"i-battery\" viewBox=\"0 0 24 24\">\n      <rect x=\"2\" y=\"7\" width=\"18\" height=\"10\" rx=\"2\" />\n      <path d=\"M22 11v2M6 10v4\" />\n    </symbol>\n    <symbol id=\"i-bookmark\" viewBox=\"0 0 24 24\">\n      <path d=\"M6 3h12v18l-6-4-6 4z\" />\n    </symbol>\n    <symbol id=\"i-x\" viewBox=\"0 0 24 24\">\n      <path d=\"M6 6l12 12M18 6L6 18\" />\n    </symbol>\n    <symbol id=\"i-qr\" viewBox=\"0 0 24 24\">\n      <rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\" />\n      <rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\" />\n      <rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\" />\n      <path d=\"M14 14h3v3h-3zM20 14v.01M14 20h.01M17 20h4v-3\" />\n    </symbol>\n  </svg>\n\n  <!-- START SCREEN: shown once, before Setup. Tap anywhere to begin. -->\n  <div class=\"start-screen\" id=\"startScreen\" role=\"button\" tabindex=\"0\" aria-label=\"Tap to start\">\n    <div class=\"ss-polaroid ss-p1\"><i class=\"ss-a\"></i></div>\n    <div class=\"ss-polaroid ss-p2\"><i class=\"ss-b\"></i></div>\n    <div class=\"ss-polaroid ss-p3\"><i class=\"ss-c\"></i></div>\n    <div class=\"ss-strip\"><i class=\"ss-a\"></i><i class=\"ss-b\"></i><i class=\"ss-r\"></i><i class=\"ss-c\"></i></div>\n    <div class=\"ss-status\"><i></i><span id=\"ssStatus\">Ready</span></div>\n    <div class=\"ss-center\">\n      <span class=\"brand-mark\"><i></i><i></i><i></i><i></i></span>\n      <div class=\"ss-word\"><b>photobooth</b><em>4u</em></div>\n      <p class=\"ss-tag\">Snap · Print · Share</p>\n      <span class=\"ss-btn\" aria-hidden=\"true\"><span class=\"halo\"></span><span class=\"halo h2\"></span><span\n          class=\"core\"></span></span>\n      <p class=\"ss-cta\">Tap to start</p>\n    </div>\n    <div class=\"ss-event\">\n      <p class=\"ev\" id=\"ssEvent\"></p>\n      <p class=\"dt\" id=\"ssDate\"></p>\n    </div>\n  </div>\n\n  <header class=\"brandbar topbar\">\n    <div class=\"brand-logo\">\n      <span class=\"brand-mark\"><i></i><i></i><i></i><i></i></span>\n      <span class=\"brand-word\"><b>photobooth</b><em>4u</em></span>\n      <img class=\"brand-client\" id=\"brandClient\" alt=\"\">\n    </div>\n    <div class=\"subtitle\" id=\"brandSubtitle\">Snap · Print · Share</div>\n    <div class=\"tab-bar\" id=\"tabBar\">\n      <button class=\"tab-btn active\" id=\"tabBtnSetup\" data-tab=\"setup\">\n        <span class=\"tab-num\">1</span> Setup\n      </button>\n      <button class=\"tab-btn\" id=\"tabBtnSession\" data-tab=\"session\">\n        <span class=\"tab-num\">2</span> Photo Session\n      </button>\n    </div>\n    <div class=\"topbar-end\"><a class=\"my-events-link web-only\" id=\"myEventsLink\" href=\"/lifetime/?booth=1\"\n        target=\"_blank\" rel=\"noopener\" hidden><svg class=\"ic\" aria-hidden=\"true\">\n          <use href=\"#i-bookmark\" />\n        </svg><span>My Events</span><span aria-hidden=\"true\">↗</span></a></div>\n  </header>\n\n  <!-- TAB 1: SETUP -->\n  <div class=\"tab-panel\" id=\"tabSetup\">\n    <div class=\"desk-upd\" id=\"deskUpdBar\" role=\"status\" hidden></div>\n    <div class=\"setup-shell\">\n\n      <div class=\"bt-switch\" id=\"btSwitch\" role=\"radiogroup\" aria-label=\"Booth type\">\n        <span class=\"bt-lbl\">Booth type</span>\n        <div class=\"seg-tabs\">\n          <button type=\"button\" class=\"on\" data-bt=\"photo\" role=\"radio\" aria-checked=\"true\">Photo booth</button>\n          <button type=\"button\" data-bt=\"card\" role=\"radio\" aria-checked=\"false\">Trading card</button>\n          <button type=\"button\" data-bt=\"cert\" role=\"radio\" aria-checked=\"false\">Certificate</button>\n        </div>\n      </div>\n\n      <nav class=\"step-bar\" id=\"stepBar\" aria-label=\"Setup steps\">\n        <button type=\"button\" class=\"step-tab\" data-step=\"1\"><span class=\"sn\">1</span><span\n            class=\"st\"><b>Design</b><small id=\"stepSum1\"></small></span></button>\n        <button type=\"button\" class=\"step-tab\" data-step=\"2\"><span class=\"sn\">2</span><span class=\"st\"><b>Text</b><small\n              id=\"stepSum2\"></small></span></button>\n        <button type=\"button\" class=\"step-tab\" data-step=\"3\"><span class=\"sn\">3</span><span\n            class=\"st\"><b>Layout</b><small id=\"stepSum3\"></small></span></button>\n        <button type=\"button\" class=\"step-tab\" data-step=\"4\"><span class=\"sn\">4</span><span class=\"st\"><b>Camera &amp;\n              printer</b><small id=\"stepSum4\"></small></span></button>\n        <button type=\"button\" class=\"step-tab\" data-step=\"5\"><span class=\"sn\">5</span><span\n            class=\"st\"><b>Extras</b><small id=\"stepSum5\"></small></span></button>\n        <button type=\"button\" class=\"step-tab\" data-step=\"6\"><span class=\"sn\">6</span><span\n            class=\"st\"><b>Share</b><small id=\"stepSum6\"></small></span></button>\n        <button type=\"button\" class=\"step-tab\" data-step=\"7\"><span class=\"sn\">7</span><span\n            class=\"st\"><b>Session</b><small id=\"stepSum7\"></small></span></button>\n      </nav>\n\n      <!-- STEP 1 · DESIGN -->\n      <section class=\"step\" id=\"step1\" data-step=\"1\">\n        <div class=\"panel-section\" id=\"btStyleSection\">\n          <p class=\"panel-label\" id=\"btStyleTitle\">Card style</p>\n          <p class=\"panel-hint step-lead\" id=\"btStyleHint\"></p>\n          <div class=\"bt-chips\" id=\"btStyleChips\"></div>\n          <label class=\"toggle-row bt-only-card\" style=\"margin-top:12px;\"><input type=\"checkbox\" id=\"btStats\"> Random\n            stats &amp; rarity (HP, ATK, DEF, SPD, Common &rarr; Legendary)</label>\n          <div class=\"bt-only-card\" id=\"btBackBox\" style=\"margin-top:14px;\">\n            <label class=\"toggle-row\"><input type=\"checkbox\" id=\"btBackOn\"> Give every card a back (guests can flip\n              it)</label>\n            <label class=\"toggle-row\" id=\"btBackPrintRow\" style=\"margin-top:6px;\"><input type=\"checkbox\"\n                id=\"btBackPrint\" checked> Print both sides on one sheet (fold in half)</label>\n            <button type=\"button\" class=\"action-btn\" id=\"btBackPrev\" style=\"margin-top:8px; width:auto;\">Preview the\n              back</button>\n          </div>\n          <div id=\"btTplBox\">\n            <p class=\"sub-label\" style=\"margin-top:18px;\">Your own templates</p>\n            <p class=\"panel-hint\">Upload a design made in Canva (PNG). Leave the photo window <b>white or\n                see-through</b>. Type a group name first (like &ldquo;Superheroes&rdquo; or &ldquo;Graduation&rdquo;) to\n              keep them together.</p>\n            <div class=\"bt-grid2\">\n              <input type=\"text\" class=\"label-input\" id=\"btTplGroup\" list=\"btTplGroups\" maxlength=\"24\"\n                placeholder=\"Group, e.g. Superheroes\" aria-label=\"Group name for the templates you upload\">\n              <datalist id=\"btTplGroups\"></datalist>\n              <label class=\"action-btn primary\" for=\"btTplInput\" style=\"margin:0; text-align:center;\">Upload\n                templates</label>\n              <input type=\"file\" id=\"btTplInput\" accept=\"image/png,image/webp,image/jpeg,image/*\" multiple hidden>\n            </div>\n            <div id=\"btTplList\"></div>\n            <label class=\"toggle-row\" id=\"btPickRow\" style=\"margin-top:10px;\"><input type=\"checkbox\" id=\"btPick\"> Let\n              guests choose their design (sorted by group)</label>\n            <label class=\"toggle-row\" id=\"btBuiltinRow\" style=\"margin-top:6px;\"><input type=\"checkbox\" id=\"btBuiltin\"\n                checked> Include the built-in styles in that choice</label>\n          </div>\n          <div class=\"bt-editor\" id=\"btTplEditor\" hidden></div>\n          <p class=\"panel-hint\" style=\"margin-top:12px;\">The event name, font and date are in the next step. Your own\n            stickers and logo from Extras still go on top.</p>\n        </div>\n        <div class=\"seg-tabs d1-tabs\" id=\"designTabs\" role=\"tablist\" aria-label=\"Design\">\n          <button type=\"button\" class=\"on\" data-pane=\"designs\" role=\"tab\" aria-selected=\"true\">Ready designs</button>\n          <button type=\"button\" data-pane=\"colours\" role=\"tab\" aria-selected=\"false\"><svg class=\"ic\" aria-hidden=\"true\">\n              <use href=\"#i-palette\" />\n            </svg> Colours &amp; background<small id=\"backdropSum\"></small></button>\n        </div>\n        <div class=\"panel-section d1-pane on\" id=\"themeSection\" data-d1=\"designs\">\n          <div class=\"step-head\">\n            <p class=\"panel-label\">Pick a design</p>\n            <button type=\"button\" class=\"link-btn\" id=\"saveThemeBtn\"><svg class=\"ic\" aria-hidden=\"true\">\n                <use href=\"#i-bookmark\" />\n              </svg> Save my design</button>\n          </div>\n          <p class=\"panel-hint step-lead\">Tap one to start from it. You can change the colours after in <a href=\"#\"\n              class=\"d1-jump\" data-pane=\"colours\">Colours &amp; background</a>.</p>\n          <div class=\"theme-tools\">\n            <input type=\"search\" class=\"label-input\" id=\"themeSearch\" placeholder=\"Search designs…\"\n              aria-label=\"Search designs\">\n          </div>\n          <div class=\"theme-cats\" id=\"themeCats\" role=\"tablist\" aria-label=\"Design categories\"></div>\n          <p class=\"panel-hint theme-lay-note\" id=\"themeLayoutNote\" hidden></p>\n          <div class=\"theme-grid\" id=\"themeGrid\"></div>\n        </div>\n\n        <div class=\"panel-section d1-pane\" id=\"backdropSection\" data-d1=\"colours\">\n          <p class=\"panel-label\">Colours &amp; background</p>\n          <p class=\"panel-hint step-lead\">These change everything <b>around</b> the photos. Each one shows in the\n            preview straight away.</p>\n          <button type=\"button\" class=\"action-btn see-prev-btn\" data-see-preview><svg class=\"ic\" aria-hidden=\"true\">\n              <use href=\"#i-eye\" />\n            </svg> Show the preview while I pick</button>\n          <div class=\"cz\">\n            <p class=\"cz-t\"><span class=\"cz-n\">1</span>Background style</p>\n            <p class=\"cz-h\">The pattern behind your photos.</p>\n            <div class=\"preset-grid\" id=\"presetGrid\">\n              <button class=\"preset-btn\" data-preset=\"none\" title=\"Plain colour\">\n                <span class=\"preset-swatch\"></span>\n                <span>Plain</span>\n              </button>\n              <button class=\"preset-btn\" data-preset=\"gold\" title=\"Gold glitter\">\n                <span class=\"preset-swatch swatch-gold\" id=\"swatchGold\"></span>\n                <span>Gold Glitter</span>\n              </button>\n              <button class=\"preset-btn\" data-preset=\"sky\" title=\"Pastel sky\">\n                <span class=\"preset-swatch swatch-sky\" id=\"swatchSky\"></span>\n                <span>Pastel Sky</span>\n              </button>\n              <button class=\"preset-btn\" data-preset=\"stars\" title=\"Black and gold\">\n                <span class=\"preset-swatch swatch-stars\" id=\"swatchStars\"></span>\n                <span>Black &amp; Gold</span>\n              </button>\n              <button class=\"preset-btn\" data-preset=\"cream\" title=\"Cream\">\n                <span class=\"preset-swatch swatch-cream\" id=\"swatchCream\"></span>\n                <span>Cream</span>\n              </button>\n              <button class=\"preset-btn\" data-preset=\"maroon\" title=\"Maroon and gold\">\n                <span class=\"preset-swatch swatch-maroon\" id=\"swatchMaroon\"></span>\n                <span>Maroon &amp; Gold</span>\n              </button>\n              <button class=\"preset-btn\" data-preset=\"custom\" title=\"Your photo\" id=\"customPresetBtn\">\n                <span class=\"preset-swatch\" id=\"customSwatch\"\n                  style=\"background:var(--panel-2); display:flex; align-items:center; justify-content:center; font-size:9px; color:var(--ink-dim);\">Photo</span>\n                <span>Your photo</span>\n              </button>\n            </div>\n          </div>\n          <div class=\"cz\" id=\"bdColorGroup\">\n            <p class=\"cz-t\"><span class=\"cz-n\">2</span>Background colour</p>\n            <p class=\"cz-h\">Changes the main colour of the background. <b>Auto</b> keeps the style&rsquo;s own colours.\n            </p>\n            <div class=\"bd-color-row\" id=\"bdColorRow\">\n              <button type=\"button\" class=\"bd-swatch bd-auto active\" data-color=\"\"\n                title=\"The design's own colours\">Auto</button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#f8c8d4\" title=\"Blush\"\n                style=\"background:#f8c8d4;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#e58ba3\" title=\"Rose\"\n                style=\"background:#e58ba3;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#f9c9a8\" title=\"Peach\"\n                style=\"background:#f9c9a8;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#cdb8ee\" title=\"Lavender\"\n                style=\"background:#cdb8ee;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#a9d4f5\" title=\"Sky blue\"\n                style=\"background:#a9d4f5;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#2f8f8f\" title=\"Teal\"\n                style=\"background:#2f8f8f;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#bfe8d2\" title=\"Mint\"\n                style=\"background:#bfe8d2;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#9db89a\" title=\"Sage\"\n                style=\"background:#9db89a;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#1f3a68\" title=\"Navy\"\n                style=\"background:#1f3a68;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#7a1f3d\" title=\"Burgundy\"\n                style=\"background:#7a1f3d;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#161616\" title=\"Black\"\n                style=\"background:#161616;\"></button>\n              <button type=\"button\" class=\"bd-swatch\" data-color=\"#ffffff\" title=\"White\"\n                style=\"background:#ffffff;\"></button>\n              <label class=\"bd-swatch bd-custom\" id=\"bdCustomSwatch\" title=\"Any colour\"><input type=\"color\"\n                  id=\"bdColorInput\" value=\"#f4b6c2\"></label>\n            </div>\n            <p class=\"panel-hint\" id=\"bdColorHint\" hidden></p>\n          </div>\n          <div class=\"cz\" id=\"accentGroup\">\n            <p class=\"cz-t\"><span class=\"cz-n\">3</span>Gold details colour</p>\n            <p class=\"cz-h\" id=\"accentHelp\">Recolours the shiny <b>gold</b> lines, glitter, stars and drawings &mdash;\n              e.g. make them silver or rose gold.</p>\n            <p class=\"cz-none\" id=\"accentNone\" hidden>Nothing to change here: this design has no gold details. Only some\n              ready designs have them, e.g. <b>Gold Chevron</b>, <b>Art Deco Navy</b>, <b>White Marble</b>, plus some\n              stickers.</p>\n            <div class=\"accent-row\" id=\"accentChips\">\n              <button type=\"button\" class=\"accent-chip active\" data-accent=\"gold\"><i\n                  style=\"background:linear-gradient(135deg,#a8792a,#fff1c4,#a8792a)\"></i>Gold</button>\n              <button type=\"button\" class=\"accent-chip\" data-accent=\"silver\"><i\n                  style=\"background:linear-gradient(135deg,#7d8288,#f7f9fb,#7d8288)\"></i>Silver</button>\n              <button type=\"button\" class=\"accent-chip\" data-accent=\"rosegold\"><i\n                  style=\"background:linear-gradient(135deg,#a5645a,#fde3dc,#a5645a)\"></i>Rose gold</button>\n              <button type=\"button\" class=\"accent-chip\" data-accent=\"champagne\"><i\n                  style=\"background:linear-gradient(135deg,#9e8a6a,#fff7e6,#9e8a6a)\"></i>Champagne</button>\n              <button type=\"button\" class=\"accent-chip\" data-accent=\"white\"><i\n                  style=\"background:#fff\"></i>White</button>\n              <button type=\"button\" class=\"accent-chip\" data-accent=\"black\"><i\n                  style=\"background:#222\"></i>Black</button>\n            </div>\n          </div>\n          <div class=\"cz\" id=\"elementsGroup\">\n            <p class=\"cz-t\"><span class=\"cz-n\">4</span>Sprinkles</p>\n            <p class=\"cz-h\">Small things scattered on the background: confetti, stars, sparkles&hellip;</p>\n            <select id=\"elementsSelect\" class=\"label-input\" style=\"font-size:13px;\"></select>\n          </div>\n          <div class=\"cz\">\n            <p class=\"cz-t\"><span class=\"cz-n\">5</span>Photo border</p>\n            <p class=\"cz-h\">The thin edge around each photo. <b>Auto</b> picks white or black, whichever stands out.</p>\n            <div id=\"frameSwatchRow\" style=\"display:flex; align-items:center; gap:10px; flex-wrap:wrap;\">\n              <button type=\"button\" class=\"frame-swatch frame-auto active\" data-color=\"auto\" data-name=\"Auto\"\n                title=\"White or black, whichever stands out\">Auto</button>\n              <button type=\"button\" class=\"frame-swatch\" data-color=\"#ffffff\" data-name=\"White\" title=\"White\"\n                style=\"background:#ffffff;\"></button>\n              <button type=\"button\" class=\"frame-swatch\" data-color=\"#f3ead6\" data-name=\"Cream\" title=\"Cream\"\n                style=\"background:#f3ead6;\"></button>\n              <button type=\"button\" class=\"frame-swatch\" data-color=\"#d9d9d9\" data-name=\"Light grey\" title=\"Light grey\"\n                style=\"background:#d9d9d9;\"></button>\n              <button type=\"button\" class=\"frame-swatch\" data-color=\"#111111\" data-name=\"Black\" title=\"Black\"\n                style=\"background:#111111;\"></button>\n              <button type=\"button\" class=\"frame-swatch\" data-color=\"#6b1a2b\" data-name=\"Maroon\" title=\"Maroon\"\n                style=\"background:#6b1a2b;\"></button>\n              <span class=\"panel-hint\" id=\"frameSwatchName\" style=\"display:none;\">Auto</span>\n            </div>\n          </div>\n          <div class=\"cz\">\n            <p class=\"cz-t\"><span class=\"cz-n\">6</span>Your own background photo <small>(optional)</small></p>\n            <p class=\"cz-h\">Use a photo (e.g. the couple or the celebrant) as the background.</p>\n            <div class=\"bg-row\">\n              <img class=\"bg-thumb\" id=\"bgThumb\" alt=\"Backdrop photo\">\n              <label class=\"upload-btn\" for=\"bgInput\">Upload photo</label>\n              <input type=\"file\" id=\"bgInput\" accept=\"image/*\">\n            </div>\n            <button class=\"remove-link\" id=\"removeBgBtn\">Remove photo</button>\n            <div id=\"bandPositionWrap\" style=\"display:none; margin-top:10px;\">\n              <p class=\"sub-label\">Placement</p>\n              <select id=\"photoPlacementSelect\" class=\"label-input\" style=\"font-size:13px;\">\n                <option value=\"band\" selected>Beside the photos</option>\n                <option value=\"background\">Full background</option>\n              </select>\n              <p class=\"panel-hint\" id=\"bandPositionHint\" style=\"margin-top:6px;\"></p>\n              <p class=\"sub-label\" style=\"margin-top:10px;\">Crop</p>\n              <select id=\"cropFocusSelect\" class=\"label-input\" style=\"font-size:13px;\"></select>\n            </div>\n          </div>\n        </div>\n        <div class=\"step-nav\"><span></span><button type=\"button\" class=\"action-btn primary next-btn\" data-go=\"2\">Next:\n            Text →</button></div>\n      </section>\n\n      <!-- STEP 2 · TEXT -->\n      <section class=\"step\" id=\"step2\" data-step=\"2\">\n        <div class=\"panel-section\" id=\"btTextSection\">\n          <p class=\"panel-label bt-only-card\">Trading card</p>\n          <p class=\"panel-label bt-only-cert\">Certificate wording</p>\n          <p class=\"panel-hint step-lead bt-only-card\">Each guest types their <b>name</b> and a <b>title line</b> (like\n            &ldquo;Dancing Queen&rdquo;) on the booth before the photo. The event name below goes at the bottom of the\n            card.</p>\n          <div class=\"bt-only-card\" style=\"margin-top:14px;\">\n            <p class=\"sub-label\">Questions for the back of the card (optional)</p>\n            <p class=\"panel-hint\">Each question you type is asked after the guest&rsquo;s name and printed on the back.\n              Leave blank to skip. Turn on the back in Design.</p>\n            <input type=\"text\" class=\"label-input\" id=\"btQ1\" maxlength=\"30\" placeholder=\"e.g. Favourite team\"\n              aria-label=\"Question 1\">\n            <input type=\"text\" class=\"label-input\" id=\"btQ2\" maxlength=\"30\" placeholder=\"e.g. Special move\"\n              aria-label=\"Question 2\" style=\"margin-top:8px;\">\n            <input type=\"text\" class=\"label-input\" id=\"btQ3\" maxlength=\"30\" placeholder=\"e.g. My story in one line\"\n              aria-label=\"Question 3\" style=\"margin-top:8px;\">\n          </div>\n          <div class=\"bt-only-cert\">\n            <p class=\"sub-label\">Certificate title</p>\n            <input type=\"text\" class=\"label-input\" id=\"btCertTitle\" maxlength=\"48\" aria-label=\"Certificate title\">\n            <p class=\"sub-label\" style=\"margin-top:12px;\">Line above the name</p>\n            <input type=\"text\" class=\"label-input\" id=\"btCertLead\" maxlength=\"60\" placeholder=\"is proudly presented to\"\n              aria-label=\"Line above the name\">\n            <p class=\"sub-label\" style=\"margin-top:12px;\">Message under the name (optional)</p>\n            <input type=\"text\" class=\"label-input\" id=\"btCertMsg\" maxlength=\"120\"\n              placeholder=\"for being a wonderful part of our celebration\" aria-label=\"Message under the name\">\n            <div class=\"bt-grid2\" style=\"margin-top:12px;\">\n              <div>\n                <p class=\"sub-label\">Signed by</p><input type=\"text\" class=\"label-input\" id=\"btCertSigner\"\n                  maxlength=\"40\" placeholder=\"Name\" aria-label=\"Signed by\">\n              </div>\n              <div>\n                <p class=\"sub-label\">Their role</p><input type=\"text\" class=\"label-input\" id=\"btCertRole\" maxlength=\"40\"\n                  placeholder=\"e.g. Principal\" aria-label=\"Their role\">\n              </div>\n            </div>\n            <label class=\"toggle-row\" style=\"margin-top:12px;\"><input type=\"checkbox\" id=\"btCertAsk\"> Ask each guest for\n              an award title (e.g. &ldquo;Best Dancer&rdquo;)</label>\n          </div>\n          <p class=\"panel-hint\" style=\"margin-top:12px;\">Event name, font and date are just below.</p>\n        </div>\n        <div class=\"panel-section\" id=\"labelSection\">\n          <p class=\"panel-label\">Make it yours</p>\n          <p class=\"sub-label\">Name on the photo</p>\n          <div class=\"name-row\">\n            <input type=\"text\" class=\"label-input\" id=\"labelInput\" placeholder=\"e.g. Sofia's 7th Birthday\"\n              maxlength=\"60\" aria-label=\"Name on the photo\">\n            <button type=\"button\" class=\"cal-btn date-btn\" id=\"dateToggle\" aria-pressed=\"false\"\n              aria-label=\"Add the date\" title=\"Add the date\">\n              <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"\n                stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <rect x=\"3\" y=\"4.5\" width=\"18\" height=\"16\" rx=\"2.5\" />\n                <path d=\"M3 9.5h18M8 2.5v4M16 2.5v4\" />\n              </svg><span class=\"date-btn-t\">Date</span>\n            </button>\n          </div>\n          <div class=\"date-chip-row\" id=\"dateRow\" style=\"display:none;\">\n            <label class=\"date-chip\" title=\"Change the date\">\n              <span id=\"datePreviewText\">MM/DD/YY</span>\n              <span style=\"font-weight:600; opacity:.75;\">· change</span>\n              <input type=\"date\" id=\"dateInput\" aria-label=\"Pick the date\">\n            </label>\n            <button type=\"button\" class=\"date-x\" id=\"dateRemove\">✕ Remove</button>\n          </div>\n          <p class=\"panel-hint\" id=\"dateHint\" hidden></p>\n\n          <div id=\"kickerRow\" style=\"display:none; margin-top:12px;\">\n            <p class=\"sub-label\">Small line</p>\n            <input type=\"text\" class=\"label-input\" id=\"kickerInput\" maxlength=\"40\"\n              style=\"font-family:'Manrope',sans-serif; font-size:14px;\" aria-label=\"Small line\">\n          </div>\n          <div id=\"receiptNoteRow\" style=\"margin-top:12px;\">\n            <p class=\"sub-label\">Receipt note &amp; social handle (optional)</p>\n            <input type=\"text\" class=\"label-input\" id=\"receiptNoteInput\" maxlength=\"45\" placeholder=\"e.g. @yourbooth · #weddingday\"\n              style=\"font-family:'Manrope',sans-serif; font-size:14px;\" aria-label=\"Receipt note or social handle\">\n            <p class=\"panel-hint\" style=\"margin:2px 0 0;\">Prints on thermal receipts (e.g. Instagram handle, hashtag, or promo code).</p>\n          </div>\n\n          <p class=\"sub-label\" style=\"margin-top:16px;\">Title style</p>\n          <div class=\"style-tiles\" id=\"titleStyleTiles\"></div>\n          <select class=\"label-input\" id=\"titleStyleSelect\" aria-label=\"Title style\" hidden></select>\n\n          <p class=\"sub-label\" style=\"margin-top:16px;\">Font</p>\n          <div class=\"font-pairs\" id=\"fontPairs\"></div>\n          <div class=\"font-mode\" id=\"fontMode\">\n            <button type=\"button\" class=\"on\" data-mode=\"name\">Name font</button>\n            <button type=\"button\" data-mode=\"date\">Small line &amp; date font</button>\n          </div>\n          <div class=\"font-cats\" id=\"fontCats\"></div>\n          <div class=\"font-cards\" id=\"fontCards\"></div>\n          <div hidden>\n            <div class=\"custom-dd\" id=\"fontDropdown\">\n              <button type=\"button\" class=\"custom-dd-btn label-input\" id=\"fontDropdownBtn\"></button>\n              <div class=\"custom-dd-list\" id=\"fontDropdownList\"></div>\n            </div>\n            <div class=\"sub-group\" id=\"dateFontGroup\">\n              <div id=\"dateFontWrap\">\n                <div class=\"custom-dd\" id=\"dateFontDropdown\">\n                  <button type=\"button\" class=\"custom-dd-btn label-input\" id=\"dateFontDropdownBtn\"></button>\n                  <div class=\"custom-dd-list\" id=\"dateFontDropdownList\"></div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <p class=\"sub-label\" style=\"margin-top:16px;\">Text colour</p>\n          <div id=\"colorSwatchRow\" style=\"display:flex; align-items:center; gap:8px; flex-wrap:wrap;\">\n            <span class=\"theme-pal\" id=\"themePalette\"></span>\n            <button type=\"button\" class=\"color-swatch-btn active\" data-color=\"#1f4166\"\n              style=\"background:#1f4166;\"></button>\n            <button type=\"button\" class=\"color-swatch-btn\" data-color=\"#2b2b2b\" style=\"background:#2b2b2b;\"></button>\n            <button type=\"button\" class=\"color-swatch-btn\" data-color=\"#5c4a3a\" style=\"background:#5c4a3a;\"></button>\n            <button type=\"button\" class=\"color-swatch-btn\" data-color=\"#c93d27\" style=\"background:#c93d27;\"></button>\n            <button type=\"button\" class=\"color-swatch-btn\" data-color=\"#f5f0e8\"\n              style=\"background:#f5f0e8; border:1.5px solid var(--line);\"></button>\n            <button type=\"button\" class=\"color-swatch-btn\" data-color=\"#ffffff\"\n              style=\"background:#ffffff; border:1.5px solid var(--line);\"></button>\n            <input type=\"color\" id=\"textColorInput\" value=\"#1f4166\" title=\"Any colour\" class=\"color-any\">\n          </div>\n\n          <details class=\"more\">\n            <summary>More options</summary>\n            <p class=\"sub-label\">Text size</p>\n            <input type=\"range\" id=\"titleSizeSlider\" min=\"60\" max=\"170\" value=\"100\" style=\"width:100%;\">\n            <label class=\"toggle-row\" style=\"margin-top:12px;\">\n              <input type=\"checkbox\" id=\"titleBgToggle\" checked>\n              Text background\n            </label>\n            <div id=\"titleBgColorWrap\" style=\"display:flex; align-items:center; gap:8px; margin-top:8px;\">\n              <span class=\"panel-hint\" style=\"margin:0;\">Colour</span>\n              <input type=\"color\" id=\"titleBgColorInput\" value=\"#ffffff\" class=\"color-any\">\n            </div>\n            <label class=\"toggle-row\" style=\"margin-top:12px;\">\n              <input type=\"checkbox\" id=\"outlineToggle\" checked> Outline\n            </label>\n            <select id=\"outlineColorSelect\" class=\"label-input pillify\" style=\"font-size:13px;\">\n              <option value=\"#ffffff\">White</option>\n              <option value=\"#000000\">Black</option>\n            </select>\n            <label class=\"toggle-row\" style=\"margin-top:12px;\"><input type=\"checkbox\" id=\"shadowToggle\" checked> Soft\n              shadow</label>\n          </details>\n        </div>\n        <div class=\"step-nav\"><button type=\"button\" class=\"action-btn back-btn\" data-go=\"1\">← Back</button><button\n            type=\"button\" class=\"action-btn primary next-btn\" data-go=\"3\">Next: Layout →</button></div>\n      </section>\n\n      <!-- STEP 3 · LAYOUT & TIMER -->\n      <section class=\"step\" id=\"step3\" data-step=\"3\">\n        <div class=\"panel-section\" id=\"formatSection\">\n          <div class=\"lay-head\">\n            <p class=\"panel-label\" style=\"margin:0;\">Layout</p>\n            <label class=\"lay-guest-toggle\"><input type=\"checkbox\" id=\"guestPickToggle\"> <span>Let guests choose\n                layout</span></label>\n          </div>\n          <p class=\"panel-hint step-lead\" id=\"guestPickHint\">Tap a layout to use it.</p>\n          <div class=\"lay-groups\" id=\"layoutGrid\"></div>\n          <div class=\"frame-details-wrap\" id=\"frameDetailsWrap\" style=\"display:none;\">\n            <div class=\"frame-ctx\" id=\"frameCtx\" style=\"display:none;\"></div>\n            <div class=\"decor-sel\" id=\"spotEditControls\" style=\"display:none;\">\n              <p class=\"panel-hint\" style=\"margin:0 0 8px;\">Tap a box to select it, then drag to move or drag its corner\n                to resize. The numbers are the photo order (1 = first shot).</p>\n              <div class=\"decor-btns\"><button type=\"button\" class=\"action-btn\" id=\"spotAdd\">+ Add spot</button><button\n                  type=\"button\" class=\"action-btn\" id=\"spotCopy\" title=\"Make another box the same size and tilt as the selected one\">Copy spot</button><button\n                  type=\"button\" class=\"action-btn\" id=\"spotDel\" style=\"color:#c0392b;\">Remove spot</button><button\n                  type=\"button\" class=\"action-btn\" id=\"spotRedetect\">Find again</button><button type=\"button\"\n                  class=\"action-btn primary\" id=\"spotDone\">Done</button></div>\n              <p class=\"sub-label\" style=\"margin:10px 0 4px;\">Photo windows</p>\n              <div class=\"decor-btns key-row\">\n                <button type=\"button\" class=\"action-btn\" id=\"spotPickColor\">&#127919; Pick window colour</button>\n                <span class=\"key-swatch\" id=\"spotKeySwatch\" title=\"Photo window colour\"></span>\n                <label class=\"key-tol\" id=\"spotKeyTolWrap\" style=\"display:none;\">Match <input type=\"range\"\n                    id=\"spotKeyTol\" min=\"6\" max=\"90\" step=\"2\"></label>\n                <button type=\"button\" class=\"action-btn\" id=\"spotKeyClear\" style=\"display:none;\">White / see-through\n                  only</button>\n              </div>\n              <p class=\"panel-hint\" id=\"spotPickHint\"\n                style=\"display:none; margin:6px 0 0; color:#C93D27; font-weight:700;\">Tap a photo window in the preview\n                to pick its colour.</p>\n              <label class=\"toggle-row\" style=\"margin-top:6px;\"><input type=\"checkbox\" id=\"spotShowWin\" checked>\n                Highlight the photo windows (blue)</label>\n              <p class=\"sub-label\" style=\"margin:10px 0 4px;\">Selected box</p>\n              <div class=\"decor-btns\"><button type=\"button\" class=\"action-btn primary\" id=\"spotSnap\"\n                  title=\"Fit this box to the photo window under it: edges, size and tilt\">&#129522; Snap to\n                  window</button></div>\n              <p class=\"panel-hint\" style=\"margin:6px 0 8px;\">Put the box roughly over one photo window (it can overlap\n                others), then tap <b>Snap to window</b>.</p>\n              <div class=\"decor-btns\"><button type=\"button\" class=\"action-btn\" id=\"spotEarlier\">&#9664; Earlier\n                  shot</button><button type=\"button\" class=\"action-btn\" id=\"spotLater\">Later shot\n                  &#9654;</button><button type=\"button\" class=\"action-btn\" id=\"spotSplitX\">Split in 2\n                  &#8596;</button><button type=\"button\" class=\"action-btn\" id=\"spotSplitY\">Split in 2\n                  &#8597;</button><button type=\"button\" class=\"action-btn\" id=\"spotSplit4\">Split in 4</button></div>\n              <div class=\"decor-btns\" style=\"margin-top:6px;\"><button type=\"button\" class=\"action-btn\" id=\"spotFront\"\n                  title=\"This photo shows on top where boxes overlap\">&#11014; Bring to front</button><button\n                  type=\"button\" class=\"action-btn\" id=\"spotBack\"\n                  title=\"This photo goes under the others where boxes overlap\">&#11015; Send to back</button></div>\n              <p class=\"panel-hint\" style=\"margin:6px 0 0;\">Drag the round <b>&#8635;</b> at the bottom of a box to tilt\n                it. <b>Bring to front</b> / <b>Send to back</b> decide which photo is on top where two boxes overlap.\n              </p>\n              <div class=\"spot-size\" id=\"spotSize\"\n                style=\"display:none; margin-top:8px; gap:8px; flex-wrap:wrap; align-items:center; font-size:12.5px; font-weight:700;\">\n                <label>Left % <input type=\"number\" id=\"spotX\" min=\"0\" max=\"100\" step=\"0.5\" style=\"width:64px;\"></label>\n                <label>Top % <input type=\"number\" id=\"spotY\" min=\"0\" max=\"100\" step=\"0.5\" style=\"width:64px;\"></label>\n                <label>Width % <input type=\"number\" id=\"spotW\" min=\"2\" max=\"100\" step=\"0.5\" style=\"width:64px;\"></label>\n                <label>Height % <input type=\"number\" id=\"spotH\" min=\"2\" max=\"100\" step=\"0.5\"\n                    style=\"width:64px;\"></label>\n                <label title=\"Boxes with the same photo number show the same photo\">Photo # <input type=\"number\" id=\"spotShot\" min=\"1\" max=\"40\" step=\"1\" style=\"width:64px;\"></label>\n                <label>Tilt ° <input type=\"number\" id=\"spotA\" min=\"-45\" max=\"45\" step=\"0.5\" style=\"width:64px;\"></label>\n                <button type=\"button\" class=\"action-btn\" id=\"spotTurnL\" style=\"width:auto; margin:0;\"\n                  title=\"Tilt 1° left\">&#8634; 1°</button>\n                <button type=\"button\" class=\"action-btn\" id=\"spotTurnR\" style=\"width:auto; margin:0;\"\n                  title=\"Tilt 1° right\">1° &#8635;</button>\n              </div>\n              <p class=\"sub-label\" style=\"margin:10px 0 4px;\">Link photos by hand</p>\n              <div class=\"decor-btns\"><button type=\"button\" class=\"action-btn\" id=\"spotCopyStrip\"\n                  title=\"Make the selected box's strip show the same photos as another strip\">Copy a strip's photos&hellip;</button><button\n                  type=\"button\" class=\"action-btn\" id=\"spotShotAuto\">Back to automatic</button></div>\n              <p class=\"panel-hint\" style=\"margin:6px 0 0;\">Boxes with the same <b>Photo #</b> show the same photo, so a\n                guest only takes as many photos as the highest number. To make a strip a copy of another: tap a box in\n                it, tap <b>Copy a strip's photos</b>, then tap a box in the strip to copy from.</p>\n            </div>\n            <div class=\"frames-box\" id=\"myFramesPanel\" style=\"display:none; margin-top:12px;\">\n              <p class=\"sub-label\" style=\"margin-top:0;\">Frames on this sheet</p>\n              <p class=\"panel-hint\" style=\"margin:0 0 10px;\" id=\"framePickHint\">Tap a frame to put it on the sheet or\n                take it off.</p>\n              <div class=\"frame-mode\" id=\"frameModeBox\" hidden>\n                <div class=\"chip-row\" id=\"frameModeChips\"></div>\n              </div>\n              <div class=\"frame-pick\" id=\"framePick\"></div>\n              <p class=\"panel-hint\" id=\"frameChooseHint\" style=\"display:none; margin-top:10px;\"></p>\n              <div id=\"sheetPanel\" style=\"display:none;\">\n                <div class=\"sheet-preset-box\" id=\"sheetPresetBox\" style=\"margin-top:10px; margin-bottom:14px; padding:12px 14px; background:var(--panel-2, #f5f2ec); border:1px solid var(--line, #e2ddd5); border-radius:12px;\">\n                  <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;\">\n                    <span class=\"sub-label\" style=\"margin:0; font-weight:800; font-size:12.5px; color:var(--ink, #1c1a1e);\">Collage Presets</span>\n                    <span class=\"panel-hint\" id=\"sheetPresetCount\" style=\"margin:0; font-size:11px; font-weight:700; color:var(--brand, #c93d27);\">1 preset</span>\n                  </div>\n                  <div style=\"display:flex; gap:8px; align-items:center; flex-wrap:wrap;\">\n                    <select class=\"mini-select\" id=\"sheetPresetSelect\" style=\"flex:1; min-width:140px; font-weight:700; background:#fff; border-radius:8px; height:36px;\" aria-label=\"Select collage preset\"></select>\n                    <button type=\"button\" class=\"action-btn\" id=\"sheetPresetSave\" style=\"width:auto; margin:0; padding:0 12px; height:36px; font-size:12px; font-weight:700;\" title=\"Save current arrangement as a new collage preset\">+ Save as…</button>\n                    <button type=\"button\" class=\"action-btn\" id=\"sheetPresetUpdate\" style=\"width:auto; margin:0; padding:0 10px; height:36px; font-size:12px; font-weight:700;\" title=\"Overwrite selected preset with current arrangement\">Save</button>\n                    <button type=\"button\" class=\"action-btn\" id=\"sheetPresetDelete\" style=\"width:auto; margin:0; padding:0 10px; height:36px; font-size:12px; font-weight:700; color:#c0392b;\" title=\"Delete selected preset\">✕</button>\n                  </div>\n                  <p class=\"panel-hint\" style=\"margin:6px 0 0; font-size:11px; line-height:1.4;\">Save different sheets (e.g. <b>Collage A</b> with 3-shot strips, <b>Collage B</b> with 4-shot strips). Turn on <b>Let guests choose layout</b> below to let guests pick!</p>\n                </div>\n                <p class=\"sub-label\" style=\"margin-top:6px;\">Sheet size</p>\n                <div class=\"sheet-size-row\">\n                  <select class=\"mini-select\" id=\"sheetSizeSelect\" aria-label=\"Sheet size\"></select>\n                  <span class=\"panel-hint\" style=\"margin:0;\">Choose the same paper size when you print.</span>\n                </div>\n                <p class=\"sub-label\" style=\"margin-top:6px;\">Arrange them on the sheet</p>\n                <div class=\"pattern-row\" id=\"sheetPatterns\"></div>\n                <div class=\"decor-btns\">\n                  <button type=\"button\" class=\"action-btn\" id=\"sheetShuffle\">⇄ Swap places</button>\n                  <button type=\"button\" class=\"action-btn\" id=\"sheetAddFrame\">+ Add a copy</button>\n                  <button type=\"button\" class=\"action-btn see-prev-btn\" data-see-preview style=\"margin:0;\"><svg\n                      class=\"ic\" aria-hidden=\"true\">\n                      <use href=\"#i-eye\" />\n                    </svg> Open preview</button>\n                </div>\n                <p class=\"panel-hint\" style=\"margin-top:8px;\">Fine-tune in the preview: <b>drag</b> a frame to move it,\n                  or <b>tap</b> it to resize, swap, turn or copy it.</p>\n              </div>\n            </div>\n          </div>\n          <div class=\"lay-ctx\" id=\"layoutCtx\">\n            <p class=\"panel-hint\" id=\"layoutHint\" style=\"margin:0;\"></p>\n          </div>\n          <div class=\"sub-group\" id=\"ownFrameBox\">\n            <input type=\"file\" id=\"overlayInput\" accept=\"image/png,image/webp,image/jpeg,image/*\" multiple hidden>\n            <p class=\"panel-hint\" id=\"overlaySizeHint\" hidden></p>\n            <div id=\"overlayOnTopBox\" class=\"sub-group\">\n              <div class=\"bg-row\">\n                <img class=\"bg-thumb\" id=\"overlayThumb\" alt=\"Overlay\" style=\"display:none;\">\n                <select class=\"mini-select\" id=\"overlayFit\" style=\"display:none;\">\n                  <option value=\"stretch\">Stretch</option>\n                  <option value=\"contain\">Keep shape</option>\n                </select>\n              </div>\n              <button class=\"remove-link\" id=\"overlayRemove\">Remove overlay</button>\n              <p class=\"panel-hint\" id=\"overlayOnTopNote\" style=\"margin-top:4px; display:none;\">No photo spots found, so\n                it sits on top as an overlay.</p>\n            </div>\n            <div class=\"frame-list\" id=\"frameList\" hidden></div>\n          </div>\n          <select id=\"photoFitSelect\" hidden>\n            <option value=\"fill\" selected>Fill the box</option>\n          </select>\n          <div class=\"guest-layouts\" id=\"guestLayouts\" hidden></div>\n        </div>\n        <div class=\"step-nav\"><button type=\"button\" class=\"action-btn back-btn\" data-go=\"2\">← Back</button><button\n            type=\"button\" class=\"action-btn primary next-btn\" data-go=\"4\">Next: Camera →</button></div>\n      </section>\n\n      <!-- STEP 4 · CAMERA -->\n      <section class=\"step\" id=\"step4\" data-step=\"4\">\n        <div class=\"panel-section\" id=\"camPreviewSection\">\n          <p class=\"panel-label\">Live view</p>\n          <p class=\"panel-hint step-lead\">What the camera sees before you start. Mirror and the live filter show here\n            too.</p>\n          <div class=\"scp-frame\" id=\"scpFrame\">\n            <video id=\"setupCamVideo\" autoplay playsinline muted></video>\n            <div class=\"scp-empty\" id=\"scpEmpty\">Waiting for the camera…</div>\n          </div>\n          <div class=\"scp-meta\">\n            <span class=\"scp-info\" id=\"scpInfo\"></span>\n            <div class=\"chip-row\" id=\"scpFitChips\">\n              <button type=\"button\" class=\"chip active\" data-fit=\"full\">Full frame</button>\n              <button type=\"button\" class=\"chip\" data-fit=\"layout\">Crop to layout</button>\n            </div>\n          </div>\n        </div>\n        <div class=\"panel-section\" id=\"cameraSection\">\n          <p class=\"panel-label\">Camera</p>\n          <select class=\"cam-select\" id=\"cameraSelect\">\n            <option value=\"\">Loading cameras…</option>\n          </select>\n          <p class=\"panel-hint\" id=\"cameraHint\">Switch cameras any time before starting.</p>\n          <div id=\"webcamResBox\" style=\"display:none; margin-top:8px;\">\n            <p class=\"panel-label\" style=\"margin-top:6px;\">USB webcam preview</p>\n            <select class=\"cam-select\" id=\"webcamPreviewRes\">\n              <option value=\"auto\">Auto (best that works, up to 1080p)</option>\n              <option value=\"max\">Max (camera's full resolution)</option>\n              <option value=\"1080\">1080p</option>\n              <option value=\"720\">720p</option>\n              <option value=\"480\">480p (smoothest, GIF / boomerang)</option>\n            </select>\n            <p class=\"panel-hint\" style=\"margin-top:4px;\">Need one exact size? Open the list and pick one under \"Exact size (forced)\". The booth then uses only that size and shows an error instead of falling back to a smaller one. If the webcam resets, use a powered USB hub.</p>\n            <p class=\"panel-label\" style=\"margin-top:6px;\">USB webcam photo</p>\n            <select class=\"cam-select\" id=\"webcamPhotoRes\">\n              <option value=\"preview\">Same as preview (instant)</option>\n              <option value=\"max\">Max resolution (switches at capture, ~1–2 s)</option>\n            </select>\n            <p class=\"panel-hint\" id=\"webcamResNote\"></p>\n          </div>\n          <p class=\"panel-hint\" id=\"usbCamNote\" style=\"display:none;\"></p>\n          <p class=\"panel-hint\" id=\"usbWhyNote\" style=\"display:none; font-weight:600;\"></p>\n          <button type=\"button\" class=\"action-btn\" id=\"usbLogBtn\" style=\"display:none; width:auto; margin:6px 0 0;\">Copy\n            camera log</button>\n          <button type=\"button\" class=\"action-btn\" id=\"usbCheckBtn\"\n            style=\"display:none; width:auto; margin:6px 0 0;\">Camera check</button>\n          <pre id=\"usbCheckOut\"\n            style=\"display:none; white-space:pre-wrap; font:12px/1.5 ui-monospace,Menlo,monospace; background:#f6f3ee; border:1px solid #ddd; border-radius:8px; padding:10px; margin:8px 0 0; max-height:260px; overflow:auto;\"></pre>\n          <button type=\"button\" class=\"action-btn\" id=\"usbCheckCopy\"\n            style=\"display:none; width:auto; margin:6px 0 0;\">Copy check result</button>\n          <label class=\"switch-row\" id=\"mirrorRow\">\n            <span>Mirror the live view</span>\n            <input type=\"checkbox\" id=\"mirrorToggle\">\n          </label>\n          <p class=\"panel-hint\" id=\"mirrorHint\">On: guests see themselves like in a mirror. Saved and printed photos\n            match the preview.</p>\n        </div>\n        <div class=\"panel-section hidden\" id=\"step4Printer\">\n          <p class=\"panel-label\">Printing</p>\n          <div class=\"s4-sum\" id=\"s4PrinterSum\"></div>\n          <div style=\"display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:6px 0 10px;\">\n            <button type=\"button\" class=\"action-btn primary\" id=\"s4PrinterBtn\" style=\"width:auto;margin:0;\">Choose\n              printer &amp; paper</button>\n            <button type=\"button\" class=\"action-btn\" id=\"s4PreviewBtn\" style=\"width:auto;margin:0;\">Print\n              preview</button>\n          </div>\n          <div style=\"display:flex;gap:12px;align-items:flex-start;\">\n            <img id=\"s4Thumb\" alt=\"How the page will look\" hidden\n              style=\"max-height:170px;border:1px solid #bbb;background:#fff;box-shadow:0 2px 8px rgba(0,0,0,.25);\">\n            <p class=\"panel-hint\" id=\"s4ThumbNote\" style=\"margin:0;\">The preview shows how the printed page will look.\n            </p>\n          </div>\n\n          <div class=\"pr-opts\" id=\"printSummaryBox\" style=\"display:none;\">\n            <p class=\"panel-hint\" id=\"printSummary\" style=\"margin:0;\"></p>\n\n            <div class=\"fb-card\">\n              <p class=\"sub-label\">Guests</p>\n              <label class=\"switch-row\"><span>Print button for guests</span><input type=\"checkbox\"\n                  id=\"ppGuestBtn\"></label>\n              <label class=\"switch-row\"><span>Let guests choose how many copies</span><input type=\"checkbox\"\n                  id=\"ppGuestCopies\"></label>\n              <label class=\"switch-row\" id=\"ppGuestReqRow\" style=\"display:none;\"><span>Let guests ask for a print from\n                  their phone</span><input type=\"checkbox\" id=\"ppGuestReq\"></label>\n              <p class=\"panel-hint\" id=\"ppGuestReqHint\" style=\"margin:4px 0 0; display:none;\">Their photo page gets an\n                &ldquo;Ask for a print&rdquo; button. Requests show under <b>Print requests</b> in the dock.</p>\n            </div>\n\n            <div class=\"fb-card\" id=\"ppVoucherCard\" style=\"display:none;\">\n              <p class=\"sub-label\">Vouchers &amp; payments</p>\n              <label class=\"switch-row\"><span>Link vouchers to printers</span><input type=\"checkbox\"\n                  id=\"ppVoucherPrinter\"></label>\n              <p class=\"panel-hint\" id=\"ppVoucherPrinterHint\" style=\"margin:4px 0 0;\">Off: prints go to the printer for the paper size. On: each payment option in Setup gets a <b>Printer</b> choice, and guests who pay or use a voucher for that option print on that printer (with its own colour and quality settings). Needs two payment options (the &ldquo;two prices&rdquo; switch) to be on.</p>\n            </div>\n\n            <div class=\"fb-card\">\n              <p class=\"sub-label\">Automatic printing</p>\n              <label class=\"switch-row\"><span>Print after each session</span><input type=\"checkbox\" id=\"ppAuto\"></label>\n              <p class=\"panel-hint\" id=\"ppAutoHint\" style=\"margin:4px 0 0;\"></p>\n              <div class=\"copies-row\"><span>Copies each time</span>\n                <span class=\"stepper\"><button type=\"button\" id=\"ppCopiesMinus\"\n                    aria-label=\"Fewer copies\">&minus;</button><b id=\"ppCopiesVal\">1</b><button type=\"button\"\n                    id=\"ppCopiesPlus\" aria-label=\"More copies\">+</button></span>\n              </div>\n              <label class=\"switch-row\"><span>Check the page before the first print</span><input type=\"checkbox\"\n                  id=\"ppPreview\"></label>\n              <label class=\"switch-row\" id=\"ppPrintFirstRow\"><span>Print first before showing QR</span><input type=\"checkbox\"\n                  id=\"ppPrintFirst\"></label>\n              <p class=\"panel-hint\" id=\"ppPrintFirstHint\" style=\"margin:4px 0 0;\">Wait until printing completes before showing the QR code on screen.</p>\n            </div>\n\n            <details class=\"pp-words\">\n              <summary>Change the wording guests see</summary>\n              <label>Print button<input type=\"text\" id=\"ppTxtPrint\" maxlength=\"24\" placeholder=\"Print\"></label>\n              <label>While printing<input type=\"text\" id=\"ppTxtPrinting\" maxlength=\"60\"\n                  placeholder=\"Printing, please hold…\"></label>\n              <label>Copies question<input type=\"text\" id=\"ppTxtCopies\" maxlength=\"40\"\n                  placeholder=\"How many copies?\"></label>\n              <label>When the print limit is reached<input type=\"text\" id=\"ppTxtLimit\" maxlength=\"70\"\n                  placeholder=\"That's all the prints for this session\"></label>\n            </details>\n            <label class=\"sub-label web-only\" for=\"ppRoute\" style=\"display:block; margin:12px 0 4px;\">Send prints to\n              (this device)</label>\n            <select id=\"ppRoute\" class=\"print-route web-only\">\n              <option value=\"here\">This device</option>\n              <option value=\"station\">Laptop print station (no pop-up)</option>\n            </select>\n            <p class=\"panel-hint web-only\" id=\"ppRouteHint\" style=\"margin:4px 0 0;\"></p>\n          </div>\n        </div>\n        <div class=\"step-nav\"><button type=\"button\" class=\"action-btn back-btn\" data-go=\"3\">← Back</button><button\n            type=\"button\" class=\"action-btn primary next-btn\" data-go=\"5\">Next: Extras →</button></div>\n      </section>\n\n      <!-- STEP 5 · EXTRAS -->\n      <section class=\"step\" id=\"step5\" data-step=\"5\">\n        <div class=\"panel-section\" id=\"decorSection\">\n          <p class=\"panel-label\">Extras</p>\n          <p class=\"panel-hint step-lead\">All optional.</p>\n\n          <!-- ── GIF / Output mode ── -->\n          <div class=\"panel-section\" id=\"gifModeSection\"\n            style=\"margin-bottom:14px; padding:14px 16px; background:var(--panel-2); border-radius:12px; border:1.5px solid var(--line);\">\n            <p class=\"sub-label\" style=\"margin:0 0 6px;\">🎞️ Output mode</p>\n            <p class=\"panel-hint\" style=\"margin:0 0 10px;\">Choose what guests receive after each session.</p>\n            <div class=\"chip-row\" id=\"outputModeChips\" role=\"group\" aria-label=\"Output mode\">\n              <button type=\"button\" class=\"chip active\" data-outmode=\"photo\">📷 Photo only</button>\n              <button type=\"button\" class=\"chip\" data-outmode=\"gif\">🎞️ GIF only</button>\n              <button type=\"button\" class=\"chip\" data-outmode=\"both\">📷 + 🎞️ Both</button>\n              <button type=\"button\" class=\"chip\" data-outmode=\"flipbook\">📖 Flipbook</button>\n            </div>\n            <p class=\"panel-hint\" id=\"gifModeHint\" style=\"margin:8px 0 0; color:var(--ink-dim);\">Guests get a photo\n              strip + QR code.</p>\n            <div id=\"flipbookOptions\" class=\"fb-opts\" style=\"display:none;\">\n              <div class=\"fb-card\">\n                <p class=\"sub-label\">1 · Recording</p>\n                <div class=\"fb-row\"><span class=\"lbl\">Clip length</span>\n                  <select id=\"flipSecSelect\" class=\"pillify\" aria-label=\"Clip length\">\n                    <option value=\"4\">4 s</option>\n                    <option value=\"5\">5 s</option>\n                    <option value=\"6\" selected>6 s</option>\n                    <option value=\"7\">7 s</option>\n                  </select>\n                </div>\n                <div class=\"fb-row\"><span class=\"lbl\">Frames in the book</span>\n                  <select id=\"flipFramesSelect\" class=\"pillify\" aria-label=\"Frames in the book\">\n                    <option value=\"16\">16</option>\n                    <option value=\"24\" selected>24</option>\n                    <option value=\"30\">30</option>\n                    <option value=\"40\">40</option>\n                  </select>\n                </div>\n                <label class=\"switch-row\"><span>Show motion prompts while recording</span><input type=\"checkbox\"\n                    id=\"flipCuesToggle\" checked></label>\n              </div>\n\n              <div class=\"fb-card\">\n                <p class=\"sub-label\">2 · Cover &amp; back</p>\n                <label class=\"switch-row\"><span>Cover card</span><input type=\"checkbox\" id=\"flipCoverToggle\"\n                    checked></label>\n                <div class=\"fb-row fb-sub\" id=\"flipCoverStyleWrap\"><span class=\"lbl\">Cover style</span>\n                  <select id=\"flipCoverStyleSelect\" class=\"pillify\" aria-label=\"Cover style\">\n                    <option value=\"title\" selected>Logo + title</option>\n                    <option value=\"photo\">Clip photo</option>\n                    <option value=\"custom\">Your image</option>\n                  </select>\n                </div>\n                <div id=\"flipCoverCustomWrap\" class=\"fb-sub\" style=\"display:none;\">\n                  <div class=\"bg-row\">\n                    <img class=\"bg-thumb\" id=\"flipCoverThumb\" alt=\"Cover\"\n                      style=\"display:none; max-width:80px; max-height:60px; border-radius:4px; object-fit:cover;\">\n                    <label class=\"upload-btn\" for=\"flipCoverInput\" style=\"font-size:13px; padding:6px 12px;\">Upload\n                      cover image</label>\n                    <input type=\"file\" id=\"flipCoverInput\" accept=\"image/*\">\n                  </div>\n                  <button type=\"button\" class=\"remove-link\" id=\"flipCoverRemove\"\n                    style=\"display:none; margin-top:6px;\">Remove custom cover</button>\n                </div>\n                <label class=\"switch-row\"><span>Back card</span><input type=\"checkbox\" id=\"flipBackToggle\"\n                    checked></label>\n                <div id=\"flipBackDetails\" class=\"fb-sub\">\n                  <label class=\"switch-row\"><span>QR code to the digital flipbook</span><input type=\"checkbox\"\n                      id=\"flipBackQrToggle\" checked></label>\n                  <div class=\"fb-row\"><span class=\"lbl\">Caption under the QR</span>\n                    <input type=\"text\" class=\"label-input\" id=\"flipBackTextInput\" maxlength=\"60\"\n                      placeholder=\"Scan to view &amp; share\">\n                  </div>\n                </div>\n              </div>\n\n              <div class=\"fb-card\">\n                <p class=\"sub-label\">3 · Printed sheets</p>\n                <div class=\"fb-row\"><span class=\"lbl\">Card order</span>\n                  <select id=\"flipCollationSelect\" class=\"pillify\" aria-label=\"Card order\">\n                    <option value=\"stack\" selected>Stack-cut</option>\n                    <option value=\"grid\">In order</option>\n                  </select>\n                </div>\n                <p class=\"panel-hint\" style=\"margin:6px 0 0;\">Stack-cut: cut the sheets as one stack and the piles\n                  come out already in order.</p>\n                <div class=\"fb-row\"><span class=\"lbl\">Cards per sheet</span>\n                  <select id=\"flipGridPresetSelect\" class=\"pillify\" aria-label=\"Cards per sheet\">\n                    <option value=\"auto\" selected>Auto</option>\n                    <option value=\"6up\">6 per sheet</option>\n                    <option value=\"8up\">8 per sheet</option>\n                  </select>\n                </div>\n                <label class=\"switch-row\"><span>Binding margin and staple dots</span><input type=\"checkbox\"\n                    id=\"flipGutterToggle\" checked></label>\n                <label class=\"switch-row\"><span>Page numbers in the margin</span><input type=\"checkbox\"\n                    id=\"flipNumbersToggle\" checked></label>\n                <p class=\"panel-hint\" style=\"margin:8px 0 0;\">Paper and printer are chosen in Camera &amp; printer.</p>\n              </div>\n\n              <div class=\"fb-card\">\n                <p class=\"sub-label\">Two printers <span class=\"fb-opt\">optional</span></p>\n                <div class=\"fb-row\"><span class=\"lbl\">Second printer</span>\n                  <select id=\"flipPrinterPoolSelect\" class=\"mini-select\" aria-label=\"Second printer\">\n                    <option value=\"\" selected>None (single printer)</option>\n                  </select>\n                </div>\n                <div class=\"fb-row\" id=\"flipPoolModeWrap\" style=\"display:none;\"><span class=\"lbl\">Share the work\n                    by</span>\n                  <select id=\"flipPoolModeSelect\" class=\"pillify\" aria-label=\"Share the work by\">\n                    <option value=\"pages\" selected>Sheets</option>\n                    <option value=\"copies\">Copies</option>\n                  </select>\n                </div>\n                <p class=\"panel-hint\" id=\"flipPoolHint\" style=\"display:none; margin:6px 0 0;\">Splits the work between\n                  two printers so guests wait about half as long.</p>\n              </div>\n            </div>\n            <div id=\"gifOptions\" class=\"fb-opts\" style=\"display:none;\">\n              <div class=\"fb-card\">\n                <p class=\"sub-label\">GIF</p>\n                <div class=\"fb-row\"><span class=\"lbl\">Picture frame</span>\n                  <select id=\"gifLayoutSelect\" class=\"pillify\" aria-label=\"GIF picture frame\">\n                    <option value=\"solo\" selected>Solo layout</option>\n                    <option value=\"follow\">Chosen layout</option>\n                    <option value=\"raw\">Plain camera</option>\n                  </select>\n                </div>\n                <p class=\"panel-hint\" id=\"gifLayoutHint\" style=\"margin:6px 0 0;\">The GIF sits in the one-photo Solo\n                  layout with your frame and title. Guests should stand in the middle.</p>\n                <p class=\"panel-hint\" style=\"margin:6px 0 0;\">It follows the first run of shots. Speed is automatic.\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"seg-tabs\" id=\"extrasTabs\" role=\"tablist\">\n            <button type=\"button\" class=\"on\" data-pane=\"logo\">Logo</button>\n            <button type=\"button\" data-pane=\"stickers\">Stickers</button>\n            <button type=\"button\" data-pane=\"filter\">Filter</button>\n            <button type=\"button\" data-pane=\"greenscreen\">Green screen</button>\n          </div>\n\n\n\n          <div class=\"pane on\" data-pane=\"logo\">\n            <div class=\"bg-row\">\n              <img class=\"bg-thumb\" id=\"logoThumb\" alt=\"Logo\" style=\"display:none;\">\n              <label class=\"upload-btn\" for=\"logoInput\">Upload logo</label>\n              <input type=\"file\" id=\"logoInput\" accept=\"image/*\">\n            </div>\n            <button class=\"remove-link\" id=\"logoRemove\">Remove logo</button>\n            <div id=\"logoControls\" style=\"display:none; margin-top:10px;\">\n              <div class=\"opt-row\">\n                <span class=\"lbl\">Position</span>\n                <select class=\"mini-select\" id=\"logoPos\">\n                  <option value=\"tl\">Top left</option>\n                  <option value=\"tc\">Top center</option>\n                  <option value=\"tr\">Top right</option>\n                  <option value=\"bl\">Bottom left</option>\n                  <option value=\"bc\">Bottom center</option>\n                  <option value=\"br\">Bottom right</option>\n                </select>\n              </div>\n              <div class=\"stepper\"><span class=\"lbl\">Size</span><input type=\"range\" id=\"logoSize\" min=\"8\" max=\"45\"\n                  value=\"20\" style=\"flex:1; max-width:220px;\"></div>\n            </div>\n          </div>\n\n          <div class=\"pane\" data-pane=\"stickers\">\n            <div class=\"chip-row pack-chips\" id=\"packChips\" role=\"tablist\" aria-label=\"Sticker packages\"></div>\n            <div class=\"prop-tray\" id=\"propTray\"></div>\n            <button type=\"button\" class=\"link-btn\" id=\"propMore\" style=\"margin-top:8px;\">More stickers</button>\n            <div class=\"bg-row\" style=\"margin-top:10px;\">\n              <label class=\"upload-btn\" for=\"propInput\">+ Upload your own (PNG)</label>\n              <input type=\"file\" id=\"propInput\" accept=\"image/*\" multiple>\n            </div>\n            <p class=\"panel-hint\" style=\"margin-top:6px;\">Tap to add, then drag it on the preview. Drag a corner of its box to resize and the round handle to turn it. Tap an empty spot to hide the box and see the final look.</p>\n            <button class=\"remove-link\" id=\"decorClear\" style=\"display:inline;\">Remove all stickers</button>\n            <div style=\"margin-top:14px; padding-top:12px; border-top:1px solid rgba(0,0,0,0.08);\">\n              <label class=\"switch-row\" id=\"guestStickersRow\" style=\"margin:0;\">\n                <span>Customise stickers post photo session</span>\n                <input type=\"checkbox\" id=\"guestStickersToggle\">\n              </label>\n              <p class=\"panel-hint\" id=\"guestStickersHint\" style=\"margin:4px 0 0;\">When turned on, guests can add and place stickers on their photo right after taking photos, before printing.</p>\n              <div id=\"guestStickerOpts\" style=\"margin-top:10px;\">\n                <p class=\"sub-label\" style=\"margin:0 0 6px;\">Sticker packages guests can use</p>\n                <div class=\"pack-checks\" id=\"packChecks\"></div>\n                <p class=\"panel-hint\" id=\"packHint\" style=\"margin:4px 0 0;\"></p>\n                <label class=\"stepper\" style=\"margin-top:10px; gap:8px; align-items:center;\"><span class=\"lbl\">Time to decorate</span>\n                  <select id=\"guestStickerSec\" style=\"padding:6px 8px; border-radius:8px; border:1.5px solid var(--line);\"></select></label>\n                <p class=\"panel-hint\" id=\"guestStickerSecHint\" style=\"margin:4px 0 0;\"></p>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"pane\" data-pane=\"greenscreen\" id=\"greenSection\">\n            <div class=\"chip-row\" id=\"bgModeChips\">\n              <button type=\"button\" class=\"chip active\" data-mode=\"off\">Off</button>\n              <button type=\"button\" class=\"chip\" data-mode=\"ai\">No cloth (AI) <span\n                  class=\"beta-tag\">Beta</span></button>\n              <button type=\"button\" class=\"chip\" data-mode=\"green\">Green screen</button>\n            </div>\n            <p class=\"panel-hint\" id=\"bgModeHint\" style=\"margin-top:8px;\"></p>\n            <div id=\"bgOpts\" style=\"display:none;\">\n              <p class=\"panel-hint bg-status\" id=\"bgStatus\"></p>\n              <p class=\"sub-label\" style=\"margin-top:12px;\">Picture behind the guests</p>\n              <div class=\"bgr-grid\" id=\"bgrGrid\"></div>\n              <div class=\"bg-row\" style=\"margin-top:10px;\">\n                <label class=\"upload-btn\" for=\"bgrInput\">+ Upload your own picture</label>\n                <input type=\"file\" id=\"bgrInput\" accept=\"image/*\">\n              </div>\n              <div id=\"greenOpts\" style=\"display:none;\">\n                <p class=\"sub-label\" style=\"margin-top:14px;\">Screen colour</p>\n                <div class=\"bd-key-row\" id=\"bgKeyRow\">\n                  <button type=\"button\" class=\"bd-key\" data-key=\"green\" style=\"--sw:#00b140;\">Green</button>\n                  <button type=\"button\" class=\"bd-key\" data-key=\"blue\" style=\"--sw:#0047bb;\">Blue</button>\n                  <button type=\"button\" class=\"bd-key\" data-key=\"pick\">Pick from camera</button>\n                </div>\n                <div class=\"stepper\" style=\"margin-top:10px;\"><span class=\"lbl\">Strength</span><input type=\"range\"\n                    id=\"keyTol\" min=\"15\" max=\"95\" value=\"48\" style=\"flex:1; max-width:220px;\"></div>\n                <p class=\"panel-hint\" style=\"margin-top:4px;\">Raise it if bits of the cloth show; lower it if parts of\n                  guests disappear.</p>\n              </div>\n              <label class=\"toggle-row\" style=\"margin-top:12px;\"><input type=\"checkbox\" id=\"bgLiveToggle\" checked> Show\n                it in the live view</label>\n              <p class=\"panel-hint\" style=\"margin-top:6px;\">Check it with <b>Preview with my camera</b> under the\n                preview.</p>\n            </div>\n          </div>\n\n          <div class=\"pane\" data-pane=\"filter\" id=\"effectsSection\">\n            <div class=\"chip-row\" id=\"filterChips\">\n              <button type=\"button\" class=\"chip active\" data-filter=\"none\">None</button>\n              <button type=\"button\" class=\"chip\" data-filter=\"bw\">B&amp;W</button>\n              <button type=\"button\" class=\"chip\" data-filter=\"sepia\">Sepia</button>\n              <button type=\"button\" class=\"chip\" data-filter=\"warm\">Warm</button>\n              <button type=\"button\" class=\"chip\" data-filter=\"cool\">Cool</button>\n              <button type=\"button\" class=\"chip\" data-filter=\"film\" data-vintage=\"1\">Film</button>\n              <button type=\"button\" class=\"chip\" data-filter=\"faded\" data-vintage=\"1\">Faded</button>\n              <button type=\"button\" class=\"chip\" data-filter=\"retro\" data-vintage=\"1\">70s</button>\n              <button type=\"button\" class=\"chip\" data-filter=\"instant\" data-vintage=\"1\">Instant</button>\n              <button type=\"button\" class=\"chip\" data-filter=\"noir\" data-vintage=\"1\">Noir</button>\n            </div>\n            <label class=\"toggle-row\" style=\"margin-top:12px;\"><input type=\"checkbox\" id=\"softSkinToggle\"> Soft\n              skin</label>\n            <label class=\"toggle-row\" id=\"dateStampRow\" style=\"margin-top:8px;\"><input type=\"checkbox\"\n                id=\"dateStampToggle\"> Date stamp (orange camera-style date on each photo)</label>\n\n            <div id=\"guestLooksRow\" style=\"margin-top:14px;\" hidden>\n              <label class=\"toggle-row\"><input type=\"checkbox\" id=\"guestLooksToggle\"> Let guests choose a look on the\n                guest screen</label>\n              <div id=\"guestLooksPick\" hidden>\n                <p class=\"panel-hint\" style=\"margin:8px 0 6px;\">Tick up to 6 looks guests can choose from. Guests see\n                  one small &ldquo;Look&rdquo; button; tapping it opens the row. Each guest starts again with the look\n                  chosen above.</p>\n                <div class=\"chip-row\" id=\"guestLooksChips\"></div>\n              </div>\n            </div>\n          </div>\n        </div>\n        <div class=\"step-nav\"><button type=\"button\" class=\"action-btn back-btn\" data-go=\"4\">← Back</button><button\n            type=\"button\" class=\"action-btn primary next-btn\" data-go=\"6\">Next: Share →</button></div>\n      </section>\n\n      <!-- STEP 6 · SHARE -->\n      <section class=\"step\" id=\"step6\" data-step=\"6\">\n        <div class=\"panel-section\" id=\"driveSetupSection\">\n          <p class=\"panel-label\">Share</p>\n          <p class=\"panel-hint step-lead\" id=\"driveStatusText\">Type a folder name to save the photos.</p>\n          <p class=\"panel-hint\" id=\"driveFolderAutoNote\" style=\"display:none; color:#1e8449; font-weight:700;\"></p>\n          <input type=\"text\" class=\"label-input\" id=\"driveFolderKeyInput\" placeholder=\"Folder name or Drive link\"\n            style=\"font-family:'Manrope',sans-serif; font-size:14px; margin:10px 0 0;\">\n          <p class=\"panel-hint\" id=\"driveFolderError\" style=\"display:none; color:#c0392b; font-weight:700;\"></p>\n          <p class=\"panel-hint\" id=\"driveFolderStatus\" style=\"display:none;\"></p>\n          <div id=\"driveFolderQrPreview\" style=\"display:none; margin-top:12px; text-align:center;\">\n            <img id=\"driveFolderQrImg\" class=\"qr-img\" style=\"width:140px;height:140px;\" alt=\"All photos QR code\">\n            <p class=\"qr-caption\" id=\"driveFolderQrCaption\">All photos</p>\n            <div class=\"folder-links\" id=\"driveFolderLinks\">\n              <a id=\"driveFolderOpen\" href=\"#\" target=\"_blank\" rel=\"noopener\">Open gallery</a>\n              <button type=\"button\" id=\"driveFolderCopy\">Copy link</button>\n              <a id=\"driveFolderDrive\" href=\"#\" target=\"_blank\" rel=\"noopener\" style=\"display:none;\">Drive folder</a>\n              <a id=\"driveFolderAll\" class=\"web-only\" href=\"/lifetime/?booth=1\" target=\"_blank\" rel=\"noopener\"\n                style=\"display:none;\">All my events ↗</a>\n            </div>\n            <button type=\"button\" class=\"action-btn\" id=\"qrSignBtn\"\n              style=\"width:auto; margin:10px auto 0; padding:9px 16px;\">Download QR sign</button>\n            <p class=\"panel-hint\" id=\"driveFolderSignHint\" style=\"margin-top:8px;\">Print the sign and put it by the\n              booth. Guests get their own QR after each session; if the booth is offline, their photo still arrives in\n              this gallery once it's back online.</p>\n          </div>\n          <p class=\"panel-hint\" id=\"driveFolderHelp\"></p>\n          <div class=\"sub-group\" id=\"gvBox\" style=\"display:none;\">\n            <p class=\"sub-label\">After guests scan their QR</p>\n            <select class=\"mini-select pillify\" id=\"gvSelect\" aria-label=\"What guests see after scanning\">\n              <option value=\"all\" selected>Everyone&rsquo;s photos</option>\n              <option value=\"mine\">Mine first</option>\n              <option value=\"only\">Only their own</option>\n            </select>\n            <p class=\"panel-hint\" id=\"gvHint\" style=\"margin-top:6px;\"></p>\n          </div>\n          <div class=\"sub-group web-only\" id=\"backupBox\">\n            <p class=\"sub-label\">Backup on this computer</p>\n            <p class=\"panel-hint\" id=\"backupStatus\" style=\"margin:0;\"></p>\n            <div id=\"backupBtns\" style=\"display:flex; gap:8px; flex-wrap:wrap; margin-top:8px;\">\n              <button type=\"button\" class=\"action-btn\" id=\"backupChooseBtn\" style=\"width:auto; margin:0;\">Choose backup\n                folder</button>\n              <button type=\"button\" class=\"action-btn primary\" id=\"backupAllowBtn\"\n                style=\"width:auto; margin:0; display:none;\">Allow saving</button>\n              <button type=\"button\" class=\"action-btn\" id=\"backupStopBtn\"\n                style=\"width:auto; margin:0; display:none;\">Stop backup</button>\n            </div>\n          </div>\n          <div class=\"sub-group\" id=\"deskBox\" hidden>\n            <p class=\"sub-label\" id=\"deskPhotosLabel\">Photos on this laptop</p>\n            <p class=\"panel-hint\" id=\"deskPhotos\" style=\"margin:0; word-break:break-all;\"></p>\n            <div class=\"desk-row\" id=\"deskPhotoRow\">\n              <button type=\"button\" class=\"action-btn\" id=\"deskOpenBtn\" style=\"width:auto; margin:0;\">Open photos\n                folder</button>\n              <button type=\"button\" class=\"action-btn\" id=\"deskChangeBtn\" style=\"width:auto; margin:0;\">Change\n                folder</button>\n            </div>\n            <p class=\"sub-label\" style=\"margin-top:14px;\">Guests&rsquo; phones</p>\n            <p class=\"panel-hint\" id=\"deskLan\" style=\"margin:0;\"></p>\n            <div id=\"deskIpadBox\" style=\"display:none;\">\n              <p class=\"sub-label\" style=\"margin-top:14px;\">iPad with this laptop&rsquo;s camera</p>\n              <label class=\"switch-row\"><span>Let an iPad use this laptop&rsquo;s camera</span><input type=\"checkbox\"\n                  id=\"deskIpadOn\"></label>\n              <p class=\"panel-hint\" id=\"deskIpad\" style=\"margin:6px 0 0; word-break:break-all;\"></p>\n              <div class=\"desk-row\" id=\"deskIpadRow\" style=\"display:none;\">\n                <button type=\"button\" class=\"action-btn\" id=\"deskIpadCopy\" style=\"width:auto; margin:0;\">Copy iPad\n                  address</button>\n                <button type=\"button\" class=\"action-btn\" id=\"deskIpadPin\" style=\"width:auto; margin:0;\">Make a new\n                  PIN</button>\n              </div>\n            </div>\n            <p class=\"sub-label\" style=\"margin-top:14px;\">Booth Wi-Fi for guests (optional)</p>\n            <p class=\"panel-hint\" style=\"margin:0 0 6px;\">Guests scan the Wi-Fi QR to join, then their photo QR. The\n              Wi-Fi this device is on is filled in when the app can read it. Leave empty if they already know the Wi-Fi.\n            </p>\n            <div id=\"deskHotspotBox\" style=\"display:none; margin:0 0 12px;\">\n              <label class=\"switch-row\"><span id=\"deskHotspotLabel\">Make this laptop the booth Wi-Fi (no router\n                  needed)</span><input type=\"checkbox\" id=\"deskHotspotOn\"></label>\n              <label class=\"switch-row\"><span>Turn it on whenever the app opens</span><input type=\"checkbox\"\n                  id=\"deskHotspotAuto\"></label>\n              <p class=\"panel-hint\" id=\"deskHotspotHint\" style=\"margin:6px 0 0;\"></p>\n              <div class=\"desk-row\" id=\"deskHotspotSetupRow\" style=\"display:none;\"><button type=\"button\"\n                  class=\"action-btn\" id=\"deskHotspotSetup\" style=\"width:auto; margin:0;\">Set up (one time)</button>\n              </div>\n              <div id=\"deskHotspotCreds\" style=\"display:none; margin-top:10px;\">\n                <p class=\"sub-label\" style=\"margin:0 0 4px;\">Name and password for the booth Wi-Fi</p>\n                <div style=\"display:flex; align-items:center; gap:6px;\">\n                  <span class=\"panel-hint\" id=\"deskHotspotPrefix\"\n                    style=\"display:none; margin:0; white-space:nowrap;\"></span>\n                  <input type=\"text\" class=\"label-input\" id=\"deskHotspotName\" placeholder=\"Booth Wi-Fi name\"\n                    maxlength=\"32\" autocomplete=\"off\" spellcheck=\"false\" style=\"flex:1; min-width:0;\">\n                </div>\n                <input type=\"text\" class=\"label-input\" id=\"deskHotspotPass\"\n                  placeholder=\"Booth Wi-Fi password (8 or more characters)\" maxlength=\"63\" autocomplete=\"off\"\n                  spellcheck=\"false\" style=\"margin-top:8px;\">\n                <div class=\"desk-row\" style=\"margin-top:8px;\"><button type=\"button\" class=\"action-btn\"\n                    id=\"deskHotspotSave\" style=\"width:auto; margin:0;\">Save name &amp; password</button></div>\n                <p class=\"panel-hint\" id=\"deskHotspotCredHint\" style=\"margin:6px 0 0;\"></p>\n              </div>\n              <div class=\"desk-row\" id=\"deskHotspotPhoneRow\" style=\"display:none; margin-top:8px;\"><button\n                  type=\"button\" class=\"action-btn\" id=\"deskHotspotPhone\" style=\"width:auto; margin:0;\">Use the\n                  phone&rsquo;s own Hotspot instead</button></div>\n            </div>\n            <input type=\"text\" class=\"label-input\" id=\"deskWifiName\" placeholder=\"Wi-Fi name\" maxlength=\"32\"\n              autocomplete=\"off\" spellcheck=\"false\">\n            <input type=\"text\" class=\"label-input\" id=\"deskWifiPass\" placeholder=\"Wi-Fi password (empty if none)\"\n              maxlength=\"63\" autocomplete=\"off\" spellcheck=\"false\" style=\"margin-top:8px;\">\n            <div class=\"desk-row\" style=\"margin-top:8px;\"><button type=\"button\" class=\"action-btn\" id=\"deskWifiDetect\"\n                style=\"width:auto; margin:0; display:none;\">Use current Wi-Fi</button></div>\n            <p class=\"panel-hint\" id=\"deskWifiHint\" style=\"margin:6px 0 0;\"></p>\n            <div id=\"deskWifiQrBox\" style=\"display:none; margin-top:12px; text-align:center;\">\n              <img id=\"deskWifiQrImg\" class=\"qr-img\" style=\"width:140px;height:140px;\" alt=\"Wi-Fi QR code\">\n              <p class=\"qr-caption\" id=\"deskWifiQrCap\"></p>\n              <button type=\"button\" class=\"action-btn\" id=\"wifiSignBtn\"\n                style=\"width:auto; margin:10px auto 0; padding:9px 16px;\">Download WIFI QR Sign</button>\n            </div>\n            <p class=\"sub-label\" id=\"deskLicLabel\" style=\"margin-top:14px;\">This laptop&rsquo;s licence</p>\n            <p class=\"panel-hint\" id=\"deskLic\" style=\"margin:0;\"></p>\n            <div class=\"desk-row\" id=\"deskLicRow\">\n              <button type=\"button\" class=\"action-btn\" id=\"deskCheckBtn\" style=\"width:auto; margin:0;\">Check for\n                changes</button>\n              <button type=\"button\" class=\"action-btn\" id=\"deskNewsBtn\" style=\"width:auto; margin:0;\">What's\n                new</button>\n              <button type=\"button\" class=\"action-btn\" id=\"deskDeactBtn\" style=\"width:auto; margin:0;\">Deactivate this\n                laptop</button>\n            </div>\n          </div>\n          <!-- Laptop and tablet apps: check for a new version by hand (also after \"Later\" or \"Close\") -->\n          <div class=\"sub-group\" id=\"appUpdBox\" hidden>\n            <p class=\"sub-label\">App updates</p>\n            <p class=\"panel-hint\" id=\"appUpdText\" style=\"margin:0;\"></p>\n            <div class=\"app-upd-bar\" id=\"appUpdBar\" hidden><i></i></div>\n            <div class=\"desk-row\">\n              <button type=\"button\" class=\"action-btn\" id=\"appUpdCheck\" style=\"width:auto; margin:0;\">Check for\n                updates</button>\n              <button type=\"button\" class=\"action-btn primary\" id=\"appUpdGo\"\n                style=\"width:auto; margin:0; display:none;\"></button>\n            </div>\n            <p class=\"panel-hint\" style=\"margin:6px 0 0;\">Needs the internet. Update before the event, not during a session. Your activation, designs and photos stay.</p>\n          </div>\n        </div>\n        <div class=\"step-nav\"><button type=\"button\" class=\"action-btn back-btn\" data-go=\"5\">← Back</button><button\n            type=\"button\" class=\"action-btn primary next-btn\" data-go=\"7\">Next: Session →</button></div>\n      </section>\n\n      <!-- STEP 7 · SESSION -->\n      <section class=\"step\" id=\"step7\" data-step=\"7\">\n        <div class=\"panel-section\" id=\"sessionSection\">\n          <p class=\"panel-label\">Session</p>\n          <p class=\"panel-hint step-lead\">How each guest's turn runs: countdown, time between photos and retakes.</p>\n          <p class=\"sub-label\" style=\"margin-top:16px;\">Countdown</p>\n          <div class=\"chip-row\" id=\"timerChips\">\n            <button type=\"button\" class=\"chip\" data-sec=\"3\">3s</button>\n            <button type=\"button\" class=\"chip active\" data-sec=\"5\">5s</button>\n            <button type=\"button\" class=\"chip\" data-sec=\"7\">7s</button>\n            <button type=\"button\" class=\"chip\" data-sec=\"10\">10s</button>\n          </div>\n          <details class=\"more\" open>\n            <summary>Timer &amp; retake options</summary>\n            <div class=\"stepper\">\n              <span class=\"lbl\">Fine-tune</span>\n              <span class=\"ctl\">\n                <button type=\"button\" class=\"step-btn\" id=\"timerMinus\" aria-label=\"Half a second less\">−</button>\n                <span class=\"step-val\" id=\"timerVal\">5 s</span>\n                <button type=\"button\" class=\"step-btn\" id=\"timerPlus\" aria-label=\"Half a second more\">+</button>\n              </span>\n            </div>\n            <div class=\"opt-row\">\n              <span class=\"lbl\">Extra time before photo 1</span>\n              <select class=\"mini-select pillify\" id=\"firstExtraSelect\">\n                <option value=\"0\" selected>None</option>\n                <option value=\"2\">+2s</option>\n                <option value=\"3\">+3s</option>\n                <option value=\"5\">+5s</option>\n              </select>\n            </div>\n            <div class=\"opt-row\">\n              <span class=\"lbl\">Between photos</span>\n              <select class=\"mini-select pillify\" id=\"advanceSelect\">\n                <option value=\"auto\" selected>Continue by itself</option>\n                <option value=\"tap\">Wait for a tap</option>\n              </select>\n            </div>\n            <div class=\"opt-row\" id=\"betweenRow\">\n              <span class=\"lbl\">Pause between photos</span>\n              <select class=\"mini-select pillify\" id=\"betweenSelect\">\n                <option value=\"0.5\">½s</option>\n                <option value=\"1\">1s</option>\n                <option value=\"1.5\">1½s</option>\n                <option value=\"2\">2s</option>\n                <option value=\"3\">3s</option>\n                <option value=\"4\" selected>4s</option>\n                <option value=\"5\">5s</option>\n                <option value=\"6\">6s</option>\n              </select>\n            </div>\n            <label class=\"toggle-row\" style=\"margin-top:10px;\"><input type=\"checkbox\" id=\"reviewEachToggle\" checked>\n              Show each photo in the pause</label>\n            <label class=\"toggle-row\" id=\"allowRetakeRow\" style=\"margin-top:6px; display:none;\"><input type=\"checkbox\"\n                id=\"allowRetakeToggle\" checked> Allow retakes</label>\n            <p class=\"panel-hint\" id=\"allowRetakeHint\" style=\"display:none; margin:2px 0 0;\">On: guests can redo any\n              photo (events). Off: guests can only Cancel and start over (bazaars, pay per print).</p>\n            <select id=\"resultReviewSelect\" hidden>\n              <option value=\"0\" selected>Until tap</option>\n            </select>\n          </details>\n          <p class=\"sub-label\" style=\"margin-top:16px;\">After the photos</p>\n          <label class=\"toggle-row\" style=\"margin-top:4px;\"><input type=\"checkbox\" id=\"qrPopToggle\"> Show the QR\n            code in a pop-up</label>\n          <div class=\"opt-row\" id=\"qrPopDelayRow\">\n            <span class=\"lbl\">Show the photo first for</span>\n            <select class=\"mini-select pillify\" id=\"qrPopDelaySelect\">\n              <option value=\"0\">No wait</option>\n              <option value=\"2\">2s</option>\n              <option value=\"3\" selected>3s</option>\n              <option value=\"4\">4s</option>\n              <option value=\"5\">5s</option>\n              <option value=\"8\">8s</option>\n            </select>\n          </div>\n          <p class=\"panel-hint\" id=\"qrPopHint\" style=\"margin:2px 0 0;\">After the last photo the finished picture is\n            shown on its own (almost the whole screen when the screen is upright), then a pop-up shows a big QR code.\n            With <b>Print first before showing QR</b> (step 4) on, the pop-up says Printing and the QR code appears\n            when the print is done.</p>\n        </div>\n        <div class=\"panel-section\" id=\"paySection\" style=\"display:none;\">\n          <p class=\"panel-label\">Guest payment</p>\n          <p class=\"panel-hint step-lead\">Guests pay before each session: scan a QR with GCash, Maya or any bank app, or\n            type a voucher you sell at the booth. <a href=\"/lifetime/photobooth4u-setup-guide.pdf#page=9\"\n              target=\"_blank\" rel=\"noopener\">How it works (guide, page 9)</a></p>\n          <div class=\"pay-modes\" id=\"payModes\" role=\"radiogroup\" aria-label=\"How guests pay\">\n            <button type=\"button\" class=\"chip\" data-mode=\"off\">Free</button>\n            <button type=\"button\" class=\"chip web-only\" data-mode=\"qr\">QR payment</button>\n            <button type=\"button\" class=\"chip\" data-mode=\"voucher\">Vouchers</button>\n            <button type=\"button\" class=\"chip web-only\" data-mode=\"both\">QR + vouchers</button>\n          </div>\n          <div id=\"payMore\">\n            <div class=\"pay-row\" id=\"paySingleRow\">\n              <span class=\"lbl\">Price per session</span>\n              <label class=\"pay-price\"><span>₱</span><input type=\"number\" inputmode=\"numeric\" min=\"20\" max=\"20000\"\n                  step=\"10\" id=\"payPrice\" value=\"100\" aria-label=\"Price per session in pesos\"></label>\n            </div>\n            <label class=\"switch-row\" style=\"margin-top:14px;\">\n              <span>Multiple payment options (e.g. Option 1 / Option 2)</span>\n              <input type=\"checkbox\" id=\"payDualToggle\">\n            </label>\n            <div id=\"payDualRows\" style=\"display:none; margin-top:10px;\">\n              <p class=\"panel-hint\" style=\"margin:0 0 8px;\">Guests choose between print options with separate labels, prices and layout types.</p>\n              <div id=\"payOptionsList\" style=\"display:flex; flex-direction:column; gap:10px;\"></div>\n              <button type=\"button\" class=\"action-btn\" id=\"payAddOptBtn\" style=\"margin-top:8px; width:100%; font-size:13px; font-weight:700; background:var(--panel-2,#f4efe7); color:var(--ink); border:1px dashed var(--line); border-radius:8px; padding:9px 12px; cursor:pointer;\">+ Add payment option</button>\n            </div>\n            <div class=\"stepper\" style=\"margin-top:12px;\">\n              <span class=\"lbl\" id=\"payPrintsLbl\">Prints included</span>\n              <span class=\"ctl\">\n                <button type=\"button\" class=\"step-btn\" id=\"payPrintsMinus\" aria-label=\"One print less\">−</button>\n                <span class=\"step-val\" id=\"payPrintsVal\">Use print settings</span>\n                <button type=\"button\" class=\"step-btn\" id=\"payPrintsPlus\" aria-label=\"One print more\">+</button>\n              </span>\n            </div>\n            <div class=\"pay-status\" id=\"payQrStatus\"></div>\n            <div class=\"pay-vbox\" id=\"payVoucherBox\">\n              <p class=\"sub-label\" style=\"margin:0;\">Vouchers for this event</p>\n              <p class=\"panel-hint\" style=\"margin:4px 0 0;\">Each voucher works once. Print, cut and sell them at the\n                booth table; guests type the 8 digits on the screen.</p>\n              <div class=\"pay-make\">\n                <select class=\"mini-select pillify\" id=\"payMakeTier\" aria-label=\"Which voucher\" style=\"max-width:180px;\">\n                  <option value=\"all\">Any layout</option>\n                  <option value=\"tier1\">Thermal (Option 1)</option>\n                  <option value=\"tier2\">Color (Option 2)</option>\n                </select>\n                <select class=\"mini-select pillify\" id=\"payMakeCount\" aria-label=\"How many vouchers\">\n                  <option value=\"10\">10 vouchers</option>\n                  <option value=\"20\" selected>20 vouchers</option>\n                  <option value=\"50\">50 vouchers</option>\n                  <option value=\"100\">100 vouchers</option>\n                </select>\n                <button type=\"button\" class=\"action-btn primary\" id=\"payMakeBtn\" style=\"width:auto; margin:0;\">Make\n                  vouchers</button>\n              </div>\n              <div id=\"payBatches\"></div>\n            </div>\n            <p class=\"panel-hint\" id=\"payLockHint\" style=\"margin-top:12px;\"></p>\n          </div>\n        </div>\n        <div class=\"panel-section\" id=\"fxSection\">\n          <p class=\"panel-label\">Light, sound and start</p>\n          <label class=\"switch-row\" style=\"margin-top:0;\"><span>Screen flash</span><input type=\"checkbox\"\n              id=\"fxFlash\"></label>\n          <p class=\"panel-hint\" style=\"margin-top:4px;\">The screen turns white as each photo is taken, lighting up faces\n            in dim rooms. Turn the tablet's brightness all the way up.</p>\n          <label class=\"switch-row\"><span>Countdown beeps and shutter click</span><input type=\"checkbox\" id=\"fxSound\"\n              checked></label>\n          <div class=\"opt-row\" id=\"fxVolRow\">\n            <span class=\"lbl\">Volume</span>\n            <select class=\"mini-select pillify\" id=\"fxVol\">\n              <option value=\"0.35\">Soft</option>\n              <option value=\"0.7\" selected>Normal</option>\n              <option value=\"1\">Loud</option>\n            </select>\n          </div>\n          <div id=\"fxVoiceBox\">\n            <label class=\"switch-row\"><span>Voice countdown (&ldquo;Get ready&hellip; Three, Two, One&hellip;\n                Smile!&rdquo;)</span><input type=\"checkbox\" id=\"fxVoice\" checked></label>\n            <div id=\"fxVoiceRow\">\n              <div class=\"opt-row\">\n                <span class=\"lbl\">Language</span>\n                <select class=\"mini-select pillify\" id=\"fxVLang\">\n                  <option value=\"en\" selected>English</option>\n                  <option value=\"fil\">Tagalog</option>\n                </select>\n              </div>\n              <div class=\"opt-row\">\n                <span class=\"lbl\">Say</span>\n                <select class=\"mini-select pillify\" id=\"fxVCount\">\n                  <option value=\"3\" selected>Last 3 numbers</option>\n                  <option value=\"all\">Every number</option>\n                </select>\n              </div>\n              <div class=\"opt-row\">\n                <span class=\"lbl\">Voice</span>\n                <select class=\"mini-select\" id=\"fxVName\" aria-label=\"Voice\"></select>\n              </div>\n              <button type=\"button\" class=\"action-btn\" id=\"fxVTest\" style=\"width:auto; margin:8px 0 0;\">Hear the\n                voice</button>\n              <p class=\"panel-hint\" id=\"fxVHint\" style=\"margin-top:6px;\"></p>\n            </div>\n          </div>\n          <div id=\"fxOwnRow\">\n            <p class=\"sub-label\" style=\"margin:12px 0 4px;\">Your own sounds (optional)</p>\n            <div class=\"snd-row\"><span class=\"lbl\">Shutter</span><span class=\"snd-name\" id=\"sndShutName\">Built-in\n                click</span><button type=\"button\" class=\"action-btn\" id=\"sndShutUp\">Upload</button><button type=\"button\"\n                class=\"link-btn\" id=\"sndShutX\" hidden>Use built-in</button></div>\n            <div class=\"snd-row\"><span class=\"lbl\">Countdown beep</span><span class=\"snd-name\" id=\"sndTickName\">Built-in\n                beeps</span><button type=\"button\" class=\"action-btn\" id=\"sndTickUp\">Upload</button><button type=\"button\"\n                class=\"link-btn\" id=\"sndTickX\" hidden>Use built-in</button></div>\n            <p class=\"panel-hint\" style=\"margin-top:4px;\">MP3, WAV or M4A. The shutter keeps its first 2 seconds, the\n              beep its first second, and silence at the start is cut so it plays right on time.</p>\n            <input type=\"file\" id=\"sndFile\" accept=\"audio/*,.mp3,.wav,.m4a,.aac,.ogg\" hidden>\n          </div>\n          <button type=\"button\" class=\"action-btn\" id=\"fxTestSound\" style=\"width:auto; margin:8px 0 0;\">Play a test\n            sound</button>\n          <p class=\"sub-label\" style=\"margin:16px 0 6px;\">Start without touching</p>\n          <select class=\"mini-select pillify\" id=\"fxHands\">\n            <option value=\"off\" selected>Off (tap)</option>\n            <option value=\"wave\">Wave</option>\n            <option value=\"smile\">Smile</option>\n          </select>\n          <p class=\"panel-hint\" id=\"fxHandsHint\" style=\"margin-top:6px;\"></p>\n          <div class=\"opt-row\" id=\"fxSensRow\" style=\"display:none;\">\n            <span class=\"lbl\">Sensitivity</span>\n            <select class=\"mini-select pillify\" id=\"fxSens\">\n              <option value=\"less\">Less</option>\n              <option value=\"normal\" selected>Normal</option>\n              <option value=\"more\">More</option>\n            </select>\n          </div>\n          <div class=\"fx-meter\" id=\"fxMeter\" hidden>\n            <div class=\"fx-track\"><b id=\"fxMeterBar\"></b><i id=\"fxMeterMark\"></i></div>\n            <p class=\"panel-hint\" id=\"fxMeterTxt\" style=\"margin:6px 0 0;\"></p>\n          </div>\n        </div>\n        <div class=\"panel-section\" id=\"orientationSection\" style=\"display:none;\">\n          <p class=\"panel-label\">Screen orientation</p>\n          <p class=\"panel-hint step-lead\">Lock the tablet to landscape or portrait for this event.</p>\n          <div class=\"chip-row\" id=\"orientChips\">\n            <button type=\"button\" class=\"chip active\" data-orient=\"landscape\">Landscape</button>\n            <button type=\"button\" class=\"chip\" data-orient=\"portrait\">Portrait</button>\n          </div>\n        </div>\n        <div class=\"panel-section\" id=\"brandSection\">\n          <p class=\"panel-label\">Welcome screen &amp; branding</p>\n          <p class=\"panel-hint step-lead\" id=\"brandLead\">Customize the screen guests see between sessions, and display\n            your logo.</p>\n          <label class=\"switch-row\" style=\"margin-top:0;\"><span>Show welcome screen between guests</span><input\n              type=\"checkbox\" id=\"welcomeToggle\" checked></label>\n          <div id=\"welcomeOpts\" style=\"margin-top:10px;\">\n            <p class=\"sub-label\" style=\"margin:0 0 6px;\">Welcome screen style</p>\n            <div class=\"chip-row\" id=\"attractModeChips\">\n              <button type=\"button\" class=\"chip active\" data-attract=\"card\">Branded card</button>\n              <button type=\"button\" class=\"chip\" data-attract=\"camera\">Live camera</button>\n              <button type=\"button\" class=\"chip\" data-attract=\"poster\">Custom poster</button>\n            </div>\n            <p class=\"panel-hint\" id=\"attractHint\" style=\"margin:6px 0 0;\">Auto-generates a branded welcome card with\n              your event title, date, 3-step guest instructions, and a sample photo print.</p>\n            <div id=\"welcomeCardCustomBlock\"\n              style=\"margin-top:12px; padding:12px; background:var(--panel-2); border-radius:12px; border:1px solid var(--line);\">\n              <label class=\"switch-row\" style=\"margin-top:0;\"><span>Personalize welcome card text &amp;\n                  font</span><input type=\"checkbox\" id=\"welcomeCustomToggle\"></label>\n              <p class=\"panel-hint\" style=\"margin:4px 0 0;\">Separate what guests see on the welcome card from your photo\n                print text.</p>\n              <div id=\"welcomeCustomFields\" style=\"display:none; margin-top:12px;\">\n                <div style=\"margin-bottom:10px;\">\n                  <p class=\"sub-label\" style=\"margin:0 0 4px;\">Greeting line</p>\n                  <input type=\"text\" class=\"label-input\" id=\"welcomeGreetingInput\" placeholder=\"Welcome to\"\n                    maxlength=\"40\" style=\"font-family:'Manrope',sans-serif; font-size:14px;\">\n                  <p class=\"panel-hint\" style=\"margin:2px 0 0;\">e.g. &ldquo;Welcome to&rdquo;, &ldquo;Welcome to the\n                    wedding of&rdquo;, or leave empty.</p>\n                </div>\n                <div style=\"margin-bottom:10px;\">\n                  <p class=\"sub-label\" style=\"margin:0 0 4px;\">Headline / Event name</p>\n                  <input type=\"text\" class=\"label-input\" id=\"welcomeTitleInput\" placeholder=\"Sofia's 7th Birthday\"\n                    maxlength=\"60\" style=\"font-family:'Manrope',sans-serif; font-size:14px;\">\n                  <p class=\"panel-hint\" style=\"margin:2px 0 0;\">Custom title on the welcome screen (not linked to Text\n                    02).</p>\n                </div>\n                <div style=\"margin-bottom:10px;\">\n                  <p class=\"sub-label\" style=\"margin:0 0 4px;\">Welcome headline font</p>\n                  <div class=\"custom-dd\" id=\"welcomeFontDropdown\">\n                    <button type=\"button\" class=\"custom-dd-btn label-input\" id=\"welcomeFontDropdownBtn\"\n                      style=\"font-size:14px; padding:8px 12px;\"></button>\n                    <div class=\"custom-dd-list\" id=\"welcomeFontDropdownList\"></div>\n                  </div>\n                </div>\n                <div style=\"margin-bottom:10px;\">\n                  <p class=\"sub-label\" style=\"margin:0 0 4px;\">Subtitle / Date line</p>\n                  <input type=\"text\" class=\"label-input\" id=\"welcomeSubInput\"\n                    placeholder=\"Leave empty to use date from Step 2\" maxlength=\"60\"\n                    style=\"font-family:'Manrope',sans-serif; font-size:14px;\">\n                </div>\n                <div style=\"margin-top:12px; padding-top:10px; border-top:1px solid var(--line);\">\n                  <label class=\"switch-row\" style=\"margin-top:0;\"><span>Show 3-step guest instructions</span><input\n                      type=\"checkbox\" id=\"welcomeStepsToggle\" checked></label>\n                  <div id=\"welcomeStepsBlock\" style=\"margin-top:8px;\">\n                    <input type=\"text\" class=\"label-input\" id=\"welcomeStep1Input\" placeholder=\"1. Tap the screen\"\n                      maxlength=\"40\" style=\"font-family:'Manrope',sans-serif; font-size:13px; margin-bottom:6px;\">\n                    <input type=\"text\" class=\"label-input\" id=\"welcomeStep2Input\" placeholder=\"2. Strike a pose\"\n                      maxlength=\"40\" style=\"font-family:'Manrope',sans-serif; font-size:13px; margin-bottom:6px;\">\n                    <input type=\"text\" class=\"label-input\" id=\"welcomeStep3Input\"\n                      placeholder=\"3. Scan the QR for your photos\" maxlength=\"40\"\n                      style=\"font-family:'Manrope',sans-serif; font-size:13px;\">\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div id=\"attractPosterRow\" style=\"display:none; margin-top:10px;\">\n              <div style=\"display:flex; align-items:center; justify-content:space-between; margin-bottom:8px;\">\n                <p class=\"sub-label\" style=\"margin:0;\">Sponsor / Media slides</p>\n                <span id=\"playlistCountBadge\" class=\"chip\"\n                  style=\"font-size:11px; padding:2px 8px; display:none; background:var(--panel-2);\"></span>\n              </div>\n\n              <!-- Playlist slides grid / reel -->\n              <div id=\"attractPlaylistGrid\" style=\"display:none; flex-direction:column; gap:6px; margin-bottom:10px;\">\n              </div>\n\n              <div class=\"bg-row\">\n                <label class=\"upload-btn\" for=\"attractPosterInput\"\n                  style=\"display:inline-flex; align-items:center; gap:6px;\">\n                  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"\n                    style=\"width:16px;height:16px;\">\n                    <path d=\"M12 5v14M5 12h14\" />\n                  </svg>\n                  <span>Add slides (Image, Video, or GIF)</span>\n                </label>\n                <input type=\"file\" id=\"attractPosterInput\" accept=\"image/*,video/mp4,video/webm,video/*\" multiple>\n              </div>\n              <button class=\"remove-link\" id=\"attractPlaylistClearAll\" style=\"display:none; margin-top:6px;\">Clear all\n                slides</button>\n\n              <div class=\"stepper\" style=\"margin-top:10px;\"><span class=\"lbl\">Media fit</span><span class=\"ctl\"><select\n                    id=\"attractPosterFit\">\n                    <option value=\"cover\">Fill tablet screen (fits scale accordingly)</option>\n                    <option value=\"contain\">Show whole media (keeps shape with bars)</option>\n                    <option value=\"stretch\">Stretch to fill the screen</option>\n                  </select></span></div>\n\n              <div class=\"stepper\" id=\"attractSlideDurationRow\" style=\"margin-top:8px; display:none;\"><span\n                  class=\"lbl\">Image slide duration</span><span class=\"ctl\"><select id=\"attractSlideDuration\">\n                    <option value=\"4\">4 seconds</option>\n                    <option value=\"6\" selected>6 seconds</option>\n                    <option value=\"8\">8 seconds</option>\n                    <option value=\"10\">10 seconds</option>\n                    <option value=\"15\">15 seconds</option>\n                  </select></span></div>\n\n              <p class=\"panel-hint\" style=\"margin:4px 0 0;\">Upload multiple videos and graphics to create an automated\n                billboard sponsor loop between guests. Videos play in full; graphics advance based on your slide\n                duration.</p>\n            </div>\n            <div id=\"welcomeBtnBlock\" style=\"margin-top:12px;\">\n              <label class=\"switch-row\" style=\"margin-top:0;\"><span>Show \"Tap to start\" button</span><input\n                  type=\"checkbox\" id=\"welcomeBtnToggle\" checked></label>\n              <p class=\"panel-hint\" id=\"welcomeBtnHint\" style=\"margin:4px 0 0;\">Turn off if your custom poster or\n                graphic already has a start button or instructions designed in.</p>\n              <div id=\"welcomeBtnOptions\" style=\"margin-top:8px;\">\n                <div id=\"welcomeMsgRow\" style=\"margin-top:8px;\">\n                  <p class=\"sub-label\" style=\"margin:0 0 4px;\">Button text</p>\n                  <input type=\"text\" class=\"label-input\" id=\"welcomeMsgInput\" placeholder=\"Tap to start\"\n                    style=\"font-family:'Manrope',sans-serif; font-size:14px;\">\n                  <p class=\"panel-hint\" style=\"margin:4px 0 0;\">Leave empty for the default \"Tap to start\" (or \"Wave\" /\n                    \"Smile\" when hands-free is on).</p>\n                </div>\n                <div id=\"welcomeBtnColorRow\" style=\"margin-top:10px;\">\n                  <p class=\"sub-label\" style=\"margin:0 0 6px;\">Button color</p>\n                  <div class=\"chip-row\" id=\"welcomeBtnColorChips\">\n                    <button type=\"button\" class=\"chip active\" data-color=\"#C93D27\"\n                      style=\"display:inline-flex; align-items:center; gap:6px;\"><i\n                        style=\"width:12px;height:12px;border-radius:50%;background:#C93D27;display:inline-block;\"></i>Red</button>\n                    <button type=\"button\" class=\"chip\" data-color=\"#C5A059\"\n                      style=\"display:inline-flex; align-items:center; gap:6px;\"><i\n                        style=\"width:12px;height:12px;border-radius:50%;background:#C5A059;display:inline-block;\"></i>Gold</button>\n                    <button type=\"button\" class=\"chip\" data-color=\"#1C1A1E\"\n                      style=\"display:inline-flex; align-items:center; gap:6px;\"><i\n                        style=\"width:12px;height:12px;border-radius:50%;background:#1C1A1E;border:1px solid rgba(255,255,255,.2);display:inline-block;\"></i>Black</button>\n                    <button type=\"button\" class=\"chip\" data-color=\"#FFFFFF\"\n                      style=\"display:inline-flex; align-items:center; gap:6px;\"><i\n                        style=\"width:12px;height:12px;border-radius:50%;background:#FFFFFF;border:1px solid rgba(0,0,0,.2);display:inline-block;\"></i>White</button>\n                    <button type=\"button\" class=\"chip\" data-color=\"#1B4D3E\"\n                      style=\"display:inline-flex; align-items:center; gap:6px;\"><i\n                        style=\"width:12px;height:12px;border-radius:50%;background:#1B4D3E;display:inline-block;\"></i>Emerald</button>\n                    <button type=\"button\" class=\"chip\" data-color=\"#D87080\"\n                      style=\"display:inline-flex; align-items:center; gap:6px;\"><i\n                        style=\"width:12px;height:12px;border-radius:50%;background:#D87080;display:inline-block;\"></i>Rose</button>\n                  </div>\n                </div>\n                <div id=\"welcomeBtnPosRow\" style=\"margin-top:10px;\">\n                  <p class=\"sub-label\" style=\"margin:0 0 6px;\">Button position</p>\n                  <div class=\"chip-row\" id=\"welcomeBtnPosChips\">\n                    <button type=\"button\" class=\"chip active\" data-pos=\"bottom\">Bottom</button>\n                    <button type=\"button\" class=\"chip\" data-pos=\"center\">Center</button>\n                    <button type=\"button\" class=\"chip\" data-pos=\"lower\">Lower third</button>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div id=\"saverBlock\" style=\"margin-top:14px;\">\n              <p class=\"sub-label\" style=\"margin:0 0 6px;\">Save power while waiting</p>\n              <div class=\"stepper\"><span class=\"lbl\">Dim the screen after</span><span class=\"ctl\"><select id=\"saverDimMin\">\n                    <option value=\"0\">Never</option><option value=\"1\">1 minute</option><option value=\"2\">2 minutes</option>\n                    <option value=\"3\">3 minutes</option><option value=\"5\">5 minutes</option><option value=\"10\">10 minutes</option>\n                    <option value=\"15\">15 minutes</option><option value=\"30\">30 minutes</option></select></span></div>\n              <div class=\"stepper\" style=\"margin-top:6px;\"><span class=\"lbl\">Turn the display off after</span><span class=\"ctl\"><select id=\"saverOffMin\">\n                    <option value=\"0\">Never</option><option value=\"2\">2 minutes</option><option value=\"3\">3 minutes</option>\n                    <option value=\"5\">5 minutes</option><option value=\"10\">10 minutes</option><option value=\"15\">15 minutes</option>\n                    <option value=\"30\">30 minutes</option><option value=\"60\">60 minutes</option></select></span></div>\n              <p class=\"panel-hint\" style=\"margin:4px 0 0;\">Counts from the last touch while the welcome screen is showing. The screen goes dim, then black; one\n                touch wakes it (that touch does not start a session). On the Android tablet the tablet's own brightness is lowered too.</p>\n            </div>\n            <div class=\"welcome-pv-card\" id=\"welcomePvCard\" style=\"margin-top:14px;\">\n              <div style=\"display:flex; align-items:center; justify-content:space-between; margin-bottom:6px;\">\n                <span class=\"sub-label\" style=\"margin:0;\">Preview</span>\n                <span class=\"panel-hint\" style=\"margin:0; font-size:11px;\">Screen between guests</span>\n              </div>\n              <div class=\"welcome-pv-frame\"\n                style=\"position:relative; width:100%; aspect-ratio:4/3; max-height:220px; border-radius:12px; overflow:hidden; border:1px solid var(--line); background:#1c1a1e; display:flex; align-items:center; justify-content:center;\">\n                <div class=\"welcome-pv-cam-hint\" id=\"welcomePvCamHint\"\n                  style=\"display:none; position:absolute; inset:0; align-items:center; justify-content:center; flex-direction:column; color:rgba(255,255,255,.5); font-size:12px; gap:4px; pointer-events:none;\">\n                  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"\n                    stroke-linejoin=\"round\" style=\"width:28px;height:28px;opacity:.7;\">\n                    <path d=\"m22 8-6 4 6 4V8Z\" />\n                    <rect width=\"14\" height=\"12\" x=\"2\" y=\"6\" rx=\"2\" />\n                  </svg>\n                  <span>Live camera mirror</span>\n                </div>\n                <img id=\"welcomePreview\" alt=\"Welcome screen preview\"\n                  style=\"position:relative; z-index:1; width:100%; height:100%; object-fit:contain; display:block;\">\n                <video id=\"welcomeVideoPreview\" autoplay loop muted playsinline\n                  style=\"display:none; position:relative; z-index:1; width:100%; height:100%; object-fit:contain;\"></video>\n              </div>\n            </div>\n          </div>\n\n          <div style=\"margin-top:16px; padding-top:14px; border-top:1px solid var(--line);\">\n            <p class=\"sub-label\" style=\"margin:0 0 8px;\">Logos on screen</p>\n            <div class=\"brand-row\" id=\"brandRowC\">\n              <input type=\"checkbox\" id=\"brandCOn\" aria-label=\"Show the top-left logo\">\n              <div class=\"brand-thumb\" id=\"brandCThumb\"></div>\n              <div class=\"brand-txt\"><b>Top-left logo</b><small>Top-left of Photo Session and the guest screen, in place\n                  of the photobooth4u logo.</small></div>\n              <label class=\"upload-btn\" for=\"brandCFile\" id=\"brandCBtn\">Change</label>\n              <input type=\"file\" id=\"brandCFile\" accept=\"image/*\">\n            </div>\n            <div class=\"brand-row\" id=\"brandRowW\">\n              <input type=\"checkbox\" id=\"brandWOn\" aria-label=\"Show the welcome logo\">\n              <div class=\"brand-thumb\" id=\"brandWThumb\"></div>\n              <div class=\"brand-txt\"><b>Welcome logo</b><small>On the welcome picture guests see between\n                  sessions.</small></div>\n              <label class=\"upload-btn\" for=\"brandWFile\" id=\"brandWBtn\">Change</label>\n              <input type=\"file\" id=\"brandWFile\" accept=\"image/*\">\n            </div>\n            <p class=\"brand-tip\" id=\"brandTip\">Tap a logo in the preview to move or resize it.</p>\n            <div class=\"bpv\" id=\"brandPv\" aria-label=\"Preview of what guests see\">\n              <div class=\"bpv-col\" id=\"bpvCol\">\n                <span class=\"bpv-brand\" id=\"bpvBrand\"><i><b></b><b></b><b></b><b></b></i>photobooth<em>4u</em></span>\n                <span><span class=\"bpv-msg\">Welcome!</span><span class=\"bpv-sub\">Tap the screen to start</span></span>\n                <span><span class=\"bpv-ev\" id=\"bpvEv\"></span><span class=\"bpv-dt\" id=\"bpvDt\"></span><span\n                    class=\"bpv-pwr\" id=\"bpvPwr\">Powered by <b>photobooth<em>4u</em></b></span></span>\n              </div>\n              <div class=\"bpv-frame\" id=\"bpvFrame\"><img id=\"bpvImg\" alt=\"\"></div>\n              <span class=\"bpv-chip\" id=\"bpvChip\">Ready</span>\n              <i class=\"bpv-guide\" id=\"bpvGuide\"></i>\n            </div>\n            <div class=\"brand-tools\">\n              <span class=\"bt-sel\" id=\"brandSelTxt\">Tap a logo to adjust it</span>\n              <button type=\"button\" class=\"action-btn\" id=\"brandCenter\">Center</button>\n              <button type=\"button\" class=\"action-btn\" id=\"brandReset\">Reset</button>\n            </div>\n          </div>\n          <div class=\"panel-section hidden\" id=\"guestSection\">\n            <p class=\"panel-label\">Guest screen</p>\n            <p class=\"guest-status\" id=\"guestStatus\"><i></i><span>Not open yet</span></p>\n            <button class=\"action-btn primary\" id=\"guestOpenBtn\"><svg class=\"ic\" aria-hidden=\"true\">\n                <use href=\"#i-monitor\" />\n              </svg> Open guest screen</button>\n            <p class=\"panel-hint\" id=\"guestHint\">Connect the second monitor (set to <b>Extend</b>), then open the guest\n              screen. Chrome or Edge can move it onto that monitor for you — allow “window management” if asked. Click\n              the guest screen once to make it full screen.</p>\n            <p class=\"panel-hint\">Guests start a session by tapping the guest screen, or pressing <b>Space</b> / a\n              presenter clicker. Setup, printing and the QR code stay on this screen.</p>\n          </div>\n          <div class=\"panel-section\" id=\"lockSection\" style=\"display:none;\">\n            <p class=\"panel-label\">Lock booth</p>\n            <p class=\"panel-hint\" style=\"margin:0 0 10px;\">For a self-service booth: guests only see tap to start →\n              layout → photos → filter → QR / print. Setup and settings are hidden until someone enters the PIN (tap the\n              small lock in the top-right corner).</p>\n            <p class=\"sub-label\" id=\"lockPinLabel\">Set a 4-digit PIN</p>\n            <div style=\"display:flex; gap:8px; flex-wrap:wrap; align-items:center;\">\n              <input type=\"password\" inputmode=\"numeric\" maxlength=\"4\" pattern=\"[0-9]*\" id=\"lockPin1\"\n                class=\"label-input\" placeholder=\"PIN\"\n                style=\"width:110px; letter-spacing:6px; font-family:'Manrope',sans-serif; font-size:16px;\">\n              <input type=\"password\" inputmode=\"numeric\" maxlength=\"4\" pattern=\"[0-9]*\" id=\"lockPin2\"\n                class=\"label-input\" placeholder=\"Again\"\n                style=\"width:110px; letter-spacing:6px; font-family:'Manrope',sans-serif; font-size:16px;\">\n              <button type=\"button\" class=\"action-btn\" id=\"lockPinSave\" style=\"width:auto; margin:0;\">Save PIN</button>\n            </div>\n            <p class=\"panel-hint\" id=\"lockPinNote\" style=\"margin:6px 0 4px;\"></p>\n            <p class=\"panel-hint\" id=\"lockTestNote\"\n              style=\"margin:0 0 10px; padding:6px 10px; border-radius:10px; background:#fff6db; border:1px solid #f0d98a; color:#6b5300; font-weight:700;\">\n              For testing: the PIN is <b>1234</b> until you set your own.</p>\n            <p class=\"panel-hint\" style=\"margin:0;\">Set or change the PIN here. When you are ready to leave the booth in\n              guest mode, use <b>Lock booth</b> in the Photo Session dock.</p>\n          </div>\n          <div class=\"step-nav\"><button type=\"button\" class=\"action-btn back-btn\" data-go=\"6\">← Back</button><button\n              class=\"action-btn primary\" id=\"goToSessionBtn\">Start photo session →</button></div>\n      </section>\n\n      <div class=\"panel-section\" id=\"previewSection\">\n        <p class=\"panel-label\">Preview <span class=\"preview-dock-close\" id=\"previewDockClose\" role=\"button\" tabindex=\"0\"\n            aria-label=\"Close preview\">✕</span></p>\n        <div class=\"setup-preview-wrap\">\n          <div class=\"setup-preview-frame\" id=\"previewFrameBox\">\n            <canvas id=\"setupPreviewCanvas\"></canvas>\n          </div>\n        </div>\n        <div class=\"decor-sel\" id=\"decorSelControls\" style=\"display:none;\">\n          <div class=\"stepper\" style=\"margin-top:0;\"><span class=\"lbl\">Size</span><input type=\"range\" id=\"decorSize\"\n              min=\"4\" max=\"90\" value=\"20\" style=\"flex:1; max-width:240px;\"></div>\n          <div class=\"stepper\"><span class=\"lbl\">Turn</span><input type=\"range\" id=\"decorRot\" min=\"-180\" max=\"180\"\n              value=\"0\" style=\"flex:1; max-width:240px;\"></div>\n          <div class=\"decor-btns\"><button type=\"button\" class=\"action-btn\" id=\"decorDup\">Copy</button><button\n              type=\"button\" class=\"action-btn\" id=\"decorFront\">To front</button><button type=\"button\" class=\"action-btn\"\n              id=\"decorDel\" style=\"color:#c0392b;\">Remove</button></div>\n        </div>\n        <div class=\"decor-sel\" id=\"sheetSelControls\" style=\"display:none;\">\n          <div class=\"stepper\" style=\"margin-top:0;\"><span class=\"lbl\">Size</span><input type=\"range\" id=\"sheetItemSize\"\n              min=\"8\" max=\"110\" value=\"50\" style=\"flex:1; max-width:240px;\"></div>\n          <div class=\"decor-btns\"><button type=\"button\" class=\"action-btn\" id=\"sheetItemSwap\">Swap frame</button><button\n              type=\"button\" class=\"action-btn\" id=\"sheetItemRotate\">Turn 90°</button><button type=\"button\"\n              class=\"action-btn\" id=\"sheetItemDup\">Copy</button><button type=\"button\" class=\"action-btn\"\n              id=\"sheetItemDel\" style=\"color:#c0392b;\">Remove</button></div>\n        </div>\n        <div class=\"sample-row\">\n          <button type=\"button\" class=\"action-btn\" id=\"sampleCamBtn\"><svg class=\"ic\" aria-hidden=\"true\">\n              <use href=\"#i-camera\" />\n            </svg> Preview with my camera</button>\n          <button type=\"button\" class=\"action-btn\" id=\"sampleResetBtn\" style=\"display:none;\">Use the sample</button>\n        </div>\n      </div>\n\n      <div class=\"setup-next-wrap\" hidden>\n        <p class=\"setup-save-note\" id=\"setupSaveNote\" aria-live=\"polite\"></p>\n      </div>\n      <button type=\"button\" class=\"preview-fab\" id=\"previewFab\" aria-controls=\"previewSection\"\n        style=\"display:none;\">Preview</button>\n\n    </div>\n\n    <div class=\"start-bar\" id=\"startBar\">\n      <div class=\"start-bar-in\">\n        <button type=\"button\" class=\"start-prev\" id=\"startPrevBtn\" aria-controls=\"previewSection\" aria-expanded=\"false\"\n          title=\"Show the preview\">\n          <canvas class=\"start-thumb\" id=\"startThumb\" width=\"40\" height=\"60\" aria-hidden=\"true\"></canvas>\n          <span class=\"sp-t\" id=\"startPrevLabel\"><b><svg class=\"ic\" aria-hidden=\"true\">\n                <use href=\"#i-eye\" />\n              </svg> Preview</b><small>Tap to see it</small></span>\n        </button>\n        <div class=\"start-info\">\n          <div class=\"start-row\"><span class=\"start-status\" id=\"startStatus\"></span><span id=\"setupChipSlot\"></span>\n            <button type=\"button\" class=\"prof-chip\" id=\"profChip\" hidden></button>\n          </div><span class=\"start-save\" id=\"startSave\"></span>\n        </div>\n        <div class=\"start-actions\">\n          <button type=\"button\" class=\"action-btn\" id=\"profilesBtn\" title=\"Save this setup under a name, or bring one back\">Profiles</button>\n          <div class=\"menu-wrap\">\n            <button type=\"button\" class=\"menu-btn\" id=\"setupMenuBtn\" aria-label=\"More\" aria-haspopup=\"true\">⋯</button>\n            <div class=\"menu\" id=\"setupMenu\" hidden>\n              <button type=\"button\" id=\"menuMyEvents\" hidden>My Events ↗ (links, payments, printing)</button>\n              <button type=\"button\" id=\"menuProfiles\">Saved profiles…</button>\n              <button type=\"button\" id=\"menuWhatsNew\">What’s new</button>\n              <button type=\"button\" id=\"menuFullscreen\">Full screen (hide tabs)</button>\n              <button type=\"button\" id=\"resetSetupBtn\" class=\"danger\">Reset setup</button>\n            </div>\n          </div>\n          <button type=\"button\" class=\"action-btn primary\" id=\"startBarBtn\"><span>Start <span class=\"hide-sm\">photo\n              </span>session →</span></button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 2: PHOTO SESSION -->\n  <div class=\"tab-panel hidden\" id=\"tabSession\">\n    <div class=\"app-shell\">\n\n      <!-- STAGE -->\n      <div class=\"stage-wrap\">\n        <div class=\"stage-surround\" id=\"stageSurround\" aria-hidden=\"true\"><video id=\"surroundVideo\" autoplay playsinline\n            muted></video></div>\n        <div class=\"stage-frame\" id=\"stageFrame\">\n          <div class=\"sprockets left\">\n            <i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i>\n          </div>\n          <div class=\"sprockets right\">\n            <i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i>\n          </div>\n\n          <video id=\"video\" autoplay playsinline muted></video>\n          <canvas id=\"previewCanvas\"></canvas>\n          <div class=\"box-guide\" id=\"boxGuide\" aria-hidden=\"true\"><span>Photo area</span></div>\n          <img class=\"shot-review\" id=\"shotReview\" alt=\"\">\n          <div class=\"welcome-overlay\" id=\"welcomeOverlay\" role=\"button\" tabindex=\"0\" aria-label=\"Tap to start\">\n            <img id=\"welcomeImg\" alt=\"Welcome — tap to start\">\n            <video id=\"welcomeVideo\" autoplay loop muted playsinline style=\"display:none;\"></video>\n            <div class=\"welcome-cta-overlay\" id=\"welcomeCtaOverlay\" style=\"display:none;\">\n              <button type=\"button\" class=\"welcome-cta-btn\" id=\"welcomeCtaBtn\">Tap to start</button>\n            </div>\n            <span class=\"welcome-pulse\" id=\"welcomePulse\" aria-hidden=\"true\"></span>\n          </div>\n          <div class=\"pick-overlay\" id=\"pickOverlay\" aria-label=\"Choose your layout\">\n            <div class=\"pick-head\">\n              <p class=\"pick-title\" id=\"pickTitle\">Choose your layout</p>\n              <p class=\"pick-sub\" id=\"pickSub\">Tap a design to start your session</p>\n            </div>\n            <div class=\"pick-grid\" id=\"pickGrid\"></div>\n          </div>\n          <div class=\"pick-overlay bt-details\" id=\"btDetailsOverlay\" aria-label=\"Your details\">\n            <div class=\"bt-form-wrap\">\n              <form class=\"bt-form\" id=\"btdForm\" autocomplete=\"off\" novalidate>\n                <p class=\"pick-title\" id=\"btdTitle\">Make your card</p>\n                <p class=\"pick-sub\" id=\"btdSub\"></p>\n                <label class=\"bt-f\"><span id=\"btdLbl1\">Your name</span><input type=\"text\" id=\"btdName\" maxlength=\"24\"\n                    autocapitalize=\"words\" enterkeyhint=\"next\"></label>\n                <label class=\"bt-f\" id=\"btdRow2\"><span id=\"btdLbl2\">Title</span><input type=\"text\" id=\"btdLine\"\n                    maxlength=\"32\" autocapitalize=\"words\" enterkeyhint=\"next\"></label>\n                <div id=\"btdQs\"></div>\n                <p class=\"bt-err\" id=\"btdErr\" aria-live=\"polite\"></p>\n                <div class=\"bt-acts\"><button type=\"button\" class=\"bt-cancel\" id=\"btdCancel\">Cancel</button><button\n                    type=\"submit\" class=\"bt-go\" id=\"btdGo\">Continue</button></div>\n              </form>\n              <div class=\"bt-prev-wrap\" id=\"btdPrevWrap\"><canvas class=\"bt-prev\" id=\"btdPrev\"></canvas>\n                <p class=\"bt-prev-cap\" id=\"btdPrevCap\"></p>\n              </div>\n            </div>\n          </div>\n          <div class=\"pick-overlay bt-details\" id=\"btPickOverlay\" aria-label=\"Choose your design\">\n            <div class=\"pick-head\">\n              <p class=\"pick-title\" id=\"btPickTitle\">Choose your card</p>\n              <p class=\"pick-sub\">Tap a design to start</p>\n            </div>\n            <div class=\"bt-gtabs\" id=\"btPickTabs\"></div>\n            <div class=\"pick-grid\" id=\"btPickGrid\"></div>\n            <button type=\"button\" class=\"bt-cancel bt-pick-cancel\" id=\"btPickCancel\">Cancel</button>\n          </div>\n\n          <div class=\"rec-dot\" id=\"recDot\"><i></i><span>LIVE</span></div>\n\n          <div class=\"countdown-overlay\" id=\"countdownOverlay\" aria-live=\"polite\">\n            <div class=\"cd-wrap\">\n              <svg class=\"cd-ring\" viewBox=\"0 0 100 100\" aria-hidden=\"true\">\n                <circle class=\"trk\" cx=\"50\" cy=\"50\" r=\"46\" />\n                <circle class=\"bar\" id=\"cdBar\" cx=\"50\" cy=\"50\" r=\"46\" pathLength=\"100\" stroke-dasharray=\"100\"\n                  stroke-dashoffset=\"0\" />\n              </svg>\n              <div class=\"countdown-num\" id=\"countdownNum\">3</div>\n            </div>\n            <div class=\"cd-shot\" id=\"cdShot\"></div>\n          </div>\n\n          <div class=\"ready-overlay\" id=\"readyOverlay\">\n            <div class=\"ready-head\">\n              <p class=\"ready-title\">Get ready!</p>\n              <p class=\"ready-sub\" id=\"readySub\">4 shots · 5,4,3,2,1,Pose</p>\n            </div>\n            <div class=\"sc-filters ready-filters\" id=\"readyFilters\" aria-label=\"Pick a filter\" hidden></div>\n            <div class=\"ready-actions\"><button type=\"button\" class=\"ready-cancel\" id=\"readyCancelBtn\">&#10005;\n                Cancel</button><button class=\"shutter-btn\" id=\"readyStartBtn\"><span class=\"ring\"></span>Start</button>\n            </div>\n            <p class=\"ready-cue\" id=\"readyCue\" aria-live=\"polite\"><i aria-hidden=\"true\"></i><span><b\n                  id=\"readyCueTxt\">Smile to start</b><small>or tap the screen</small></span></p>\n            <button type=\"button\" class=\"ready-cancel ready-hands-cancel\" id=\"readyHandsCancelBtn\">&#10005;\n              Cancel</button>\n          </div>\n          <div class=\"flash-overlay\" id=\"flashOverlay\"></div>\n\n          <!-- Full-screen sticker editor. Moved to <body> when it opens; the photo canvas is moved into gsoCanvasBox while it is open. -->\n          <div class=\"guest-sticker-overlay hidden\" id=\"guestStickerOverlay\">\n            <div class=\"gso-stage\" id=\"gsoStage\">\n              <div class=\"gso-canvas-box\" id=\"gsoCanvasBox\"></div>\n              <div class=\"gso-tools\" id=\"gsoTools\" style=\"display:none;\">\n                <button type=\"button\" id=\"gsoSizeDown\" title=\"Make smaller\"><span class=\"ico\">➖</span>Smaller</button>\n                <button type=\"button\" id=\"gsoSizeUp\" title=\"Make bigger\"><span class=\"ico\">➕</span>Bigger</button>\n                <button type=\"button\" id=\"gsoRotate\" title=\"Rotate\"><span class=\"ico\">🔄</span>Turn</button>\n                <button type=\"button\" id=\"gsoDup\" title=\"Duplicate\"><span class=\"ico\">📑</span>Copy</button>\n                <button type=\"button\" class=\"danger\" id=\"gsoDelete\" title=\"Delete sticker\"><span class=\"ico\">🗑️</span>Remove</button>\n              </div>\n              <div class=\"gso-zoom\" id=\"gsoZoom\">\n                <button type=\"button\" id=\"gsoZoomOut\" title=\"Zoom out\" aria-label=\"Zoom out\">−</button>\n                <button type=\"button\" class=\"fit\" id=\"gsoZoomFit\" title=\"Show the whole photo\">Fit</button>\n                <button type=\"button\" id=\"gsoZoomIn\" title=\"Zoom in\" aria-label=\"Zoom in\">+</button>\n              </div>\n            </div>\n            <div class=\"gso-panel\" id=\"gsoPanel\" data-size=\"m\">\n              <button type=\"button\" class=\"gso-grab\" id=\"gsoGrab\" aria-label=\"Show more or fewer stickers\"></button>\n              <div class=\"gso-top\">\n                <div class=\"gso-title-wrap\">\n                  <p class=\"gso-title\"><span>✨</span> Decorate your photo</p>\n                  <p class=\"gso-sub\">Tap a sticker to add it · drag to move · pinch to resize</p>\n                </div>\n                <div class=\"gso-timer-pill\"><span id=\"gsoTimerSec\">35</span>s left</div>\n              </div>\n              <div class=\"gso-timer-bar\"><div class=\"gso-timer-fill\" id=\"gsoTimerFill\"></div></div>\n              <div class=\"gso-packs\" id=\"gsoPacks\" hidden></div>\n              <div class=\"gso-tray-row\" id=\"gsoTray\"></div>\n              <div class=\"gso-actions-row\">\n                <button type=\"button\" class=\"gso-btn-skip\" id=\"gsoSkipBtn\">Skip stickers</button>\n                <button type=\"button\" class=\"gso-btn-skip\" id=\"gsoPreviewBtn\" title=\"See how your photo will look\">👁 Preview</button>\n                <button type=\"button\" class=\"gso-btn-done\" id=\"gsoDoneBtn\">✓ Done &amp; Print</button>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"camera-error\" id=\"cameraError\">\n            <p id=\"cameraErrorText\">We need access to your camera to start the booth.</p>\n            <div style=\"display:flex; gap:8px; flex-wrap:wrap; justify-content:center;\">\n              <button class=\"action-btn primary\" id=\"retryCameraBtn\" style=\"width:auto; padding:10px 20px;\">Try\n                Again</button>\n              <button class=\"action-btn\" id=\"chooseCameraBtn\" type=\"button\" style=\"width:auto; padding:10px 20px;\"><svg\n                  class=\"ic\" aria-hidden=\"true\">\n                  <use href=\"#i-camera\" />\n                </svg> Choose camera</button>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"film-track\" id=\"filmTrack\"></div>\n\n        <div class=\"session-controls\" id=\"sessionControls\">\n          <div class=\"ready-below\">\n            <p class=\"ready-summary\" id=\"readySummary\"></p>\n          </div>\n          <div class=\"sc-row\">\n            <button type=\"button\" class=\"sc-btn sc-danger\" id=\"cancelSessionBtn\" hidden>&#10005; Cancel</button>\n            <button type=\"button\" class=\"sc-btn sc-strong\" id=\"retakeBtn\" hidden>&#8634; Retake</button>\n            <button type=\"button\" class=\"sc-btn sc-done\" id=\"doneBtn\" hidden>Done</button>\n            <button type=\"button\" class=\"sc-btn\" id=\"mirrorQuickBtn\">Mirror: On</button>\n          </div>\n          <p class=\"sc-hint sc-hint-big\" id=\"reviewHint\" hidden><svg class=\"ic\" aria-hidden=\"true\">\n              <use href=\"#i-tap\" />\n            </svg> Not happy with one? <b>Tap that photo</b> on the right, then press Retake.</p>\n          <div class=\"sc-filters\" id=\"quickFilters\" aria-label=\"Filter\"></div>\n        </div>\n\n        <div class=\"start-btn-wrap\">\n          <button class=\"shutter-btn\" id=\"startBtn\"><span class=\"ring\"></span>Start</button>\n          <button type=\"button\" class=\"shutter-btn print-quick\" id=\"printQuickBtn\" hidden><svg class=\"ic\"\n              aria-hidden=\"true\">\n              <use href=\"#i-printer\" />\n            </svg> Print</button>\n        </div>\n      </div>\n\n      <!-- PANEL -->\n      <div class=\"panel\">\n\n        <div class=\"panel-section hidden\" id=\"uploadQueueSection\">\n          <p class=\"panel-label\">Waiting to upload</p>\n          <p class=\"panel-hint\" id=\"uploadQueueText\" style=\"margin:0; color:var(--ink); font-weight:700;\"></p>\n          <p class=\"panel-hint\" id=\"uploadQueueHint\"></p>\n          <div style=\"display:flex; gap:8px; flex-wrap:wrap; margin-top:8px;\">\n            <button type=\"button\" class=\"action-btn\" id=\"uploadRetryBtn\" style=\"width:auto; margin:0;\">Retry\n              now</button>\n            <button type=\"button\" class=\"action-btn\" id=\"uploadSaveBtn\" style=\"width:auto; margin:0;\">Save to this\n              computer</button>\n          </div>\n        </div>\n\n        <div class=\"panel-section hidden\" id=\"backupSection\">\n          <p class=\"panel-label\">Backup folder</p>\n          <p class=\"panel-hint\" id=\"backupSessionStatus\" style=\"margin:0;\"></p>\n          <button type=\"button\" class=\"action-btn\" id=\"backupSessionAllowBtn\"\n            style=\"display:none; width:auto; margin:8px 0 0;\">Allow saving</button>\n        </div>\n\n        <div class=\"panel-section hidden\" id=\"qrSection\">\n          <p class=\"panel-label\" id=\"qrSectionTitle\">Your photo is ready</p>\n          <div class=\"print-first-hold\" id=\"printFirstHold\" style=\"display:none;\">\n            <div class=\"pf-spinner\"></div>\n            <p style=\"font-weight:700; font-size:16px; margin:0 0 4px;\" id=\"printFirstStatus\">Printing your photo…</p>\n            <p class=\"panel-hint\" style=\"margin:0;\">Your download QR code will appear right here once printing finishes.</p>\n          </div>\n          <div class=\"qr-results\" id=\"qrResults\"></div>\n          <p class=\"panel-hint\" id=\"qrHint\">Scan with your phone camera to save it.</p>\n          <div class=\"actions\" id=\"shareSlot\" style=\"margin-top:10px;\"></div>\n          <div class=\"result-actions\" id=\"resultActions\">\n            <button type=\"button\" class=\"result-done\" id=\"resultDoneBtn\">Done</button>\n          </div>\n          <div class=\"result-timer\" id=\"resultTimer\" aria-hidden=\"true\"><i id=\"resultTimerBar\"></i></div>\n        </div>\n\n\n\n\n        <div class=\"panel-section hidden\" id=\"printSection\">\n          <p class=\"panel-label\">Print settings</p>\n          <div class=\"ps-group\">\n            <p class=\"ps-title\">This photo</p>\n            <p class=\"sub-label\" style=\"margin-bottom:6px;\">Paper size</p>\n            <div class=\"print-size-row\" id=\"printSizeRow\"></div>\n            <div class=\"custom-size-row hidden\" id=\"customSizeRow\">\n              <span>Own size</span>\n              <input type=\"number\" id=\"csW\" min=\"1\" step=\"0.1\" placeholder=\"W\" inputmode=\"decimal\"\n                aria-label=\"Paper width\">\n              <span>&times;</span>\n              <input type=\"number\" id=\"csH\" min=\"1\" step=\"0.1\" placeholder=\"H\" inputmode=\"decimal\"\n                aria-label=\"Paper height\">\n              <select id=\"csU\" aria-label=\"Unit\">\n                <option value=\"in\">in</option>\n                <option value=\"mm\">mm</option>\n              </select>\n              <button type=\"button\" id=\"csAdd\">Add</button>\n            </div>\n            <label class=\"switch-row hidden\" id=\"keychainRow\" style=\"margin:4px 0 10px;\">\n              <span>Keychain strips at real size (2.5×7.5 in)</span>\n              <input type=\"checkbox\" id=\"keychainToggle\">\n            </label>\n            <div id=\"thermalQualityBox\" class=\"hidden\">\n              <p class=\"sub-label\" style=\"margin:10px 0 6px;\">Print quality</p>\n              <div class=\"print-size-row\" id=\"thermalQualityRow\">\n                <button type=\"button\" class=\"print-size-btn\" data-tq=\"best\">Best</button>\n                <button type=\"button\" class=\"print-size-btn\" data-tq=\"normal\">Normal</button>\n                <button type=\"button\" class=\"print-size-btn\" data-tq=\"draft\">Draft</button>\n              </div>\n              <p class=\"panel-hint\" id=\"thermalQualityHint\" style=\"margin:2px 0 6px;\"></p>\n              <p class=\"sub-label\" style=\"margin:10px 0 4px;\">Too dark or too light?</p>\n              <p class=\"panel-hint\" style=\"margin:0 0 6px;\">Prints one strip at five Lightness levels. Pick the one that looks best and it is saved as this printer&rsquo;s Lightness (also in Lightness &amp; Colour Correction).</p>\n              <button type=\"button\" class=\"action-btn\" id=\"thermalDarkTestBtn\" style=\"width:auto;margin:0 0 6px;\">Print a darkness test strip</button>\n              <div class=\"print-size-row\" id=\"thermalDarkPick\" hidden>\n                <button type=\"button\" class=\"print-size-btn\" data-lite=\"0\">0</button>\n                <button type=\"button\" class=\"print-size-btn\" data-lite=\"15\">+15</button>\n                <button type=\"button\" class=\"print-size-btn\" data-lite=\"30\">+30</button>\n                <button type=\"button\" class=\"print-size-btn\" data-lite=\"45\">+45</button>\n                <button type=\"button\" class=\"print-size-btn\" data-lite=\"60\">+60</button>\n              </div>\n              <p class=\"sub-label\" style=\"margin:10px 0 4px;\">Lines across the picture?</p>\n              <p class=\"panel-hint\" style=\"margin:0 0 6px;\">For Bluetooth, USB and Wi-Fi receipt printers. Prints one strip in four ways. Pick the one with no lines and no strange text; it is saved for this printer only. Then print a real strip to check a long picture.</p>\n              <button type=\"button\" class=\"action-btn\" id=\"thermalSmoothTestBtn\" style=\"width:auto;margin:0 0 6px;\">Print a smooth-print test strip</button>\n              <div class=\"print-size-row\" id=\"thermalSmoothPick\" hidden>\n                <button type=\"button\" class=\"print-size-btn\" data-smooth=\"1\">1 · Careful</button>\n                <button type=\"button\" class=\"print-size-btn\" data-smooth=\"2\">2 · Standard</button>\n                <button type=\"button\" class=\"print-size-btn\" data-smooth=\"3\">3 · Smooth</button>\n                <button type=\"button\" class=\"print-size-btn\" data-smooth=\"4\">4 · Smooth + slow</button>\n              </div>\n              <p class=\"panel-hint\" id=\"thermalSmoothHint\" style=\"margin:2px 0 6px;\"></p>\n            </div>\n            <div id=\"printerQualityBox\" class=\"hidden\">\n              <p class=\"sub-label\" style=\"margin:10px 0 6px;\">Print quality (this printer)</p>\n              <div class=\"print-size-row\" id=\"printerQualityRow\">\n                <button type=\"button\" class=\"print-size-btn\" data-pq=\"best\">Best</button>\n                <button type=\"button\" class=\"print-size-btn\" data-pq=\"normal\">Normal</button>\n                <button type=\"button\" class=\"print-size-btn\" data-pq=\"draft\">Draft</button>\n              </div>\n              <p class=\"panel-hint\" id=\"printerQualityHint\" style=\"margin:2px 0 6px;\"></p>\n            </div>\n            <div id=\"photoFitBox\">\n              <p class=\"sub-label\" style=\"margin:10px 0 6px;\">Photo size on the paper</p>\n              <div class=\"print-size-row\" id=\"photoSizeRow\"></div>\n              <p class=\"panel-hint\" id=\"photoFitHint\" style=\"margin:2px 0 6px;\"></p>\n              <label class=\"switch-row\" id=\"borderlessRow\" style=\"margin:8px 0 2px;\"><span>Borderless, no\n                  trimming</span><input type=\"checkbox\" id=\"borderlessToggle\"></label>\n              <p class=\"panel-hint\" id=\"borderlessHint\" style=\"margin:2px 0 8px;\"></p>\n              <div id=\"edgeAdjBox\">\n                <p class=\"sub-label\" style=\"margin:10px 0 6px;\">Edges (this printer)</p>\n                <div id=\"edgeAdjGrid\" style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:6px 12px;max-width:380px;\"></div>\n                <p class=\"panel-hint\" id=\"edgeAdjHint\" style=\"margin:4px 0 6px;\"></p>\n                <button type=\"button\" class=\"action-btn\" id=\"edgeTestBtn\" style=\"width:auto;margin:0 0 6px;\">Print edge test</button>\n              </div>\n              <div style=\"display:flex;gap:10px;align-items:center;margin:6px 0 8px;\">\n                <img id=\"ppThumb\" alt=\"How the page will look\" hidden\n                  style=\"max-height:140px;border:1px solid #bbb;background:#fff;box-shadow:0 2px 8px rgba(0,0,0,.25);\">\n                <p class=\"panel-hint\" id=\"ppThumbNote\" style=\"margin:0;\">Finish a photo session to see a preview here.\n                </p>\n                <button type=\"button\" class=\"action-btn\" id=\"printPreviewBtn\"\n                  style=\"width:auto;margin:0;\">Preview</button>\n              </div>\n            </div>\n            <!-- Lightness & Colour Correction (Thermal & Photo printing) -->\n            <div class=\"color-adj-box\" id=\"colorAdjBox\"\n              style=\"margin-top:14px; padding:12px 14px; background:var(--panel-2, #faf6f0); border:1px solid var(--line); border-radius:12px;\">\n              <p class=\"sub-label\" style=\"margin:0 0 6px;\">Printer profile</p>\n              <div class=\"print-size-row\" id=\"pfChips\" role=\"group\" aria-label=\"Printer profile\"></div>\n              <p class=\"panel-hint\" id=\"colorAdjFor\" style=\"margin:6px 0 8px; font-size:11.5px;\"></p>\n              <div style=\"display:flex; align-items:center; gap:8px; border-top:1px solid var(--line); padding-top:8px;\">\n                <button type=\"button\" id=\"colorAdjToggle\" aria-expanded=\"false\" aria-controls=\"colorAdjBody\"\n                  style=\"flex:1; display:flex; align-items:center; gap:8px; background:none; border:none; padding:0; text-align:left; cursor:pointer; color:inherit; font:inherit;\">\n                  <span id=\"colorAdjChev\" aria-hidden=\"true\" style=\"display:inline-block; transition:transform .15s; font-size:14px;\">&#9656;</span>\n                  <span>\n                    <span class=\"panel-label\" style=\"display:block; margin:0; font-size:13px; font-weight:700;\">Lightness &amp; Colour Correction</span>\n                    <span id=\"colorAdjSub\" class=\"panel-hint\" style=\"display:block; margin:0; font-size:11.5px;\">No adjustments</span>\n                  </span>\n                </button>\n                <span id=\"colorAdjDot\" title=\"Adjusted\" aria-label=\"Adjusted\" hidden\n                  style=\"width:8px; height:8px; border-radius:50%; background:#d97706; display:inline-block;\"></span>\n                <button type=\"button\" class=\"link-btn\" id=\"btnResetColorAdj\"\n                  style=\"font-size:12px; color:var(--ink-dim); text-decoration:underline; cursor:pointer; background:none; border:none; padding:0;\">Reset</button>\n              </div>\n              <div id=\"colorAdjBody\" hidden style=\"margin-top:8px;\">\n              <p class=\"panel-hint\" style=\"margin:0 0 10px; font-size:11.5px; line-height:1.4;\">Changes the printed photo\n                and the print preview only. The guests' camera and on-screen photos stay as they are. If a print is too\n                dark, raise Lightness (+20 to +40).</p>\n\n              <div style=\"display:flex; flex-direction:column; gap:8px;\">\n                <div>\n                  <div\n                    style=\"display:flex; justify-content:space-between; font-size:12px; font-weight:600; margin-bottom:2px;\">\n                    <span>Lightness / Exposure</span>\n                    <b id=\"valAdjBrightness\">0</b>\n                  </div>\n                  <input type=\"range\" id=\"sliderAdjBrightness\" min=\"-100\" max=\"100\" value=\"0\"\n                    style=\"width:100%; cursor:pointer;\">\n                </div>\n\n                <div>\n                  <div\n                    style=\"display:flex; justify-content:space-between; font-size:12px; font-weight:600; margin-bottom:2px;\">\n                    <span style=\"color:#b91c1c;\">Red balance</span>\n                    <b id=\"valAdjRed\" style=\"color:#b91c1c;\">0</b>\n                  </div>\n                  <input type=\"range\" id=\"sliderAdjRed\" min=\"-100\" max=\"100\" value=\"0\"\n                    style=\"width:100%; cursor:pointer; accent-color:#b91c1c;\">\n                </div>\n\n                <div>\n                  <div\n                    style=\"display:flex; justify-content:space-between; font-size:12px; font-weight:600; margin-bottom:2px;\">\n                    <span style=\"color:#15803d;\">Green balance</span>\n                    <b id=\"valAdjGreen\" style=\"color:#15803d;\">0</b>\n                  </div>\n                  <input type=\"range\" id=\"sliderAdjGreen\" min=\"-100\" max=\"100\" value=\"0\"\n                    style=\"width:100%; cursor:pointer; accent-color:#15803d;\">\n                </div>\n\n                <div>\n                  <div\n                    style=\"display:flex; justify-content:space-between; font-size:12px; font-weight:600; margin-bottom:2px;\">\n                    <span style=\"color:#1d4ed8;\">Blue balance</span>\n                    <b id=\"valAdjBlue\" style=\"color:#1d4ed8;\">0</b>\n                  </div>\n                  <input type=\"range\" id=\"sliderAdjBlue\" min=\"-100\" max=\"100\" value=\"0\"\n                    style=\"width:100%; cursor:pointer; accent-color:#1d4ed8;\">\n                </div>\n              </div>\n              <button type=\"button\" class=\"link-btn\" id=\"btnCopyColorAdj\"\n                style=\"margin-top:10px; font-size:12px; color:var(--ink-dim); text-decoration:underline; cursor:pointer; background:none; border:none; padding:0;\" hidden></button>\n              </div>\n            </div>\n\n            <div class=\"copies-row\"><span>Copies</span>\n              <span class=\"stepper\"><button type=\"button\" id=\"copiesMinus\" aria-label=\"Fewer copies\">&minus;</button><b\n                  id=\"copiesVal\">1</b><button type=\"button\" id=\"copiesPlus\" aria-label=\"More copies\">+</button></span>\n            </div>\n            <p class=\"panel-hint print-limit-hint\" id=\"printLimitHint\" hidden></p>\n            <button class=\"action-btn primary ps-print\" id=\"printBtn\"><svg class=\"ic\" aria-hidden=\"true\">\n                <use href=\"#i-printer\" />\n              </svg> Print</button>\n            <p class=\"panel-hint\" id=\"printHint\"></p>\n          </div>\n          <div class=\"ps-group\">\n            <label class=\"switch-row hidden\" id=\"autoPrintRow\" style=\"margin-top:0;\">\n              <span>Send a print automatically after each session</span>\n              <input type=\"checkbox\" id=\"autoPrintToggle\">\n            </label>\n            <p class=\"panel-hint hidden\" id=\"autoPrintHint\"></p>\n          </div>\n          <div class=\"ps-group\">\n            <p class=\"ps-title\">Printer</p>\n            <p class=\"panel-hint\">Choose how prints reach the printer.</p>\n            <label class=\"sub-label web-only\" for=\"printRouteSelect\" style=\"display:block; margin:0 0 6px;\">Send prints\n              to</label>\n            <select id=\"printRouteSelect\" class=\"print-route web-only\">\n              <option value=\"here\">Print from this device</option>\n              <option value=\"station\">Send to a laptop print station</option>\n            </select>\n            <p class=\"panel-hint web-only\" id=\"stationHint\" style=\"margin:6px 0 8px;\"></p>\n            <div class=\"printer-pick\" id=\"printerPick\">\n              <label class=\"switch-row web-only\" style=\"margin:6px 0 2px;\">\n                <span>Print directly with Print Helper (skip dialog)</span>\n                <input type=\"checkbox\" id=\"helperToggle\">\n              </label>\n              <p class=\"panel-hint web-only\" style=\"margin:2px 0 8px;\">When connected, sends prints to the selected\n                printer without a dialog.</p>\n              <label class=\"sub-label\" for=\"printerSelect\" style=\"display:block; margin:8px 0 4px;\">Printer for <span\n                  id=\"printerPickSize\">this size</span></label>\n              <select id=\"printerSelect\" class=\"printer-input\"></select>\n              <button type=\"button\" class=\"action-btn\" id=\"bluetoothPrinterBtn\"\n                style=\"display:none;width:auto;margin:8px 8px 0 0;\">Set up Bluetooth printer</button>\n              <button type=\"button\" class=\"action-btn\" id=\"refreshPrintersBtn\"\n                style=\"display:none;width:auto;margin:8px 0 0;\">Refresh printer list</button>\n              <button type=\"button\" class=\"action-btn\" id=\"findNetPrintersBtn\"\n                style=\"display:none;width:auto;margin:8px 8px 0 0;\">Find Wi-Fi / network printers</button>\n              <div id=\"netPrinterBox\" style=\"display:none;margin-top:8px;\">\n                <p class=\"panel-hint\" id=\"netPrinterStatus\" style=\"margin:0 0 6px;\"></p>\n                <div id=\"netPrinterList\" style=\"display:flex;flex-direction:column;gap:6px;margin-bottom:6px;\"></div>\n                <div style=\"display:flex;gap:6px;flex-wrap:wrap;\">\n                  <input type=\"text\" id=\"netPrinterIp\" class=\"printer-input\" inputmode=\"decimal\"\n                    placeholder=\"Not listed? Type its IP, e.g. 192.168.1.50\" style=\"flex:1;min-width:180px;\">\n                  <button type=\"button\" class=\"action-btn\" id=\"netPrinterIpBtn\"\n                    style=\"width:auto;margin:0;\">Search</button>\n                </div>\n              </div>\n              <p class=\"panel-hint\" style=\"margin:6px 0 0;\">For desktop Bluetooth printers: pair the printer in system\n                settings, then refresh and select it here.</p>\n              <button type=\"button\" class=\"action-btn\" id=\"printerSetupBtn\"\n                style=\"display:none;width:auto;margin:8px 0 0;\">Configure printer</button>\n              <div id=\"printerOptionsBox\" style=\"display:none;margin-top:8px;\"></div>\n              <input type=\"text\" id=\"printerNameInput\" hidden>\n              <datalist id=\"printerList\"></datalist>\n              <p class=\"panel-hint\" id=\"printerHelperHint\" style=\"margin:4px 0 10px;\"></p>\n              <div id=\"secondPrinterBox\" hidden>\n                <label class=\"sub-label\" for=\"secondPrinterSelect\" style=\"display:block; margin:8px 0 4px;\">Second\n                  printer (optional)</label>\n                <select id=\"secondPrinterSelect\" class=\"printer-input\"></select>\n                <div class=\"print-size-row\" id=\"secondModeRow\" style=\"margin-top:6px;\" hidden>\n                  <button type=\"button\" class=\"print-size-btn\" data-sm=\"share\">Share the work</button>\n                  <button type=\"button\" class=\"print-size-btn\" data-sm=\"extra\">Also print another size</button>\n                </div>\n                <div id=\"secondSizeRow\" hidden style=\"margin-top:6px;\">\n                  <label class=\"sub-label\" for=\"secondSizeSelect\" style=\"display:block; margin:0 0 4px;\">Paper on the\n                    second printer</label>\n                  <select id=\"secondSizeSelect\" class=\"printer-input\"></select>\n                </div>\n                <p class=\"panel-hint\" id=\"secondHint\" style=\"margin:4px 0 10px;\"></p>\n              </div>\n            </div>\n            <div class=\"printer-pick\" id=\"btThermalRow\" style=\"display:none;margin-top:10px;\">\n              <label class=\"switch-row\" style=\"margin:6px 0 2px;\">\n                <span>Bluetooth thermal receipt printer</span>\n                <input type=\"checkbox\" id=\"btThermalToggle\">\n              </label>\n              <p class=\"panel-hint\" style=\"margin:2px 0 8px;\">Direct printing for 58 mm and 80 mm Bluetooth thermal\n                receipt printers without a print dialog.</p>\n              <div id=\"btThermalControls\" style=\"margin-top:8px;\">\n                <p class=\"panel-hint\" id=\"btThermalWarnHint\"\n                  style=\"display:none;color:#b91c1c;font-weight:600;margin:0 0 8px;\"></p>\n                <p class=\"panel-hint\" id=\"btThermalPaperHint\"\n                  style=\"display:none;color:#856404;background:#fff3cd;padding:6px 10px;border-radius:4px;margin:0 0 8px;\">\n                </p>\n                <div style=\"display:flex;gap:8px;flex-wrap:wrap;align-items:center;\">\n                  <button type=\"button\" class=\"action-btn\" id=\"btThermalConnectBtn\"\n                    style=\"width:auto;margin:0 0 8px 0;\">Connect Bluetooth Printer</button>\n                  <button type=\"button\" class=\"action-btn\" id=\"btThermalSettingsBtn\"\n                    style=\"display:none;width:auto;margin:0 0 8px 0;\">Pair in Android Bluetooth settings</button>\n                  <button type=\"button\" class=\"action-btn\" id=\"btThermalTestBtn\"\n                    style=\"display:none;width:auto;margin:0 0 8px 0;\">Test print</button>\n                  <button type=\"button\" class=\"action-btn\" id=\"btThermalDisconnectBtn\"\n                    style=\"display:none;width:auto;margin:0 0 8px 0;\">Disconnect</button>\n                </div>\n                <p class=\"panel-hint\" id=\"btThermalStatusHint\" style=\"margin:4px 0 6px;\"></p>\n                <label class=\"pstat-auto\" style=\"margin:2px 0 2px;\"><input type=\"checkbox\" id=\"btAutoReconnect\" checked> Reconnect\n                  automatically when the printer is switched back on</label>\n                <p class=\"panel-hint\" id=\"btAutoNote\" style=\"margin:0 0 8px;\"></p>\n                <details id=\"btThermalFixBox\" style=\"margin:4px 0 8px;\">\n                  <summary style=\"cursor:pointer;font-weight:700;font-size:13px;\">Prints gibberish, strange text or gaps?</summary>\n                  <p class=\"panel-hint\" style=\"margin:6px 0;\">Small mobile printers (58mm) can lose data if it arrives too fast. Run the checks in order and stop at the first one that goes wrong.</p>\n                  <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n                    <button type=\"button\" class=\"action-btn\" id=\"btCheckText\" style=\"width:auto;margin:0;\">1 · Text only</button>\n                    <button type=\"button\" class=\"action-btn\" id=\"btCheckSmall\" style=\"width:auto;margin:0;\">2 · Small picture</button>\n                    <button type=\"button\" class=\"action-btn\" id=\"btCheckFull\" style=\"width:auto;margin:0;\">3 · Full test strip</button>\n                  </div>\n                  <p class=\"panel-hint\" style=\"margin:6px 0 2px;\">Text fine but the picture garbles? Pick <b>Slow and safe</b> (58 mm paper only) and <b>Compatibility</b> below, then check again. If the picture already prints right, keep <b>Automatic</b> and <b>Standard</b>: the slower settings can leave faint lines across it. Nothing prints at all? Power the printer off and on (do not hold FEED), then try 1 again.</p>\n                  <div style=\"display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:6px;\">\n                    <label style=\"font-size:12px;\">Speed\n                      <select class=\"mini-select\" id=\"btProfSpeed\">\n                        <option value=\"auto\">Automatic</option>\n                        <option value=\"safe\">Slow and safe</option>\n                        <option value=\"fast\">Fast</option>\n                      </select>\n                    </label>\n                    <label style=\"font-size:12px;\">Picture mode\n                      <select class=\"mini-select\" id=\"btProfCmd\">\n                        <option value=\"raster\">Standard</option>\n                        <option value=\"star\">Compatibility</option>\n                      </select>\n                    </label>\n                  </div>\n                </details>\n                <p class=\"panel-hint\" style=\"margin:4px 0 6px; font-size:12px; color:var(--ink-dim);\">Thermal print too\n                  dark? Increase <b>Lightness / Exposure</b> (+20 to +40) in Print settings above to lighten the output.\n                </p>\n              </div>\n            </div>\n            <div class=\"printer-pick\" id=\"wifiPrinterRow\" style=\"display:none;margin-top:10px;\">\n              <label class=\"sub-label\" style=\"display:block; margin:6px 0 2px;\">Wi-Fi &amp; USB Printers</label>\n              <p class=\"panel-hint\" style=\"margin:2px 0 8px;\">Automatically detects connected USB and local network\n                printers for direct driverless printing.</p>\n              <button type=\"button\" class=\"action-btn\" id=\"wifiPrinterFindBtn\"\n                style=\"width:auto;margin:0 8px 8px 0;\">Find Wi-Fi &amp; USB printers</button>\n              <button type=\"button\" class=\"action-btn\" id=\"wifiPrinterTestBtn\"\n                style=\"display:none;width:auto;margin:0 8px 8px 0;\">Test print</button>\n              <button type=\"button\" class=\"action-btn\" id=\"wifiPrinterForgetBtn\"\n                style=\"display:none;width:auto;margin:0 8px 8px 0;\">Forget</button>\n              <button type=\"button\" class=\"action-btn\" id=\"wifiPrinterSettingsBtn\"\n                style=\"display:none;width:auto;margin:0 8px 8px 0;\">Open Android print settings</button>\n              <p class=\"panel-hint\" id=\"wifiPrinterStatus\" style=\"margin:4px 0 6px;\"></p>\n              <details id=\"wifiDiag\" style=\"display:none;margin:0 0 8px;\">\n                <summary>Colour diagnostics (advanced)</summary>\n                <p class=\"panel-hint\" style=\"margin:4px 0 6px;\">Prints diagnostic test patterns to calibrate color\n                  output.</p>\n                <label class=\"sub-label\" for=\"wifiDiagK\" style=\"display:block;margin:4px 0 2px;\">Colour-mode\n                  command</label>\n                <select id=\"wifiDiagK\" class=\"printer-input\">\n                  <option value=\"2\">2 (colour)</option>\n                  <option value=\"1\">1</option>\n                  <option value=\"-1\">none</option>\n                </select>\n                <p class=\"panel-hint\" style=\"margin:8px 0 2px;\">Colour calibration (rows from the yellow nozzles; saved\n                  on this tablet and used for colour prints)</p>\n                <div style=\"display:flex;flex-wrap:wrap;gap:6px;align-items:center;\">\n                  <label>Magenta <input type=\"number\" id=\"wifiCalM\" class=\"printer-input\" style=\"width:76px;\" min=\"0\"\n                      max=\"400\"></label>\n                  <label>Cyan <input type=\"number\" id=\"wifiCalC\" class=\"printer-input\" style=\"width:76px;\" min=\"0\"\n                      max=\"400\"></label>\n                  <label>Black <input type=\"number\" id=\"wifiCalK\" class=\"printer-input\" style=\"width:76px;\" min=\"0\"\n                      max=\"400\"></label>\n                  <label>Nozzles <select id=\"wifiCalN\" class=\"printer-input\">\n                      <option value=\"59\">59</option>\n                      <option value=\"60\">60</option>\n                    </select></label>\n                  <label>Lighten <select id=\"wifiCalG\" class=\"printer-input\">\n                      <option value=\"1\">none</option>\n                      <option value=\"1.3\">1.3</option>\n                      <option value=\"1.6\">1.6</option>\n                      <option value=\"2\">2.0</option>\n                      <option value=\"2.4\">2.4</option>\n                    </select></label>\n                  <button type=\"button\" class=\"action-btn\" id=\"wifiCalReset\" style=\"width:auto;margin:0;\">Reset</button>\n                </div>\n                <div style=\"display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;\">\n                  <button type=\"button\" class=\"action-btn\" data-diag=\"1\" style=\"width:auto;margin:0;\">1 Black</button>\n                  <button type=\"button\" class=\"action-btn\" data-diag=\"2\" style=\"width:auto;margin:0;\">2 Cyan</button>\n                  <button type=\"button\" class=\"action-btn\" data-diag=\"3\" style=\"width:auto;margin:0;\">3 Magenta</button>\n                  <button type=\"button\" class=\"action-btn\" data-diag=\"4\" style=\"width:auto;margin:0;\">4 Yellow</button>\n                  <button type=\"button\" class=\"action-btn\" data-diag=\"5\" style=\"width:auto;margin:0;\">5 C+M+Y</button>\n                  <button type=\"button\" class=\"action-btn\" data-diag=\"6\" style=\"width:auto;margin:0;\">6 Black, 180\n                    lines</button>\n                  <button type=\"button\" class=\"action-btn\" data-diag=\"7\" style=\"width:auto;margin:0;\">7 Colour bars,\n                    short</button>\n                  <button type=\"button\" class=\"action-btn\" data-diag=\"8\" style=\"width:auto;margin:0;\">8 Colour bars,\n                    full page</button>\n                </div>\n              </details>\n              <div id=\"wifiOptions\" style=\"display:none;margin:0 0 8px;\">\n                <label class=\"sub-label\" style=\"display:block;margin:6px 0 2px;\" id=\"wifiOptColorLbl\">Colour</label>\n                <select id=\"wifiOptColor\" class=\"printer-input\"></select>\n                <label class=\"sub-label\" style=\"display:block;margin:6px 0 2px;\" id=\"wifiOptQualityLbl\">Quality</label>\n                <select id=\"wifiOptQuality\" class=\"printer-input\"></select>\n                <label class=\"sub-label\" style=\"display:block;margin:6px 0 2px;\" id=\"wifiOptMediaLbl\">Paper type</label>\n                <select id=\"wifiOptMedia\" class=\"printer-input\"></select>\n              </div>\n              <div id=\"wifiPrinterList\" style=\"display:flex;flex-direction:column;gap:6px;margin-bottom:8px;\"></div>\n              <div style=\"display:flex;gap:6px;flex-wrap:wrap;\">\n                <input type=\"text\" id=\"wifiPrinterIp\" class=\"printer-input\" inputmode=\"decimal\"\n                  placeholder=\"Printer not listed? Type its IP, e.g. 192.168.1.50\" style=\"flex:1;min-width:180px;\">\n                <button type=\"button\" class=\"action-btn\" id=\"wifiPrinterAddBtn\"\n                  style=\"width:auto;margin:0;\">Add</button>\n              </div>\n            </div>\n            <details class=\"ps-steps\" id=\"printStepsWrap\">\n              <summary>Printer setup checklist</summary>\n              <ol class=\"print-steps\" id=\"printSteps\"></ol>\n            </details>\n          </div>\n        </div>\n\n        <div class=\"panel-section\" id=\"actionsSection\">\n          <div class=\"actions\">\n            <button class=\"action-btn hidden\" id=\"shareBtn\">↗ Share</button>\n          </div>\n        </div>\n\n\n\n\n      </div>\n\n    </div>\n  </div>\n\n  <div class=\"ppv-ov\" id=\"ppvOverlay\" hidden role=\"dialog\" aria-label=\"Print preview\">\n    <div class=\"ppv-card\">\n      <h3>Check the print</h3>\n      <p class=\"ppv-sub\" id=\"ppvSub\"></p>\n      <div class=\"ppv-stage\">\n        <div class=\"ppv-page\" id=\"ppvPage\"><img id=\"ppvImg\" alt=\"How the print will look\"></div>\n      </div>\n      <div class=\"ppv-nav\" id=\"ppvNav\" hidden></div>\n      <p class=\"ppv-note\" id=\"ppvNote\"></p>\n      <label class=\"ppv-never\"><input type=\"checkbox\" id=\"ppvNever\"> Don't show this again</label>\n      <div class=\"ppv-row\"><button type=\"button\" class=\"desk-btn\" id=\"ppvCancel\">Cancel</button><button type=\"button\"\n          class=\"desk-btn primary\" id=\"ppvPrint\">Print</button></div>\n    </div>\n  </div>\n  <div class=\"print-modal\" id=\"printModal\" hidden>\n    <div class=\"pm-card\" role=\"dialog\" aria-label=\"Print settings\">\n      <button type=\"button\" class=\"pm-close\" id=\"printModalClose\" aria-label=\"Close\">&#10005;</button>\n      <div id=\"printModalBody\"></div>\n    </div>\n  </div>\n  <div class=\"print-modal\" id=\"camModal\" hidden>\n    <div class=\"pm-card\" role=\"dialog\" aria-label=\"Camera\">\n      <button type=\"button\" class=\"pm-close\" id=\"camModalClose\" aria-label=\"Close\">&#10005;</button>\n      <div id=\"camModalBody\"></div>\n    </div>\n  </div>\n  <!-- QR pop-up after a session: the finished photo first, then the result card (#qrSection is moved in here) -->\n  <div class=\"qrpop-ov\" id=\"qrPopOv\" hidden>\n    <canvas class=\"qrpop-photo\" id=\"qrPopPhoto\" aria-hidden=\"true\"></canvas>\n    <div class=\"qrpop-slot\" id=\"qrPopSlot\"></div>\n  </div>\n  <div class=\"copies-sheet\" id=\"copiesSheet\" hidden>\n    <div class=\"cs-card\" role=\"dialog\" aria-labelledby=\"copiesSheetTitle\">\n      <p class=\"cs-title\" id=\"copiesSheetTitle\">How many copies?</p>\n      <span class=\"stepper\"><button type=\"button\" data-d=\"-1\" aria-label=\"Fewer\">&minus;</button><b\n          id=\"copiesSheetVal\">1</b><button type=\"button\" data-d=\"1\" aria-label=\"More\">+</button></span>\n      <p class=\"cs-left\" id=\"copiesSheetLeft\"></p>\n      <div class=\"cs-btns\"><button type=\"button\" id=\"copiesSheetCancel\">Cancel</button><button type=\"button\" class=\"go\"\n          id=\"copiesSheetGo\">Print</button></div>\n    </div>\n  </div>\n  <div class=\"copies-sheet\" id=\"autoPrintPrompt\" hidden>\n    <div class=\"cs-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"autoPrintPromptTitle\">\n      <p class=\"cs-title\" id=\"autoPrintPromptTitle\">Print automatically?</p>\n      <p class=\"cs-left\">Send a print after each session. You can change this later in Setup.</p>\n      <div class=\"cs-btns\"><button type=\"button\" id=\"autoPrintPromptLater\">Not now</button><button type=\"button\"\n          class=\"go\" id=\"autoPrintPromptEnable\">Turn on</button></div>\n    </div>\n  </div>\n  <div class=\"copies-sheet\" id=\"askSheet\" hidden>\n    <form class=\"cs-card ask-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"askTitle\" id=\"askForm\">\n      <p class=\"cs-title\" id=\"askTitle\"></p>\n      <input type=\"text\" class=\"label-input\" id=\"askInput\" maxlength=\"60\" autocomplete=\"off\" spellcheck=\"false\"\n        aria-labelledby=\"askTitle\">\n      <p class=\"cs-left\" id=\"askHint\"></p>\n      <div class=\"cs-btns\"><button type=\"button\" id=\"askCancel\">Cancel</button><button type=\"submit\" class=\"go\"\n          id=\"askGo\">Save</button></div>\n    </form>\n  </div>\n  <div class=\"copies-sheet\" id=\"profilesSheet\" hidden>\n    <div class=\"cs-card prof-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"profTitle\">\n      <p class=\"cs-title\" id=\"profTitle\">Saved profiles</p>\n      <p class=\"cs-left\">Save your whole setup under a name (e.g. “Wedding – Santos”). Bring it back any time with one tap.</p>\n      <button type=\"button\" class=\"prof-new\" id=\"profSaveNew\">＋ Save current setup as a profile</button>\n      <button type=\"button\" class=\"prof-undo\" id=\"profUndo\" hidden></button>\n      <div class=\"prof-list\" id=\"profList\"></div>\n      <div class=\"prof-tools\">\n        <button type=\"button\" id=\"profExport\">Export file</button>\n        <button type=\"button\" id=\"profImport\">Import file</button>\n        <input type=\"file\" id=\"profImportFile\" accept=\".json,application/json\" hidden>\n      </div>\n      <p class=\"prof-note\">A file keeps your overlays and logos tied to your account, so importing works best on the same code.</p>\n      <label class=\"prof-ask\"><input type=\"checkbox\" id=\"profAsk\" checked> Ask me to save when I press Start</label>\n      <div class=\"cs-btns\"><button type=\"button\" id=\"profClose\">Close</button></div>\n    </div>\n  </div>\n  <div class=\"copies-sheet pb-choice\" id=\"pbChoice\" hidden>\n    <div class=\"cs-card\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"pbChoiceTitle\">\n      <p class=\"cs-title\" id=\"pbChoiceTitle\"></p>\n      <p class=\"cs-left\" id=\"pbChoiceBody\"></p>\n      <div class=\"pb-choice-btns\" id=\"pbChoiceBtns\"></div>\n    </div>\n  </div>\n  <div class=\"printing-note\" id=\"printingNote\" role=\"status\" aria-live=\"polite\" hidden></div>\n  <div class=\"pay-badge\" id=\"payBadge\" aria-hidden=\"true\"></div>\n  <div class=\"pay-sheet\" id=\"paySheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"payTitle\" hidden>\n    <div class=\"pay-card\">\n      <button type=\"button\" class=\"pay-back\" id=\"payBack\" aria-label=\"Other ways to pay\" hidden>←</button>\n      <button type=\"button\" class=\"pay-x\" id=\"payClose\" aria-label=\"Close\">✕</button>\n      <p class=\"pay-kicker\">Photo session</p>\n      <h2 class=\"pay-title\" id=\"payTitle\">₱100</h2>\n      <p class=\"pay-sub\" id=\"paySub\">1 photo session</p>\n      <div class=\"pay-view\" id=\"payChoose\">\n        <div id=\"payDualChooseBox\" style=\"display:none; margin-bottom:12px;\">\n          <p class=\"panel-hint\" style=\"margin:0 0 8px; font-weight:700; color:var(--ink);\">Choose your print:</p>\n          <div id=\"payOptionsGrid\" style=\"display:grid; grid-template-columns:repeat(auto-fit, minmax(130px, 1fr)); gap:8px;\"></div>\n        </div>\n        <button type=\"button\" class=\"pay-opt\" id=\"payOptQr\"><span class=\"ico\">QR</span><span><b>Pay with\n              QR</b><small>GCash · Maya · any bank app</small></span></button>\n        <button type=\"button\" class=\"pay-opt\" id=\"payOptVoucher\"><span class=\"ico\">#</span><span><b>I have a\n              voucher</b><small>Bought at the booth table</small></span></button>\n      </div>\n      <div class=\"pay-view\" id=\"payQr\" hidden>\n        <div class=\"pay-qr-box\"><img id=\"payQrImg\" alt=\"Payment QR code\">\n          <div class=\"pay-qr-wait\" id=\"payQrWait\">Making your QR…</div>\n        </div>\n        <p class=\"pay-steps\">Open <b>GCash</b>, <b>Maya</b> or your bank app → <b>Scan QR</b> → pay</p>\n        <div class=\"pay-timer\"><i id=\"payTimerBar\"></i></div>\n        <p class=\"pay-state\" id=\"payQrState\"><span class=\"dot\"></span>Waiting for payment</p>\n        <span class=\"pay-test\" id=\"payTestTag\" hidden>Test mode</span><br>\n        <button type=\"button\" class=\"pay-link\" id=\"paySim\" hidden>Simulate payment</button>\n      </div>\n      <div class=\"pay-view\" id=\"payVoucher\" hidden>\n        <div class=\"pay-code\" id=\"payCode\" aria-live=\"polite\"></div>\n        <p class=\"pay-err\" id=\"payErr\"></p>\n        <div class=\"pay-pad\" id=\"payPad\">\n          <button type=\"button\" data-k=\"1\">1</button><button type=\"button\" data-k=\"2\">2</button><button type=\"button\"\n            data-k=\"3\">3</button>\n          <button type=\"button\" data-k=\"4\">4</button><button type=\"button\" data-k=\"5\">5</button><button type=\"button\"\n            data-k=\"6\">6</button>\n          <button type=\"button\" data-k=\"7\">7</button><button type=\"button\" data-k=\"8\">8</button><button type=\"button\"\n            data-k=\"9\">9</button>\n          <button type=\"button\" class=\"fn\" data-k=\"c\">Clear</button><button type=\"button\" data-k=\"0\">0</button><button\n            type=\"button\" class=\"fn\" data-k=\"b\" aria-label=\"Delete\">⌫</button>\n        </div>\n      </div>\n      <div class=\"pay-view\" id=\"payDone\" hidden>\n        <div class=\"pay-check\">✓</div>\n        <p class=\"pay-done-t\" id=\"payDoneT\">Payment received</p>\n        <p class=\"pay-done-s\">Get ready for your photos!</p>\n      </div>\n      <div class=\"pay-view\" id=\"payProblem\" hidden>\n        <p class=\"pay-problem\" id=\"payProblemT\"></p>\n        <button type=\"button\" class=\"pay-btn\" id=\"payRetry\">Try again</button>\n      </div>\n    </div>\n  </div>\n  <div class=\"op-dock\" id=\"opDock\" hidden>\n    <span class=\"dock-chip-slot\" id=\"dockChipSlot\"></span>\n    <div class=\"dock-row\">\n      <button type=\"button\" class=\"dock-btn\" id=\"camFab\" hidden aria-label=\"Camera\"><svg viewBox=\"0 0 24 24\" fill=\"none\"\n          stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <path d=\"M4 8h3l2-3h6l2 3h3a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1z\" />\n          <circle cx=\"12\" cy=\"13\" r=\"3.5\" />\n        </svg><span>Camera</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"printFab\" hidden aria-label=\"Printer settings\"><svg viewBox=\"0 0 24 24\"\n          fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"\n          aria-hidden=\"true\">\n          <path d=\"M7 9V3h10v6\" />\n          <rect x=\"3\" y=\"9\" width=\"18\" height=\"8\" rx=\"2\" />\n          <path d=\"M7 14h10v7H7z\" />\n        </svg><span>Printer</span></button>\n      <button type=\"button\" class=\"dock-btn pstat-fab\" id=\"pstatFab\" hidden aria-label=\"Printer status\" aria-expanded=\"false\"\n        data-state=\"ready\"><i class=\"pstat-dot\" aria-hidden=\"true\"></i><span class=\"pstat-txt\">Printer ready</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"backupFab\" hidden aria-label=\"Backup folder\" aria-expanded=\"false\"\n        aria-controls=\"backupPop\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"\n          stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <path d=\"M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\" />\n        </svg><span>Backup folder</span><i class=\"bk-dot\" aria-hidden=\"true\"></i></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"galleryFab\" hidden aria-label=\"All photos gallery\"\n        aria-expanded=\"false\" aria-controls=\"galleryPop\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\"\n          stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" />\n          <rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" />\n          <rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" />\n          <path d=\"M14 14h3v3h-3zm0 6h3m3-6v3m0 3h.01\" />\n        </svg><span>All photos</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"extrasFab\" hidden aria-label=\"Extras\" aria-expanded=\"false\"\n        aria-controls=\"extrasPop\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"\n          stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <rect x=\"4\" y=\"4\" width=\"6\" height=\"6\" rx=\"1.5\" />\n          <rect x=\"14\" y=\"4\" width=\"6\" height=\"6\" rx=\"1.5\" />\n          <rect x=\"4\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\" />\n          <rect x=\"14\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\" />\n        </svg><span>Extras</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"wifiFab\" hidden aria-label=\"Booth Wi-Fi\" aria-expanded=\"false\"\n        aria-controls=\"wifiPop\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"\n          stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <path d=\"M2 9a15 15 0 0 1 20 0\" />\n          <path d=\"M5.5 12.5a10 10 0 0 1 13 0\" />\n          <path d=\"M9 16a5 5 0 0 1 6 0\" />\n          <path d=\"M12 19.5h.01\" />\n        </svg><span>Wi-Fi</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"lockFab\" hidden aria-label=\"Lock booth\"><svg viewBox=\"0 0 24 24\"\n          fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"\n          aria-hidden=\"true\">\n          <rect x=\"4\" y=\"10\" width=\"16\" height=\"11\" rx=\"2\" />\n          <path d=\"M8 10V7a4 4 0 0 1 8 0v3\" />\n        </svg><span>Lock booth</span></button>\n    </div>\n    <div class=\"extras-pop\" id=\"extrasPop\" hidden>\n      <button type=\"button\" class=\"dock-btn\" id=\"deskFab\" hidden aria-label=\"Photographer desk\"><svg viewBox=\"0 0 24 24\"\n          fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"\n          aria-hidden=\"true\">\n          <rect x=\"3\" y=\"5\" width=\"14\" height=\"14\" rx=\"2\" />\n          <path d=\"M7 3h12a2 2 0 0 1 2 2v12\" />\n          <circle cx=\"10\" cy=\"12\" r=\"2.5\" />\n        </svg><span>Photographer desk</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"spinFab\" hidden aria-label=\"360 desk\"><svg viewBox=\"0 0 24 24\"\n          fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"\n          aria-hidden=\"true\">\n          <path d=\"M21 12a9 9 0 1 1-3-6.7\" />\n          <path d=\"M21 4v5h-5\" />\n          <circle cx=\"12\" cy=\"12\" r=\"2.5\" />\n        </svg><span>360 desk</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"capFab\" hidden aria-label=\"Record 360\"><svg viewBox=\"0 0 24 24\"\n          fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"\n          aria-hidden=\"true\">\n          <circle cx=\"12\" cy=\"12\" r=\"9\" />\n          <circle cx=\"12\" cy=\"12\" r=\"3.5\" fill=\"currentColor\" />\n        </svg><span>Record 360</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"reqFab\" hidden aria-label=\"Print requests\"><svg viewBox=\"0 0 24 24\"\n          fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"\n          aria-hidden=\"true\">\n          <path d=\"M6 9V3h12v6\" />\n          <rect x=\"3\" y=\"9\" width=\"18\" height=\"9\" rx=\"2\" />\n          <path d=\"M7 14h10v7H7z\" />\n        </svg><span>Print requests</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"studioFab\" hidden aria-label=\"Arrange and print\"><svg viewBox=\"0 0 24 24\"\n          fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"\n          aria-hidden=\"true\">\n          <rect x=\"3\" y=\"3\" width=\"7\" height=\"18\" rx=\"1.5\" />\n          <rect x=\"14\" y=\"3\" width=\"7\" height=\"18\" rx=\"1.5\" />\n        </svg><span>Arrange &amp; Print</span></button>\n      <button type=\"button\" class=\"dock-btn\" id=\"vgFab\" hidden aria-label=\"Video guestbook\"><svg viewBox=\"0 0 24 24\"\n          fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"\n          aria-hidden=\"true\">\n          <rect x=\"3\" y=\"6\" width=\"13\" height=\"12\" rx=\"2\" />\n          <path d=\"m16 10 5-3v10l-5-3z\" />\n        </svg><span>Video guestbook</span></button>\n    </div>\n    <div class=\"dock-pwr\" id=\"dockPwr\" hidden>Powered by <span class=\"pm\"\n        aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span><b>photobooth<em>4u</em></b></div>\n  </div>\n  <div class=\"backup-pop pstat-pop\" id=\"pstatPop\" role=\"dialog\" aria-label=\"Printers\" hidden>\n    <button type=\"button\" class=\"pstat-close\" id=\"pstatPopClose\" aria-label=\"Close\">&#215;</button>\n    <p class=\"bp-title\">Printers</p>\n    <div class=\"pstat-list\" id=\"pstatList\"></div>\n    <label class=\"pstat-auto\"><input type=\"checkbox\" id=\"pstatAuto\" checked> Reconnect automatically when a printer is switched back on</label>\n    <div class=\"bp-btns\"><button type=\"button\" class=\"action-btn primary\" id=\"pstatReconnect\">Reconnect now</button><button\n        type=\"button\" class=\"action-btn\" id=\"pstatTest\" hidden>Test print</button><button type=\"button\" class=\"action-btn\"\n        id=\"pstatSettings\">Print settings</button><button type=\"button\" class=\"action-btn\" id=\"pstatClear\" hidden>Clear\n        waiting</button></div>\n  </div>\n  <div class=\"backup-pop\" id=\"backupPop\" role=\"dialog\" aria-label=\"Backup folder\" hidden>\n    <p class=\"bp-title\">Backup folder</p>\n    <p class=\"bp-text\" id=\"backupPopText\"></p>\n    <div class=\"bp-btns\"><button type=\"button\" class=\"action-btn primary\" id=\"backupPopAllow\">Allow\n        saving</button><button type=\"button\" class=\"action-btn\" id=\"backupPopChange\">Change folder</button></div>\n  </div>\n  <div class=\"gallery-pop\" id=\"galleryPop\" role=\"dialog\" aria-label=\"All photos gallery\" hidden>\n    <button type=\"button\" class=\"gallery-close\" id=\"galleryPopClose\" aria-label=\"Close\">&#215;</button>\n    <p class=\"bp-title\">All photos</p><img id=\"galleryPopQr\" alt=\"All photos gallery QR code\"><a class=\"gallery-link\"\n      id=\"galleryPopLink\" href=\"#\" target=\"_blank\" rel=\"noopener\">Open event gallery</a>\n    <div class=\"bp-btns\"><button type=\"button\" class=\"action-btn\" id=\"galleryPopCopy\">Copy link</button></div>\n  </div>\n  <div class=\"gallery-pop\" id=\"wifiPop\" role=\"dialog\" aria-label=\"Booth Wi-Fi\" hidden>\n    <button type=\"button\" class=\"gallery-close\" id=\"wifiPopClose\" aria-label=\"Close\">&#215;</button>\n    <p class=\"bp-title\">Booth Wi-Fi</p><img id=\"wifiPopQr\" alt=\"Wi-Fi QR code\">\n    <p class=\"gallery-link\" id=\"wifiPopName\" style=\"margin:0;font-weight:700;font-size:14px;color:var(--ink);\"></p>\n    <p class=\"gallery-link\" id=\"wifiPopPass\" style=\"margin:2px 0 10px;\"></p>\n    <p class=\"gallery-link\" style=\"margin:0;\">Scan to join, then scan your photo QR.</p>\n  </div>\n  <button type=\"button\" class=\"lock-icon\" id=\"lockIcon\" aria-label=\"Unlock\" title=\"Unlock\" hidden><svg class=\"ic\"\n      aria-hidden=\"true\">\n      <use href=\"#i-lock\" />\n    </svg></button>\n  <div class=\"pin-modal\" id=\"pinModal\" hidden>\n    <div class=\"pin-card\" role=\"dialog\" aria-label=\"Enter PIN\">\n      <p class=\"pin-title\">Enter PIN to unlock</p>\n      <div class=\"pin-dots\" id=\"pinDots\"><i></i><i></i><i></i><i></i></div>\n      <p class=\"pin-msg\" id=\"pinMsg\"></p>\n      <div class=\"pin-pad\" id=\"pinPad\">\n        <button type=\"button\" data-k=\"1\">1</button><button type=\"button\" data-k=\"2\">2</button><button type=\"button\"\n          data-k=\"3\">3</button>\n        <button type=\"button\" data-k=\"4\">4</button><button type=\"button\" data-k=\"5\">5</button><button type=\"button\"\n          data-k=\"6\">6</button>\n        <button type=\"button\" data-k=\"7\">7</button><button type=\"button\" data-k=\"8\">8</button><button type=\"button\"\n          data-k=\"9\">9</button>\n        <button type=\"button\" data-k=\"x\" class=\"pin-fn\">Cancel</button><button type=\"button\"\n          data-k=\"0\">0</button><button type=\"button\" data-k=\"b\" class=\"pin-fn\">&#9003;</button>\n      </div>\n    </div>\n  </div>\n  <div class=\"toast\" id=\"toast\"></div>\n  <div id=\"printArea\"></div>\n  <div class=\"spin-studio-ov\" id=\"spinOverlay\" hidden role=\"dialog\" aria-label=\"360 desk\">\n    <header class=\"spin-studio-head\">\n      <div class=\"spin-head-left\">\n        <button type=\"button\" class=\"spin-back-btn\" id=\"spinClose\" title=\"Return to booth\">\n          <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"vertical-align:-2px;margin-right:4px;\"><line x1=\"19\" y1=\"12\" x2=\"5\" y2=\"12\"></line><polyline points=\"12 19 5 12 12 5\"></polyline></svg>\n          Back to Booth\n        </button>\n        <div class=\"spin-head-title-wrap\">\n          <h2 class=\"spin-head-title\">🎥 360 Video Studio &amp; Desk</h2>\n          <span class=\"spin-head-sub\" id=\"spinHeadStatus\">Full-Page Live Preview &amp; Processing Studio</span>\n        </div>\n      </div>\n      <div class=\"spin-head-nav\" id=\"spinHeadTabs\">\n        <button type=\"button\" class=\"spin-tab-btn active\" data-tab=\"spinSecVideos\">🎬 Videos &amp; Queue</button>\n        <button type=\"button\" class=\"spin-tab-btn\" data-tab=\"spinSecPresets\">✨ Presets</button>\n        <button type=\"button\" class=\"spin-tab-btn\" data-tab=\"spinSecLook\">🎨 Look &amp; Frame</button>\n        <button type=\"button\" class=\"spin-tab-btn\" data-tab=\"spinSecText\">✍️ Text &amp; Branding</button>\n        <button type=\"button\" class=\"spin-tab-btn\" data-tab=\"spinSecAudio\">🎵 Audio &amp; FX</button>\n        <button type=\"button\" class=\"spin-tab-btn spin-preview-tab-btn\" data-tab=\"spinStudioPreview\">👁️ Live Preview</button>\n      </div>\n      <div class=\"spin-head-right\">\n        <button type=\"button\" class=\"desk-btn primary\" id=\"spinTopPick\">＋ Add Videos</button>\n        <button type=\"button\" class=\"desk-btn\" id=\"spinTopFolder\">📁 Folder</button>\n      </div>\n    </header>\n\n    <div class=\"spin-studio-body\">\n      <!-- LEFT COLUMN: CONTROLS & WORKSPACE -->\n      <div class=\"spin-studio-controls\" id=\"spinStudioControls\">\n        <!-- LOCK BANNER WHEN PROCESSING / LOCKED -->\n        <div id=\"spinEditLockBanner\" class=\"spin-lock-banner\" hidden>\n          <div style=\"display:flex;align-items:center;gap:10px;flex:1;\">\n            <span style=\"font-size:20px;\">🔒</span>\n            <div>\n              <b id=\"spinLockTitle\" style=\"font-size:13px;\">Editing Locked</b>\n              <div id=\"spinLockSub\" style=\"font-size:12px;opacity:0.9;\">Processing video changes in progress…</div>\n            </div>\n          </div>\n          <button type=\"button\" class=\"desk-btn primary\" id=\"spinUnlockEditBtn\" style=\"padding:4px 12px;font-size:12px;margin:0;\">✏️ Unlock / Edit</button>\n        </div>\n\n        <!-- SECTION 1: VIDEOS & INBOX -->\n        <div class=\"spin-panel-card\" id=\"spinSecVideos\">\n          <div class=\"spin-card-title\">\n            <span>🎬 360 Video Queue</span>\n            <span class=\"spin-pill\" id=\"spinQueueBadge\">0 videos</span>\n          </div>\n\n          <div class=\"desk-drop\" id=\"spinDrop\">Drop the 360 videos here, or <button type=\"button\" class=\"desk-btn\"\n              id=\"spinPick\">Choose videos</button> <button type=\"button\" class=\"desk-btn\" id=\"spinPickDir\">Choose\n              folder</button><input type=\"file\" id=\"spinFile\" accept=\"video/*\" multiple hidden><input type=\"file\"\n              id=\"spinDirFile\" webkitdirectory multiple hidden></div>\n\n          <div class=\"spin-send\" id=\"spinSend\" hidden>\n            <div class=\"spin-qr\" id=\"spinSendQr\"></div>\n            <div class=\"spin-sendtxt\"><b>📱 Send from the phone that recorded</b><br>Scan this with that phone on the booth\n              Wi-Fi, then pick the video. Videos saved into the folder below also appear here automatically.<br><span\n                id=\"spinDirTxt\" style=\"font-size:11.5px;opacity:0.85;\"></span> <button type=\"button\" class=\"desk-btn\" id=\"spinDirBtn\" style=\"padding:2px 8px;font-size:11px;\">Change\n                folder</button><br><b>Recording tablet?</b> The 360 capture screen on the Android app sends its clips here.\n              Type this address into it: <span class=\"spin-link\" id=\"spinSendLink\"></span> <button type=\"button\"\n                class=\"desk-btn\" id=\"spinLinkCopy\" style=\"padding:2px 8px;font-size:11px;\">Copy</button></div>\n          </div>\n\n          <div class=\"spin-send\" id=\"spinWeb\" hidden>\n            <div class=\"spin-qr\" id=\"spinWebQr\"></div>\n            <div class=\"spin-sendtxt\"><b>📱 Videos from a phone</b><br><span id=\"spinWebNote\">One moment…</span>\n              <div class=\"spin-link\" id=\"spinWebLink\"></div><button type=\"button\" class=\"desk-btn\" id=\"spinWebCopy\" style=\"padding:2px 8px;font-size:11px;margin-top:4px;\">Copy\n                link</button>\n            </div>\n          </div>\n\n          <div class=\"desk-hint\" id=\"spinNoEdit\" hidden>Editing (slow motion, frame, music) is not available in this copy of\n            the app, so videos are shared as they are.</div>\n          <div class=\"desk-hint\" id=\"spinHint\"></div>\n          <div class=\"desk-grid\" id=\"spinGrid\"></div>\n          <div class=\"desk-foot\"><button type=\"button\" class=\"desk-btn\" id=\"spinClear\">Clear list</button><span\n              class=\"sp\"></span></div>\n        </div>\n\n        <!-- SECTION 2: DESIGN PRESETS -->\n        <div class=\"spin-panel-card\" id=\"spinSecPresets\" style=\"background:#fffcf5;border-color:#ecd9b5;\">\n          <div class=\"spin-card-title\" style=\"margin-bottom:8px;\">\n            <span>✨ Design &amp; Layout Presets</span>\n            <span class=\"spin-pill\" style=\"background:#fae7c9;color:#855400;\">Multi-Preset</span>\n          </div>\n          <div class=\"spin-row\" style=\"gap:8px;align-items:center;\">\n            <label style=\"font-weight:700;font-size:12px;display:flex;align-items:center;gap:6px;\">Preset:\n              <select id=\"spinDesignPresetSelect\" style=\"min-width:210px;font-weight:600;\"></select>\n            </label>\n            <button type=\"button\" class=\"desk-btn\" id=\"spinSavePresetBtn\" style=\"padding:5px 12px;font-size:12px;background:#fff;font-weight:700;\">💾 Save As Preset</button>\n            <button type=\"button\" class=\"desk-btn\" id=\"spinDeletePresetBtn\" style=\"padding:5px 10px;font-size:12px;\" title=\"Delete current custom preset\">🗑️ Delete</button>\n          </div>\n        </div>\n\n        <!-- SECTION 2: LOOK, STYLE & FRAMES -->\n        <div class=\"spin-panel-card\" id=\"spinSecLook\">\n          <div class=\"spin-card-title\">\n            <span>🎨 Look, Speed &amp; Frames</span>\n            <span class=\"spin-pill active\">Live Sync</span>\n          </div>\n\n          <div class=\"spin-look\" id=\"spinLook\">\n            <div class=\"spin-row\">\n              <label>Style Preset <select id=\"spinPreset\">\n                  <option value=\"classic\">Classic slow-mo</option>\n                  <option value=\"ramp\">Speed ramp</option>\n                  <option value=\"boomerang\">Boomerang</option>\n                  <option value=\"plain\">Original speed + frame</option>\n                  <option value=\"super\">Super slow-mo (0.25×)</option>\n                  <option value=\"fastslow\">Fast, then slow (2×, 0.5×)</option>\n                  <option value=\"fsf\">Fast, slow, fast (2×, 0.5×, 2×)</option>\n                  <option value=\"roller\">Slow-mo roller (1×, 0.25×, 2×, 0.5× and back)</option>\n                  <option value=\"custom\">Custom</option>\n                </select></label>\n              <label>Motion Speed <select id=\"spinSpeed\">\n                  <option value=\"slow\">Slow motion (0.5×)</option>\n                  <option value=\"ramp\">Speed ramp</option>\n                  <option value=\"boomerang\">Boomerang</option>\n                  <option value=\"normal\">Normal</option>\n                  <option value=\"custom\">Speed sequence (from the style)</option>\n                </select></label>\n              <label class=\"chk\"\n                title=\"Tip: Record at 60 fps (or 120 fps for 0.25×) for instant real slow motion with no extra processing wait.\"><input\n                  type=\"checkbox\" id=\"spinSmooth\"> Smoother slow motion (30 fps clips; 60+ fps is smooth\n                automatically)</label>\n              <label class=\"chk\" id=\"spinGpuWrap\" hidden\n                title=\"Use hardware GPU video encoding when available (falls back to CPU automatically).\"><input\n                  type=\"checkbox\" id=\"spinGpu\"> GPU fast encode</label>\n              <label class=\"chk\" title=\"Smooth camera punch-in zoom during slow motion and speed ramps\"><input\n                  type=\"checkbox\" id=\"spinZoom\" checked> Dynamic zoom</label>\n              <label class=\"chk\" title=\"Optical white flash at speed change and beat drops\"><input\n                  type=\"checkbox\" id=\"spinFlash\" checked> Beat flash</label>\n              <label>Format <select id=\"spinOrient\">\n                  <option value=\"portrait\">Portrait (phones 9:16)</option>\n                  <option value=\"landscape\">Landscape (16:9)</option>\n                  <option value=\"square\">Square 1:1 (Instagram)</option>\n                </select></label>\n              <label>Quality <select id=\"spinQual\">\n                  <option value=\"1080\">1080p Full HD</option>\n                  <option value=\"720\">720p (faster)</option>\n                </select></label>\n              <label title=\"Cinematic color grading filter applied to the video\">Color Grade <select id=\"spinLut\">\n                  <option value=\"none\" selected>Natural (Original)</option>\n                  <option value=\"glam_bw\">Glamour B&amp;W (Kardashian style)</option>\n                  <option value=\"teal_orange\">Blockbuster Teal &amp; Orange</option>\n                  <option value=\"golden_hour\">Golden Hour Warm Glow</option>\n                  <option value=\"vibrant\">Vibrant Pop</option>\n                  <option value=\"vintage\">Vintage Film</option>\n                </select></label>\n              <label title=\"Seconds into video where the slow motion speed ramp and flash hits (0 or empty = automatic middle)\">Beat drop (s) <input type=\"number\" id=\"spinDropTime\" min=\"0\" max=\"30\" step=\"0.1\" placeholder=\"Auto\" style=\"width:58px;padding:3px 6px;font-size:12px;border-radius:6px;border:1.5px solid var(--line);\"></label>\n            </div>\n            <div class=\"spin-row\">\n              <label class=\"chk\"><input type=\"checkbox\" id=\"spinOverlayOn\" checked> Frame &amp; overlay</label>\n              <label>Designer frame <select id=\"spinFrameStyle\">\n                  <option value=\"floral_gold\" selected>Wedding Floral &amp; Gold</option>\n                  <option value=\"gilded_art_deco\">Gilded Art Deco / Gala</option>\n                  <option value=\"neon_cyberpunk\">Neon Club / Cyberpunk</option>\n                  <option value=\"classic_box\">Classic Frame &amp; Label Band</option>\n                  <option value=\"custom\">Custom Uploaded Frame PNG</option>\n                  <option value=\"none\">None (Transparent / Logo only)</option>\n                </select></label>\n              <div id=\"spinClassicControls\" style=\"display:none;align-items:center;gap:8px;flex-wrap:wrap;background:#fff;padding:4px 8px;border-radius:8px;border:1px solid var(--line);\">\n                <label>Border <input type=\"color\" id=\"spinClassicBorderColor\" value=\"#D4AF37\" style=\"width:24px;height:22px;padding:0;border:none;cursor:pointer;vertical-align:middle;\"></label>\n                <label class=\"chk\"><input type=\"checkbox\" id=\"spinClassicBandOn\" checked> Bottom Band</label>\n                <label id=\"spinClassicBandColorWrap\">Band Color <input type=\"color\" id=\"spinClassicBandColor\" value=\"#1C1A1E\" style=\"width:24px;height:22px;padding:0;border:none;cursor:pointer;vertical-align:middle;\"></label>\n                <label id=\"spinClassicBandAlphaWrap\">Opacity <input type=\"range\" id=\"spinClassicBandAlpha\" min=\"0\" max=\"100\" value=\"85\" style=\"width:55px\"></label>\n              </div>\n              <label class=\"desk-btn\" style=\"padding:4px 10px;font-size:12px;cursor:pointer;margin:0;\">\n                Upload Custom PNG\n                <input type=\"file\" id=\"spinModalCustomFile\" accept=\"image/png,image/webp\" style=\"display:none\">\n              </label>\n              <label>Animated effect <select id=\"spinFx\">\n                  <option value=\"none\">None (no effect)</option>\n                </select></label>\n              <span id=\"spinFxBadge\" class=\"spin-fx-pill\" hidden></span>\n            </div>\n\n            <!-- Effect Movement & Live Physics Customizer -->\n            <div id=\"spinFxCustomizer\" style=\"display:none;margin-top:6px;padding:8px 10px;background:#fff;border-radius:10px;border:1.5px solid var(--line);box-shadow:0 1px 4px rgba(0,0,0,.04);\">\n              <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;\">\n                <b style=\"font-size:12px;color:var(--ink);\">✨ Effect Motion &amp; Behavior</b>\n                <span class=\"spin-pill\" style=\"font-size:10px;\">Live Physics</span>\n              </div>\n              <div class=\"spin-row\" style=\"gap:8px 12px;flex-wrap:wrap;\">\n                <label style=\"font-size:12px;display:flex;align-items:center;gap:4px;\">\n                  Trajectory\n                  <select id=\"spinFxMovement\" style=\"font-size:12px;padding:3px 6px;border-radius:6px;border:1px solid var(--line);\">\n                    <option value=\"vortex\" selected>🌀 Vortex Orbit (360° Spin)</option>\n                    <option value=\"fall\">⬇️ Falling Cascade</option>\n                    <option value=\"rise\">⬆️ Rising Float</option>\n                    <option value=\"burst\">💥 Radial Burst</option>\n                    <option value=\"beat_pulse\">🎵 Beat Pulse</option>\n                    <option value=\"drift\">💨 Wind Drift</option>\n                  </select>\n                </label>\n                <label style=\"font-size:12px;display:flex;align-items:center;gap:4px;\">\n                  Location\n                  <select id=\"spinFxLocation\" style=\"font-size:12px;padding:3px 6px;border-radius:6px;border:1px solid var(--line);\">\n                    <option value=\"full\" selected>Full Screen</option>\n                    <option value=\"center\">Center Turntable</option>\n                    <option value=\"edges\">Perimeter / Edges</option>\n                    <option value=\"top\">Top Half</option>\n                    <option value=\"bottom\">Bottom Half</option>\n                  </select>\n                </label>\n                <label style=\"font-size:12px;display:flex;align-items:center;gap:4px;\">\n                  Speed <input type=\"range\" id=\"spinFxSpeed\" min=\"20\" max=\"300\" value=\"100\" style=\"width:65px\">\n                  <span id=\"spinFxSpeedVal\" style=\"font-size:11px;min-width:32px;\">1.0×</span>\n                </label>\n                <label style=\"font-size:12px;display:flex;align-items:center;gap:4px;\">\n                  Opacity <input type=\"range\" id=\"spinFxOpacity\" min=\"10\" max=\"100\" value=\"85\" style=\"width:60px\">\n                  <span id=\"spinFxOpacityVal\" style=\"font-size:11px;min-width:28px;\">85%</span>\n                </label>\n                <label style=\"font-size:12px;display:flex;align-items:center;gap:4px;\">\n                  Size <input type=\"range\" id=\"spinFxScale\" min=\"40\" max=\"250\" value=\"100\" style=\"width:60px\">\n                  <span id=\"spinFxScaleVal\" style=\"font-size:11px;min-width:28px;\">1.0×</span>\n                </label>\n                <label style=\"font-size:12px;display:flex;align-items:center;gap:4px;\">\n                  Wobble <input type=\"range\" id=\"spinFxWobble\" min=\"0\" max=\"100\" value=\"50\" style=\"width:55px\">\n                  <span id=\"spinFxWobbleVal\" style=\"font-size:11px;min-width:24px;\">50%</span>\n                </label>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- SECTION 3: TEXT & EVENT BRANDING -->\n        <div class=\"spin-panel-card\" id=\"spinSecText\">\n          <div class=\"spin-card-title\">\n            <span>✍️ Text &amp; Event Branding</span>\n            <span class=\"spin-pill\">WYSIWYG &amp; Drag-to-Position</span>\n          </div>\n\n          <div class=\"spin-look\" style=\"margin:0;\">\n            <div class=\"spin-row\" style=\"justify-content:space-between;\">\n              <label class=\"chk\"><input type=\"checkbox\" id=\"spinTextOn\" checked> Enable Text Overlay</label>\n              <span class=\"spin-dim\" style=\"font-size:11px;font-style:italic;\">💡 Drag text or corner handle ⇲ on the preview to position &amp; resize!</span>\n            </div>\n\n            <!-- LINE 1 CONTROLS -->\n            <div style=\"background:#fff;border:1.5px solid var(--line);border-radius:10px;padding:8px 10px;margin-top:4px;\">\n              <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;\">\n                <b style=\"font-size:12px;color:var(--ink);\">Line 1 · Heading / Names</b>\n                <span class=\"spin-dim\" id=\"spinText1PosLabel\" style=\"font-size:11px;\">Y: 18%</span>\n              </div>\n              <input type=\"text\" id=\"spinText1\" maxlength=\"60\" placeholder=\"e.g. Sarah &amp; Michael\" style=\"width:100%;box-sizing:border-box;font-size:13px;padding:6px 10px;border-radius:8px;border:1.5px solid var(--line);margin-bottom:6px;\">\n              <div class=\"spin-text-hint\" id=\"spinText1Hint\" hidden></div>\n              <div class=\"spin-row\" style=\"gap:6px 10px;\">\n                <label>Font <select id=\"spinText1Font\" style=\"max-width:140px;\">\n                    <option value=\"cursive\" selected>Alex Brush (Romantic)</option>\n                    <option value=\"dancing\">Dancing Script (Casual)</option>\n                    <option value=\"serif\">Cinzel (Roman Serif)</option>\n                    <option value=\"playfair\">Playfair Display (Serif)</option>\n                    <option value=\"sans\">Montserrat (Modern Clean)</option>\n                    <option value=\"impact\">Bebas Neue (Bold Display)</option>\n                    <option value=\"oswald\">Oswald (Condensed)</option>\n                    <option value=\"typewriter\">Courier (Typewriter)</option>\n                  </select></label>\n                <label>Color <input type=\"color\" id=\"spinText1Color\" value=\"#FFF2A8\" style=\"width:28px;height:24px;padding:0;border:none;cursor:pointer;vertical-align:middle;\"></label>\n                <label>Size <input type=\"range\" id=\"spinText1Size\" min=\"16\" max=\"120\" value=\"52\" style=\"width:70px\"> <span id=\"spinText1SizeVal\" style=\"font-size:11px;min-width:24px;font-weight:700;\">52</span></label>\n              </div>\n            </div>\n\n            <!-- LINE 2 CONTROLS -->\n            <div style=\"background:#fff;border:1.5px solid var(--line);border-radius:10px;padding:8px 10px;margin-top:6px;\">\n              <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;\">\n                <b style=\"font-size:12px;color:var(--ink);\">Line 2 · Subtitle / Date / Hashtag</b>\n                <span class=\"spin-dim\" id=\"spinText2PosLabel\" style=\"font-size:11px;\">Y: 26%</span>\n              </div>\n              <input type=\"text\" id=\"spinText2\" maxlength=\"80\" placeholder=\"e.g. October 24, 2026\" style=\"width:100%;box-sizing:border-box;font-size:13px;padding:6px 10px;border-radius:8px;border:1.5px solid var(--line);margin-bottom:6px;\">\n              <div class=\"spin-text-hint\" id=\"spinText2Hint\" hidden></div>\n              <div class=\"spin-row\" style=\"gap:6px 10px;\">\n                <label>Font <select id=\"spinText2Font\" style=\"max-width:140px;\">\n                    <option value=\"serif\" selected>Cinzel (Roman Serif)</option>\n                    <option value=\"playfair\">Playfair Display (Serif)</option>\n                    <option value=\"cursive\">Alex Brush (Romantic)</option>\n                    <option value=\"dancing\">Dancing Script (Casual)</option>\n                    <option value=\"sans\">Montserrat (Modern Clean)</option>\n                    <option value=\"impact\">Bebas Neue (Bold Display)</option>\n                    <option value=\"oswald\">Oswald (Condensed)</option>\n                    <option value=\"typewriter\">Courier (Typewriter)</option>\n                  </select></label>\n                <label>Color <input type=\"color\" id=\"spinText2Color\" value=\"#FFFFFF\" style=\"width:28px;height:24px;padding:0;border:none;cursor:pointer;vertical-align:middle;\"></label>\n                <label>Size <input type=\"range\" id=\"spinText2Size\" min=\"12\" max=\"90\" value=\"34\" style=\"width:70px\"> <span id=\"spinText2SizeVal\" style=\"font-size:11px;min-width:24px;font-weight:700;\">34</span></label>\n              </div>\n            </div>\n\n            <!-- POSITION & TIMING ROW -->\n            <div class=\"spin-row\" style=\"margin-top:6px;\">\n              <label>Position Preset <select id=\"spinTextPos\">\n                  <option value=\"top\">Top (15%)</option>\n                  <option value=\"upper\">Upper Third (28%)</option>\n                  <option value=\"middle\">Center (50%)</option>\n                  <option value=\"lower\">Lower Third (72%)</option>\n                  <option value=\"bottom\">Bottom (86%)</option>\n                  <option value=\"custom\">Custom (Drag on Canvas)</option>\n                </select></label>\n              <label id=\"spinModalYWrap\" style=\"display:inline-flex;align-items:center;gap:6px;\">\n                Y: <input type=\"range\" id=\"spinModalTextY\" min=\"5\" max=\"95\" value=\"18\" step=\"1\" style=\"width:70px\">\n                <span id=\"spinModalTextYVal\" style=\"min-width:24px;font-size:11px;font-weight:700;\">18%</span>\n              </label>\n              <label>Align <select id=\"spinModalTextAlign\">\n                  <option value=\"center\" selected>Center</option>\n                  <option value=\"left\">Left</option>\n                  <option value=\"right\">Right</option>\n                </select></label>\n              <label>Timing <select id=\"spinTextTiming\">\n                  <option value=\"always\" selected>Always on</option>\n                  <option value=\"fade\">Fade in / out</option>\n                </select></label>\n            </div>\n          </div>\n        </div>\n\n        <!-- SECTION 4: AUDIO & PROCESSING -->\n        <div class=\"spin-panel-card\" id=\"spinSecAudio\">\n          <div class=\"spin-card-title\">\n            <span>🎵 Audio, Music &amp; Automation</span>\n          </div>\n\n          <div class=\"spin-look\" style=\"margin:0;\">\n            <div class=\"spin-row\">\n              <label>Sound track <select id=\"spinAudio\">\n                  <option value=\"music\">Music</option>\n                  <option value=\"original\">Original video sound</option>\n                  <option value=\"none\">Mute (no sound)</option>\n                </select></label>\n              <button type=\"button\" class=\"desk-btn\" id=\"spinMusicBtn\">Choose music track</button>\n              <span id=\"spinMusicName\" class=\"spin-dim\" style=\"font-weight:600;\">no music chosen</span>\n              <label style=\"margin-left:auto;\">Volume <input type=\"range\" id=\"spinVol\" min=\"0\" max=\"100\" value=\"80\"></label>\n            </div>\n            <div class=\"spin-row\" style=\"margin-top:6px;gap:12px;flex-wrap:wrap;\">\n              <label class=\"chk\"><input type=\"checkbox\" id=\"spinAuto\"> Automatically process and edit incoming 360 videos</label>\n              <label class=\"chk\"><input type=\"checkbox\" id=\"spinAutoShare\"> and get the QR code ready automatically</label>\n              <label class=\"chk\"><input type=\"checkbox\" id=\"spinAutoPrint\"> and 🖨️ auto-print strip / keychain</label>\n              <label style=\"margin-left:auto;font-size:12px;display:flex;align-items:center;gap:6px;\">\n                Print mode\n                <select id=\"spinPrintMode\" style=\"padding:3px 8px;font-size:12px;border-radius:6px;\">\n                  <option value=\"sequence\">Multi-angle sequence (matches strip)</option>\n                  <option value=\"solo\">Solo (1 hero frame)</option>\n                </select>\n              </label>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- RIGHT COLUMN: STICKY LIVE PREVIEW PANEL -->\n      <div class=\"spin-studio-preview\" id=\"spinStudioPreview\">\n        <div class=\"spin-preview-card\">\n          <div class=\"spin-preview-head\">\n            <div style=\"display:flex;align-items:center;gap:8px;\">\n              <b style=\"font-size:15px;color:var(--ink);\">Live 360 Studio Preview</b>\n              <span class=\"spin-pill\" id=\"spinCurClipBadge\">Sample Demo</span>\n              <span class=\"spin-pill spin-state-pill\" id=\"spinStateBadge\" hidden></span>\n            </div>\n            <label style=\"display:flex;align-items:center;gap:5px;cursor:pointer;font-size:12px;margin:0;font-weight:600;\">\n              <input type=\"checkbox\" id=\"spinModalTogglePreview\" checked> Overlay Preview\n            </label>\n          </div>\n\n          <!-- Video & Canvas Stage -->\n          <div class=\"spin-stage-wrap\" id=\"spinStageWrap\">\n            <video id=\"spinVideo\" playsinline loop></video>\n            <canvas id=\"spinPreviewCanvas\"></canvas>\n          </div>\n\n          <!-- Interactive Timeline Scrub & Playback Controls -->\n          <div class=\"spin-timeline-bar\">\n            <button type=\"button\" class=\"desk-btn\" id=\"spinModalPlayBtn\" style=\"padding:5px 12px;font-size:12px;font-weight:700;\">▶ Play</button>\n            <button type=\"button\" class=\"desk-btn\" id=\"spinMuteBtn\" title=\"Mute / unmute the preview sound\" aria-label=\"Mute or unmute preview\" style=\"padding:5px 9px;font-size:13px;\">🔊</button>\n            <span class=\"spin-time-counter\" id=\"spinTimeCounter\">0:00 / 0:00</span>\n            <input type=\"range\" class=\"spin-time-seek\" id=\"spinTimeSeek\" min=\"0\" max=\"100\" value=\"0\" step=\"0.1\">\n          </div>\n\n          <!-- Playback Speed & Quick Trim Bar -->\n          <div class=\"spin-play-bar\" style=\"display:flex;align-items:center;justify-content:space-between;gap:6px;flex-wrap:wrap;padding:5px 8px;background:rgba(0,0,0,0.04);border-radius:8px;margin-bottom:8px;font-size:12px;\">\n            <div style=\"display:flex;align-items:center;gap:4px;\">\n              <span style=\"opacity:0.75;font-size:11px;\">Speed:</span>\n              <button type=\"button\" class=\"desk-btn spin-speed-btn\" data-rate=\"0.25\">0.25x</button>\n              <button type=\"button\" class=\"desk-btn spin-speed-btn\" data-rate=\"0.5\">0.5x</button>\n              <button type=\"button\" class=\"desk-btn spin-speed-btn active\" data-rate=\"1.0\">1x</button>\n              <button type=\"button\" class=\"desk-btn spin-speed-btn\" data-rate=\"2.0\">2x</button>\n            </div>\n            <div class=\"spin-trim\" id=\"spinTrim\" style=\"display:inline-flex;align-items:center;gap:4px;margin:0;\">\n              <span>Trim: <input type=\"number\" id=\"spinTrimA\" min=\"0\" step=\"0.1\" placeholder=\"0\" style=\"width:42px;font-size:11px;padding:2px 4px;border:1px solid #ccc;border-radius:4px;\"> s &ndash; <input type=\"number\" id=\"spinTrimB\" min=\"0\" step=\"0.1\" placeholder=\"end\" style=\"width:42px;font-size:11px;padding:2px 4px;border:1px solid #ccc;border-radius:4px;\"> s</span>\n            </div>\n          </div>\n\n          <!-- Progress bar -->\n          <div class=\"spin-prog\" id=\"spinProg\" hidden>\n            <div class=\"bar\"><i id=\"spinBar\"></i></div><span id=\"spinProgTxt\"></span>\n          </div>\n\n          <!-- Action buttons -->\n          <div class=\"spin-action-row\" style=\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px;\">\n            <button type=\"button\" class=\"desk-btn primary\" id=\"spinEditBtn\" style=\"flex:1;min-width:130px;padding:9px 14px;font-weight:800;font-size:13px;\"><span>🎬 Edit / Process</span></button>\n            <button type=\"button\" class=\"desk-btn\" id=\"spinShareBtn\" style=\"flex:1;min-width:110px;padding:9px 14px;font-weight:700;font-size:13px;background:var(--blue-deep,#1F3A52);color:#fff;\">📱 Share + QR</button>\n            <button type=\"button\" class=\"desk-btn\" id=\"spinPrintBtn\" style=\"flex:1;min-width:110px;padding:9px 14px;font-weight:700;font-size:13px;background:#2E5A44;color:#fff;\" title=\"Extract photo from 360 video and print strip / keychain\">🖨️ Spin &amp; Print</button>\n            <button type=\"button\" class=\"desk-btn\" id=\"spinViewBtn\" hidden style=\"padding:9px 12px;font-size:12px;\">View original</button>\n            <button type=\"button\" class=\"desk-btn\" id=\"spinRemove\" style=\"padding:9px 12px;font-size:12px;color:#c0392b;\">Remove</button>\n          </div>\n\n          <!-- QR Codes for Guest Sharing -->\n          <div class=\"qs-qr\" id=\"spinQrBox\"></div>\n          <p class=\"qs-note\" id=\"spinMsg\" style=\"margin:4px 0 0;font-size:12px;color:var(--ink-dim);\"></p>\n\n          <!-- Legacy modal compatibility stubs (hidden) -->\n          <div id=\"spinModal\" hidden style=\"display:none!important;\"></div>\n          <button type=\"button\" id=\"spinModalClose\" hidden style=\"display:none!important;\"></button>\n          <div id=\"spinModalEditBox\" hidden style=\"display:none!important;\"></div>\n          <select id=\"spinModalFrameStyle\" hidden style=\"display:none!important;\"></select>\n          <input type=\"text\" id=\"spinTrimText1\" hidden style=\"display:none!important;\">\n          <input type=\"text\" id=\"spinTrimText2\" hidden style=\"display:none!important;\">\n          <select id=\"spinModalTextPos\" hidden style=\"display:none!important;\"></select>\n          <select id=\"spinModalTextFont\" hidden style=\"display:none!important;\"></select>\n          <input type=\"color\" id=\"spinModalTextColor\" hidden style=\"display:none!important;\">\n          <select id=\"spinModalFx\" hidden style=\"display:none!important;\"></select>\n          <select id=\"spinTextFont\" hidden style=\"display:none!important;\"></select>\n          <input type=\"color\" id=\"spinTextColor\" hidden style=\"display:none!important;\">\n          <span id=\"spinLockStatusText\" hidden style=\"display:none!important;\"></span>\n          <div id=\"spinControlsCol\" hidden style=\"display:none!important;\"></div>\n          <div id=\"spinStudioWrap\" hidden style=\"display:none!important;\"></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 360 Output & Share QR Modal Prompt -->\n  <div class=\"spin-share-ov\" id=\"spinShareModal\" hidden role=\"dialog\" aria-label=\"360 Output and QR Code\">\n    <div class=\"spin-share-backdrop\" id=\"spinShareBackdrop\"></div>\n    <div class=\"spin-share-card\" id=\"spinShareCard\">\n      <div class=\"spin-share-head\">\n        <div class=\"spin-share-head-left\">\n          <div class=\"spin-share-badge\">READY TO SHARE</div>\n          <h3 class=\"spin-share-title\" id=\"spinShareTitle\">✨ Your 360 Video is Ready</h3>\n        </div>\n        <div class=\"spin-share-head-right\">\n          <button type=\"button\" class=\"spin-share-toggle-btn\" id=\"spinShareToggleQr\" title=\"Hide the QR codes and watch the video bigger\">\n            <span id=\"spinShareToggleQrIcon\">👁️</span> <span id=\"spinShareToggleQrText\">Full-screen video</span>\n          </button>\n          <button type=\"button\" class=\"spin-share-close-btn\" id=\"spinShareClose\" title=\"Close modal\">✕</button>\n        </div>\n      </div>\n\n      <div class=\"spin-share-body\" id=\"spinShareBody\">\n        <!-- Left: Step 1 (Join Booth Wi-Fi) -->\n        <div class=\"spin-share-col left\" id=\"spinShareColWifi\">\n          <div class=\"spin-qr-box\">\n            <div class=\"spin-qr-step-num\">1</div>\n            <b class=\"spin-qr-title\">Join Booth Wi-Fi</b>\n            <span class=\"spin-qr-subtitle\">Connect phone to download directly</span>\n            <div class=\"spin-qr-img-frame\">\n              <img id=\"spinShareWifiQrImg\" alt=\"Booth Wi-Fi QR\">\n            </div>\n            <div class=\"spin-qr-meta\" id=\"spinShareWifiMeta\">SSID: Photobooth4U</div>\n            <button type=\"button\" class=\"spin-pw-btn\" id=\"spinShareWifiReveal\" hidden>Show password</button>\n          </div>\n        </div>\n\n        <!-- Center: Video Output -->\n        <div class=\"spin-share-col center\" id=\"spinShareColVideo\">\n          <div class=\"spin-share-stage\">\n            <video id=\"spinShareVideo\" playsinline loop autoplay controls></video>\n          </div>\n        </div>\n\n        <!-- Right: Step 2 (Scan to Download / Gallery) -->\n        <div class=\"spin-share-col right\" id=\"spinShareColDownload\">\n          <div class=\"spin-qr-box\">\n            <div class=\"spin-qr-step-num\">2</div>\n            <b class=\"spin-qr-title\" id=\"spinShareDlTitle\">Scan to Save</b>\n            <span class=\"spin-qr-subtitle\" id=\"spinShareDlSub\">Watch &amp; save video to camera roll</span>\n            <div class=\"spin-qr-img-frame\">\n              <img id=\"spinShareDlQrImg\" alt=\"Guest Download QR\">\n            </div>\n            <div class=\"spin-qr-meta-url\" id=\"spinShareDlUrl\">photobooth4u.com</div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"spin-share-foot\">\n        <p class=\"spin-share-note\" id=\"spinShareNote\">Guests scan Step 1 to join the booth Wi-Fi, then Step 2 to save their 360 video.</p>\n        <div class=\"spin-share-actions\">\n          <button type=\"button\" class=\"desk-btn\" id=\"spinSharePrintBtn\" style=\"font-weight:700;background:#2E5A44;color:#fff;\" title=\"Print photo strip or keychain from this 360 clip\">🖨️ Spin &amp; Print</button>\n          <button type=\"button\" class=\"desk-btn\" id=\"spinShareCopyBtn\">📋 Copy Link</button>\n          <button type=\"button\" class=\"desk-btn primary\" id=\"spinShareDoneBtn\">Back to Studio</button>\n        </div>\n      </div>\n    </div>\n  </div>\n  <!-- Spin & Print preview: look at the strip / keychain here, in the 360 booth, before the print screen -->\n  <div class=\"spin-share-ov spin-pp-ov\" id=\"spinPrintPv\" hidden role=\"dialog\" aria-label=\"Spin and Print preview\">\n    <div class=\"spin-share-backdrop\" id=\"spinPpBackdrop\"></div>\n    <div class=\"spin-share-card\">\n      <div class=\"spin-share-head\">\n        <div class=\"spin-share-head-left\">\n          <div class=\"spin-share-badge\">PRINT PREVIEW</div>\n          <h3 class=\"spin-share-title\">🖨️ Spin &amp; Print preview</h3>\n        </div>\n        <div class=\"spin-share-head-right\">\n          <button type=\"button\" class=\"spin-share-close-btn\" id=\"spinPpClose\" title=\"Back to studio\">✕</button>\n        </div>\n      </div>\n      <div class=\"spin-pp-busy\" id=\"spinPpBusy\" role=\"status\" aria-live=\"polite\" hidden><i aria-hidden=\"true\"></i> Taking the frames again…</div>\n      <div class=\"spin-pp-body\">\n        <div class=\"spin-pp-left\">\n          <div class=\"spin-pp-page\"><img id=\"spinPpImg\" alt=\"How the print will look\"></div>\n          <div class=\"spin-pp-nav\" id=\"spinPpNav\" hidden>\n            <button type=\"button\" class=\"desk-btn\" data-go=\"-1\" aria-label=\"Previous page\">‹</button>\n            <span id=\"spinPpPageNote\"></span>\n            <button type=\"button\" class=\"desk-btn\" data-go=\"1\" aria-label=\"Next page\">›</button>\n          </div>\n        </div>\n        <div class=\"spin-pp-right\">\n          <b class=\"spin-pp-h\">Frames taken from the 360 video</b>\n          <div class=\"spin-pp-frames\" id=\"spinPpFrames\"></div>\n          <label class=\"spin-pp-mode\">Print mode\n            <select id=\"spinPpMode\">\n              <option value=\"sequence\">Multi-angle sequence (matches strip)</option>\n              <option value=\"solo\">Solo (1 hero frame)</option>\n            </select>\n          </label>\n          <label class=\"spin-pp-mode\" style=\"margin-top:12px;\">Paper size\n            <select id=\"spinPpPaper\" aria-label=\"Paper size for this print\"></select>\n          </label>\n          <label class=\"spin-pp-mode\" style=\"margin-top:12px;\">Re-pick moments\n            <span class=\"spin-pp-slide\"><span>earlier</span>\n              <input type=\"range\" id=\"spinPpOffset\" min=\"-40\" max=\"40\" step=\"2\" value=\"0\" aria-label=\"Move all frames earlier or later in the clip\">\n              <span>later</span> <b id=\"spinPpOffsetVal\">0%</b>\n              <button type=\"button\" class=\"desk-btn\" id=\"spinPpOffsetReset\" style=\"padding:3px 9px;font-size:11px;\">Reset</button></span>\n          </label>\n          <p class=\"spin-pp-sub\" id=\"spinPpSub\"></p>\n        </div>\n      </div>\n      <div class=\"spin-share-foot\">\n        <p class=\"spin-share-note\">Nothing is printed yet. Check the layout, then continue. You choose the number of copies on the next screen.</p>\n        <div class=\"spin-share-actions\">\n          <button type=\"button\" class=\"desk-btn\" id=\"spinPpBack\">Back to Studio</button>\n          <button type=\"button\" class=\"desk-btn primary\" id=\"spinPpPrint\" style=\"background:#2E5A44;color:#fff;\">Continue to print</button>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"desk-ov\" id=\"reqOverlay\" hidden role=\"dialog\" aria-label=\"Print requests\">\n    <div class=\"desk-card\">\n      <div class=\"desk-head\"><b>&#128424; Print requests</b><span class=\"sp\"></span><button type=\"button\"\n          class=\"desk-btn\" id=\"reqClose\">Close</button></div>\n      <div class=\"desk-hint\" id=\"reqHint\"></div>\n      <div class=\"desk-grid\" id=\"reqGrid\"></div>\n    </div>\n  </div>\n  <div class=\"desk-ov\" id=\"studioOverlay\" hidden role=\"dialog\" aria-label=\"Arrange and print\">\n    <div class=\"desk-card st-card\">\n      <div class=\"desk-head\"><b>&#9638; Arrange &amp; Print</b><span class=\"sp\"></span><button type=\"button\" class=\"desk-btn\" id=\"stClose\">Close</button></div>\n      <div class=\"st-body\">\n        <div class=\"st-col\">\n          <p class=\"st-h\">1 &middot; Pick strips</p>\n          <div class=\"st-row\" id=\"stTabs\"></div>\n          <div class=\"st-row\" id=\"stSrcBar\"></div>\n          <div class=\"st-grid\" id=\"stGrid\"></div>\n          <input type=\"file\" id=\"stFiles\" accept=\"image/png,image/jpeg,image/webp\" multiple hidden>\n        </div>\n        <div class=\"st-col\">\n          <p class=\"st-h\">2 &middot; Paper and arrangement</p>\n          <div class=\"st-row\">\n            <label>Paper <select id=\"stPaper\" aria-label=\"Paper size\"></select></label>\n            <label>Gap <input type=\"number\" id=\"stGap\" min=\"0\" max=\"30\" step=\"0.5\"> mm</label>\n            <label>Margin <input type=\"number\" id=\"stMargin\" min=\"0\" max=\"40\" step=\"0.5\"> mm</label>\n            <label class=\"st-chk\"><input type=\"checkbox\" id=\"stCut\" checked> Cut lines</label>\n          </div>\n          <div class=\"st-row\" id=\"stPrinterRow\" hidden>\n            <label>Printer for <span id=\"stPrinterFor\"></span> <select id=\"stPrinter\" aria-label=\"Printer\"></select></label>\n          </div>\n          <div class=\"st-chips\" id=\"stChips\"></div>\n          <p class=\"st-hint\" id=\"stChipsHint\">Tap strips on the left. Tap one again to take it off.</p>\n          <div class=\"st-row\"><button type=\"button\" class=\"desk-btn\" id=\"stClear\" hidden>Clear all</button></div>\n          <div class=\"st-edit\" id=\"stEdit\" hidden>\n            <div class=\"st-edit-h\"><b id=\"stEName\"></b><span class=\"st-q\" id=\"stEQ\"></span></div>\n            <div class=\"st-row\">\n              <button type=\"button\" class=\"desk-btn primary\" id=\"stCrop\">&#9986; Crop&hellip;</button>\n              <button type=\"button\" class=\"desk-btn\" id=\"stFit\">Show whole picture</button></div>\n            <div class=\"st-row\"><span class=\"st-l\">Size</span>\n              <button type=\"button\" class=\"desk-btn\" data-pw=\"2.5\" data-ph=\"7.5\">Keychain 2.5&times;7.5</button>\n              <button type=\"button\" class=\"desk-btn\" data-pw=\"2\" data-ph=\"6\">2&times;6</button>\n              <button type=\"button\" class=\"desk-btn\" data-pw=\"4\" data-ph=\"6\">4&times;6</button></div>\n            <div class=\"st-row\">\n              <label>Width <input type=\"number\" id=\"stW\" min=\"0.5\" max=\"40\" step=\"0.05\"> in</label>\n              <label>Height <input type=\"number\" id=\"stH\" min=\"0.5\" max=\"40\" step=\"0.05\"> in</label>\n              <label>Copies <input type=\"number\" id=\"stC\" min=\"1\" max=\"20\" value=\"1\"></label></div>\n            <div class=\"st-row\">\n              <button type=\"button\" class=\"desk-btn\" id=\"stSame\">Same size for all</button>\n              <button type=\"button\" class=\"desk-btn\" id=\"stDel\">Remove</button></div>\n          </div>\n          <div class=\"st-row\"><button type=\"button\" class=\"desk-btn\" id=\"stAuto\">Auto-arrange</button></div>\n          <p class=\"st-hint\">Drag a strip in the preview to move it on its sheet. <b>Crop</b> trims a strip to any shape; the size buttons then fit it to Keychain, 2&times;6 or 4&times;6.</p>\n          <div class=\"st-pages\" id=\"stPages\"></div>\n          <p class=\"st-info\" id=\"stInfo\"></p>\n          <div class=\"st-row\"><label>Print each sheet <input type=\"number\" id=\"stSheets\" min=\"1\" max=\"10\" value=\"1\"> time(s)</label>\n            <span class=\"sp\" style=\"flex:1\"></span><button type=\"button\" class=\"desk-btn primary\" id=\"stPrint\" disabled>Print</button></div>\n          <p class=\"st-info st-status\" id=\"stStatus\" role=\"status\" hidden></p>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"desk-ov st-crop-ov\" id=\"stCropOv\" hidden role=\"dialog\" aria-label=\"Crop picture\">\n    <div class=\"desk-card st-crop-card\">\n      <div class=\"desk-head\"><b>&#9986; Crop</b><span class=\"sp\"></span><button type=\"button\" class=\"desk-btn\" id=\"stCropCancel\">Cancel</button><button type=\"button\" class=\"desk-btn primary\" id=\"stCropOk\">Done</button></div>\n      <div class=\"st-row st-crop-pad\" id=\"stCropRatios\">\n        <span class=\"st-l\">Shape</span>\n        <button type=\"button\" class=\"desk-btn primary\" data-t=\"0\">Free</button>\n        <button type=\"button\" class=\"desk-btn\" data-t=\"0.3333333\">Strip / keychain 1:3</button>\n        <button type=\"button\" class=\"desk-btn\" data-t=\"0.6666667\">4&times;6 2:3</button>\n        <button type=\"button\" class=\"desk-btn\" data-t=\"1\">Square</button>\n        <button type=\"button\" class=\"desk-btn\" data-t=\"orig\">Original</button>\n      </div>\n      <div class=\"st-crop-stage\"><canvas id=\"stCropCv\"></canvas></div>\n      <p class=\"st-hint st-crop-pad\"><span id=\"stCropInfo\"></span> &middot; Drag the edges or corners to crop. Drag inside the box to move it.</p>\n    </div>\n  </div>\n  <div class=\"qs-ov vg-ov\" id=\"vgOverlay\" hidden role=\"dialog\" aria-label=\"Video guestbook\">\n    <video id=\"vgVideo\" autoplay muted playsinline></video>\n    <div class=\"qs-top\"><button type=\"button\" class=\"qs-btn\" id=\"vgClose\">Close</button><span class=\"qs-count\"\n        id=\"vgInfo\"></span><span></span></div>\n    <div class=\"cap-big\" id=\"vgBig\" hidden></div>\n    <div class=\"vg-panel\">\n      <p class=\"vg-title\" id=\"vgTitle\">Leave a video message</p>\n      <p class=\"vg-sub\" id=\"vgSub\"></p>\n      <div class=\"vg-qr\" id=\"vgQr\" hidden></div>\n      <div class=\"vg-row\"><button type=\"button\" class=\"cap-go\" id=\"vgMain\">Record a message</button><button\n          type=\"button\" class=\"cap-go alt\" id=\"vgSecond\" hidden>Retake</button></div>\n    </div>\n  </div>\n  <div class=\"qs-ov cap-ov\" id=\"capOverlay\" hidden role=\"dialog\" aria-label=\"360 capture\">\n    <video id=\"capVideo\" autoplay muted playsinline></video>\n    <div class=\"qs-top\"><button type=\"button\" class=\"qs-btn\" id=\"capClose\">Close</button><span class=\"qs-count\"\n        id=\"capInfo\"></span><button type=\"button\" class=\"qs-btn\" id=\"capFlip\">Flip camera</button></div>\n    <div class=\"cap-big\" id=\"capBig\" hidden></div>\n    <div class=\"cap-panel\" id=\"capPanel\">\n      <p class=\"cap-warn\" id=\"capWarn\" hidden></p>\n      <div class=\"cap-row\">\n        <label>Length <select id=\"capLen\">\n            <option value=\"6\">6 s</option>\n            <option value=\"8\" selected>8 s</option>\n            <option value=\"10\">10 s</option>\n            <option value=\"12\">12 s</option>\n            <option value=\"15\">15 s</option>\n          </select></label>\n        <label>Start <select id=\"capMode\">\n            <option value=\"button\">With the button</option>\n            <option value=\"motion\">When the arm moves</option>\n          </select></label>\n        <label id=\"capSensRow\" hidden>Sensitivity <select id=\"capSens\">\n            <option value=\"low\">Low</option>\n            <option value=\"mid\" selected>Medium</option>\n            <option value=\"high\">High</option>\n          </select></label>\n      </div>\n      <div class=\"cap-row\" id=\"capLaptopRow\" hidden>\n        <label>Laptop address <input type=\"text\" id=\"capLaptop\" placeholder=\"192.168.1.20:47777/send/...\"\n            autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\"></label>\n        <button type=\"button\" class=\"desk-btn\" id=\"capTest\">Test</button><span class=\"cap-msg\" id=\"capLaptopMsg\"></span>\n      </div>\n      <p class=\"cap-status\" id=\"capStatus\"></p>\n      <button type=\"button\" class=\"cap-go\" id=\"capGo\">Record</button>\n    </div>\n  </div>\n  <div class=\"desk-ov\" id=\"deskOverlay\" hidden role=\"dialog\" aria-label=\"Photographer desk\">\n    <div class=\"desk-card\">\n      <div class=\"desk-head\"><b>📷 Photographer desk</b><span class=\"sp\"></span><button type=\"button\" class=\"desk-btn\"\n          id=\"deskClose\">Close</button></div>\n      <div class=\"desk-phone\" id=\"deskPhone\" hidden>\n        <div class=\"qr\" id=\"deskPhoneQr\"></div>\n        <div><b>📱 Photos from a phone</b><br><span id=\"deskPhoneNote\">One moment…</span>\n          <div class=\"lnk\" id=\"deskPhoneLink\"></div><button type=\"button\" class=\"desk-btn\" id=\"deskPhoneCopy\">Copy\n            link</button>\n        </div>\n      </div>\n      <div class=\"desk-drop\" id=\"deskDrop\">Drop the photographer's photos here, or <button type=\"button\"\n          class=\"desk-btn\" id=\"deskPick\">Choose photos</button><input type=\"file\" id=\"deskFile\"\n          accept=\"image/jpeg,image/png,image/webp\" multiple hidden></div>\n      <div class=\"desk-watch\" id=\"deskWatch\" hidden><span id=\"deskWatchTxt\"></span><button type=\"button\"\n          class=\"desk-btn\" id=\"deskWatchBtn\">Choose folder</button></div>\n      <div class=\"desk-watch\" id=\"deskSoloRow\"><label><input type=\"checkbox\" id=\"deskSolo\"> One photo per print (Solo\n          layout, even when the event uses a strip)</label></div>\n      <div class=\"desk-hint\" id=\"deskHint\"></div>\n      <div class=\"desk-grid\" id=\"deskGrid\"></div>\n      <div class=\"desk-foot\"><button type=\"button\" class=\"desk-btn\" id=\"deskClear\">Clear list</button><span\n          class=\"sp\"></span><button type=\"button\" class=\"desk-btn\" id=\"deskOrig\" disabled>Print original</button><button\n          type=\"button\" class=\"desk-btn primary\" id=\"deskMake\" disabled>Make print + QR</button></div>\n    </div>\n  </div>\n  <style id=\"printPageStyle\"></style>\n\n  <!-- Laptop app: \"a new version is out\" on the Tap to start screen. This is its own script on purpose: if the booth\n       script below ever fails to start (as in 1.0.53), the start screen stays up and the owner can still update. -->\n  <script id=\"pbUpdPrompt\">\n    (function () {\n      try {\n        var api = window.pb4u, up = api && api.desktop && api.update;\n        if (!up) return;\n        var css = document.createElement('style');\n        css.textContent =\n          '.pbu-chip,.pbu-ov{font-family:Manrope,system-ui,sans-serif}' +\n          '.pbu-chip[hidden],.pbu-ov[hidden]{display:none!important}' +\n          '.pbu-chip{position:fixed;z-index:255;top:max(10px,env(safe-area-inset-top));left:50%;transform:translateX(-50%);max-width:calc(100vw - 100px);min-height:40px;padding:0 18px;border:0;border-radius:999px;background:#1C1A1E;color:#fff;font:800 13.5px Manrope,system-ui,sans-serif;box-shadow:0 6px 20px rgba(0,0,0,.28);cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}' +\n          '.pbu-ov{position:fixed;inset:0;z-index:9700;display:flex;align-items:center;justify-content:center;padding:16px;background:rgba(20,16,22,.6)}' +\n          '.pbu-card{width:min(440px,100%);padding:20px 22px;border-radius:20px;background:#fff;color:#1C1A1E;box-shadow:0 24px 60px rgba(0,0,0,.35)}' +\n          '.pbu-card b{display:block;font-size:17px;font-weight:800}' +\n          '.pbu-card p{margin:6px 0 0;font-size:13.5px;line-height:1.5;color:#5b5560}' +\n          '.pbu-bar{height:6px;margin-top:14px;border-radius:6px;background:#ece8f0;overflow:hidden}' +\n          '.pbu-bar i{display:block;height:100%;width:0;background:#1C1A1E}' +\n          '.pbu-row{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:10px;margin-top:16px}' +\n          '.pbu-row button{min-height:44px;padding:0 20px;border-radius:999px;border:1.5px solid #cfc8d6;background:#fff;color:#1C1A1E;font:700 14px Manrope,system-ui,sans-serif;cursor:pointer}' +\n          '.pbu-row button.go{background:#1C1A1E;border-color:#1C1A1E;color:#fff}' +\n          '.pbu-row button:disabled{opacity:.6}';\n        document.head.appendChild(css);\n\n        var mk = function (tag, cls) { var e = document.createElement(tag); if (cls) e.className = cls; return e; };\n        var chip = mk('button', 'pbu-chip'); chip.type = 'button'; chip.hidden = true;\n        var ov = mk('div', 'pbu-ov'); ov.hidden = true;\n        document.body.appendChild(chip); document.body.appendChild(ov);\n\n        var u = null, later = false, sig = '';\n        var startUp = function () { var s = document.getElementById('startScreen'); return !!s && !s.classList.contains('gone') && s.style.display !== 'none'; };\n        var wanted = function () { return !!(u && u.latest && u.state !== 'idle' && !(later && u.state === 'ready')); };\n        var take = function (i) { if (i && i.latest !== undefined) { u = i; sync(); } };\n        var pct = function () { return (u.progress || 0) + '%'; };\n\n        function label() {\n          if (u.state === 'downloading') return 'Downloading update ' + pct();\n          if (u.state === 'ready') return u.os === 'win' ? 'Update ready — tap to install' : 'Update downloaded — tap for steps';\n          if (u.state === 'error') return 'Update problem — tap to retry';\n          return 'Update ' + u.latest + ' available — tap';\n        }\n        function button(text, cls, fn) {\n          var b = mk('button', cls); b.type = 'button'; b.textContent = text;\n          b.addEventListener('click', function () { try { fn(b); } catch (e) { } });\n          return b;\n        }\n        function fillCard() {\n          var s = [u.state, u.latest, u.os, u.state === 'downloading' ? '' : u.progress, u.error].join('|');\n          if (s === sig) {\n            var bi = ov.querySelector('.pbu-bar i'); if (bi) bi.style.width = pct();\n            var pc = ov.querySelector('.pbu-pc'); if (pc) pc.textContent = pct();\n            return;\n          }\n          sig = s;\n          ov.innerHTML = '';\n          var card = mk('div', 'pbu-card'), title = mk('b'), note = mk('p'), row = mk('div', 'pbu-row');\n          var keep = 'This laptop has ' + (u.current || '?') + '. Your activation, designs and photos stay.';\n          if (u.state === 'downloading') {\n            title.textContent = 'Downloading version ' + u.latest;\n            note.appendChild(document.createTextNode('Almost there: '));\n            var pc = mk('span', 'pbu-pc'); pc.textContent = pct(); note.appendChild(pc);\n          } else if (u.state === 'ready' && u.os === 'win') {\n            title.textContent = 'Version ' + u.latest + ' is ready';\n            note.textContent = 'Restart now to install it (Windows asks once for permission), or choose Later and it installs when you close the app.';\n            row.appendChild(button('Later', '', function () { later = true; ov.hidden = true; sync(); }));\n            row.appendChild(button('Restart now', 'go', function (b) { b.disabled = true; b.textContent = 'Restarting…'; up.install(); }));\n          } else if (u.state === 'ready') {\n            title.textContent = 'Version ' + u.latest + ' is downloaded';\n            note.textContent = 'In the window that opened, drag photobooth4u into Applications and choose Replace. Then quit this app and open it again.';\n            row.appendChild(button('Show it again', 'go', function () { up.open(); }));\n          } else if (u.state === 'error') {\n            title.textContent = 'Couldn’t download version ' + u.latest;\n            note.textContent = u.error || 'Check the internet connection and try again.';\n            row.appendChild(button('Try again', 'go', function (b) { b.disabled = true; up.download().then(take); }));\n          } else {\n            title.textContent = 'Version ' + u.latest + ' of the app is out';\n            note.textContent = keep;\n            row.appendChild(button('Download', 'go', function (b) { b.disabled = true; up.download().then(take); }));\n          }\n          row.insertBefore(button('Close', '', function () { ov.hidden = true; }), row.firstChild);\n          card.appendChild(title); card.appendChild(note);\n          if (u.state === 'downloading') { var bar = mk('div', 'pbu-bar'), fill = mk('i'); fill.style.width = pct(); bar.appendChild(fill); card.appendChild(bar); }\n          card.appendChild(row);\n          ov.appendChild(card);\n        }\n        function sync() {\n          var show = wanted() && startUp() && !document.body.classList.contains('booth-locked');\n          chip.hidden = !show;\n          if (!show) { ov.hidden = true; return; }\n          chip.textContent = label();\n          if (!ov.hidden) fillCard();\n        }\n\n        chip.addEventListener('click', function (e) { e.stopPropagation(); if (!wanted()) return; sig = ''; fillCard(); ov.hidden = false; });\n        ov.addEventListener('click', function (e) { if (e.target === ov) ov.hidden = true; });\n        up.on(take);\n        api.info().then(function (i) { take(i && i.update); }).catch(function () { });\n        // The app checks on its own 20 s after it opens; ask now so the prompt shows right away.\n        setTimeout(function () { try { up.check().then(take).catch(function () { }); } catch (e) { } }, 1500);\n        setInterval(sync, 1500);   // the chip goes away with the start screen (Setup has its own update bar)\n      } catch (e) { /* never let the update prompt stop the booth */ }\n    })();\n  </script>\n\n  <script>\n    (function () {\n      // Windows / Mac app (desktop/): photos save on this laptop, guests get them\n      // over the booth Wi-Fi, and printing + the Windows camera are built in.\n      const DESKTOP = !!(window.pb4u && window.pb4u.desktop && window.__PB && window.__PB.desktop);\n      // Android tablet app (android/): an offline kiosk. Photos are saved on the tablet through the app (window.__PBLocal)\n      // and guests on the same Wi-Fi open them from the tablet, like the laptop app does.\n      const ANDROID_LOCAL = !!(window.__PBLocal && typeof window.__PBLocal.drive === 'function' && window.__PB && window.__PB.android);\n      // Photos stay on this device and guests reach them over the booth Wi-Fi (laptop app and Android tablet app).\n      // An iPad / tablet that opened the booth from the laptop app over the booth Wi-Fi (http://<laptop>:47777/ipad/<PIN>): the\n      // laptop does the camera, the photo folder and the licence; this page only shows the booth (desktop/lib/lan.mjs).\n      const LANREMOTE = !DESKTOP && !!(window.__PB && window.__PB.lanRemote && window.__PB.lanRemote.base);\n      const LOCALSHARE = DESKTOP || ANDROID_LOCAL || LANREMOTE;\n      // The laptop's address on the booth Wi-Fi, as the guests' phones reach it ('' when unknown).\n      function lanBaseNow() {\n        try {\n          if (LANREMOTE) return String(window.__PB.lanRemote.base || '');\n          return (ANDROID_LOCAL ? window.__PBLocal.lanBase() : window.pb4u.lanBase()) || '';\n        } catch (e) { return ''; }\n      }\n      if (LOCALSHARE) document.documentElement.classList.add('pb-desktop');   // hides the online-only options (web-only)\n      const LOCAL_DEVICE = ANDROID_LOCAL ? 'tablet' : 'laptop';\n      // Line icons from the SVG sprite at the top of the page.\n      function ICON(name) { return '<svg class=\"ic\" aria-hidden=\"true\"><use href=\"#i-' + name + '\"/></svg>'; }\n      const video = document.getElementById('video');\n      const previewCanvas = document.getElementById('previewCanvas');\n      const cameraError = document.getElementById('cameraError');\n      const cameraErrorText = document.getElementById('cameraErrorText');\n      const retryCameraBtn = document.getElementById('retryCameraBtn');\n      const countdownOverlay = document.getElementById('countdownOverlay');\n      const countdownNum = document.getElementById('countdownNum');\n      const readyOverlay = document.getElementById('readyOverlay');\n      const readyStartBtn = document.getElementById('readyStartBtn');\n      const flashOverlay = document.getElementById('flashOverlay');\n      const recDot = document.getElementById('recDot');\n      const filmTrack = document.getElementById('filmTrack');\n      const startBtn = document.getElementById('startBtn');\n      const bgInput = document.getElementById('bgInput');\n      const bgThumb = document.getElementById('bgThumb');\n      const removeBgBtn = document.getElementById('removeBgBtn');\n      const labelInput = document.getElementById('labelInput');\n      const layoutGrid = document.getElementById('layoutGrid');\n      const layoutHint = document.getElementById('layoutHint');\n      const shareBtn = document.getElementById('shareBtn');\n      const toast = document.getElementById('toast');\n      const qrSection = document.getElementById('qrSection');\n      const qrResults = document.getElementById('qrResults');\n      const driveStatusText = document.getElementById('driveStatusText');\n      const driveFolderKeyInput = document.getElementById('driveFolderKeyInput');\n      const driveFolderStatus = document.getElementById('driveFolderStatus');\n      const driveFolderError = document.getElementById('driveFolderError');\n      const driveFolderQrPreview = document.getElementById('driveFolderQrPreview');\n      const driveFolderQrImg = document.getElementById('driveFolderQrImg');\n      const driveFolderQrCaption = document.getElementById('driveFolderQrCaption');\n      const tabBtnSetup = document.getElementById('tabBtnSetup');\n      const tabBtnSession = document.getElementById('tabBtnSession');\n      const tabSetup = document.getElementById('tabSetup');\n      const tabSession = document.getElementById('tabSession');\n      const goToSessionBtn = document.getElementById('goToSessionBtn');\n      const fontDropdownBtn = document.getElementById('fontDropdownBtn');\n      const dateToggle = document.getElementById('dateToggle');\n      const dateRow = document.getElementById('dateRow');\n      const dateInput = document.getElementById('dateInput');\n      const datePreviewText = document.getElementById('datePreviewText');\n      const dateFontWrap = document.getElementById('dateFontWrap');\n      const presetGrid = document.getElementById('presetGrid');\n      const setupPreviewCanvas = document.getElementById('setupPreviewCanvas');\n      const textColorInput = document.getElementById('textColorInput');\n      const outlineToggle = document.getElementById('outlineToggle');\n      const shadowToggle = document.getElementById('shadowToggle');\n      const bandPositionWrap = document.getElementById('bandPositionWrap');\n      const bandPositionSelect = document.getElementById('bandPositionSelect');\n      const readySub = document.getElementById('readySub');\n      let currentFont = \"'Times New Roman', serif\";\n      let currentDateFont = \"'Times New Roman', serif\";\n      let backdropPreset = 'none'; // none | gold | sky | stars | cream | maroon | custom\n      let elementsChoice = 'auto'; // auto = the preset's own decorations, else a key of ELEMENT_SETS\n      let backdropColor = null;    // null = the style's own colors, else a '#rrggbb' picked in Backdrop color\n      let textColor = '#1f4166';\n      let useOutline = true;\n      let useShadow = true;\n      let outlineColor = '#ffffff';\n      let bgBandPosition = 'above'; // above | below (strip + custom photo only)\n      let photoHue = 205;   // dominant hue of the uploaded photo (0-360)\n      let photoSat = 0.4;   // how colorful that dominant color is (0-1)\n      let frameColorChoice = 'auto'; // 'auto' or a '#rrggbb' Polaroid color\n      let cropFocus = 'center';\n      let titleBgEnabled = true;\n      let titleBgColor = '#ffffff';\n      let photoPlacement = 'band'; // band | background (custom photo only)\n      let currentFrameColor = '#ffffff';\n\n      // ---- Tab switching ----\n      function switchTab(tab) {\n        if (tab !== 'session' && document.body.classList.contains('booth-locked')) return;\n        const toSession = tab === 'session';\n        tabBtnSetup.classList.toggle('active', !toSession);\n        tabBtnSession.classList.toggle('active', toSession);\n        tabSetup.classList.toggle('hidden', toSession);\n        tabSession.classList.toggle('hidden', !toSession);\n        document.body.classList.toggle('in-session', toSession);   // smaller header: the camera gets the room\n        try { if (typeof scpRefresh === 'function') scpRefresh(); } catch (e) { }\n        window.scrollTo(0, 0);\n        if (toSession && typeof applyStageAspect === 'function') requestAnimationFrame(function () { applyStageAspect(); });\n        try { refreshPrintFab(); refreshPanelSolo(); } catch (e) { }\n        try { placeTimeChip(); scheduleDock(); } catch (e) { }\n      }\n      tabBtnSetup.addEventListener('click', () => switchTab('setup'));\n      tabBtnSession.addEventListener('click', () => switchTab('session'));\n\n      function showDriveFolderError(msg) {\n        driveFolderError.textContent = msg;\n        driveFolderError.style.display = 'block';\n        driveFolderKeyInput.style.borderColor = '#c0392b';\n      }\n      function clearDriveFolderError() {\n        driveFolderError.style.display = 'none';\n        driveFolderError.textContent = '';\n        driveFolderKeyInput.style.borderColor = '';\n      }\n\n      goToSessionBtn.addEventListener('click', () => {\n        if (!rawFolderKey()) {\n          if (typeof goStep === 'function') goStep(6);\n          showDriveFolderError('Type a folder name first.');\n          driveFolderKeyInput.focus();\n          return;\n        }\n        clearDriveFolderError();\n        switchTab('session');\n      });\n\n      // ---- Font pickers (event name gets its own font, date gets its own) ----\n      // Built as custom dropdowns (not native <select>) because mobile browsers\n      // ignore per-<option> font-family styling, so a native select can't\n      // preview each font — this one renders every item in its real font.\n      const FONT_OPTIONS = [\n        [\"'Times New Roman', serif\", 'Times New Roman'],\n        ['Arial, sans-serif', 'Arial'],\n        [\"'Pacifico', cursive\", 'Pacifico'],\n        [\"'Dancing Script', cursive\", 'Dancing Script'],\n        [\"'Great Vibes', cursive\", 'Great Vibes'],\n        [\"'Sacramento', cursive\", 'Sacramento'],\n        [\"'Alex Brush', cursive\", 'Alex Brush'],\n        [\"'Satisfy', cursive\", 'Satisfy'],\n        [\"'Parisienne', cursive\", 'Parisienne'],\n        [\"'Playfair Display', serif\", 'Playfair Display'],\n        [\"'Inter', sans-serif\", 'Inter'],\n        [\"'Cormorant Garamond', serif\", 'Cormorant Garamond'],\n        [\"'Cinzel', serif\", 'Cinzel'],\n        [\"'Marck Script', cursive\", 'Marck Script'],\n        [\"'Tangerine', cursive\", 'Tangerine'],\n        [\"'Allura', cursive\", 'Allura'],\n        [\"'Cookie', cursive\", 'Cookie'],\n        [\"'Italianno', cursive\", 'Italianno'],\n        [\"'Petit Formal Script', cursive\", 'Petit Formal Script'],\n        [\"'Lobster', cursive\", 'Lobster'],\n        [\"'Josefin Sans', sans-serif\", 'Josefin Sans'],\n        [\"'Montserrat', sans-serif\", 'Montserrat'],\n        [\"'Poppins', sans-serif\", 'Poppins'],\n        [\"'Raleway', sans-serif\", 'Raleway'],\n        [\"'Merriweather', serif\", 'Merriweather'],\n        [\"'Fredoka', sans-serif\", 'Fredoka'],\n        [\"'Abril Fatface', cursive\", 'Abril Fatface'],\n        [\"'Bebas Neue', cursive\", 'Bebas Neue'],\n        [\"'Caveat', cursive\", 'Caveat'],\n        [\"'Amatic SC', cursive\", 'Amatic SC'],\n        [\"'EB Garamond', serif\", 'EB Garamond'],\n        [\"'Quicksand', sans-serif\", 'Quicksand'],\n        [\"'Comfortaa', sans-serif\", 'Comfortaa']\n      ];\n\n      function buildFontDropdown(btn, listEl, options, onPick) {\n        options.forEach(([value, label]) => {\n          const item = document.createElement('div');\n          item.className = 'custom-dd-item';\n          item.textContent = label;\n          item.style.fontFamily = value;\n          item.dataset.value = value;\n          item.addEventListener('click', () => {\n            btn.textContent = label;\n            btn.style.fontFamily = value;\n            [...listEl.children].forEach(c => c.classList.toggle('active', c === item));\n            listEl.classList.remove('open');\n            onPick(value);\n          });\n          listEl.appendChild(item);\n        });\n        // Set initial button label/font from the first option (the default font).\n        btn.textContent = options[0][1];\n        btn.style.fontFamily = options[0][0];\n        listEl.children[0].classList.add('active');\n        btn.addEventListener('click', (e) => {\n          e.stopPropagation();\n          const wasOpen = listEl.classList.contains('open');\n          document.querySelectorAll('.custom-dd-list.open').forEach(l => l.classList.remove('open'));\n          if (!wasOpen) listEl.classList.add('open');\n        });\n      }\n      document.addEventListener('click', () => {\n        document.querySelectorAll('.custom-dd-list.open').forEach(l => l.classList.remove('open'));\n      });\n\n      buildFontDropdown(fontDropdownBtn, document.getElementById('fontDropdownList'), FONT_OPTIONS, (value) => {\n        currentFont = value;\n        applyLabelInputFont();\n        qrResults.innerHTML = '';\n        lastRenderedFolderUrl = null;\n        renderComposite();\n        renderSetupPreview();\n      });\n      buildFontDropdown(document.getElementById('dateFontDropdownBtn'), document.getElementById('dateFontDropdownList'), FONT_OPTIONS, (value) => {\n        currentDateFont = value;\n        qrResults.innerHTML = '';\n        lastRenderedFolderUrl = null;\n        renderComposite();\n        renderSetupPreview();\n      });\n\n      // ---- Date subtitle (MM/DD/YY, shown below the event name) ----\n      function formatDateMMDDYY(value) {\n        if (!value) return '';\n        const parts = value.split('-'); // value is YYYY-MM-DD from <input type=\"date\">\n        if (parts.length !== 3) return '';\n        const [yyyy, mm, dd] = parts;\n        return mm + '/' + dd + '/' + yyyy.slice(2);\n      }\n      // Date is optional and controlled by the calendar icon next to the event\n      // name: tap it once to add today's date, tap the date chip to pick another\n      // day (the real date input sits invisibly on top of the chip, so the native\n      // picker opens on iPad and Android alike), and Remove / tap the icon again\n      // to drop it.\n      let dateOn = false;\n      const dateHint = document.getElementById('dateHint');\n      const dateFontGroup = document.getElementById('dateFontGroup');\n      function todayISO() {\n        const d = new Date();\n        const p = n => (n < 10 ? '0' : '') + n;\n        return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate());\n      }\n      function currentDateLabel() {\n        if (!dateOn) return '';\n        return formatDateMMDDYY(dateInput.value);\n      }\n      function setDateOn(on) {\n        dateOn = on;\n        if (on && !dateInput.value) dateInput.value = todayISO();\n        dateToggle.classList.toggle('on', on);\n        dateToggle.setAttribute('aria-pressed', on ? 'true' : 'false');\n        dateToggle.setAttribute('aria-label', on ? 'Remove the date' : 'Add the date under the event name');\n        dateToggle.title = on ? 'Remove the date' : 'Add the date';\n        dateRow.style.display = on ? 'flex' : 'none';\n        dateFontWrap.style.display = on ? 'block' : 'none';\n        dateFontGroup.style.display = on ? 'block' : 'none';\n        datePreviewText.textContent = formatDateMMDDYY(dateInput.value) || 'MM/DD/YY';\n        dateHint.textContent = on\n          ? 'The date prints under the event name. Tap the date to pick another day.'\n          : 'Tap the calendar to add today’s date under the event name.';\n        qrResults.innerHTML = '';\n        lastRenderedFolderUrl = null;\n        renderComposite();\n        renderSetupPreview();\n        if (typeof refreshStartScreen === 'function') refreshStartScreen();\n      }\n      dateToggle.addEventListener('click', () => setDateOn(!dateOn));\n      document.getElementById('dateRemove').addEventListener('click', () => setDateOn(false));\n      // Clicking the (invisible) date input on a computer only focuses it — Chrome\n      // opens the calendar from its own icon, which is hidden here — so the\n      // calendar is opened by hand on every click of the chip.\n      function openDatePicker() {\n        try {\n          if (typeof dateInput.showPicker === 'function') { dateInput.showPicker(); return true; }\n        } catch (err) { }\n        try { dateInput.focus(); } catch (err) { }\n        return false;\n      }\n      dateRow.querySelector('.date-chip').addEventListener('click', (e) => {\n        if (e.target !== dateInput) e.preventDefault();\n        openDatePicker();\n      });\n      dateInput.addEventListener('input', () => {\n        if (!dateInput.value) dateInput.value = todayISO();\n        setDateOn(true);\n      });\n      dateInput.addEventListener('change', () => {\n        if (!dateInput.value) dateInput.value = todayISO();\n        setDateOn(true);\n      });\n\n      // ---- Text style: color / outline / shadow ----\n      const colorSwatchRow = document.getElementById('colorSwatchRow');\n      const titleSizeSlider = document.getElementById('titleSizeSlider');\n      let titleSizeMultiplier = 1;\n      colorSwatchRow.addEventListener('click', (e) => {\n        const btn = e.target.closest('.color-swatch-btn');\n        if (!btn) return;\n        textColor = btn.dataset.color;\n        textColorInput.value = textColor;\n        [...colorSwatchRow.querySelectorAll('.color-swatch-btn')].forEach(b => b.classList.toggle('active', b === btn));\n        qrResults.innerHTML = '';\n        lastRenderedFolderUrl = null;\n        renderComposite();\n        renderSetupPreview();\n      });\n      textColorInput.addEventListener('input', () => {\n        textColor = textColorInput.value;\n        [...colorSwatchRow.querySelectorAll('.color-swatch-btn')].forEach(b => b.classList.remove('active'));\n        qrResults.innerHTML = '';\n        lastRenderedFolderUrl = null;\n        renderComposite();\n        renderSetupPreview();\n      });\n      titleSizeSlider.addEventListener('input', () => {\n        // 60–170% of the default size; the shrink-to-fit loop and a hard height\n        // clamp in drawLabelBand still guard against overflow at the max setting.\n        titleSizeMultiplier = titleSizeSlider.value / 100;\n        renderComposite();\n        renderSetupPreview();\n      });\n      outlineToggle.addEventListener('change', () => {\n        useOutline = outlineToggle.checked;\n        renderComposite();\n        renderSetupPreview();\n      });\n      shadowToggle.addEventListener('change', () => {\n        useShadow = shadowToggle.checked;\n        renderComposite();\n        renderSetupPreview();\n      });\n      const outlineColorSelect = document.getElementById('outlineColorSelect');\n      outlineColorSelect.addEventListener('change', () => {\n        outlineColor = outlineColorSelect.value;\n        renderComposite();\n        renderSetupPreview();\n      });\n      const titleBgToggle = document.getElementById('titleBgToggle');\n      const titleBgColorInput = document.getElementById('titleBgColorInput');\n      const titleBgColorWrap = document.getElementById('titleBgColorWrap');\n      titleBgToggle.addEventListener('change', () => {\n        titleBgEnabled = titleBgToggle.checked;\n        titleBgColorWrap.style.display = titleBgEnabled ? 'flex' : 'none';\n        renderComposite();\n        renderSetupPreview();\n      });\n      titleBgColorInput.addEventListener('input', () => {\n        titleBgColor = titleBgColorInput.value;\n        renderComposite();\n        renderSetupPreview();\n      });\n      const frameSwatchRow = document.getElementById('frameSwatchRow');\n      const frameSwatchName = document.getElementById('frameSwatchName');\n      const photoPlacementSelect = document.getElementById('photoPlacementSelect');\n      photoPlacementSelect.addEventListener('change', () => {\n        photoPlacement = photoPlacementSelect.value;\n        setActivePresetBtn();\n        updateBandPositionVisibility();\n        renderComposite();\n        renderSetupPreview();\n      });\n      frameSwatchRow.addEventListener('click', (e) => {\n        const btn = e.target.closest('.frame-swatch');\n        if (!btn) return;\n        frameColorChoice = btn.dataset.color;\n        frameSwatchName.textContent = btn.dataset.name;\n        [...frameSwatchRow.querySelectorAll('.frame-swatch')].forEach(b => b.classList.toggle('active', b === btn));\n        qrResults.innerHTML = '';\n        lastRenderedFolderUrl = null;\n        renderComposite();\n        renderSetupPreview();\n      });\n      const cropFocusSelect = document.getElementById('cropFocusSelect');\n      // Strip crops a wide photo down to a short band, so only vertical focus\n      // makes sense; Grid crops a tall photo down to a narrow column, so only\n      // horizontal focus makes sense — only show the options that actually apply.\n      const CROP_OPTIONS_BY_LAYOUT = {\n        strip: [['top', 'Top'], ['center', 'Center'], ['bottom', 'Bottom']],\n        grid: [['left', 'Left'], ['center', 'Center'], ['right', 'Right']]\n      };\n      function rebuildCropFocusOptions() {\n        // A wide band (strip + photo above it) crops top/bottom; every other spot\n        // for the photo is taller than the photo, so it crops left/right.\n        const opts = (isStripLayout() && placement() === 'band') ? CROP_OPTIONS_BY_LAYOUT.strip : CROP_OPTIONS_BY_LAYOUT.grid;\n        const stillValid = opts.some(([v]) => v === cropFocus);\n        cropFocusSelect.innerHTML = '';\n        opts.forEach(([value, label]) => {\n          const opt = document.createElement('option');\n          opt.value = value; opt.textContent = label;\n          if (value === (stillValid ? cropFocus : 'center')) opt.selected = true;\n          cropFocusSelect.appendChild(opt);\n        });\n        cropFocus = stillValid ? cropFocus : 'center';\n      }\n      cropFocusSelect.addEventListener('change', () => {\n        cropFocus = cropFocusSelect.value;\n        renderComposite();\n        renderSetupPreview();\n      });\n\n      // ---- Strip/Grid + custom photo: photo always goes above (strip) or on\n      // the left (grid) — no manual choice, keeps things simple and consistent. ----\n      function updateBandPositionVisibility() {\n        const show = backdropPreset === 'custom' && !!backgroundImg;\n        bandPositionWrap.style.display = show ? 'block' : 'none';\n        photoPlacementSelect.style.display = layoutDef().bandOk ? '' : 'none';\n        rebuildCropFocusOptions();\n        const hintEl = document.getElementById('bandPositionHint');\n        if (hintEl) {\n          if (!layoutDef().bandOk) {\n            hintEl.textContent = 'With this layout, your photo fills the background.';\n          } else if (photoPlacement === 'background') {\n            hintEl.textContent = 'Your photo fills the background.';\n          } else {\n            hintEl.textContent = currentLayout === 'grid'\n              ? 'Your photo on the left, the shots and name on the right.'\n              : 'Your photo sits above the shots.';\n          }\n        }\n      }\n\n      // ---- Google Drive upload, via a Google Apps Script relay ----\n      // Guests never sign into anything: the photo is POSTed to a small script\n      // that already runs under YOUR Google account (set up once, see the\n      // instructions Claude gave you), which drops the file straight into the\n      // Drive folder for this booking.\n      const DRIVE_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbxv0WfF9rxFY9QlseCoSjrA7vePwHE-Uc8QTURZYyN6yIzcTj4SIlktEWT6Xnaw6Pv9OA/exec';\n\n      function driveScriptUrl() {\n        return LOCALSHARE ? '/local/drive' : DRIVE_SCRIPT_URL;\n      }\n      // Android: a web page can't write to the tablet's storage, so the save goes through the app (window.__PBLocal.drive),\n      // which answers with the same JSON the Drive script / laptop app would.\n      function driveFetch(init) {\n        if (!ANDROID_LOCAL) return fetch(driveScriptUrl(), init);\n        return new Promise(function (resolve, reject) {\n          setTimeout(function () {\n            try {\n              const text = window.__PBLocal.drive(String((init && init.body) || '{}'));\n              resolve(new Response(text, { status: 200, headers: { 'Content-Type': 'application/json' } }));\n            } catch (e) { reject(e); }\n          }, 0);\n        });\n      }\n\n      // Lifetime codes: the renter types only the event name; the folder is always\n      // \"<their folder name> · <event name>\", so they can never upload into anyone\n      // else's folder (links and slashes are stripped from what they type).\n      function folderPrefix() {\n        const pb = window.__PB;\n        return (pb && pb.folderPrefix) ? String(pb.folderPrefix) : '';\n      }\n      function cleanEventName(v) {\n        return String(v || '').replace(/[^\\p{L}\\p{N} '\\u2019&().,!_-]/gu, '').replace(/[\\p{L}\\p{N}_.-]{20,}/gu, '').replace(/\\s+/g, ' ').trim().slice(0, 60);\n      }\n      function rawFolderKey() {\n        const v = (driveFolderKeyInput.value || '').trim();\n        const pre = folderPrefix();\n        if (!pre) return v;\n        const ev = cleanEventName(v);\n        return ev ? pre + ' \\u00b7 ' + ev : '';\n      }\n      // Codes shared by several devices add \"_cam2\" etc. to file names, so two\n      // devices at the same event never write \"5_strip.jpg\" twice.\n      function deviceTag() {\n        const pb = window.__PB;\n        return (pb && pb.multiDevice) ? '_cam' + (pb.deviceNo || 1) : '';\n      }\n\n      // Bonus codes: photos go into a subfolder of the event folder (e.g.\n      // \"Sofia's Dedication/Bonus\") and every file name starts with BONUS_.\n      // Both come from the rental code via window.__PB; normal bookings have neither.\n      function driveSubfolder() {\n        const pb = window.__PB;\n        return (pb && pb.subfolder) ? String(pb.subfolder) : '';\n      }\n      function filePrefix() {\n        const pb = window.__PB;\n        return (pb && pb.filePrefix) ? String(pb.filePrefix) : '';\n      }\n\n      function hasFolderKey() {\n        return !!rawFolderKey();\n      }\n\n      function driveReady() {\n        // Drive is only \"ready\" once a booking folder name/link is actually\n        // typed — no silent fallback to a shared default folder.\n        return !!driveScriptUrl() && hasFolderKey();\n      }\n\n      function blobToBase64(blob) {\n        return new Promise((resolve, reject) => {\n          const reader = new FileReader();\n          // The data URL is \"data:<type>;base64,<data>\"; a recorded video's type can itself contain commas (codecs), so cut at \";base64,\".\n          reader.onloadend = () => { const r = String(reader.result), i = r.indexOf(';base64,'); resolve(i >= 0 ? r.slice(i + 8) : r.split(',')[1]); };\n          reader.onerror = reject;\n          reader.readAsDataURL(blob);\n        });\n      }\n\n      // ---- Signed upload ticket ----\n      // The Drive script only accepts requests carrying a ticket from our server,\n      // and the ticket names the one folder this booth may use. Cached per folder\n      // and refreshed a few minutes before it expires.\n      let ticketCache = null;\n      async function getUploadTicket(folderKey) {\n        if (LOCALSHARE) return 'local';\n        const key = folderKey !== undefined ? folderKey : rawFolderKey();\n        if (ticketCache && ticketCache.key === key && ticketCache.exp - Date.now() > 5 * 60000) return ticketCache.ticket;\n        let token = null, deviceId = null;\n        try { token = localStorage.getItem('pb_token'); deviceId = localStorage.getItem('pb_device'); } catch (e) { }\n        const res = await fetch('/api/ticket', {\n          method: 'POST',\n          headers: { 'content-type': 'application/json' },\n          body: JSON.stringify({ token, deviceId, folderKey: key })\n        });\n        const data = await res.json().catch(() => ({}));\n        if (!res.ok || !data.ticket) throw new Error(data.error || 'Could not get permission to upload');\n        ticketCache = { key, ticket: data.ticket, exp: data.exp };\n        return data.ticket;\n      }\n\n      // dest = { folderKey, subfolder } for photos queued earlier (they keep the\n      // folder they were taken for); left out = the folder set up right now.\n      async function uploadToDrive(blob, filename, dest) {\n        const folderKey = dest ? dest.folderKey : rawFolderKey();\n        const subfolder = dest ? dest.subfolder : driveSubfolder();\n        // Sent as text/plain (not application/json) on purpose: it keeps this a\n        // CORS \"simple request\" so the browser skips a preflight OPTIONS call,\n        // which Apps Script Web Apps don't handle — this is what makes the\n        // request work cross-origin at all.\n        const base64Data = await blobToBase64(blob);\n        const ticket = await getUploadTicket(folderKey);\n        const res = await driveFetch({\n          method: 'POST',\n          headers: { 'Content-Type': 'text/plain;charset=utf-8' },\n          body: JSON.stringify({\n            filename: filename,\n            mimeType: blob.type || 'image/png',\n            imageBase64: base64Data,\n            folderKey: folderKey,\n            subfolder: subfolder || undefined,\n            guestCode: ((LOCALSHARE || outputMode === 'both') && (gvActive() || outputMode === 'both') && gvFileNum(filename)) ? gvCodeFor(gvFileNum(filename)) : undefined,   // this file belongs to that guest's own page\n            ticket\n          })\n        });\n        if (!res.ok) throw new Error('Drive upload failed (' + res.status + ')');\n        const data = await res.json();\n        if (!data.ok) throw new Error(data.error || 'Drive upload failed');\n        // folderUrl is optional on the Apps Script side (older scripts may not\n        // return it yet) — everything still works, we just can't show the\n        // one persistent folder QR until it's added. See note in the script.\n        try { gvAfterUpload(filename, blob.type, data, folderKey); } catch (e) { console.error('Guest view:', e); }\n        return { fileId: data.fileId, downloadUrl: data.downloadUrl, folderUrl: data.folderUrl || null };\n      }\n\n\n\n      // contentH = area used for photos. Actual canvas height = contentH + label band.\n      // Strip: 600px wide, each photo is 600x600 square, 4 stacked = tall vertical strip\n      const STRIP_W = 600;\n      const STRIP_PHOTO = 500; // square photo size\n      const STRIP_GAP = 6;\n      const STRIP_MARGIN = 42;\n      const STRIP_SHOTS = 3; // classic strips show 3 photos, not 4\n      const STRIP_CONTENT_H = STRIP_MARGIN * 2 + STRIP_PHOTO * STRIP_SHOTS + STRIP_GAP * (STRIP_SHOTS - 1);\n\n      const GRID_SHOTS = 4;\n      // Shots are taken at the live preview's 4:5 shape. The plain 2x2 grid is sized so\n      // every polaroid holds a full, uncropped 4:5 shot (a polaroid frame is 1.15 x 1.5\n      // photo-widths, and that math sets the canvas height below).\n      const SHOT_ASPECT = 4 / 5;\n      const GRID_MARGIN_R = 0.05, GRID_GAP_R = 0.037;\n      const GRID_FRAME_W = 1 + 0.12 / SHOT_ASPECT;   // frame width  / photo width\n      const GRID_FRAME_H = 1.2 / SHOT_ASPECT;        // frame height / photo width\n      const GRID_W = 1200;\n      const GRID_H = Math.round(\n        GRID_W * GRID_MARGIN_R * 2 + GRID_W * GRID_GAP_R +\n        2 * GRID_FRAME_H * ((GRID_W * (1 - GRID_MARGIN_R * 2 - GRID_GAP_R) / 2) / GRID_FRAME_W)\n      );\n      // Grid with a custom photo beside it keeps the wide layout (1 shot on top, 3 below).\n      const GRID_SIDE_W = 1500;\n      const GRID_SIDE_H = 960;\n\n      // Strip 4: same look as the classic strip, one more shot, slightly smaller\n      // squares so it stays close to a 2x6 strip's shape.\n      const STRIP4_PHOTO = 400;\n      const STRIP4_CONTENT_H = STRIP_MARGIN * 2 + STRIP4_PHOTO * 4 + STRIP_GAP * 3;\n\n      // ---- Sheet layouts: every one is a 4R (4x6) portrait sheet ----\n      // Rows of cells, as relative heights; each row has 1+ columns. The shot\n      // index runs left to right, top to bottom. The label band (event name /\n      // date) sits under the cells and the whole canvas is always 1200x1800, so\n      // it prints edge to edge on 4R.\n      const SHEET_W = 1200, SHEET_H = 1800;\n      const SHEET_ROWS = {\n        grid4: [[1, 2], [1, 2]],\n        hero: [[1.55, 1], [1, 3]],\n        solo: [[1, 1]],\n        duo: [[1, 1], [1, 1]],\n        trio: [[1, 1], [1, 1], [1, 1]],\n        feature: [[1.2, 1], [1, 2]],\n        film6: [[1, 2], [1, 2], [1, 2]]\n      };\n      // Cell boxes for a sheet layout inside a W x H content area.\n      function sheetCells(key, W, H) {\n        const rows = SHEET_ROWS[key];\n        const m = W * 0.05, g = W * 0.025;\n        const iw = W - m * 2, ih = H - m - m * 0.5;\n        const totalWeight = rows.reduce((a, r) => a + r[0], 0);\n        const rowsH = ih - g * (rows.length - 1);\n        const cells = [];\n        let y = m;\n        rows.forEach(([weight, cols]) => {\n          const rh = rowsH * weight / totalWeight;\n          const cw = (iw - g * (cols - 1)) / cols;\n          for (let c = 0; c < cols; c++) cells.push({ x: m + c * (cw + g), y, w: cw, h: rh });\n          y += rh + g;\n        });\n        return cells;\n      }\n\n      // Every layout the booth offers. kind: 'strip' (tall strip; prints two side\n      // by side on wider paper), 'polaroid' (the original 2x2 polaroid grid), or\n      // 'sheet' (cells on a 4R sheet). bandOk = supports a custom photo placed in\n      // its own band/side next to the shots (otherwise a custom photo is used as\n      // the full background).\n      const LAYOUT_DEFS = {\n        strip: { name: 'Classic strip', shots: 3, kind: 'strip', bandOk: true, hint: '3 shots in a tall strip. Prints 2 strips on 4R, cut down the middle.' },\n        strip4: { name: 'Strip 4', shots: 4, kind: 'strip', bandOk: true, hint: '4 shots in a tall strip. Prints 2 strips on 4R, cut down the middle.' },\n        grid: { name: 'Polaroid 4', shots: 4, kind: 'polaroid', bandOk: true, hint: '4 polaroids. Every shot in full, nothing cropped.' },\n        grid4: { name: 'Grid 4', shots: 4, kind: 'sheet', hint: '4 even shots on one 4R sheet.' },\n        hero: { name: 'Hero 1+3', shots: 4, kind: 'sheet', hint: '1 big shot on top, 3 small below.' },\n        solo: { name: 'Solo', shots: 1, kind: 'sheet', hint: '1 big shot.' },\n        duo: { name: 'Duo', shots: 2, kind: 'sheet', hint: '2 shots, stacked.' },\n        trio: { name: 'Trio', shots: 3, kind: 'sheet', hint: '3 wide shots, stacked.' },\n        feature: { name: 'Feature 1+2', shots: 3, kind: 'sheet', hint: '1 wide shot on top, 2 below.' },\n        film6: { name: 'Film 6', shots: 6, kind: 'sheet', hint: '6 shots in a 2×3 grid.' },\n        land3: { name: 'Landscape 3', shots: 3, kind: 'landscape', hint: 'Landscape 4R: the name in its own panel, 3 shots.' },\n        land4: { name: 'Landscape 4', shots: 4, kind: 'landscape', hint: 'Landscape 4R: 1 big shot and the name on top, 3 below.' },\n        // Receipt photo booth: looks like a shop receipt. Black & white is made for\n        // 80 mm / 58 mm thermal receipt printers; the colour one suits photo printers.\n        receipt: { name: 'Receipt (3 shots)', shots: 3, kind: 'receipt', hint: 'Black & white layout formatted for 58 mm and 80 mm thermal receipt printers.' },\n        receiptc: { name: 'Receipt colour (3 shots)', shots: 3, kind: 'receipt', color: true, hint: 'The receipt look with colour photos. Prints on photo paper (2 side by side on 4R) or a receipt printer.' },\n        receipt1: { name: 'Receipt Solo (1 shot)', shots: 1, kind: 'receipt', hint: '1 large portrait photo receipt with header, totals and barcode. Thermal or photo paper.' },\n        receipt1c: { name: 'Receipt Solo colour', shots: 1, kind: 'receipt', color: true, hint: '1 large colour photo receipt. Thermal or photo paper.' },\n        receipt2: { name: 'Receipt Duo (2 shots)', shots: 2, kind: 'receipt', hint: '2 stacked photos on receipt paper. Thermal or photo paper.' },\n        receipt2c: { name: 'Receipt Duo colour', shots: 2, kind: 'receipt', color: true, hint: '2 stacked colour photos on receipt paper.' },\n        receipt4: { name: 'Receipt Strip 4 (4 shots)', shots: 4, kind: 'receipt', hint: '4 shots in a tall receipt. Thermal or photo paper.' },\n        receipt4c: { name: 'Receipt 4 colour', shots: 4, kind: 'receipt', color: true, hint: '4 colour shots on receipt paper or 4R.' },\n        // Only offered when the booth type (top of Setup) is Trading card / Certificate.\n        card: { name: 'Trading card', shots: 1, kind: 'card', hint: 'One collectible card: the guest’s photo, name, a title line and random stats. 2.5 × 3.5 in.' },\n        cert: { name: 'Certificate', shots: 1, kind: 'cert', hint: 'A landscape certificate with the guest’s name, an award line, a round photo, a seal and the date.' },\n        // Your own uploaded frames (see \"Frames with photo spots\" below). Shown once a frame is uploaded.\n        myframe: {\n          name: 'My frame', kind: 'frame', get shots() { var f = typeof activeFrame === 'function' ? activeFrame() : null; return f ? Math.max(1, frameShotCount(f)) : 1; },\n          hint: 'One of your frames on its own. Photos fill its white or see-through spots.'\n        },\n        framesheet: {\n          name: 'Frame collage', kind: 'frame', get shots() { return typeof sheetShots === 'function' ? sheetShots() : 1; },\n          hint: 'Two or more of your frames together on one sheet. Tick them below, choose the sheet size and an arrangement, then drag them in the preview.'\n        }\n      };\n      const LAYOUT_ORDER = ['strip', 'strip4', 'grid', 'grid4', 'hero', 'solo', 'duo', 'feature', 'film6', 'land3', 'land4', 'receipt', 'receipt1', 'receipt2', 'receipt4', 'receiptc', 'receipt1c', 'receipt2c', 'receipt4c'];\n      // The built-in layouts, plus your frames once at least one is uploaded.\n      function layoutOrder() {\n        var has = typeof myFrames !== 'undefined' && myFrames && myFrames.length;\n        // No frames yet: one \"My frame\" card that opens the upload (not two look-alike cards).\n        return has ? ['myframe', 'framesheet'].concat(LAYOUT_ORDER) : LAYOUT_ORDER.concat(['myframe']);\n      }\n      function layoutDef(key) { return LAYOUT_DEFS[key || currentLayout] || LAYOUT_DEFS.strip; }\n      function isStripLayout(key) {\n        var k = key || currentLayout, d = layoutDef(k);\n        if (d.kind === 'frame') {\n          var f = k === 'myframe' && typeof activeFrame === 'function' ? activeFrame() : null;\n          return !!f && f.w / f.h < 0.45;      // a 2x6-style frame prints two side by side\n        }\n        return d.kind === 'strip';\n      }\n\n      const LAYOUTS = {\n        strip: { w: STRIP_W, contentH: STRIP_CONTENT_H, render: (ctx, shots, W, H) => renderStrip(ctx, shots, W, H, 3, STRIP_PHOTO) },\n        strip4: { w: STRIP_W, contentH: STRIP4_CONTENT_H, render: (ctx, shots, W, H) => renderStrip(ctx, shots, W, H, 4, STRIP4_PHOTO) },\n        grid: { w: GRID_W, contentH: GRID_H, render: renderGrid }\n      };\n      function shotsNeeded(layoutKey) {\n        if (/^sheet:/.test(layoutKey) && typeof presetById === 'function') {\n          return presetShotCount(presetById(layoutKey.slice(6)));\n        }\n        return layoutDef(layoutKey).shots;\n      }\n      // A custom photo can only sit in its own band/side on layouts built for it;\n      // everywhere else it becomes the full background.\n      function placement(layoutKey) {\n        return layoutDef(layoutKey).bandOk ? photoPlacement : 'background';\n      }\n      const LABEL_BAND_RATIO = 0.16; // relative to canvas width\n\n      let state = 'idle'; // idle | capturing | result\n      let currentLayout = 'strip';\n      // Booth type (top of Setup): the normal photo booth, a trading card booth or a certificate booth.\n      var boothType = 'photo';                      // 'photo' | 'card' | 'cert'\n      var photoLayoutMemo = 'strip';                // the photo layout to go back to\n      var btCfg = {\n        card: { style: 'fire', stats: true, tpl: null, pick: false, builtin: true, back: { on: false, print: true }, qs: ['', '', ''] },\n        cert: { style: 'gold', title: 'Certificate of Achievement', lead: 'is proudly presented to', msg: '', signer: '', role: '', askAward: true, tpl: null, pick: false, builtin: true }\n      };\n      var guestInfo = { name: '', line: '' };       // what this guest typed (and the design they picked) for their card / certificate\n      var myTpls = [];                              // own card / certificate templates (uploaded PNGs with a photo window + text zones)\n      var MAX_TPLS = 30;\n      var tplEdit = null;                           // { id, sel } while a template is being edited in Setup\n      var btForce = null;                           // draws one design for a thumbnail\n      var btdOpen = false;                          // the name / title form is on screen\n      let backgroundImg = null;\n      let shotCanvases = new Array(shotsNeeded('strip')).fill(null);\n      let mainIndex = 0;\n      let streamActive = false;\n      let toastTimer = null;\n\n      // ---- Decorative clouds & stars (matches the dedication-template backdrop) ----\n      function drawStar(ctx, cx, cy, outerR, points, rotation, color, opacity) {\n        const innerR = outerR * 0.45;\n        ctx.save();\n        ctx.globalAlpha = opacity;\n        ctx.fillStyle = color;\n        ctx.translate(cx, cy);\n        ctx.rotate(rotation);\n        ctx.beginPath();\n        for (let i = 0; i < points * 2; i++) {\n          const r = (i % 2 === 0) ? outerR : innerR;\n          const angle = (Math.PI / points) * i;\n          const x = r * Math.sin(angle);\n          const y = -r * Math.cos(angle);\n          if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);\n        }\n        ctx.closePath();\n        ctx.fill();\n        ctx.restore();\n      }\n\n      function drawCloud(ctx, cx, cy, scale, color, opacity) {\n        ctx.save();\n        ctx.globalAlpha = opacity;\n        ctx.fillStyle = color;\n        ctx.beginPath();\n        ctx.arc(cx - 34 * scale, cy + 4 * scale, 17 * scale, 0, Math.PI * 2);\n        ctx.arc(cx - 12 * scale, cy - 10 * scale, 21 * scale, 0, Math.PI * 2);\n        ctx.arc(cx + 14 * scale, cy - 8 * scale, 19 * scale, 0, Math.PI * 2);\n        ctx.arc(cx + 36 * scale, cy + 5 * scale, 15 * scale, 0, Math.PI * 2);\n        ctx.arc(cx + 2 * scale, cy + 10 * scale, 23 * scale, 0, Math.PI * 2);\n        ctx.closePath();\n        ctx.fill();\n        ctx.restore();\n      }\n\n      // Relative (0-1) positions so decorations scale to any canvas size/layout.\n      const STAR_SPOTS = [\n        { x: 0.06, y: 0.05, r: 0.020, rot: 0.2 }, { x: 0.15, y: 0.11, r: 0.013, rot: -0.4 },\n        { x: 0.90, y: 0.06, r: 0.017, rot: 0.5 }, { x: 0.95, y: 0.16, r: 0.012, rot: -0.2 },\n        { x: 0.04, y: 0.32, r: 0.011, rot: 0.3 }, { x: 0.08, y: 0.55, r: 0.015, rot: -0.5 },\n        { x: 0.92, y: 0.40, r: 0.013, rot: 0.4 }, { x: 0.05, y: 0.78, r: 0.017, rot: 0.1 },\n        { x: 0.93, y: 0.75, r: 0.014, rot: -0.3 }, { x: 0.88, y: 0.92, r: 0.018, rot: 0.25 },\n        { x: 0.10, y: 0.94, r: 0.012, rot: -0.15 }, { x: 0.5, y: 0.05, r: 0.010, rot: 0.3 }\n      ];\n      const CLOUD_SPOTS = [\n        { x: 0.10, y: 0.16, scale: 0.9 }, { x: 0.90, y: 0.22, scale: 1.05 },\n        { x: 0.06, y: 0.62, scale: 0.8 }, { x: 0.94, y: 0.60, scale: 0.95 },\n        { x: 0.14, y: 0.90, scale: 0.85 }, { x: 0.86, y: 0.10, scale: 0.7 }\n      ];\n\n      function drawDecorations(ctx, w, h, P) {\n        P = P || DEFAULT_PAL;\n        const shortSide = Math.min(w, h);\n        CLOUD_SPOTS.forEach(c => drawCloud(ctx, c.x * w, c.y * h, c.scale * (shortSide / 700), P.cloud, P.cloudOp));\n        STAR_SPOTS.forEach(s => drawStar(ctx, s.x * w, s.y * h, s.r * shortSide, 5, s.rot, P.gold, 0.85));\n      }\n\n      // ---- Backdrop presets (drawn procedurally, no external images needed) ----\n      function seededRand(seed) {\n        let s = seed % 2147483647;\n        if (s <= 0) s += 2147483646;\n        return function () {\n          s = (s * 16807) % 2147483647;\n          return (s - 1) / 2147483646;\n        };\n      }\n\n      // ---- Backdrop palettes. DEFAULT_PAL is each style's original look; picking a\n      // Backdrop color builds a matching palette so the same generic decorations\n      // (glitter flecks, clouds, stars, speckle) are drawn on top of any color. ----\n      function hexToRgb(hex) {\n        hex = String(hex).replace('#', '');\n        if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');\n        const n = parseInt(hex, 16);\n        return [(n >> 16) & 255, (n >> 8) & 255, n & 255];\n      }\n      function rgbToHex(r, g, b) {\n        return '#' + [r, g, b].map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');\n      }\n      function mixHex(a, b, t) {\n        const A = hexToRgb(a), B = hexToRgb(b);\n        return rgbToHex(A[0] + (B[0] - A[0]) * t, A[1] + (B[1] - A[1]) * t, A[2] + (B[2] - A[2]) * t);\n      }\n      function lumOf(hex) {\n        const c = hexToRgb(hex);\n        return (0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]) / 255;\n      }\n      function colorDist(a, b) {\n        const A = hexToRgb(a), B = hexToRgb(b);\n        return Math.sqrt((A[0] - B[0]) ** 2 + (A[1] - B[1]) ** 2 + (A[2] - B[2]) ** 2);\n      }\n\n      const DEFAULT_PAL = {\n        g5: ['#8a6a24', '#d9ae52', '#f6e3a1', '#caa24a', '#7a5c1e'],  // gold glitter gradient\n        sky3: ['#bfe0f7', '#e6f4ff', '#fdf6ee'],\n        night2: ['#0b0d1a', '#1c2038'],\n        cream2: ['#faf3e6', '#f0e2c6'],\n        maroon3: ['#3f0a1a', '#7a1f3d', '#521128'],\n        fleck: '#fff9dd', big: '#ffffff', cross: '#fffdf2',\n        cloud: '#ffffff', cloudOp: 0.55,\n        gold: '#f0c869', dot: '#ffffff', speck: '#c9a86a'\n      };\n      // Party colors for confetti / balloons / butterflies: bright pastels on dark\n      // backdrops, richer tones on light ones so they still show.\n      const FESTIVE_ON_DARK = ['#f7b6c8', '#ffe08a', '#a9d4f5', '#bfe8d2', '#d6c3f5', '#ffc9a3', '#f0c869'];\n      const FESTIVE_ON_LIGHT = ['#e5708f', '#e2a92c', '#4f9fd6', '#4fb98a', '#9a7ad6', '#f08a4b', '#b8963e'];\n\n      let palCache = { color: null, pal: null };\n      function buildPalette(base) {\n        if (palCache.color === base) return palCache.pal;\n        const lum = lumOf(base);\n        const isLight = lum > 0.72, isDark = lum < 0.35;\n        const k = isLight ? 0.16 : 0.4;\n        const shade = (amt) => mixHex(base, '#000000', amt);\n        const tint = (amt) => mixHex(base, '#ffffff', amt);\n        const goldOk = colorDist('#f0c869', base) > 90;\n        const pal = {\n          g5: [shade(k), tint(0.12), tint(isLight ? 0.5 : 0.55), shade(0.06), shade(k * 1.15)],\n          sky3: isDark ? [shade(0.3), base, tint(0.2)] : [base, tint(0.55), tint(0.85)],\n          night2: [shade(isLight ? 0.2 : 0.45), isLight ? base : tint(0.08)],\n          cream2: [tint(0.2), shade(0.05)],\n          // sparkle tones: bright tints on mid/dark colors, darker tones on very light ones\n          fleck: isLight ? shade(0.28) : tint(0.88),\n          big: isLight ? shade(0.42) : '#ffffff',\n          cross: isLight ? shade(0.5) : tint(0.95),\n          cloud: isDark ? '#ffffff' : '#ffffff',\n          cloudOp: isDark ? 0.2 : (isLight ? 0.7 : 0.5),\n          gold: goldOk ? '#f0c869' : (isLight ? shade(0.45) : '#ffffff'),\n          dot: isLight ? shade(0.4) : '#ffffff',\n          speck: isLight ? shade(0.32) : (isDark ? tint(0.55) : shade(0.28)),\n          maroon3: [shade(0.35), base, shade(0.2)],\n          // used by the newer Elements sets (hearts, florals, bokeh, ...)\n          accent: isLight ? shade(0.25) : (isDark ? tint(0.45) : tint(0.6)),\n          accent2: isLight ? shade(0.45) : tint(0.88),\n          glow: isLight ? shade(0.15) : '#ffffff',\n          festive: lum > 0.6 ? FESTIVE_ON_LIGHT : FESTIVE_ON_DARK,\n          petal: isLight ? mixHex(shade(0.15), '#e58ba3', 0.55) : tint(0.8),\n          petal2: isLight ? mixHex(shade(0.1), '#f3d58a', 0.5) : mixHex(tint(0.7), '#f7b6c8', 0.45),\n          center: '#e2b543',\n          leaf: mixHex('#6f9a6a', base, 0.2),\n          snow: isLight ? shade(0.35) : '#ffffff',\n          light: isLight\n        };\n        palCache = { color: base, pal: pal };\n        return pal;\n      }\n\n      // ---- Backdrops = a base fill + an Elements set drawn on top ----\n      // Each preset has its own fill and its own default elements (\"Auto\"). The\n      // Elements picker can swap in any other set, drawn over the same fill (and\n      // over any picked Backdrop color), so looks can be mixed and matched.\n\n      // Base fills\n      function fillGold(ctx, w, h, P) {\n        const g = ctx.createLinearGradient(0, 0, w, h);\n        g.addColorStop(0, P.g5[0]);\n        g.addColorStop(0.35, P.g5[1]);\n        g.addColorStop(0.6, P.g5[2]);\n        g.addColorStop(0.8, P.g5[3]);\n        g.addColorStop(1, P.g5[4]);\n        ctx.fillStyle = g;\n        ctx.fillRect(0, 0, w, h);\n      }\n      function fillSky(ctx, w, h, P) {\n        const g = ctx.createLinearGradient(0, 0, 0, h);\n        g.addColorStop(0, P.sky3[0]);\n        g.addColorStop(0.55, P.sky3[1]);\n        g.addColorStop(1, P.sky3[2]);\n        ctx.fillStyle = g;\n        ctx.fillRect(0, 0, w, h);\n      }\n      function fillNight(ctx, w, h, P) {\n        const g = ctx.createLinearGradient(0, 0, 0, h);\n        g.addColorStop(0, P.night2[0]);\n        g.addColorStop(1, P.night2[1]);\n        ctx.fillStyle = g;\n        ctx.fillRect(0, 0, w, h);\n      }\n      function fillCream(ctx, w, h, P) {\n        const g = ctx.createLinearGradient(0, 0, w, h);\n        g.addColorStop(0, P.cream2[0]);\n        g.addColorStop(1, P.cream2[1]);\n        ctx.fillStyle = g;\n        ctx.fillRect(0, 0, w, h);\n      }\n      function fillMaroon(ctx, w, h, P) {\n        const g = ctx.createLinearGradient(0, 0, w, h);\n        g.addColorStop(0, P.maroon3[0]);\n        g.addColorStop(0.5, P.maroon3[1]);\n        g.addColorStop(1, P.maroon3[2]);\n        ctx.fillStyle = g;\n        ctx.fillRect(0, 0, w, h);\n      }\n\n      // Elements: the four original sets (unchanged output) ...\n      function drawGlitterElements(ctx, w, h, P) {\n        const rand = seededRand(42);\n        // Denser, more visible glitter — a fine speckle layer plus larger bright flecks.\n        const count = Math.round((w * h) / 900);\n        for (let i = 0; i < count; i++) {\n          const x = rand() * w, y = rand() * h;\n          const r = rand() * 1.8 + 0.4;\n          ctx.globalAlpha = rand() * 0.65 + 0.35;\n          ctx.fillStyle = P.fleck;\n          ctx.beginPath();\n          ctx.arc(x, y, r, 0, Math.PI * 2);\n          ctx.fill();\n        }\n        const bigCount = Math.round((w * h) / 9000);\n        for (let i = 0; i < bigCount; i++) {\n          const x = rand() * w, y = rand() * h;\n          const r = rand() * 2.6 + 1.6;\n          ctx.globalAlpha = rand() * 0.5 + 0.5;\n          ctx.fillStyle = P.big;\n          ctx.beginPath();\n          ctx.arc(x, y, r, 0, Math.PI * 2);\n          ctx.fill();\n          // small sparkle cross for a few of the larger flecks\n          if (rand() > 0.5) {\n            ctx.strokeStyle = P.cross;\n            ctx.lineWidth = Math.max(0.6, r * 0.25);\n            ctx.beginPath();\n            ctx.moveTo(x - r * 2.2, y); ctx.lineTo(x + r * 2.2, y);\n            ctx.moveTo(x, y - r * 2.2); ctx.lineTo(x, y + r * 2.2);\n            ctx.stroke();\n          }\n        }\n        ctx.globalAlpha = 1;\n      }\n\n      function drawGoldStarElements(ctx, w, h, P) {\n        const rand = seededRand(7);\n        for (let i = 0; i < 36; i++) {\n          const x = rand() * w, y = rand() * h;\n          const r = rand() * (Math.min(w, h) * 0.012) + Math.min(w, h) * 0.003;\n          drawStar(ctx, x, y, r, 4, rand() * Math.PI, P.gold, rand() * 0.5 + 0.45);\n        }\n        for (let i = 0; i < 80; i++) {\n          const x = rand() * w, y = rand() * h;\n          ctx.globalAlpha = rand() * 0.6 + 0.2;\n          ctx.fillStyle = P.dot;\n          ctx.beginPath();\n          ctx.arc(x, y, rand() * 1.1 + 0.3, 0, Math.PI * 2);\n          ctx.fill();\n        }\n        ctx.globalAlpha = 1;\n      }\n\n      function drawSpeckleElements(ctx, w, h, P) {\n        const rand = seededRand(19);\n        // Fine speckle layer, like the visible grain in Gold Glitter / Pastel Sky.\n        const speckleCount = Math.round((w * h) / 1400);\n        for (let i = 0; i < speckleCount; i++) {\n          const x = rand() * w, y = rand() * h;\n          ctx.globalAlpha = rand() * 0.35 + 0.15;\n          ctx.fillStyle = P.speck;\n          ctx.beginPath();\n          ctx.arc(x, y, rand() * 1.1 + 0.3, 0, Math.PI * 2);\n          ctx.fill();\n        }\n        // Bigger soft dot clusters for visible texture, not just a hint of one.\n        for (let i = 0; i < 26; i++) {\n          const x = rand() * w, y = rand() * h;\n          ctx.globalAlpha = rand() * 0.25 + 0.3;\n          ctx.fillStyle = P.speck;\n          ctx.beginPath();\n          ctx.arc(x, y, rand() * 3.4 + 1.5, 0, Math.PI * 2);\n          ctx.fill();\n        }\n        // A few tiny accent stars, echoing Pastel Sky's decorations.\n        for (let i = 0; i < 10; i++) {\n          const x = rand() * w, y = rand() * h;\n          const r = rand() * (Math.min(w, h) * 0.01) + Math.min(w, h) * 0.004;\n          drawStar(ctx, x, y, r, 5, rand() * Math.PI, P.speck, rand() * 0.35 + 0.4);\n        }\n        ctx.globalAlpha = 0.5;\n        ctx.strokeStyle = P.speck;\n        ctx.lineWidth = Math.max(1, w * 0.0015);\n        ctx.beginPath();\n        ctx.arc(w * 0.5, h * 0.08, w * 0.14, Math.PI * 0.15, Math.PI * 0.85);\n        ctx.stroke();\n        ctx.beginPath();\n        ctx.arc(w * 0.5, h * 0.97, w * 0.14, Math.PI * 1.15, Math.PI * 1.85);\n        ctx.stroke();\n        ctx.globalAlpha = 1;\n      }\n\n      // ... and the new sets. Sizes follow the canvas's short side, and counts\n      // follow its area, so they look the same on the strip, grid and previews.\n      function elCount(w, h, perSquare) {\n        const S = Math.min(w, h);\n        return Math.max(4, Math.round(perSquare * (w * h) / (S * S)));\n      }\n      // Photos cover most of the canvas, so most decorations go where they show:\n      // the side and top borders and the caption area at the bottom.\n      function visiblePos(rand, w, h) {\n        const band = Math.min(w, h) * 0.06, r = rand();\n        if (r < 0.4) return [rand() < 0.5 ? rand() * band : w - rand() * band, rand() * h];\n        if (r < 0.6) return [rand() * w, rand() * band];\n        if (r < 0.85) return [rand() * w, h - rand() * h * 0.12];\n        return [rand() * w, rand() * h];\n      }\n\n      function heartPath(ctx, s) {\n        const t = s / 2;\n        ctx.beginPath();\n        ctx.moveTo(0, t * 0.75);\n        ctx.bezierCurveTo(-t * 1.25, -t * 0.1, -t * 0.65, -t * 1.15, 0, -t * 0.4);\n        ctx.bezierCurveTo(t * 0.65, -t * 1.15, t * 1.25, -t * 0.1, 0, t * 0.75);\n        ctx.closePath();\n      }\n      function drawHeartElements(ctx, w, h, P) {\n        const rand = seededRand(101), S = Math.min(w, h);\n        const n = elCount(w, h, 16);\n        for (let i = 0; i < n; i++) {\n          const s = S * (rand() * 0.05 + 0.03);\n          ctx.save();\n          ctx.translate(...visiblePos(rand, w, h));\n          ctx.rotate((rand() - 0.5) * 0.8);\n          ctx.globalAlpha = rand() * 0.4 + 0.45;\n          ctx.fillStyle = i % 3 === 0 ? P.accent2 : P.accent;\n          heartPath(ctx, s);\n          ctx.fill();\n          ctx.restore();\n        }\n        // tiny hearts as filler\n        for (let i = 0; i < n * 2; i++) {\n          const s = S * (rand() * 0.012 + 0.01);\n          ctx.save();\n          ctx.translate(...visiblePos(rand, w, h));\n          ctx.rotate((rand() - 0.5) * 0.8);\n          ctx.globalAlpha = rand() * 0.35 + 0.35;\n          ctx.fillStyle = P.accent2;\n          heartPath(ctx, s);\n          ctx.fill();\n          ctx.restore();\n        }\n        ctx.globalAlpha = 1;\n      }\n\n      function drawConfettiElements(ctx, w, h, P) {\n        const rand = seededRand(202), S = Math.min(w, h);\n        const n = elCount(w, h, 90);\n        for (let i = 0; i < n; i++) {\n          const [x, y] = visiblePos(rand, w, h);\n          ctx.save();\n          ctx.translate(x, y);\n          ctx.rotate(rand() * Math.PI);\n          ctx.globalAlpha = rand() * 0.3 + 0.7;\n          ctx.fillStyle = P.festive[Math.floor(rand() * P.festive.length)];\n          const kind = rand();\n          if (kind < 0.55) {\n            const cw = S * (rand() * 0.008 + 0.008);\n            ctx.fillRect(-cw / 2, -cw, cw, cw * 2);\n          } else if (kind < 0.85) {\n            ctx.beginPath();\n            ctx.arc(0, 0, S * (rand() * 0.005 + 0.004), 0, Math.PI * 2);\n            ctx.fill();\n          } else {\n            // little curly streamer\n            ctx.strokeStyle = ctx.fillStyle;\n            ctx.lineWidth = S * 0.004;\n            ctx.lineCap = 'round';\n            const L = S * 0.02;\n            ctx.beginPath();\n            ctx.moveTo(-L, 0);\n            ctx.bezierCurveTo(-L / 2, -L / 2, 0, L / 2, L / 2, 0);\n            ctx.stroke();\n          }\n          ctx.restore();\n        }\n        ctx.globalAlpha = 1;\n      }\n\n      function drawBokehElements(ctx, w, h, P) {\n        const rand = seededRand(303), S = Math.min(w, h);\n        const n = elCount(w, h, 12);\n        // white glow reads on every color; light backdrops also get soft color dots\n        const tones = P.light ? ['#ffffff', P.festive[0], '#ffffff', P.festive[2]] : [P.glow, P.accent, P.glow, P.accent2];\n        for (let i = 0; i < n; i++) {\n          const [x, y] = visiblePos(rand, w, h);\n          const r = S * (rand() * 0.09 + 0.03);\n          const c = hexToRgb(tones[i % tones.length]);\n          const g = ctx.createRadialGradient(x, y, 0, x, y, r);\n          const a = rand() * 0.25 + (P.light ? 0.35 : 0.25);\n          g.addColorStop(0, 'rgba(' + c.join(',') + ',' + a + ')');\n          g.addColorStop(0.7, 'rgba(' + c.join(',') + ',' + (a * 0.7) + ')');\n          g.addColorStop(1, 'rgba(' + c.join(',') + ',0)');\n          ctx.fillStyle = g;\n          ctx.beginPath();\n          ctx.arc(x, y, r, 0, Math.PI * 2);\n          ctx.fill();\n        }\n      }\n\n      function drawFlower(ctx, x, y, r, petals, rot, petal, center) {\n        ctx.save();\n        ctx.translate(x, y);\n        ctx.rotate(rot);\n        ctx.fillStyle = petal;\n        for (let i = 0; i < petals; i++) {\n          ctx.save();\n          ctx.rotate(i * Math.PI * 2 / petals);\n          ctx.beginPath();\n          ctx.ellipse(0, -r * 0.55, r * 0.32, r * 0.55, 0, 0, Math.PI * 2);\n          ctx.fill();\n          ctx.restore();\n        }\n        ctx.fillStyle = center;\n        ctx.beginPath();\n        ctx.arc(0, 0, r * 0.26, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.restore();\n      }\n      function drawLeaf(ctx, x, y, len, rot, color) {\n        ctx.save();\n        ctx.translate(x, y);\n        ctx.rotate(rot);\n        ctx.fillStyle = color;\n        ctx.beginPath();\n        ctx.moveTo(0, 0);\n        ctx.quadraticCurveTo(len * 0.5, -len * 0.35, len, 0);\n        ctx.quadraticCurveTo(len * 0.5, len * 0.35, 0, 0);\n        ctx.fill();\n        ctx.restore();\n      }\n      function drawFloralElements(ctx, w, h, P) {\n        const rand = seededRand(404), S = Math.min(w, h);\n        // Clusters in each corner, plus scattered small blooms.\n        const corners = [[0, 0], [w, 0], [0, h], [w, h]];\n        corners.forEach(([cx, cy], ci) => {\n          const dx = cx ? -1 : 1, dy = cy ? -1 : 1;\n          for (let k = 0; k < 4; k++) {\n            const lx = cx + dx * S * (rand() * 0.12 + 0.02), ly = cy + dy * S * (rand() * 0.12 + 0.02);\n            ctx.globalAlpha = 0.8;\n            drawLeaf(ctx, lx, ly, S * (rand() * 0.06 + 0.07), rand() * Math.PI * 2, P.leaf);\n          }\n          for (let k = 0; k < 3; k++) {\n            const fx = cx + dx * S * (rand() * 0.12 + 0.03), fy = cy + dy * S * (rand() * 0.12 + 0.03);\n            ctx.globalAlpha = 0.92;\n            drawFlower(ctx, fx, fy, S * (rand() * 0.035 + 0.04), 5, rand() * Math.PI, (k + ci) % 2 ? P.petal : P.petal2, P.center);\n          }\n        });\n        const n = elCount(w, h, 10);\n        for (let i = 0; i < n; i++) {\n          const [x, y] = visiblePos(rand, w, h);\n          ctx.globalAlpha = rand() * 0.3 + 0.55;\n          drawLeaf(ctx, x, y, S * 0.045, rand() * Math.PI * 2, P.leaf);\n          drawFlower(ctx, x, y, S * (rand() * 0.015 + 0.02), 5, rand() * Math.PI, i % 2 ? P.petal : P.petal2, P.center);\n        }\n        ctx.globalAlpha = 1;\n      }\n\n      function drawBalloon(ctx, x, y, rx, color, stringColor, sway) {\n        const ry = rx * 1.22;\n        // string\n        ctx.strokeStyle = stringColor;\n        ctx.lineWidth = Math.max(1, rx * 0.05);\n        ctx.globalAlpha = 0.6;\n        ctx.beginPath();\n        ctx.moveTo(x, y + ry);\n        ctx.bezierCurveTo(x + sway, y + ry * 1.8, x - sway, y + ry * 2.4, x + sway * 0.5, y + ry * 3.2);\n        ctx.stroke();\n        // body\n        ctx.globalAlpha = 0.95;\n        ctx.fillStyle = color;\n        ctx.beginPath();\n        ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);\n        ctx.fill();\n        // knot\n        ctx.beginPath();\n        ctx.moveTo(x, y + ry * 0.96);\n        ctx.lineTo(x - rx * 0.14, y + ry * 1.12);\n        ctx.lineTo(x + rx * 0.14, y + ry * 1.12);\n        ctx.closePath();\n        ctx.fill();\n        // shine\n        ctx.globalAlpha = 0.4;\n        ctx.fillStyle = '#ffffff';\n        ctx.beginPath();\n        ctx.ellipse(x - rx * 0.38, y - ry * 0.38, rx * 0.18, ry * 0.28, -0.5, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.globalAlpha = 1;\n      }\n      function drawBalloonElements(ctx, w, h, P) {\n        const rand = seededRand(505), S = Math.min(w, h);\n        // Bunches at the top corners, a few floating along the sides.\n        const spots = [\n          [0.07, 0.05], [0.16, 0.035], [0.11, 0.09], [0.93, 0.05], [0.84, 0.035], [0.89, 0.09],\n          [0.05, 0.4], [0.95, 0.55], [0.06, 0.72], [0.94, 0.85], [0.5, 0.025]\n        ];\n        spots.forEach(([fx, fy], i) => {\n          drawBalloon(ctx, fx * w, fy * h, S * (rand() * 0.02 + 0.035), P.festive[i % P.festive.length], P.accent2, S * 0.012 * (rand() - 0.5) * 2);\n        });\n      }\n\n      function drawButterfly(ctx, x, y, s, rot, c1, c2, body) {\n        ctx.save();\n        ctx.translate(x, y);\n        ctx.rotate(rot);\n        [-1, 1].forEach(side => {\n          ctx.fillStyle = c1;\n          ctx.beginPath();\n          ctx.ellipse(side * s * 0.5, -s * 0.28, s * 0.5, s * 0.36, side * 0.5, 0, Math.PI * 2);\n          ctx.fill();\n          ctx.fillStyle = c2;\n          ctx.beginPath();\n          ctx.ellipse(side * s * 0.36, s * 0.3, s * 0.32, s * 0.26, -side * 0.5, 0, Math.PI * 2);\n          ctx.fill();\n        });\n        ctx.fillStyle = body;\n        ctx.beginPath();\n        ctx.ellipse(0, 0, s * 0.07, s * 0.5, 0, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.strokeStyle = body;\n        ctx.lineWidth = Math.max(1, s * 0.04);\n        ctx.beginPath();\n        ctx.moveTo(0, -s * 0.45); ctx.quadraticCurveTo(-s * 0.1, -s * 0.75, -s * 0.25, -s * 0.8);\n        ctx.moveTo(0, -s * 0.45); ctx.quadraticCurveTo(s * 0.1, -s * 0.75, s * 0.25, -s * 0.8);\n        ctx.stroke();\n        ctx.restore();\n      }\n      function drawButterflyElements(ctx, w, h, P) {\n        const rand = seededRand(606), S = Math.min(w, h);\n        const n = elCount(w, h, 9);\n        for (let i = 0; i < n; i++) {\n          ctx.globalAlpha = rand() * 0.3 + 0.6;\n          const c = P.festive[Math.floor(rand() * P.festive.length)];\n          const [bx, by] = visiblePos(rand, w, h);\n          drawButterfly(ctx, bx, by, S * (rand() * 0.03 + 0.03), (rand() - 0.5) * 1.2, c, mixHex(c, '#ffffff', 0.35), P.accent2);\n        }\n        ctx.globalAlpha = 1;\n      }\n\n      function drawSnowflake(ctx, x, y, r, rot, color) {\n        ctx.save();\n        ctx.translate(x, y);\n        ctx.rotate(rot);\n        ctx.strokeStyle = color;\n        ctx.lineWidth = Math.max(1, r * 0.09);\n        ctx.lineCap = 'round';\n        for (let i = 0; i < 6; i++) {\n          ctx.rotate(Math.PI / 3);\n          ctx.beginPath();\n          ctx.moveTo(0, 0); ctx.lineTo(0, -r);\n          ctx.moveTo(0, -r * 0.55); ctx.lineTo(-r * 0.25, -r * 0.78);\n          ctx.moveTo(0, -r * 0.55); ctx.lineTo(r * 0.25, -r * 0.78);\n          ctx.stroke();\n        }\n        ctx.restore();\n      }\n      function drawSnowflakeElements(ctx, w, h, P) {\n        const rand = seededRand(707), S = Math.min(w, h);\n        const n = elCount(w, h, 14);\n        for (let i = 0; i < n; i++) {\n          ctx.globalAlpha = rand() * 0.35 + 0.5;\n          const [sx, sy] = visiblePos(rand, w, h);\n          drawSnowflake(ctx, sx, sy, S * (rand() * 0.03 + 0.015), rand() * Math.PI, P.snow);\n        }\n        // soft snow dots\n        for (let i = 0; i < n * 5; i++) {\n          ctx.globalAlpha = rand() * 0.4 + 0.3;\n          ctx.fillStyle = P.snow;\n          ctx.beginPath();\n          const [dx, dy] = visiblePos(rand, w, h);\n          ctx.arc(dx, dy, S * (rand() * 0.004 + 0.002), 0, Math.PI * 2);\n          ctx.fill();\n        }\n        ctx.globalAlpha = 1;\n      }\n\n      const ELEMENT_SETS = {\n        none: null,\n        glitter: drawGlitterElements,\n        clouds: drawDecorations,\n        goldstars: drawGoldStarElements,\n        speckle: drawSpeckleElements,\n        hearts: drawHeartElements,\n        confetti: drawConfettiElements,\n        bokeh: drawBokehElements,\n        florals: drawFloralElements,\n        balloons: drawBalloonElements,\n        butterflies: drawButterflyElements,\n        snowflakes: drawSnowflakeElements\n      };\n      const ELEMENT_OPTIONS = [\n        ['auto', 'Auto'], ['none', 'None'], ['glitter', 'Glitter'], ['clouds', 'Clouds & stars'],\n        ['goldstars', 'Gold stars'], ['speckle', 'Speckle'], ['hearts', 'Hearts'], ['confetti', 'Confetti'],\n        ['bokeh', 'Bokeh'], ['florals', 'Florals'], ['balloons', 'Balloons'], ['butterflies', 'Butterflies'],\n        ['snowflakes', 'Snowflakes']\n      ];\n\n      // Maroon & Gold: deep maroon with gold glitter.\n      const MAROON_PAL = Object.assign({}, DEFAULT_PAL, {\n        fleck: '#f3d58a', big: '#ffe7a3', cross: '#fff1c2'\n      });\n      const BACKDROP_PRESETS = {\n        gold: { fill: fillGold, elements: 'glitter', base: '#d9ae52' },\n        sky: { fill: fillSky, elements: 'clouds', base: '#cfe8fa' },\n        stars: { fill: fillNight, elements: 'goldstars', base: '#12152a' },\n        cream: { fill: fillCream, elements: 'speckle', base: '#f5ead6' },\n        maroon: { fill: fillMaroon, elements: 'glitter', base: '#6b1a2b', pal: MAROON_PAL }\n      };\n\n      // ---- Theme backdrops (drawn in code, so they print sharp at any size).\n      // Each reads backdropColor first, so picking a Backdrop color recolors the\n      // base while keeping the pattern. ----\n      function themeBase(def) { return backdropColor || def; }\n      // Pattern / accent color used by the theme artwork (Setup -> Backdrop -> Pattern color).\n      var accent = 'gold';\n      var ACCENTS = {\n        gold: ['#a8792a', '#e8c873', '#fff1c4', '#d9b25c', '#a8792a'],\n        silver: ['#7d8288', '#c9ced3', '#f7f9fb', '#aeb4ba', '#7d8288'],\n        rosegold: ['#a5645a', '#e3a99c', '#fde3dc', '#cf8d80', '#a5645a'],\n        champagne: ['#9e8a6a', '#dccbaa', '#fff7e6', '#c9b48e', '#9e8a6a'],\n        white: ['#d6d6d6', '#ffffff', '#ffffff', '#f0f0f0', '#d6d6d6'],\n        black: ['#000000', '#2b2b2b', '#4d4d4d', '#2b2b2b', '#000000']\n      };\n      var accentUsed = false, previewUsesAccent = true;   // did the last Setup preview draw any gold details?\n      function goldGrad(ctx, x0, y0, x1, y1) {\n        accentUsed = true;\n        var c = ACCENTS[accent] || ACCENTS.gold;\n        var g = ctx.createLinearGradient(x0, y0, x1, y1);\n        g.addColorStop(0, c[0]); g.addColorStop(0.3, c[1]); g.addColorStop(0.5, c[2]);\n        g.addColorStop(0.7, c[3]); g.addColorStop(1, c[4]);\n        return g;\n      }\n      function vGrad(ctx, h, a, b) { var g = ctx.createLinearGradient(0, 0, 0, h); g.addColorStop(0, a); g.addColorStop(1, b); return g; }\n\n      // Gold chevron on ivory\n      function fillChevron(ctx, w, h) {\n        var base = themeBase('#fbf7ef');\n        ctx.fillStyle = vGrad(ctx, h, mixHex(base, '#ffffff', 0.4), mixHex(base, '#e9dcc0', 0.35)); ctx.fillRect(0, 0, w, h);\n        var period = w / 7, amp = period * 0.32, gap = period * 0.62;\n        ctx.save(); ctx.lineJoin = 'miter'; ctx.lineCap = 'butt';\n        ctx.strokeStyle = goldGrad(ctx, 0, 0, w, h); ctx.globalAlpha = 0.5; ctx.lineWidth = Math.max(2, w * 0.011);\n        for (var y = -amp; y < h + amp; y += gap) {\n          ctx.beginPath();\n          for (var x = -period, i = 0; x <= w + period; x += period / 2, i++) {\n            var yy = y + (i % 2 ? amp : 0);\n            if (i === 0) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);\n          }\n          ctx.stroke();\n        }\n        ctx.restore();\n      }\n\n      // Art deco: navy with gold sunburst corners and a double gold border\n      function fillDeco(ctx, w, h) {\n        var base = themeBase('#13213f');\n        ctx.fillStyle = vGrad(ctx, h, mixHex(base, '#000000', 0.05), mixHex(base, '#000000', 0.35)); ctx.fillRect(0, 0, w, h);\n        var gold = goldGrad(ctx, 0, 0, w, h), u = Math.min(w, h);\n        ctx.save();\n        ctx.strokeStyle = gold; ctx.globalAlpha = 0.07; ctx.lineWidth = Math.max(1, u * 0.002);\n        for (var x = w / 28; x < w; x += w / 14) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke(); }\n        ctx.globalAlpha = 0.9;\n        var m1 = u * 0.03, m2 = u * 0.045;\n        ctx.lineWidth = Math.max(2, u * 0.006); ctx.strokeRect(m1, m1, w - 2 * m1, h - 2 * m1);\n        ctx.lineWidth = Math.max(1, u * 0.0025); ctx.strokeRect(m2, m2, w - 2 * m2, h - 2 * m2);\n        var R = u * 0.26;\n        [[m2, m2, 0], [w - m2, m2, Math.PI / 2], [w - m2, h - m2, Math.PI], [m2, h - m2, Math.PI * 1.5]].forEach(function (c) {\n          ctx.save(); ctx.translate(c[0], c[1]); ctx.rotate(c[2]);\n          ctx.lineWidth = Math.max(1, u * 0.003);\n          for (var r = R * 0.35; r <= R; r += R * 0.16) { ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI / 2); ctx.stroke(); }\n          for (var k = 0; k <= 9; k++) {\n            var a = (Math.PI / 2) * (k / 9);\n            ctx.beginPath(); ctx.moveTo(Math.cos(a) * R * 0.18, Math.sin(a) * R * 0.18); ctx.lineTo(Math.cos(a) * R, Math.sin(a) * R); ctx.stroke();\n          }\n          ctx.fillStyle = gold; ctx.beginPath(); ctx.arc(0, 0, R * 0.12, 0, Math.PI / 2); ctx.lineTo(0, 0); ctx.fill();\n          ctx.restore();\n        });\n        ctx.restore();\n      }\n\n      // Confetti helper: dots and foil strips, thicker toward the top and bottom edges\n      function scatterConfetti(ctx, w, h, colors, count, seed, gold) {\n        var rand = seededRand(seed), u = Math.min(w, h);\n        for (var i = 0; i < count; i++) {\n          var top = rand() < 0.5, t = Math.pow(rand(), 1.8);\n          // top edge, or the area just above the event name (kept clear so it stays readable)\n          var x = rand() * w, y = top ? t * h * 0.42 : h * 0.86 - t * h * 0.34;\n          var r = u * (0.004 + rand() * 0.012);\n          ctx.globalAlpha = 0.65 + rand() * 0.35;\n          ctx.fillStyle = gold && rand() < 0.7 ? goldGrad(ctx, x - r, y - r, x + r, y + r) : colors[Math.floor(rand() * colors.length)];\n          if (rand() < 0.72) { ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill(); }\n          else { ctx.save(); ctx.translate(x, y); ctx.rotate(rand() * Math.PI); ctx.fillRect(-r * 1.6, -r * 0.45, r * 3.2, r * 0.9); ctx.restore(); }\n        }\n        ctx.globalAlpha = 1;\n      }\n      function fillBlackGold(ctx, w, h) {\n        var base = themeBase('#141414');\n        var g = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.1, w / 2, h / 2, Math.max(w, h) * 0.75);\n        g.addColorStop(0, mixHex(base, '#ffffff', 0.06)); g.addColorStop(1, mixHex(base, '#000000', 0.6));\n        ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);\n        scatterConfetti(ctx, w, h, ['#f6e3a1', '#d4af37', '#fff6d6'], Math.round(w * h / 5200), 77, true);\n      }\n      function fillGoldConfetti(ctx, w, h) {\n        var base = themeBase('#fffdf8');\n        ctx.fillStyle = vGrad(ctx, h, base, mixHex(base, '#f3e7d3', 0.5)); ctx.fillRect(0, 0, w, h);\n        scatterConfetti(ctx, w, h, ['#f2c4ce', '#e9d8b4', '#f7dfe4', '#e6c27a'], Math.round(w * h / 5600), 91, true);\n      }\n\n      // White marble with grey and gold veins\n      function fillMarble(ctx, w, h) {\n        var base = themeBase('#f7f5f1');\n        ctx.fillStyle = vGrad(ctx, h, mixHex(base, '#ffffff', 0.5), mixHex(base, '#e7e3dc', 0.6)); ctx.fillRect(0, 0, w, h);\n        var rand = seededRand(1234), u = Math.min(w, h);\n        ctx.save(); ctx.lineCap = 'round';\n        for (var v = 0; v < 14; v++) {\n          var goldVein = v % 5 === 0;\n          ctx.strokeStyle = goldVein ? goldGrad(ctx, 0, 0, w, h) : 'rgba(150,145,138,1)';\n          ctx.globalAlpha = goldVein ? 0.75 : 0.12 + rand() * 0.2;\n          ctx.lineWidth = u * (goldVein ? 0.004 : 0.002 + rand() * 0.006);\n          var x = rand() * w, y = -h * 0.1, steps = 9;\n          ctx.beginPath(); ctx.moveTo(x, y);\n          for (var s = 0; s < steps; s++) {\n            var nx = x + (rand() - 0.35) * w * 0.35, ny = y + h * (0.1 + rand() * 0.16);\n            ctx.quadraticCurveTo(x + (rand() - 0.5) * w * 0.3, (y + ny) / 2, nx, ny);\n            x = nx; y = ny;\n          }\n          ctx.stroke();\n        }\n        ctx.restore();\n      }\n\n      // Blush stripes (hearts by default)\n      function fillBlushStripes(ctx, w, h) {\n        var base = themeBase('#fbe3e8');\n        var light = mixHex(base, '#ffffff', 0.6), sw = w / 14;\n        ctx.fillStyle = light; ctx.fillRect(0, 0, w, h);\n        ctx.fillStyle = base;\n        for (var x = 0; x < w; x += sw * 2) ctx.fillRect(x, 0, sw, h);\n      }\n      // Pastel party (balloons by default)\n      function fillPartyPastel(ctx, w, h) {\n        var base = themeBase('#e9dcff');\n        var g = ctx.createLinearGradient(0, 0, w, h);\n        g.addColorStop(0, base); g.addColorStop(0.55, mixHex(base, '#ffe6d6', 0.7)); g.addColorStop(1, mixHex(base, '#d8f3e6', 0.6));\n        ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);\n      }\n      // Christmas pine (snowflakes by default)\n      function fillPine(ctx, w, h) {\n        var base = themeBase('#174d39');\n        ctx.fillStyle = vGrad(ctx, h, mixHex(base, '#000000', 0.15), mixHex(base, '#000000', 0.45)); ctx.fillRect(0, 0, w, h);\n        var u = Math.min(w, h);\n        ctx.save(); ctx.strokeStyle = goldGrad(ctx, 0, 0, w, h); ctx.globalAlpha = 0.85;\n        var m = u * 0.022; ctx.lineWidth = Math.max(2, u * 0.005); ctx.strokeRect(m, m, w - 2 * m, h - 2 * m);\n        ctx.fillStyle = '#b3202b'; ctx.globalAlpha = 1;\n        var rand = seededRand(25);\n        for (var i = 0; i < 18; i++) {\n          var edge = i % 4, t = rand();\n          if (edge === 2) t = t < 0.5 ? t * 0.36 : 0.64 + (t - 0.5) * 0.72;   // bottom: keep the middle (under the event name) clear\n          var x = edge === 0 ? t * w : edge === 1 ? w - m : edge === 2 ? t * w : m;\n          var y = edge === 0 ? m : edge === 1 ? t * h : edge === 2 ? h - m : t * h;\n          ctx.beginPath(); ctx.arc(x, y, u * 0.012, 0, Math.PI * 2); ctx.fill();\n        }\n        ctx.restore();\n      }\n      // Midnight with soft gold bokeh (gold stars by default)\n      function fillMidnight(ctx, w, h) {\n        var base = themeBase('#141a3a');\n        ctx.fillStyle = vGrad(ctx, h, mixHex(base, '#000000', 0.25), mixHex(base, '#3a2a5a', 0.25)); ctx.fillRect(0, 0, w, h);\n        var rand = seededRand(808), u = Math.min(w, h);\n        for (var i = 0; i < 26; i++) {\n          var x = rand() * w, y = rand() * h, r = u * (0.03 + rand() * 0.07);\n          var g = ctx.createRadialGradient(x, y, 0, x, y, r);\n          g.addColorStop(0, 'rgba(255,214,130,' + (0.18 + rand() * 0.2) + ')'); g.addColorStop(1, 'rgba(255,214,130,0)');\n          ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();\n        }\n      }\n      // Rustic wood planks with warm string lights\n      function fillRustic(ctx, w, h) {\n        var base = themeBase('#8a5a2e');\n        var rand = seededRand(4242), plank = h / 9;\n        for (var i = 0; i * plank < h; i++) {\n          var tone = mixHex(base, i % 2 ? '#5a3618' : '#a4723f', 0.25 + rand() * 0.2);\n          ctx.fillStyle = vGrad(ctx, plank, tone, mixHex(tone, '#000000', 0.12));\n          ctx.save(); ctx.translate(0, i * plank); ctx.fillRect(0, 0, w, plank);\n          ctx.strokeStyle = 'rgba(40,22,8,.18)'; ctx.lineWidth = 1.2;\n          for (var k = 0; k < 6; k++) {\n            var yy = plank * (0.15 + rand() * 0.7);\n            ctx.beginPath(); ctx.moveTo(0, yy);\n            ctx.bezierCurveTo(w * 0.3, yy + (rand() - 0.5) * plank * 0.3, w * 0.7, yy + (rand() - 0.5) * plank * 0.3, w, yy);\n            ctx.stroke();\n          }\n          ctx.fillStyle = 'rgba(20,10,2,.45)'; ctx.fillRect(0, plank - 2, w, 2);\n          ctx.restore();\n        }\n        function lights(y0, sag) {\n          var u = Math.min(w, h), n = 9;\n          ctx.save(); ctx.strokeStyle = 'rgba(30,24,18,.85)'; ctx.lineWidth = Math.max(1.5, u * 0.003);\n          ctx.beginPath(); ctx.moveTo(-w * 0.05, y0); ctx.quadraticCurveTo(w / 2, y0 + sag * 2, w * 1.05, y0); ctx.stroke();\n          for (var j = 1; j < n; j++) {\n            var t = j / n, x = -w * 0.05 + t * w * 1.1;\n            var y = (1 - t) * (1 - t) * y0 + 2 * (1 - t) * t * (y0 + sag * 2) + t * t * y0;\n            var r = u * 0.018;\n            var g = ctx.createRadialGradient(x, y + r, 0, x, y + r, r * 5);\n            g.addColorStop(0, 'rgba(255,214,120,.55)'); g.addColorStop(1, 'rgba(255,214,120,0)');\n            ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y + r, r * 5, 0, Math.PI * 2); ctx.fill();\n            ctx.fillStyle = '#fff3c9'; ctx.beginPath(); ctx.ellipse(x, y + r * 1.2, r * 0.75, r, 0, 0, Math.PI * 2); ctx.fill();\n            ctx.fillStyle = 'rgba(30,24,18,.9)'; ctx.fillRect(x - r * 0.45, y - r * 0.1, r * 0.9, r * 0.5);\n          }\n          ctx.restore();\n        }\n        lights(h * 0.03, h * 0.035);\n      }\n\n\n      // Graduation: caps and stars (navy by default; the maroon theme recolors it)\n      function drawCapIcon(ctx, x, y, r, rot, stroke) {\n        ctx.save(); ctx.translate(x, y); ctx.rotate(rot);\n        ctx.strokeStyle = stroke; ctx.lineWidth = Math.max(1.2, r * 0.09); ctx.lineJoin = 'round';\n        ctx.beginPath(); ctx.moveTo(0, -r * 0.55); ctx.lineTo(r, -r * 0.1); ctx.lineTo(0, r * 0.3); ctx.lineTo(-r, -r * 0.1); ctx.closePath(); ctx.stroke();\n        ctx.beginPath(); ctx.moveTo(-r * 0.5, r * 0.08); ctx.lineTo(-r * 0.5, r * 0.42); ctx.quadraticCurveTo(0, r * 0.62, r * 0.5, r * 0.42); ctx.lineTo(r * 0.5, r * 0.08); ctx.stroke();\n        ctx.beginPath(); ctx.moveTo(0, -r * 0.1); ctx.lineTo(r * 0.72, r * 0.05); ctx.lineTo(r * 0.72, r * 0.55); ctx.stroke();\n        ctx.restore();\n      }\n      function fillGraduation(ctx, w, h) {\n        var base = themeBase('#14254a');\n        ctx.fillStyle = vGrad(ctx, h, mixHex(base, '#000000', 0.05), mixHex(base, '#000000', 0.42)); ctx.fillRect(0, 0, w, h);\n        var rand = seededRand(2026), u = Math.min(w, h), gold = goldGrad(ctx, 0, 0, w, h);\n        for (var i = 0; i < 34; i++) {\n          var top = rand() < 0.5, t = Math.pow(rand(), 1.5);\n          var x = rand() * w, y = top ? t * h * 0.4 : h * 0.86 - t * h * 0.32;\n          ctx.globalAlpha = 0.55 + rand() * 0.4;\n          if (rand() < 0.45) drawCapIcon(ctx, x, y, u * (0.03 + rand() * 0.035), (rand() - 0.5) * 0.8, gold);\n          else { ctx.fillStyle = gold; ctx.save(); ctx.translate(x, y); ctx.rotate(rand()); starPathAt(ctx, u * (0.008 + rand() * 0.014)); ctx.fill(); ctx.restore(); }\n        }\n        ctx.globalAlpha = 1;\n      }\n      function starPathAt(ctx, r) {\n        ctx.beginPath();\n        for (var i = 0; i < 10; i++) { var rr = i % 2 ? r * 0.45 : r, a = -Math.PI / 2 + i * Math.PI / 5; ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr); }\n        ctx.closePath();\n      }\n      // Laurel branch along a line (used by Diploma and Sage)\n      function laurel(ctx, x0, y0, x1, y1, leaf, color, flip) {\n        var n = Math.max(4, Math.round(Math.hypot(x1 - x0, y1 - y0) / (leaf * 1.1)));\n        var ang = Math.atan2(y1 - y0, x1 - x0);\n        ctx.save(); ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = Math.max(1, leaf * 0.12);\n        ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();\n        for (var i = 1; i < n; i++) {\n          var t = i / n, x = x0 + (x1 - x0) * t, y = y0 + (y1 - y0) * t;\n          [1, -1].forEach(function (side) {\n            ctx.save(); ctx.translate(x, y); ctx.rotate(ang + side * (flip ? -0.75 : 0.75));\n            ctx.beginPath(); ctx.ellipse(leaf * 0.55, 0, leaf * 0.55, leaf * 0.2, 0, 0, Math.PI * 2); ctx.fill();\n            ctx.restore();\n          });\n        }\n        ctx.restore();\n      }\n      function fillDiploma(ctx, w, h) {\n        var base = themeBase('#f6efdf');\n        ctx.fillStyle = vGrad(ctx, h, mixHex(base, '#ffffff', 0.35), mixHex(base, '#e2d3b0', 0.45)); ctx.fillRect(0, 0, w, h);\n        var u = Math.min(w, h), gold = goldGrad(ctx, 0, 0, w, h), m = u * 0.02;\n        ctx.save(); ctx.strokeStyle = gold; ctx.lineWidth = Math.max(2, u * 0.006); ctx.strokeRect(m, m, w - 2 * m, h - 2 * m);\n        ctx.lineWidth = Math.max(1, u * 0.002); ctx.strokeRect(m * 1.5, m * 1.5, w - 3 * m, h - 3 * m); ctx.restore();\n        var leaf = u * 0.045;\n        laurel(ctx, m * 4.4, h * 0.5, m * 4.4, m * 6, leaf, gold, false);\n        laurel(ctx, w - m * 4.4, h * 0.5, w - m * 4.4, m * 6, leaf, gold, true);\n        laurel(ctx, m * 4.4, h * 0.5, m * 4.4, h - m * 5, leaf, gold, true);\n        laurel(ctx, w - m * 4.4, h * 0.5, w - m * 4.4, h - m * 5, leaf, gold, false);\n        drawCapIcon(ctx, w / 2, m * 6.4, u * 0.05, 0, gold);\n      }\n      // Christening: sky with doves and soft rays\n      function drawDoveShape(ctx, x, y, r, flip) {\n        ctx.save(); ctx.translate(x, y); if (flip) ctx.scale(-1, 1);\n        ctx.fillStyle = 'rgba(255,255,255,.92)';\n        ctx.beginPath(); ctx.ellipse(0, r * 0.15, r * 0.55, r * 0.24, -0.15, 0, Math.PI * 2); ctx.fill();\n        ctx.beginPath(); ctx.moveTo(-r * 0.15, r * 0.05); ctx.bezierCurveTo(-r * 0.5, -r * 0.6, -r * 0.1, -r * 0.95, r * 0.2, -r * 0.7); ctx.bezierCurveTo(r * 0.05, -r * 0.4, r * 0.15, -r * 0.1, r * 0.1, r * 0.05); ctx.closePath(); ctx.fill();\n        ctx.beginPath(); ctx.arc(r * 0.55, -r * 0.02, r * 0.16, 0, Math.PI * 2); ctx.fill();\n        ctx.beginPath(); ctx.moveTo(-r * 0.5, r * 0.2); ctx.lineTo(-r * 0.95, r * 0.05); ctx.lineTo(-r * 0.9, r * 0.35); ctx.closePath(); ctx.fill();\n        ctx.restore();\n      }\n      function fillAngel(ctx, w, h) {\n        var base = themeBase('#bcd9f2');\n        ctx.fillStyle = vGrad(ctx, h, base, mixHex(base, '#ffffff', 0.85)); ctx.fillRect(0, 0, w, h);\n        var u = Math.min(w, h);\n        ctx.save(); ctx.globalAlpha = 0.18; ctx.fillStyle = '#ffffff';\n        for (var i = 0; i < 9; i++) {\n          var a = -Math.PI / 2 + (i - 4) * 0.2;\n          ctx.beginPath(); ctx.moveTo(w / 2, -h * 0.1);\n          ctx.lineTo(w / 2 + Math.cos(a - 0.04) * h * 1.4, -h * 0.1 + Math.sin(a - 0.04) * -h * 1.4);\n          ctx.lineTo(w / 2 + Math.cos(a + 0.04) * h * 1.4, -h * 0.1 + Math.sin(a + 0.04) * -h * 1.4); ctx.fill();\n        }\n        ctx.restore();\n        var rand = seededRand(316);\n        for (var d = 0; d < 7; d++) {\n          var top = d % 2 === 0;\n          drawDoveShape(ctx, w * (0.1 + rand() * 0.8), top ? h * (0.04 + rand() * 0.12) : h * (0.7 + rand() * 0.14), u * (0.05 + rand() * 0.035), rand() < 0.5);\n        }\n        ctx.fillStyle = goldGrad(ctx, 0, 0, w, h);\n        var cx = w / 2, cy = h * 0.035, r = u * 0.03;\n        ctx.fillRect(cx - r * 0.12, cy - r * 0.6, r * 0.24, r * 1.6); ctx.fillRect(cx - r * 0.5, cy - r * 0.2, r, r * 0.24);\n      }\n      // Christening: sage with a laurel frame and a small gold cross\n      function fillSage(ctx, w, h) {\n        var base = themeBase('#a9bfa3');\n        ctx.fillStyle = vGrad(ctx, h, mixHex(base, '#ffffff', 0.25), mixHex(base, '#5d7a5a', 0.25)); ctx.fillRect(0, 0, w, h);\n        var u = Math.min(w, h), m = u * 0.05, leaf = u * 0.05, green = 'rgba(255,255,255,.55)';\n        laurel(ctx, m, h - m, m, m * 1.5, leaf, green, false);\n        laurel(ctx, w - m, h - m, w - m, m * 1.5, leaf, green, true);\n        ctx.fillStyle = goldGrad(ctx, 0, 0, w, h);\n        var cx = w / 2, cy = m * 0.9, r = u * 0.04;\n        ctx.fillRect(cx - r * 0.12, cy - r * 0.6, r * 0.24, r * 1.6); ctx.fillRect(cx - r * 0.5, cy - r * 0.2, r, r * 0.24);\n      }\n      Object.assign(BACKDROP_PRESETS, {\n        grad: { fill: fillGraduation, elements: 'none', base: '#14254a' },\n        diploma: { fill: fillDiploma, elements: 'none', base: '#f6efdf' },\n        angel: { fill: fillAngel, elements: 'none', base: '#bcd9f2' },\n        sage: { fill: fillSage, elements: 'none', base: '#a9bfa3' },\n        chevron: { fill: fillChevron, elements: 'none', base: '#fbf7ef' },\n        deco: { fill: fillDeco, elements: 'none', base: '#13213f' },\n        blackgold: { fill: fillBlackGold, elements: 'none', base: '#141414' },\n        goldconfetti: { fill: fillGoldConfetti, elements: 'none', base: '#fffdf8' },\n        marble: { fill: fillMarble, elements: 'none', base: '#f7f5f1' },\n        blush: { fill: fillBlushStripes, elements: 'hearts', base: '#fbe3e8', pal: Object.assign({}, buildPalette('#f4c3cf')) },\n        party: { fill: fillPartyPastel, elements: 'balloons', base: '#e9dcff', pal: Object.assign({}, buildPalette('#efe5ff')) },\n        pine: { fill: fillPine, elements: 'snowflakes', base: '#174d39', pal: Object.assign({}, buildPalette('#174d39')) },\n        midnight: { fill: fillMidnight, elements: 'goldstars', base: '#141a3a', pal: Object.assign({}, buildPalette('#141a3a'), { gold: '#f0c869' }) },\n        rustic: { fill: fillRustic, elements: 'none', base: '#8a5a2e' }\n      });\n      palCache = { color: null, pal: null };\n\n      // The color the backdrop \"reads as\" — picked Backdrop color, else the style's own.\n      function backdropBaseColor(preset) {\n        if (backdropColor) return backdropColor;\n        const p = BACKDROP_PRESETS[preset || backdropPreset];\n        return p ? p.base : '#ffffff';\n      }\n      function elementsKeyFor(preset) {\n        const p = BACKDROP_PRESETS[preset];\n        if (elementsChoice === 'auto') return p ? p.elements : 'none';\n        return elementsChoice;\n      }\n      // Draws a built-in backdrop (not a custom photo): fill, then elements.\n      function paintBackdrop(ctx, w, h, preset, elKey) {\n        const p = BACKDROP_PRESETS[preset];\n        const fillPal = backdropColor ? buildPalette(backdropColor) : (p && p.pal) || DEFAULT_PAL;\n        if (p) {\n          p.fill(ctx, w, h, fillPal);\n        } else {\n          // Plain: a flat color — white unless a Backdrop color is picked.\n          ctx.fillStyle = backdropColor || '#ffffff';\n          ctx.fillRect(0, 0, w, h);\n        }\n        const draw = ELEMENT_SETS[elKey];\n        if (!draw) return;\n        // A preset's own elements keep its designed palette; any other set gets a\n        // palette built to contrast with whatever color the backdrop reads as.\n        const ownSet = p && elKey === p.elements;\n        draw(ctx, w, h, ownSet ? fillPal : buildPalette(backdropBaseColor(preset)));\n      }\n\n      // ---- Polaroid frame color: the Polaroid color picked in Setup, or on Auto\n      // white/black so it stands out against the backdrop. ----\n      function frameColorFor() {\n        if (frameColorChoice !== 'auto') return frameColorChoice;\n        if (backdropPreset === 'custom' && backgroundImg) {\n          return (backdropColor && placement() === 'band' && lumOf(backdropColor) > 0.72) ? '#111111' : '#ffffff';\n        }\n        if (backdropPreset === 'none' && !backdropColor) return '#000000'; // flat white bg\n        // A light picked Backdrop color needs a dark frame to stay readable.\n        if (backdropColor && lumOf(backdropColor) > 0.72) return '#111111';\n        return '#ffffff';\n      }\n\n      function drawBackdrop(ctx, w, h) {\n        if (backdropPreset === 'custom' && backgroundImg && placement() === 'background') {\n          drawImageCover(ctx, backgroundImg, 0, 0, w, h, cropFocus);\n          const draw = elementsChoice === 'auto' ? null : ELEMENT_SETS[elementsChoice];\n          if (draw) draw(ctx, w, h, buildPalette(hslToHex(photoHue, photoSat, 0.5)));\n          return;\n        }\n        const preset = backdropPreset === 'custom' ? 'none' : backdropPreset;\n        paintBackdrop(ctx, w, h, preset, elementsKeyFor(preset));\n      }\n\n      // ---- QR / temporary hosting ----\n      async function uploadToLitterbox(blob, filename, time) {\n        const form = new FormData();\n        form.append('reqtype', 'fileupload');\n        form.append('time', time || '1h');\n        form.append('fileToUpload', blob, filename);\n        const res = await fetch('https://litterbox.catbox.moe/resources/internals/api.php', {\n          method: 'POST',\n          body: form\n        });\n        if (!res.ok) throw new Error('Upload failed (' + res.status + ')');\n        const url = (await res.text()).trim();\n        if (!url.startsWith('http')) throw new Error(url || 'Upload failed');\n        return url;\n      }\n\n      function qrImageUrl(targetUrl) {\n        try {\n          const q = qrcode(0, 'M'); q.addData(String(targetUrl)); q.make();\n          return q.createDataURL(8, 2);\n        } catch (e) {\n          return 'https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=' + encodeURIComponent(targetUrl);\n        }\n      }\n\n      function addQrResult(label, fileUrl) {\n        const wrap = document.createElement('div');\n        wrap.className = 'qr-result';\n\n        const img = document.createElement('img');\n        img.className = 'qr-img';\n        img.src = qrImageUrl(fileUrl);\n        img.alt = label + ' QR code';\n\n        const cap = document.createElement('p');\n        cap.className = 'qr-caption';\n        cap.textContent = label;\n\n        const link = document.createElement('a');\n        link.href = fileUrl;\n        link.target = '_blank';\n        link.rel = 'noopener';\n        link.className = 'qr-link';\n        link.textContent = 'Open link';\n\n        wrap.appendChild(img);\n        wrap.appendChild(cap);\n        wrap.appendChild(link);\n        qrResults.appendChild(wrap);\n        guestRender();\n      }\n\n\n      // ---- Per-booking-folder caching ----\n      // The Drive folder for a booking never changes mid-event, so we only need\n      // to look up/show its QR once. It's cached in localStorage per folder key\n      // so it survives page reloads and doesn't need to be regenerated.\n      function currentFolderKey() {\n        // The bonus subfolder gets its own cache entries, so its QR and session\n        // numbers never mix with the event folder's on the same device.\n        const base = rawFolderKey() || 'default';\n        return driveSubfolder() ? base + '/' + driveSubfolder() : base;\n      }\n      function folderUrlStorageKey() { return 'photoBoothDrive:' + currentFolderKey() + ':folderUrl'; }\n      function sessionNumStorageKey() { return 'photoBoothDrive:' + currentFolderKey() + ':sessionNum'; }\n\n      function getCachedFolderUrl() {\n        return localStorage.getItem(folderUrlStorageKey());\n      }\n      function rememberFolderUrl(url) {\n        if (!url) return;\n        localStorage.setItem(folderUrlStorageKey(), url);\n        try { if (gvMode !== 'all') gvApply(); } catch (e) { }\n      }\n      function nextSessionNumber() {\n        const n = parseInt(localStorage.getItem(sessionNumStorageKey()) || '0', 10) + 1;\n        localStorage.setItem(sessionNumStorageKey(), String(n));\n        return n;\n      }\n      // Called after the folder resolves, so a precreated/reused folder that\n      // already has files in it (from another device, or a previous event)\n      // doesn't collide with them — we trust the server's scan of the actual\n      // folder contents over whatever this browser happens to remember.\n      function syncSessionNumberFromServer(serverNext) {\n        if (!serverNext) return;\n        const localNext = parseInt(localStorage.getItem(sessionNumStorageKey()) || '0', 10) + 1;\n        if (serverNext > localNext) {\n          localStorage.setItem(sessionNumStorageKey(), String(serverNext - 1));\n        }\n      }\n\n      // Tells the server which Drive folder this code used (and that a session\n      // finished), so the customer can find every event's link on /lifetime.\n      // Rentals only; trials and the no-code booth skip it. Never blocks the booth.\n      function registerEvent(folderUrl, session) {\n        const pb = window.__PB;\n        if (LOCALSHARE || !pb || pb.type !== 'rental' || !folderUrl) return;\n        let token = null, deviceId = null;\n        try { token = localStorage.getItem('pb_token'); deviceId = localStorage.getItem('pb_device'); } catch (e) { }\n        if (!token || !deviceId) return;\n        try {\n          fetch('/api/events', {\n            method: 'POST', keepalive: true,\n            headers: { 'content-type': 'application/json' },\n            body: JSON.stringify({ token, deviceId, folderKey: rawFolderKey(), folderUrl, session: !!session })\n          }).catch(() => { });\n        } catch (e) { }\n      }\n\n      let currentFolderLink = '';\n      // Guests' QR: the online gallery (/g/<folder id>) unless Admin chose the Drive folder.\n      // Windows / Mac app: photos live on this laptop (\"pb4u-local:<id>\"); guests'\n      // phones on the same Wi-Fi open http://<laptop address>:<port>/e/<id>/.\n      function localShareUrl(folderUrl, file) {\n        var m = /^pb4u-local:([A-Za-z0-9]+)/.exec(String(folderUrl || ''));\n        if (!m) return null;\n        var base = lanBaseNow();\n        return base ? base + '/e/' + m[1] + '/' + (file ? 'p/' + encodeURIComponent(file) : '') : null;\n      }\n      const NO_LAN_TEXT = 'Saved on this ' + LOCAL_DEVICE + '. Connect the ' + LOCAL_DEVICE + ' to the booth Wi-Fi to show the QR.';\n      // Optional booth Wi-Fi the guests join first (app only; set in Share & start).\n      const WIFI_KEY = 'pb_wifi';\n      function wifiInfo() {\n        if (!LOCALSHARE) return null;\n        try { var w = JSON.parse(localStorage.getItem(WIFI_KEY) || 'null'); return w && w.ssid ? { ssid: String(w.ssid), pass: String(w.pass || '') } : null; } catch (e) { return null; }\n      }\n      function wifiQrText(w) {\n        var e = function (t) { return String(t).replace(/([\\\\;,\":])/g, '\\\\$1'); };\n        return 'WIFI:T:' + (w.pass ? 'WPA' : 'nopass') + ';S:' + e(w.ssid) + ';' + (w.pass ? 'P:' + e(w.pass) + ';' : '') + ';';\n      }\n      function saveWifiInfo(ssid, pass) {\n        try { if (ssid) localStorage.setItem(WIFI_KEY, JSON.stringify({ ssid: ssid, pass: pass })); else localStorage.removeItem(WIFI_KEY); } catch (e) { }\n        refreshWifiUI();\n      }\n      // The booth Wi-Fi's own name and password, chosen by the operator (laptop and Android apps).\n      // cfg.save(name, pass) -> Promise of { ok, error, info }; cfg.after(info) runs with the fresh info once it is saved.\n      // Returns null on a page without the boxes; .render(info) fills them in from the app's booth Wi-Fi info.\n      function hotspotCredsUI(cfg) {\n        var wrap = document.getElementById('deskHotspotCreds'), nm = document.getElementById('deskHotspotName'), pw = document.getElementById('deskHotspotPass');\n        var pre = document.getElementById('deskHotspotPrefix'), btn = document.getElementById('deskHotspotSave'), hint = document.getElementById('deskHotspotCredHint');\n        if (!(wrap && nm && pw && pre && btn && hint)) return null;\n        var dirty = false, msg = '';\n        function say(t, bad) { hint.className = 'panel-hint' + (bad ? ' bad' : ''); hint.textContent = t; }\n        function typed() { dirty = true; msg = ''; }\n        nm.addEventListener('input', typed); pw.addEventListener('input', typed);\n        btn.addEventListener('click', function () {\n          btn.disabled = true; msg = 'Saving…'; say(msg, false);\n          var done = function (r) {\n            btn.disabled = false;\n            if (r && r.ok) { dirty = false; msg = 'Saved ✓'; say(msg, false); setTimeout(function () { msg = ''; }, 4000); }\n            else { msg = (r && r.error) || 'Couldn’t save. Try again.'; say(msg, true); }\n            if (r && r.info && cfg.after) cfg.after(r.info);\n          };\n          try { Promise.resolve(cfg.save(nm.value.trim(), pw.value)).then(done, function () { done(null); }); } catch (e) { done(null); }\n        });\n        return {\n          render: function (i) {\n            if (!i || !i.canCustom) { wrap.style.display = 'none'; return; }\n            wrap.style.display = '';\n            var pfx = i.prefix || '';\n            pre.style.display = pfx ? '' : 'none'; pre.textContent = pfx;\n            var s = String(i.wantSsid != null ? i.wantSsid : (i.ssid || '')), p = String(i.wantPass != null ? i.wantPass : (i.pass || ''));\n            if (pfx && s.indexOf(pfx) === 0) s = s.slice(pfx.length);\n            if (!dirty && document.activeElement !== nm && document.activeElement !== pw) { nm.value = s; pw.value = p; }\n            if (msg) return;\n            // Android sometimes makes its own network (older Android, or when it can't use the chosen name).\n            if (i.on && !i.external && i.wantSsid != null && i.ssid && (i.ssid !== i.wantSsid || i.pass !== i.wantPass)) say('Android made its own Wi-Fi “' + i.ssid + '” this time, not the name and password above. The Join QR uses it.', true);\n            else say('', false);\n          }\n        };\n      }\n      // Booth Wi-Fi QR: in Share & start (with the sign button) and behind the Wi-Fi button in the dock.\n      function refreshWifiUI() {\n        const w = wifiInfo();\n        const box = document.getElementById('deskWifiQrBox');\n        if (box) {\n          box.style.display = w ? '' : 'none';\n          if (w) { document.getElementById('deskWifiQrImg').src = qrImageUrl(wifiQrText(w)); document.getElementById('deskWifiQrCap').textContent = 'Join “' + w.ssid + '”'; }\n        }\n        const fab = document.getElementById('wifiFab'); if (!fab) return;\n        fab.hidden = !w;\n        if (w) {\n          document.getElementById('wifiPopQr').src = qrImageUrl(wifiQrText(w));\n          document.getElementById('wifiPopName').textContent = w.ssid;\n          document.getElementById('wifiPopPass').textContent = w.pass ? 'Password: ' + w.pass : 'No password';\n        } else closeWifiPop();\n        if (typeof scheduleDock === 'function') scheduleDock();\n      }\n      function closeWifiPop() {\n        const pop = document.getElementById('wifiPop'); if (!pop || pop.hidden) return;\n        pop.hidden = true;\n        const fab = document.getElementById('wifiFab'); if (fab) fab.setAttribute('aria-expanded', 'false');\n      }\n      function openWifiPop() {\n        const pop = document.getElementById('wifiPop'), fab = document.getElementById('wifiFab');\n        if (!pop || !fab || fab.hidden) return;\n        pop.hidden = false; fab.setAttribute('aria-expanded', 'true');\n        const r = fab.getBoundingClientRect();\n        pop.style.left = Math.max(12, Math.min(r.left, window.innerWidth - pop.offsetWidth - 12)) + 'px';\n        pop.style.bottom = (window.innerHeight - r.top + 10) + 'px';\n      }\n      function galleryUrlFor(folderUrl) {\n        if (LOCALSHARE) return localShareUrl(folderUrl);\n        var m = /\\/folders\\/([A-Za-z0-9_-]{10,})/.exec(String(folderUrl || ''));\n        return m ? location.origin + '/g/' + m[1] : null;\n      }\n      function usesGallery(folderUrl) { return LOCALSHARE || (!(window.__PB && window.__PB.qrTarget === 'drive') && !!galleryUrlFor(folderUrl)); }\n      function shareUrlFor(folderUrl) { return LOCALSHARE ? localShareUrl(folderUrl) : (usesGallery(folderUrl) ? galleryUrlFor(folderUrl) : folderUrl); }\n\n      // App: the event folder on this laptop, its guests' QR (when on Wi-Fi) and an Open folder link.\n      let localFolderUrl = '', localFolderName = '';\n      function showLocalFolderPreview(folderUrl, name) {\n        localFolderUrl = folderUrl; if (name) localFolderName = name;\n        var url = shareUrlFor(folderUrl);\n        currentFolderLink = url || '';\n        refreshGalleryUI();\n        var open = document.getElementById('driveFolderOpen');\n        open.style.display = url ? '' : 'none';\n        if (url) { open.href = url; open.textContent = 'Open gallery'; }\n        document.getElementById('driveFolderCopy').style.display = url ? '' : 'none';\n        var dl = document.getElementById('driveFolderDrive');\n        if (dl) { dl.href = '#'; dl.textContent = 'Open folder'; dl.style.display = ANDROID_LOCAL ? 'none' : ''; }\n        document.getElementById('driveFolderAll').style.display = 'none';\n        document.getElementById('driveFolderQrCaption').textContent = url ? 'All photos (same Wi-Fi)' : 'No Wi-Fi yet: connect this ' + LOCAL_DEVICE + ' to the booth Wi-Fi (a pocket router or phone hotspot works, no internet needed) to show the guests\\u2019 QR.';\n        driveFolderStatus.style.display = 'block';\n        driveFolderStatus.textContent = '\\u2713 Folder ready' + (localFolderName ? ': ' + localFolderName : '') + '. Every photo saves on this ' + LOCAL_DEVICE + '.';\n        if (typeof refreshSetupNav === 'function') refreshSetupNav();\n        driveFolderQrImg.style.display = url && !gvPrivate() ? '' : 'none';\n        if (url) driveFolderQrImg.src = qrImageUrl(url);\n        document.getElementById('qrSignBtn').style.display = url && !gvPrivate() ? '' : 'none';\n        if (gvPrivate()) document.getElementById('driveFolderQrCaption').textContent = 'Guests see only their own photos. This link is for you.';\n        driveFolderQrPreview.style.display = 'block';\n      }\n      function showDriveFolderPreview(folderUrl, name) {\n        if (LOCALSHARE) return showLocalFolderPreview(folderUrl, name);\n        var url = shareUrlFor(folderUrl), gallery = usesGallery(folderUrl);\n        currentFolderLink = url;\n        refreshGalleryUI();\n        document.getElementById('driveFolderOpen').href = gvOpUrl(url);\n        document.getElementById('driveFolderOpen').textContent = gallery ? 'Open gallery' : 'Open folder';\n        var dl = document.getElementById('driveFolderDrive');\n        if (dl) { dl.href = folderUrl; dl.style.display = 'none'; }   // renters use the gallery; the Drive folder stays private\n        document.getElementById('driveFolderQrCaption').textContent = gvPrivate() ? 'Guests see only their own photos. This link is for you.' : 'All photos';\n        document.getElementById('driveFolderAll').style.display = (window.__PB && window.__PB.type === 'rental') ? '' : 'none';\n        driveFolderStatus.style.display = 'block';\n        driveFolderStatus.textContent = '✓ Folder ready' + (name ? (': ' + name) : '') + '. Every photo saves here.';\n        if (typeof refreshSetupNav === 'function') refreshSetupNav();\n        driveFolderQrImg.src = qrImageUrl(url);\n        // Guests see only their own photos: the event QR and sign are not for them, so they are not shown.\n        driveFolderQrImg.style.display = gvPrivate() ? 'none' : '';\n        document.getElementById('qrSignBtn').style.display = gvPrivate() ? 'none' : '';\n        driveFolderQrPreview.style.display = 'block';\n      }\n\n      // A printable \"Scan for your photos\" sign with the event gallery QR (A5, 300 dpi PNG).\n      async function downloadQrSign() {\n        const url = currentFolderLink; if (!url) { showToast('Set up the event folder first.'); return; }\n        try { if (document.fonts && document.fonts.ready) await document.fonts.ready; } catch (e) { }\n        const W = 1748, H = 2480, c = document.createElement('canvas'); c.width = W; c.height = H;\n        const x = c.getContext('2d');\n        x.fillStyle = '#F5F1EA'; x.fillRect(0, 0, W, H);\n        x.fillStyle = '#ffffff'; x.fillRect(110, 110, W - 220, H - 220);\n        x.textAlign = 'center'; x.fillStyle = '#1C1A1E';\n        const name = ((labelInput && labelInput.value) || '').trim();\n        const fit = (t, font, size, maxW) => { let f = size; do { x.font = font.replace('#', f); f -= 4; } while (f > 40 && x.measureText(t).width > maxW); };\n        x.fillStyle = '#6B666C'; fit('SCAN FOR YOUR PHOTOS', \"800 #px 'Manrope', system-ui, sans-serif\", 64, W - 400);\n        x.fillText('SCAN FOR YOUR PHOTOS', W / 2, 330);\n        x.fillStyle = '#1C1A1E'; fit(name || 'Photo booth', \"600 #px 'Fraunces', Georgia, serif\", 150, W - 360);\n        x.fillText(name || 'Photo booth', W / 2, 500);\n        let q = null; try { q = qrcode(0, 'M'); q.addData(String(url)); q.make(); } catch (e) { }\n        if (q) {\n          const n = q.getModuleCount(), size = 1100, cell = Math.floor(size / (n + 4)), qs = cell * (n + 4);\n          const ox = Math.round((W - qs) / 2), oy = 620;\n          x.fillStyle = '#ffffff'; x.fillRect(ox, oy, qs, qs);\n          x.fillStyle = '#000000';\n          for (let r = 0; r < n; r++) for (let k = 0; k < n; k++) if (q.isDark(r, k)) x.fillRect(ox + (k + 2) * cell, oy + (r + 2) * cell, cell, cell);\n          x.strokeStyle = '#E4DCCF'; x.lineWidth = 6; x.strokeRect(ox - 3, oy - 3, qs + 6, qs + 6);\n        }\n        x.fillStyle = '#1C1A1E'; x.font = \"700 58px 'Manrope', system-ui, sans-serif\";\n        x.fillText('Open your phone camera and point it here.', W / 2, 1880);\n        x.fillStyle = '#6B666C'; x.font = \"600 46px 'Manrope', system-ui, sans-serif\";\n        x.fillText('Every photo from the booth lands in this gallery.', W / 2, 1960);\n        x.fillText('No signal at the booth? Your photo still arrives later.', W / 2, 2030);\n        try { const mk = brandMarkCanvas(), mw = 520, mh = Math.round(mw * mk.height / mk.width); x.drawImage(mk, (W - mw) / 2, 2180, mw, mh); } catch (e) { }\n        await saveSignPng(c, 'qr-sign', name, 'QR sign');\n      }\n      document.getElementById('qrSignBtn').addEventListener('click', downloadQrSign);\n\n      async function saveSignPng(c, base, name, title) {\n        const blob = await new Promise(r => c.toBlob(r, 'image/png'));\n        const file = base + (name ? '-' + name.replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase() : '') + '.png';\n        // Laptop app: a Save As box (File Explorer / Finder) that starts in the folder you used last time.\n        if (window.pb4u && window.pb4u.saveFile) {\n          try {\n            const r = await window.pb4u.saveFile(file, new Uint8Array(await blob.arrayBuffer()));\n            if (r === null) { showToast('Not saved.'); return; }\n            if (r && r.ok) {\n              showToast(title + ' saved in ' + String(r.dir || '').split(/[\\\\/]/).filter(Boolean).pop() + '. Print it on A5 or bigger.', 6000);\n              return;\n            }\n            if (r && r.error) { showToast(r.error, 5000); return; }\n          } catch (e) { /* an older app: use the normal download below */ }\n        }\n        // Android app: its WebView cannot download a blob: link (nothing was saved, though it said so); the app puts it\n        // in the Gallery instead (Pictures > photobooth4u).\n        const PL = window.__PBLocal;\n        if (PL && (typeof PL.saveImage === 'function' || /PB4uAndroid/.test(navigator.userAgent || '') || window.__PBNet)) {      // not the iOS app: its share sheet saves\n          if (typeof PL.saveImage === 'function') {\n            try {\n              const r = JSON.parse(PL.saveImage(file, await blobToBase64(blob)) || '{}');\n              if (r.ok) { showToast(title + ' saved in the Gallery (Pictures › photobooth4u). Print it on A5 or bigger.', 6000); return; }\n              showToast(r.error === 'old-android' ? 'This tablet’s Android is too old to save into the Gallery. Make the sign on a laptop or phone instead.' : ('Not saved: ' + (r.error || 'the Gallery did not accept it.')), 6500);\n            } catch (e) { showToast('Not saved: ' + ((e && e.message) || e), 5000); }\n          } else {\n            showToast('Update the photobooth4u app to save the ' + title + ' on this tablet.', 6000);\n          }\n          return;\n        }\n        try {\n          const f = new File([blob], file, { type: 'image/png' });\n          if (isMobileOS() && navigator.canShare && navigator.canShare({ files: [f] })) { await navigator.share({ files: [f], title: title }); return; }\n        } catch (e) { if (e && e.name === 'AbortError') return; }\n        const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = file; document.body.appendChild(a); a.click();\n        setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 3000);\n        showToast(title + ' saved. Print it on A5 or bigger.');\n      }\n\n      // Apps: a printable \"Join our Wi-Fi\" sign (A5, 300 dpi PNG) with the booth Wi-Fi QR, name and password.\n      // The photos' QR is not here: guests get it on the booth screen after each session.\n      async function downloadWifiSign() {\n        const w = wifiInfo(); if (!w) { showToast('Add the booth Wi-Fi name first.'); return; }\n        let q = null; try { q = qrcode(0, 'M'); q.addData(String(wifiQrText(w))); q.make(); } catch (e) { return; }\n        try { if (document.fonts && document.fonts.ready) await document.fonts.ready; } catch (e) { }\n        const W = 1748, H = 2480, c = document.createElement('canvas'); c.width = W; c.height = H;\n        const x = c.getContext('2d');\n        x.fillStyle = '#F5F1EA'; x.fillRect(0, 0, W, H);\n        x.fillStyle = '#ffffff'; x.fillRect(110, 110, W - 220, H - 220);\n        x.textAlign = 'center';\n        const name = ((labelInput && labelInput.value) || '').trim();\n        const fit = (t, font, size, maxW) => { let f = size; do { x.font = font.replace('#', f); f -= 4; } while (f > 40 && x.measureText(t).width > maxW); };\n        x.fillStyle = '#6B666C'; fit('JOIN OUR WI-FI', \"800 #px 'Manrope', system-ui, sans-serif\", 64, W - 400);\n        x.fillText('JOIN OUR WI-FI', W / 2, 330);\n        x.fillStyle = '#1C1A1E'; fit(name || 'Photo booth', \"600 #px 'Fraunces', Georgia, serif\", 150, W - 360);\n        x.fillText(name || 'Photo booth', W / 2, 500);\n        const n = q.getModuleCount(), size = 1100, cell = Math.floor(size / (n + 4)), qs = cell * (n + 4);\n        const ox = Math.round((W - qs) / 2), oy = 620;\n        x.fillStyle = '#ffffff'; x.fillRect(ox, oy, qs, qs);\n        x.fillStyle = '#000000';\n        for (let r = 0; r < n; r++) for (let k = 0; k < n; k++) if (q.isDark(r, k)) x.fillRect(ox + (k + 2) * cell, oy + (r + 2) * cell, cell, cell);\n        x.strokeStyle = '#E4DCCF'; x.lineWidth = 6; x.strokeRect(ox - 3, oy - 3, qs + 6, qs + 6);\n        x.fillStyle = '#1C1A1E'; fit(w.ssid, \"800 #px 'Manrope', system-ui, sans-serif\", 72, W - 360);\n        x.fillText(w.ssid, W / 2, 1860);\n        x.fillStyle = '#6B666C';\n        if (w.pass) { fit('Password: ' + w.pass, \"600 #px 'Manrope', system-ui, sans-serif\", 54, W - 360); x.fillText('Password: ' + w.pass, W / 2, 1940); }\n        else { x.font = \"600 54px 'Manrope', system-ui, sans-serif\"; x.fillText('No password', W / 2, 1940); }\n        x.font = \"600 46px 'Manrope', system-ui, sans-serif\";\n        x.fillText('Point your phone camera here, then scan your photo QR at the booth.', W / 2, 2030);\n        try { const mk = brandMarkCanvas(), mw = 520, mh = Math.round(mw * mk.height / mk.width); x.drawImage(mk, (W - mw) / 2, 2180, mw, mh); } catch (e) { }\n        await saveSignPng(c, 'wifi-sign', name, 'Wi-Fi sign');\n      }\n      document.getElementById('wifiSignBtn').addEventListener('click', downloadWifiSign);\n\n      let resolveTimer = null;\n\n      // Resolves (or creates) the Drive folder for whatever's currently typed,\n      // as soon as it's typed — no need to wait for a photo session.\n      async function resolveDriveFolder() {\n        const key = rawFolderKey();\n        if (!key) {\n          driveFolderStatus.style.display = 'none';\n          driveFolderQrPreview.style.display = 'none';\n          return;\n        }\n        const cached = getCachedFolderUrl();\n        if (cached && !LOCALSHARE) {            // the apps always ask (it's instant, and gives the folder's name)\n          showDriveFolderPreview(cached);\n          registerEvent(cached, false);\n          return;\n        }\n        driveFolderStatus.style.display = 'block';\n        driveFolderStatus.textContent = 'Setting up the folder\\u2026';\n        driveFolderQrPreview.style.display = 'none';\n        try {\n          const ticket = await getUploadTicket();\n          const res = await driveFetch({\n            method: 'POST',\n            headers: { 'Content-Type': 'text/plain;charset=utf-8' },\n            body: JSON.stringify({ folderKey: key, subfolder: driveSubfolder() || undefined, resolveOnly: true, ticket })\n          });\n          const data = await res.json();\n          if (!data.ok) throw new Error(data.error || 'Could not set up that folder');\n          rememberFolderUrl(data.folderUrl);\n          registerEvent(data.folderUrl, false);\n          syncSessionNumberFromServer(data.nextSessionNumber);\n          showDriveFolderPreview(data.folderUrl, data.folderName);\n        } catch (err) {\n          console.error('Drive folder setup failed:', err);\n          driveFolderStatus.innerHTML = '';\n          var msg = document.createElement('span');\n          msg.style.color = '#c0392b'; msg.style.fontWeight = '700';\n          msg.textContent = \"Couldn't set up the folder, so there's no QR yet. \" + driveErrorText(err);\n          var again = document.createElement('button');\n          again.type = 'button'; again.className = 'link-btn'; again.textContent = 'Try again';\n          again.style.display = 'block';\n          again.addEventListener('click', function () { ticketCache = null; resolveDriveFolder(); });\n          driveFolderStatus.append(msg, again);\n          driveFolderQrPreview.style.display = 'none';\n        }\n      }\n      // Turns a Drive/ticket error into a plain reason the operator (or owner) can act on.\n      function driveErrorText(err) {\n        var m = String((err && err.message) || err || '');\n        if (/UPLOAD_SECRET env var/i.test(m)) return 'Owner: UPLOAD_SECRET is missing in Netlify (Environment variables). Add it and redeploy.';\n        if (/UPLOAD_SECRET is not set/i.test(m)) return 'Owner: the Apps Script has no UPLOAD_SECRET. Add it in Project Settings → Script Properties, then Deploy → New version.';\n        if (/missing or expired ticket/i.test(m)) return 'Owner: the UPLOAD_SECRET in the Apps Script and in Netlify are not exactly the same.';\n        if (/only use its own event folder|locked|trial-ended|expired/i.test(m)) return 'The code or trial has changed. Reload the page.';\n        if (/Unexpected token|JSON|not valid json/i.test(m)) return 'Owner: the Apps Script did not answer. Re-deploy it as a New version with access \"Anyone\".';\n        if (/Failed to fetch|NetworkError|Load failed/i.test(m)) return 'Check the internet, then try again.';\n        return m ? '(' + m.slice(0, 160) + ')' : 'Check the internet, then try again.';\n      }\n\n      // ---- Small on-device store: photos waiting to upload + the backup folder ----\n      var dbPromise = null;\n      function boothDb() {\n        if (!dbPromise) {\n          dbPromise = new Promise((resolve, reject) => {\n            if (!('indexedDB' in window)) return reject(new Error('No IndexedDB'));\n            const req = indexedDB.open('pb4u-booth', 1);\n            req.onupgradeneeded = () => {\n              const d = req.result;\n              if (!d.objectStoreNames.contains('uploads')) d.createObjectStore('uploads', { keyPath: 'id' });\n              if (!d.objectStoreNames.contains('kv')) d.createObjectStore('kv');\n            };\n            req.onsuccess = () => resolve(req.result);\n            req.onerror = () => reject(req.error);\n          });\n          dbPromise.catch(() => { dbPromise = null; });\n        }\n        return dbPromise;\n      }\n      async function dbDo(store, mode, fn) {\n        const d = await boothDb();\n        return new Promise((resolve, reject) => {\n          const tx = d.transaction(store, mode);\n          const req = fn(tx.objectStore(store));\n          tx.oncomplete = () => resolve(req ? req.result : undefined);\n          tx.onerror = () => reject(tx.error);\n          tx.onabort = () => reject(tx.error);\n        });\n      }\n\n      // ---- Photos waiting to upload ----\n      var queueCount = 0, queueBusy = false, queueTimer = null;\n      function isPermanentUploadError(err) {\n        const m = String((err && err.message) || err || '');\n        return /only use its own event folder|locked|trial-ended|expired|Could not get permission|ticket/i.test(m);\n      }\n      async function queueUpload(blob, filename, dest) {\n        const item = {\n          id: dest.folderKey + '|' + (dest.subfolder || '') + '|' + filename,\n          blob: blob, filename: filename, folderKey: dest.folderKey, subfolder: dest.subfolder || '',\n          t: Date.now(), error: ''\n        };\n        await dbDo('uploads', 'readwrite', st => st.put(item));\n        await refreshQueueUI();\n        scheduleQueue(30000);\n        return true;\n      }\n      async function queuedItems() {\n        try { return (await dbDo('uploads', 'readonly', st => st.getAll())) || []; } catch (e) { return []; }\n      }\n      async function refreshQueueUI() {\n        const items = await queuedItems();\n        queueCount = items.length;\n        const sec = document.getElementById('uploadQueueSection');\n        if (!sec) return items;\n        sec.classList.toggle('hidden', !items.length || state === 'capturing');\n        if (!items.length) return items;\n        const stuck = items.filter(i => i.error);\n        document.getElementById('uploadQueueText').textContent =\n          (items.length === 1 ? '1 photo' : items.length + ' photos') + ' waiting to upload';\n        document.getElementById('uploadQueueHint').textContent = stuck.length\n          ? (stuck.length === 1 ? '1 photo' : stuck.length + ' photos') + ' can’t upload with this code: ' + stuck[0].error + ' Tap Save to this computer so they aren’t lost.'\n          : 'Kept safely on this device. They upload by themselves when the internet is back.';\n        return items;\n      }\n      function scheduleQueue(ms) {\n        clearTimeout(queueTimer);\n        queueTimer = setTimeout(() => processQueue(false), ms);\n      }\n      async function processQueue(manual) {\n        if (queueBusy) return;\n        queueBusy = true;\n        const before = queueCount;\n        let uploaded = 0;\n        try {\n          const items = (await queuedItems()).sort((a, b) => a.t - b.t);\n          for (const it of items) {\n            if (it.error && !manual) continue;          // needs the operator's attention\n            if (!LOCALSHARE && !navigator.onLine && !manual) break;\n            try {\n              const r = await uploadToDrive(it.blob, it.filename, { folderKey: it.folderKey, subfolder: it.subfolder });\n              await dbDo('uploads', 'readwrite', st => st.delete(it.id));\n              uploaded++;\n              if (r.folderUrl && it.folderKey === rawFolderKey()) rememberFolderUrl(r.folderUrl);\n            } catch (e) {\n              if (isPermanentUploadError(e)) {\n                it.error = driveErrorText(e);\n                try { await dbDo('uploads', 'readwrite', st => st.put(it)); } catch (e2) { }\n                continue;\n              }\n              break;                                    // still offline: try again later\n            }\n          }\n        } catch (e) { console.error('Upload queue:', e); }\n        queueBusy = false;\n        const left = await refreshQueueUI();\n        if (left.some(i => !i.error)) scheduleQueue(30000);\n        if (uploaded && !left.length) showToast(before > 1 ? 'All waiting photos uploaded ✓' : 'Waiting photo uploaded ✓');\n        else if (manual && left.length) showToast(left.length === 1 ? '1 photo pending upload. Check network connection.' : left.length + ' photos pending upload. Check network connection.', 5000);\n      }\n      async function saveQueuedToComputer() {\n        const items = await queuedItems();\n        if (!items.length) return;\n        let saved = 0;\n        for (const it of items) {\n          let ok = false;\n          if (backupDir && backupOk) ok = await saveToBackupFolder(it.blob, it.filename);\n          if (!ok) {\n            const url = URL.createObjectURL(it.blob);\n            const a = document.createElement('a'); a.href = url; a.download = it.filename; a.click();\n            setTimeout(() => URL.revokeObjectURL(url), 60000);\n            ok = true;\n            await wait(350);\n          }\n          // Photos that can never upload with this code are done once saved;\n          // the rest stay in line for Drive.\n          if (ok && it.error) { try { await dbDo('uploads', 'readwrite', st => st.delete(it.id)); } catch (e) { } }\n          if (ok) saved++;\n        }\n        await refreshQueueUI();\n        showToast(saved === 1 ? '1 photo saved to this computer.' : saved + ' photos saved to this computer.');\n      }\n      (function () {\n        const r = document.getElementById('uploadRetryBtn');\n        if (r) r.addEventListener('click', () => processQueue(true));\n        const sv = document.getElementById('uploadSaveBtn');\n        if (sv) sv.addEventListener('click', saveQueuedToComputer);\n        window.addEventListener('online', () => scheduleQueue(1000));\n        window.addEventListener('beforeunload', e => {\n          if (queueCount && !queueBusy) { e.preventDefault(); e.returnValue = ''; }\n        });\n        refreshQueueUI().then(items => { if (items.length) scheduleQueue(4000); });\n      })();\n\n      // ---- Backup folder on this computer (Chrome / Edge on a computer) ----\n      // Pick a folder once; every session is also saved there, in a subfolder\n      // named after the event, instead of going to Downloads.\n      var canBackupFolder = typeof window.showDirectoryPicker === 'function' && !DESKTOP;\n      var backupDir = null, backupOk = false;\n      function safeFileName(v) {\n        return String(v || '').replace(/[\\\\/:*?\"<>|\\u0000-\\u001f]/g, ' ').replace(/\\s+/g, ' ').trim().replace(/[. ]+$/, '').slice(0, 80);\n      }\n      function backupEventFolderName() {\n        const raw = (driveFolderKeyInput.value || '').trim();\n        const ev = /^https?:/i.test(raw) ? '' : safeFileName(cleanEventName(raw));\n        const d = new Date(), pad = n => String(n).padStart(2, '0');\n        return ev || ('Photobooth ' + d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()));\n      }\n      async function checkBackupPermission(ask) {\n        backupOk = false;\n        if (!backupDir) return false;\n        try {\n          const opts = { mode: 'readwrite' };\n          let p = await backupDir.queryPermission(opts);\n          if (p !== 'granted' && ask) p = await backupDir.requestPermission(opts);\n          backupOk = p === 'granted';\n        } catch (e) { backupOk = false; }\n        return backupOk;\n      }\n      function refreshBackupUI() {\n        const status = document.getElementById('backupStatus');\n        if (!status) return;\n        const choose = document.getElementById('backupChooseBtn');\n        const allow = document.getElementById('backupAllowBtn');\n        const stop = document.getElementById('backupStopBtn');\n        const sStatus = document.getElementById('backupSessionStatus');\n        const sAllow = document.getElementById('backupSessionAllowBtn');\n        const sec = document.getElementById('backupSection');\n        if (!canBackupFolder) {\n          status.textContent = 'Works in Chrome or Edge on a computer. On this device each photo is saved to Downloads instead.';\n          document.getElementById('backupBtns').style.display = 'none';\n          if (sec) sec.classList.add('hidden');\n          return;\n        }\n        document.getElementById('backupBtns').style.display = 'flex';\n        let text, sText;\n        if (!backupDir) {\n          text = 'Every photo is saved to Downloads. Choose a folder to keep them organised by event instead, as a second copy if Drive has problems.';\n        } else if (backupOk) {\n          text = 'Saving every photo to “' + backupDir.name + ' / ' + backupEventFolderName() + '” ✓';\n          sText = 'Saving to “' + backupDir.name + ' / ' + backupEventFolderName() + '” ✓';\n        } else {\n          text = 'Backup folder “' + backupDir.name + '” needs permission again. Tap Allow saving.';\n          sText = 'Paused: tap Allow saving so photos are copied to “' + backupDir.name + '”.';\n        }\n        status.textContent = text;\n        choose.textContent = backupDir ? 'Change folder' : 'Choose backup folder';\n        allow.style.display = backupDir && !backupOk ? '' : 'none';\n        stop.style.display = backupDir ? '' : 'none';\n        if (sStatus) sStatus.textContent = sText || '';\n        if (sAllow) sAllow.style.display = backupDir && !backupOk ? '' : 'none';\n        if (sec) sec.classList.toggle('hidden', !backupDir || state === 'capturing');\n        // Photo Session: a \"Backup folder\" button in the bottom-left bar (green dot = saving, red = needs a tap).\n        const fab = document.getElementById('backupFab');\n        if (fab) {\n          const was = fab.hidden;\n          fab.hidden = !backupDir;\n          fab.querySelector('.bk-dot').classList.toggle('bad', !!backupDir && !backupOk);\n          fab.title = sText || '';\n          document.getElementById('backupPopText').textContent = sText || '';\n          document.getElementById('backupPopAllow').style.display = backupDir && !backupOk ? '' : 'none';\n          if (!backupDir) closeBackupPop();\n          if (was !== fab.hidden && typeof scheduleDock === 'function') scheduleDock();\n        }\n      }\n      function closeBackupPop() {\n        const pop = document.getElementById('backupPop'); if (!pop || pop.hidden) return;\n        pop.hidden = true;\n        const fab = document.getElementById('backupFab'); if (fab) fab.setAttribute('aria-expanded', 'false');\n      }\n      function refreshGalleryUI() {\n        const fab = document.getElementById('galleryFab');\n        const link = document.getElementById('galleryPopLink');\n        const qr = document.getElementById('galleryPopQr');\n        if (!fab || !link || !qr) return;\n        const url = currentFolderLink || '';\n        const hide = gvPrivate();      // guests see only their own photos: no All photos button, link or QR at the booth\n        fab.hidden = !url || hide;\n        if (url && !hide) { link.href = url; link.textContent = url; qr.src = qrImageUrl(url); }\n        else { link.href = '#'; link.textContent = ''; qr.removeAttribute('src'); closeGalleryPop(); }\n        if (typeof scheduleDock === 'function') scheduleDock();\n        if (typeof guestRender === 'function') guestRender();\n      }\n      function closeGalleryPop() {\n        const pop = document.getElementById('galleryPop'); if (!pop || pop.hidden) return;\n        pop.hidden = true;\n        const fab = document.getElementById('galleryFab'); if (fab) fab.setAttribute('aria-expanded', 'false');\n      }\n      function openGalleryPop() {\n        const pop = document.getElementById('galleryPop'), fab = document.getElementById('galleryFab');\n        if (!pop || !fab || !currentFolderLink) return;\n        pop.hidden = false; fab.setAttribute('aria-expanded', 'true');\n        const r = fab.getBoundingClientRect();\n        pop.style.left = Math.max(12, Math.min(r.left, window.innerWidth - pop.offsetWidth - 12)) + 'px';\n        pop.style.bottom = (window.innerHeight - r.top + 10) + 'px';\n      }\n      function openBackupPop() {\n        const pop = document.getElementById('backupPop'), fab = document.getElementById('backupFab');\n        if (!pop || !fab) return;\n        pop.hidden = false; fab.setAttribute('aria-expanded', 'true');\n        const r = fab.getBoundingClientRect();\n        pop.style.left = Math.max(12, Math.min(r.left, window.innerWidth - pop.offsetWidth - 12)) + 'px';\n        pop.style.bottom = (window.innerHeight - r.top + 10) + 'px';\n      }\n      async function saveToBackupFolder(blob, filename) {\n        if (!backupDir || !backupOk) return false;\n        try {\n          let dir = await backupDir.getDirectoryHandle(backupEventFolderName(), { create: true });\n          const sub = safeFileName(driveSubfolder());\n          if (sub) dir = await dir.getDirectoryHandle(sub, { create: true });\n          const fh = await dir.getFileHandle(filename, { create: true });\n          const w = await fh.createWritable();\n          await w.write(blob);\n          await w.close();\n          return true;\n        } catch (e) {\n          console.error('Backup folder save failed:', e);\n          if (e && e.name === 'NotAllowedError') backupOk = false;\n          refreshBackupUI();\n          return false;\n        }\n      }\n      async function allowBackup() { await checkBackupPermission(true); refreshBackupUI(); }\n      (function () {\n        if (!document.getElementById('backupStatus')) return;\n        document.getElementById('backupChooseBtn').addEventListener('click', async () => {\n          try {\n            const dir = await window.showDirectoryPicker({ id: 'pb4u-backup', mode: 'readwrite', startIn: 'pictures' });\n            backupDir = dir; backupOk = true;\n            try { await dbDo('kv', 'readwrite', st => st.put(dir, 'backupDir')); } catch (e) { }\n            showToast('Backup folder set ✓');\n          } catch (e) {\n            if (!e || e.name !== 'AbortError') showToast('Couldn’t use that folder. Try another one (not a system folder).', 5000);\n          }\n          refreshBackupUI(); updateUI();\n        });\n        document.getElementById('backupAllowBtn').addEventListener('click', allowBackup);\n        document.getElementById('backupSessionAllowBtn').addEventListener('click', allowBackup);\n        document.getElementById('backupFab').addEventListener('click', (e) => { e.stopPropagation(); const pop = document.getElementById('backupPop'); if (pop.hidden) openBackupPop(); else closeBackupPop(); });\n        document.getElementById('backupPopAllow').addEventListener('click', (e) => { e.stopPropagation(); allowBackup(); });\n        document.getElementById('backupPopChange').addEventListener('click', (e) => { e.stopPropagation(); closeBackupPop(); document.getElementById('backupChooseBtn').click(); });\n        document.getElementById('backupPop').addEventListener('click', (e) => e.stopPropagation());\n        document.getElementById('galleryFab').addEventListener('click', (e) => { e.stopPropagation(); const pop = document.getElementById('galleryPop'); if (pop.hidden) openGalleryPop(); else closeGalleryPop(); });\n        document.getElementById('wifiFab').addEventListener('click', (e) => { e.stopPropagation(); closeGalleryPop(); const pop = document.getElementById('wifiPop'); if (pop.hidden) openWifiPop(); else closeWifiPop(); });\n        document.getElementById('wifiPopClose').addEventListener('click', closeWifiPop);\n        document.getElementById('wifiPop').addEventListener('click', (e) => e.stopPropagation());\n        document.addEventListener('click', closeWifiPop);\n        window.addEventListener('resize', closeWifiPop);\n        document.getElementById('galleryPopClose').addEventListener('click', closeGalleryPop);\n        document.getElementById('galleryPop').addEventListener('click', (e) => e.stopPropagation());\n        document.getElementById('galleryPopCopy').addEventListener('click', async () => {\n          try { await navigator.clipboard.writeText(currentFolderLink); showToast('Gallery link copied.'); }\n          catch (e) { showToast('Could not copy the gallery link.'); }\n        });\n        document.addEventListener('click', closeBackupPop);\n        document.addEventListener('click', closeGalleryPop);\n        document.addEventListener('keydown', (e) => { if (e.key === 'Escape') { closeBackupPop(); closeGalleryPop(); closeWifiPop(); } });\n        window.addEventListener('resize', () => { closeBackupPop(); closeGalleryPop(); });\n        document.getElementById('backupStopBtn').addEventListener('click', async () => {\n          backupDir = null; backupOk = false;\n          try { await dbDo('kv', 'readwrite', st => st.delete('backupDir')); } catch (e) { }\n          refreshBackupUI(); updateUI();\n        });\n        // Opening the photo session is a good moment to ask again (operator tap).\n        goToSessionBtn.addEventListener('click', () => { if (backupDir && !backupOk) allowBackup(); });\n        driveFolderKeyInput.addEventListener('input', refreshBackupUI);\n        refreshBackupUI();\n        refreshGalleryUI();\n        refreshWifiUI();\n        if (canBackupFolder) {\n          dbDo('kv', 'readonly', st => st.get('backupDir')).then(async h => {\n            if (!h) return;\n            backupDir = h;\n            await checkBackupPermission(false);\n            refreshBackupUI(); updateUI();\n          }).catch(() => { });\n        }\n      })();\n\n      let sessionNumber = null; // set once per completed session, reused across its retakes\n      let lastRenderedFolderUrl = null;\n\n      function renderFolderQR(url) {\n        if (lastRenderedFolderUrl === url) return; // same folder as last time — nothing to redraw\n        qrResults.innerHTML = '';\n        lastRenderedFolderUrl = url;\n        addQrResult(usesGallery(url) ? 'Photo gallery' : 'Shared Google Drive Folder', shareUrlFor(url));\n      }\n\n      function renderSingleFileQR(url, label) {\n        qrResults.innerHTML = '';\n        lastRenderedFolderUrl = null;\n        addQrResult(label || 'Download', url);\n      }\n\n      async function uploadLayoutForQR(layoutKey, onRetry) {\n        const tempCanvas = document.createElement('canvas');\n        renderCompositeToCanvas(layoutKey, tempCanvas);\n        // High-quality JPEG: looks the same as PNG but about a fifth of the size,\n        // so QR codes appear faster on venue Wi-Fi. Flattened onto white first so\n        // any transparent edges don't turn black.\n        const flat = document.createElement('canvas');\n        flat.width = tempCanvas.width; flat.height = tempCanvas.height;\n        const fctx = flat.getContext('2d');\n        fctx.fillStyle = '#ffffff'; fctx.fillRect(0, 0, flat.width, flat.height);\n        fctx.drawImage(tempCanvas, 0, 0);\n        const blob = await new Promise(resolve => flat.toBlob(resolve, 'image/jpeg', 0.92));\n        const label = layoutDef(layoutKey).name + ' Layout';\n        // e.g. \"1_strip.jpg\" / \"2_grid.jpg\" so files sort cleanly in the folder —\n        // only the chosen format is ever uploaded, so the folder only ever\n        // fills up with that one kind of file.\n        // Bonus sessions: \"BONUS_1_strip.jpg\", so they stand apart from event-day files.\n        // Multi-device codes: \"3_strip_cam2.jpg\".\n        const filename = filePrefix() + (sessionNumber || 1) + '_' + layoutKey + deviceTag() + '.jpg';\n\n        if (driveReady() || LOCALSHARE) {\n          // Weak venue internet: try 3 times, then keep the photo on this device\n          // and upload it by itself once the connection is back.\n          const dest = { folderKey: rawFolderKey(), subfolder: driveSubfolder() };\n          let drive = null, lastErr = null;\n          // Saving on this device (laptop / tablet app) never needs the internet.\n          const online = LOCALSHARE || navigator.onLine !== false;\n          // Clearly offline: keep it for later straight away (no 5 s of retries).\n          if (!online) lastErr = new Error('offline');\n          for (let attempt = 0; attempt < 3 && !drive && online; attempt++) {\n            if (attempt) { if (onRetry) onRetry(attempt); await wait(attempt === 1 ? 1500 : 4000); }\n            try { drive = await uploadToDrive(blob, filename, dest); }\n            catch (e) { lastErr = e; if (isPermanentUploadError(e)) break; }\n          }\n          if (!drive) {\n            let queued = false;\n            try { queued = await queueUpload(blob, filename, dest); } catch (e) { console.error('Could not keep photo for later:', e); }\n            const err = lastErr || new Error('Upload failed');\n            err.queued = queued;\n            throw err;\n          }\n          if (queueCount) scheduleQueue(1500);\n          if (drive.folderUrl) rememberFolderUrl(drive.folderUrl);\n          registerEvent(drive.folderUrl || getCachedFolderUrl(), true);\n          return { label: label + ' (Google Drive)', url: drive.downloadUrl, fileId: drive.fileId };\n        } else {\n          const url = await uploadToLitterbox(blob, filename, '1h');\n          return { label: label, url: url };\n        }\n      }\n\n\n      // ---- What guests see after scanning their QR (Setup -> Share: \"After guests scan their QR\") ----\n      //   'all'  everyone's photos (today's behaviour)   'mine' their own photos first, with a button for everyone's\n      //   'only' their own photos and nothing else; the booth also hides its All photos button and the guest screen's All photos QR.\n      // A guest's own page is a link made from a random code per session (website: /p/<code>, laptop app: /o/<code>), so it never\n      // contains the event folder or a photo number. Website with a rental code, and the laptop app.\n      var gvMode = 'all', gvLinkQ = [], gvSent = {};\n      var GV_CODE_RE = /^[A-Za-z0-9_-]{16,40}$/;\n      // The website: a rental code, and also the free trial (its own photos stay private too).\n      function gvServer() { var pb = window.__PB; return !!(pb && (pb.type === 'rental' || pb.type === 'trial')); }\n      function gvAvailable() { return LOCALSHARE ? !!(LANREMOTE || (window.pb4u && typeof window.pb4u.guestViewSet === 'function') || (ANDROID_LOCAL && typeof window.__PBLocal.guestViewSet === 'function')) : gvServer(); }\n      function gvActive() { return gvAvailable() && gvMode !== 'all'; }\n      function gvPrivate() { return gvAvailable() && gvMode === 'only'; }\n      function gvStore(k) { try { return JSON.parse(localStorage.getItem(k) || 'null'); } catch (e) { return null; } }\n      function gvCodeFor(n) {\n        var key = 'pb_gvc:' + currentFolderKey(), o = gvStore(key) || {}, k = String(n || 1);\n        if (!GV_CODE_RE.test(String(o[k] || ''))) {\n          var a = new Uint8Array(18); crypto.getRandomValues(a);\n          var t = ''; a.forEach(function (b) { t += String.fromCharCode(b); });\n          o[k] = btoa(t).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/, '');\n          var keys = Object.keys(o); if (keys.length > 400) keys.slice(0, keys.length - 400).forEach(function (x) { delete o[x]; });\n          try { localStorage.setItem(key, JSON.stringify(o)); } catch (e) { }\n        }\n        return o[k];\n      }\n      // The link of a session's own page (null when the laptop is not on a Wi-Fi network).\n      function gvSessionUrl(n) {\n        var code = gvCodeFor(n || sessionNumber || 1);\n        if (LOCALSHARE) { var base = lanBaseNow(); return base ? base + '/o/' + code : null; }\n        return location.origin + '/p/' + code;\n      }\n      function gvFileNum(filename) {\n        var m = /^(?:BONUS_)?(\\d+)_(?!guestbook|360)/.exec(String(filename || ''));\n        return m ? Number(m[1]) : 0;\n      }\n      async function gvApi(body) {\n        var token = null, deviceId = null; try { token = localStorage.getItem('pb_token'); deviceId = localStorage.getItem('pb_device'); } catch (e) { }\n        var r = await fetch('/api/guestview', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(Object.assign({ token: token, deviceId: deviceId }, body)) });\n        var j = await r.json().catch(function () { return {}; });\n        if (!r.ok) throw new Error(j.error || ('error ' + r.status));\n        return j;\n      }\n      function gvFolderId(folderUrl) { var m = /\\/folders\\/([A-Za-z0-9_-]{10,80})/.exec(String(folderUrl || '')); return m ? m[1] : ''; }\n      // Tells the laptop app / the server which mode this event is in. The server also hands back the booth's own key to the\n      // event gallery, so the operator can still open it when guests may not.\n      async function gvApply() {\n        if (!gvAvailable()) return;\n        try {\n          if (LOCALSHARE) {\n            if (ANDROID_LOCAL) window.__PBLocal.guestViewSet(gvMode);\n            else if (LANREMOTE) await fetch('/local/guestview', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ mode: gvMode }) });\n            else await window.pb4u.guestViewSet(gvMode);\n            return;\n          }\n          var fid = gvFolderId(getCachedFolderUrl()); if (!fid) return;\n          if (gvSent[fid] === gvMode) return;\n          var j = await gvApi({ action: 'mode', folderKey: rawFolderKey(), folder: fid, mode: gvMode });\n          gvSent[fid] = gvMode;\n          if (j && j.opKey) { try { localStorage.setItem('pb_gvk:' + fid, j.opKey); } catch (e) { } try { showDriveFolderPreview(getCachedFolderUrl(), ''); } catch (e) { } }\n        } catch (e) { console.error('Guest view:', e); }\n      }\n      // Website: every saved file of a guest's session is added to their page. Kept and retried if the internet drops.\n      function gvQueueLoad() { if (!gvLinkQ.length) { var q = gvStore('pb_gvq'); if (Array.isArray(q)) gvLinkQ = q.slice(0, 100); } }\n      function gvQueueSave() { try { localStorage.setItem('pb_gvq', JSON.stringify(gvLinkQ)); } catch (e) { } }\n      var gvFlushing = false;\n      async function gvFlush() {\n        if (gvFlushing) return; gvFlushing = true;\n        try {\n          gvQueueLoad();\n          while (gvLinkQ.length && navigator.onLine !== false) {\n            var it = gvLinkQ[0];\n            try {\n              await gvApi({ action: 'link', folderKey: it.folderKey, folder: it.folder, code: it.code, name: it.event, files: [{ id: it.id, name: it.name, mime: it.mime }] });\n              gvLinkQ.shift(); gvQueueSave();\n            } catch (e) { if (/locked|belongs|Bad request|event/i.test(String(e.message))) { gvLinkQ.shift(); gvQueueSave(); continue; } setTimeout(gvFlush, 6000); break; }\n          }\n        } finally { gvFlushing = false; }\n      }\n      // Called after every upload (see uploadToDrive).\n      function gvAfterUpload(filename, mime, data, folderKey) {\n        if ((!gvActive() && outputMode !== 'both') || LOCALSHARE) return;\n        var n = gvFileNum(filename), fid = gvFolderId(data.folderUrl || getCachedFolderUrl());\n        if (!n || !fid || !data.fileId) return;\n        gvApply();\n        gvQueueLoad();\n        gvLinkQ.push({ code: gvCodeFor(n), folderKey: folderKey, folder: fid, id: data.fileId, name: filename, mime: mime || '', event: (labelInput.value || '').trim().slice(0, 80) });\n        gvQueueSave(); gvFlush();\n      }\n      var GV_HINTS = {\n        all: 'Guests open the whole event gallery, with their own photo first.',\n        mine: 'Guests see their own photos first, with a Show photos with other guests button.',\n        only: 'Guests see only their own photos. The All photos button and the guest screen\\u2019s QR are hidden here, and the event gallery is closed to them. Use Lock booth so guests can\\u2019t open Setup or Extras.'\n      };\n      function refreshGvUI() {\n        var box = document.getElementById('gvBox'); if (!box) return;\n        box.style.display = gvAvailable() ? '' : 'none';\n        setSelectValue('gvSelect', gvMode);\n        try { pillSyncAll(); } catch (e) { }\n        document.getElementById('gvHint').textContent = GV_HINTS[gvMode] || '';\n      }\n      function gvChanged() {\n        refreshGvUI();\n        try { refreshGalleryUI(); } catch (e) { }\n        try { var fu = getCachedFolderUrl(); if (fu) (LOCALSHARE ? showLocalFolderPreview : showDriveFolderPreview)(fu, ''); } catch (e) { }\n        gvApply();\n        if (typeof scheduleSetupSave === 'function') scheduleSetupSave();\n      }\n      function applyGvSetup(v) { gvMode = v === 'mine' || v === 'only' ? v : 'all'; refreshGvUI(); try { refreshGalleryUI(); } catch (e) { } gvApply(); }\n      document.getElementById('gvSelect').addEventListener('change', function () { gvMode = this.value === 'mine' || this.value === 'only' ? this.value : 'all'; gvChanged(); });\n      setTimeout(refreshGvUI, 0);\n      // The operator's link to the event gallery when guests may not open it: it carries the booth's own key.\n      function gvOpUrl(url) {\n        if (!url || !gvPrivate()) return url;\n        var k = ''; try { k = localStorage.getItem('pb_gvk:' + gvFolderId(getCachedFolderUrl())) || ''; } catch (e) { }\n        return k ? url + (url.indexOf('?') < 0 ? '?k=' : '&k=') + k : url;\n      }\n      // Where a QR points while the guest's own photo is still saving (or the booth is offline).\n      function qrFallbackUrl(folderUrl) { return gvActive() ? gvSessionUrl() : shareUrlFor(folderUrl); }\n\n      // ---- The guest's own QR codes, shown after each session ----\n      // The session QR opens the saved photo in the online gallery (or, when guests may only see their own photos, their own page).\n      function fileShareUrl(fileId, own) {\n        if (own && (gvActive() || outputMode === 'both')) { const u = gvSessionUrl(); if (u || gvPrivate()) return u; }\n        if (LOCALSHARE) { const i = String(fileId).indexOf('/'); return i > 0 ? localShareUrl('pb4u-local:' + fileId.slice(0, i), fileId.slice(i + 1)) : null; }\n        const folderUrl = getCachedFolderUrl();\n        const g = folderUrl && usesGallery(folderUrl) ? galleryUrlFor(folderUrl) : null;\n        if (g) return g + '#' + fileId;\n        return 'https://drive.google.com/file/d/' + encodeURIComponent(fileId) + '/view';\n      }\n      function qrSlot(kind, label, waitText) {\n        const wrap = document.createElement('div');\n        wrap.className = 'qr-result'; wrap.dataset.kind = kind;\n        const box = document.createElement('div'); box.className = 'qr-box';\n        const w = document.createElement('span'); w.className = 'qr-wait'; w.textContent = waitText;\n        box.appendChild(w);\n        const cap = document.createElement('p'); cap.className = 'qr-caption'; cap.textContent = label;\n        wrap.append(box, cap);\n        qrResults.appendChild(wrap);\n        return wrap;\n      }\n      function fillQrSlot(kind, url) {\n        const wrap = qrResults.querySelector('.qr-result[data-kind=\"' + kind + '\"]'); if (!wrap) return;\n        const box = wrap.querySelector('.qr-box'); box.innerHTML = '';\n        if (!url) {\n          // App with no Wi-Fi: the photo is safe on the laptop, there's just no link for phones.\n          const w0 = document.createElement('span'); w0.className = 'qr-wait'; w0.textContent = LOCALSHARE ? NO_LAN_TEXT : 'No link yet';\n          box.appendChild(w0);\n          const l0 = wrap.querySelector('.qr-link'); if (l0) l0.remove();\n          guestRender(); return;\n        }\n        const img = document.createElement('img'); img.className = 'qr-img'; img.src = qrImageUrl(url); img.alt = wrap.querySelector('.qr-caption').textContent + ' QR code';\n        box.appendChild(img);\n        let link = wrap.querySelector('.qr-link');\n        if (!link) { link = document.createElement('a'); link.className = 'qr-link'; link.target = '_blank'; link.rel = 'noopener'; link.textContent = 'Open'; wrap.appendChild(link); }\n        link.href = url;\n        guestRender();\n      }\n      function failQrSlot(kind, text) {\n        const wrap = qrResults.querySelector('.qr-result[data-kind=\"' + kind + '\"]'); if (!wrap) return;\n        const w = wrap.querySelector('.qr-wait'); if (w) w.textContent = text;\n        guestRender();\n      }\n\n      let qrGeneration = 0;\n      async function showQRForCurrentPhoto() {\n        if (!shotCanvases.every(Boolean)) return;\n        const myGeneration = ++qrGeneration;\n        qrResults.innerHTML = '';\n        lastRenderedFolderUrl = null;\n        const isBoth = (outputMode === 'both');\n        qrSlot('photo', isBoth ? 'Your photo & GIF' : 'Your photo', isBoth ? 'Saving your photo & GIF…' : 'Saving your photo…');\n        // Guests get a working QR straight away: the event's All photos page,\n        // swapped for their own photo's QR as soon as the upload finishes. (The offline app has no extra\n        // All photos QR here: the dock's All photos button already shows it.)\n        const evFolder = getCachedFolderUrl();\n        const gv = gvActive() || isBoth;       // guests get their own page: its link works straight away, whatever the upload does\n        let slowTimer = null;\n        const setCap = (t) => { const w = qrResults.querySelector('.qr-result[data-kind=\"photo\"] .qr-caption'); if (w) w.textContent = t; };\n        const OFFLINE_CAP = 'Scan now \\u00b7 your photo arrives here once the booth is back online';\n        if (evFolder || gv) {\n          setCap(gv ? (navigator.onLine === false && !LOCALSHARE ? OFFLINE_CAP : (isBoth ? 'Your photo & GIF \\u00b7 saving\\u2026' : 'Your photos \\u00b7 saving\\u2026')) : LOCALSHARE ? 'All photos \\u00b7 saving your photo\\u2026' : navigator.onLine === false ? OFFLINE_CAP : 'All photos \\u00b7 your photo is uploading\\u2026');\n          fillQrSlot('photo', qrFallbackUrl(evFolder));\n          slowTimer = setTimeout(() => { if (myGeneration === qrGeneration) setCap(gv ? (isBoth ? 'Your photo & GIF \\u00b7 they will appear here shortly' : 'Your photos \\u00b7 they will appear here shortly') : 'All photos \\u00b7 your photo will appear here shortly'); }, 60000);\n        }\n        guestRender();\n        let result = null, lastError = null;\n        const onRetry = () => { if (myGeneration !== qrGeneration) return; if (evFolder) setCap('All photos \\u00b7 weak internet, still uploading\\u2026'); else failQrSlot('photo', 'Weak internet. Trying again\\u2026'); };\n        try { result = await uploadLayoutForQR(currentLayout, onRetry); }\n        catch (err) { lastError = err; console.error('Photo upload failed:', err); }\n        clearTimeout(slowTimer);\n        if (myGeneration !== qrGeneration) return null;\n        if (!result && lastError && lastError.queued && !isPermanentUploadError(lastError)) {\n          // Kept on this device; it uploads later. Give the guest the event's\n          // All photos QR instead, where their photo will appear.\n          const folderUrl = getCachedFolderUrl();\n          const wrap = qrResults.querySelector('.qr-result[data-kind=\"photo\"]');\n          if ((folderUrl || gv) && wrap) {\n            wrap.querySelector('.qr-caption').textContent = OFFLINE_CAP;\n            fillQrSlot('photo', qrFallbackUrl(folderUrl));\n            wrap.classList.add('qr-offline');\n          } else {\n            failQrSlot('photo', 'No internet right now. Your photo is saved on this booth and goes online by itself later.');\n          }\n          showToast('Offline: photo saved locally. Will sync automatically when online.', 6000);\n          return null;\n        }\n        if (!result && (evFolder || gv)) {\n          setCap(gv ? (isBoth ? 'Your photo & GIF \\u00b7 they appear here once saved' : 'Your photos \\u00b7 they appear here once saved') : 'All photos \\u00b7 your photo appears here once it uploads');\n          showToast('Photo not saved yet. ' + driveErrorText(lastError), 7000);\n          return null;\n        }\n        if (!result) {\n          failQrSlot('photo', lastError && lastError.queued ? 'Not uploaded. Kept on this device.' : 'Couldn’t save. Check the internet.');\n          showToast('Photo not saved. ' + driveErrorText(lastError), 7000);\n          return null;\n        }\n        setCap(qrResults.querySelector('.qr-result[data-kind=\"wifi\"]') ? (isBoth ? '2 \\u00b7 Your photo & GIF' : '2 \\u00b7 Your photo') : (isBoth ? 'Your photo & GIF' : 'Your photo'));\n        fillQrSlot('photo', result.fileId ? fileShareUrl(result.fileId, true) : result.url);\n        showToast(isBoth ? 'Photo saved (GIF creating…)' : 'Photo saved');\n        return myGeneration;\n      }\n\n      // ──────────────────────────────────────────────────────────────────\n      // GIF MODE — session capture + encode + upload\n      // ──────────────────────────────────────────────────────────────────\n\n      var outputMode = 'photo';    // 'photo' | 'gif' | 'both' | 'flipbook'\n      var flipSec = 6, flipFrames = 24, flipCover = true, flipBack = true, flipbookResult = null;   // flipbook (included extra): clip length, frames, and the result on screen\n      var flipCollation = 'stack'; // 'stack' (cut-and-stack) | 'grid' (sequential)\n      var flipGutter = true;       // 6mm binding gutter with staple dots & crease guide\n      var flipNumbers = true;      // frame numbering in the binding gutter\n      var flipGridPreset = 'auto'; // 'auto' | '6up' | '8up': print grid preset\n      var flipPrinterPool = '';    // secondary printer name for multi-printer speed pooling\n      var flipPoolMode = 'pages';  // 'pages' (alternate sheets) | 'copies' (alternate copies)\n      var flipCoverStyle = 'title'; // 'title' | 'photo' | 'custom'\n      var flipCoverAssetId = null;  // asset ID for custom uploaded cover image\n      var flipBackQr = true;        // embed digital flipbook QR code on back card\n      var flipBackText = '';        // custom text below QR (defaults to 'Scan to view & share')\n      var flipCues = true;          // dynamic motion prompts during clip recording\n      var flipViewMode = 'flip';    // 'flip' (interactive single booklet) | 'grid' (multi-card overview)\n      var flipCurrentCard = 0;      // current card index in interactive flip player\n      var flipAutoPlaying = false;  // auto-flipping state\n      var flipPlayTimer = null;     // auto-play interval\n      var gifLayoutMode = 'solo';  // 'solo' | 'follow' | 'raw': what the GIF frames are placed in\n      function refreshGifLayoutUI() {\n        var sel = document.getElementById('gifLayoutSelect'), gh = document.getElementById('gifLayoutHint');\n        if (sel) sel.value = gifLayoutMode;\n        if (gh) gh.textContent = gifLayoutMode === 'raw' ? 'The GIF is the plain camera view, without your frame or title.'\n          : gifLayoutMode === 'follow' ? 'The GIF uses the layout chosen for the photos, with the same picture in every spot.'\n            : 'The GIF sits in the one-photo Solo layout with your frame, title and design, even when the photos use a strip. Guests should stand in the middle of the picture.';\n      }\n      var gifSpeed = 0;            // 0 chooses 2x or 3x automatically from the recorded session length\n      var gifSessionCapture = null;\n      var completedGifCapture = null;\n\n      function isGifAllowed() { return !(window.__PB) || !!(window.__PB.gifOpt); }\n\n      function refreshGifUI() {\n        var on = isGifAllowed(), fb = extraOn('flipbook');\n        var s = document.getElementById('gifModeSection');\n        if (s) s.style.display = (on || fb) ? '' : 'none';\n    