// asset id -> decoded AudioBuffer\n      function dataUrlBytes(url) {\n        const b = atob(String(url).split(',')[1] || ''), a = new Uint8Array(b.length);\n        for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i);\n        return a.buffer;\n      }\n      function decodeAudio(c, ab) {\n        return new Promise(function (res, rej) { try { const pr = c.decodeAudioData(ab, res, rej); if (pr && pr.then) pr.then(res, rej); } catch (e) { rej(e); } });\n      }\n      // Decodes the chosen sounds once their files are here (they may still be loading from the server).\n      function prepSounds(tries) {\n        const c = audioCtx(); if (!c) return;\n        let waiting = false;\n        [fx.sShut, fx.sTick].forEach(function (o) {\n          if (!o || sndBufs[o.id]) return;\n          const rec = typeof ASSETS !== 'undefined' && ASSETS[o.id];\n          if (!rec) { waiting = true; return; }\n          sndBufs[o.id] = 'loading';\n          decodeAudio(c, dataUrlBytes(rec.url)).then(function (b) { sndBufs[o.id] = b; }, function () { delete sndBufs[o.id]; });\n        });\n        if (waiting && (tries || 0) < 15) setTimeout(function () { prepSounds((tries || 0) + 1); }, 2000);\n      }\n      function playOwn(o) {\n        const c = soundOk(), b = o && sndBufs[o.id];\n        if (!c || !b || b === 'loading') return false;\n        const s = c.createBufferSource(), g = c.createGain();\n        s.buffer = b; g.gain.value = fx.vol * 1.1;\n        s.connect(g); g.connect(c.destination); s.start(c.currentTime);\n        return true;\n      }\n      // A picked sound file -> mono 22 kHz WAV, leading silence cut, at most maxSec long (small enough to sync).\n      async function soundFileToWav(file, maxSec) {\n        if (!file) throw new Error('No file picked.');\n        if (file.size > 20000000) throw new Error('That file is too big. Use a short sound (a few seconds).');\n        const c = audioCtx(); if (!c) throw new Error('This browser can\\u2019t play sounds.');\n        let ab;\n        try { ab = await decodeAudio(c, await file.arrayBuffer()); }\n        catch (e) { throw new Error('That file isn\\u2019t a sound this device can play. Try an MP3 or WAV.'); }\n        const len = ab.length, sr = ab.sampleRate, nch = ab.numberOfChannels, mono = new Float32Array(len);\n        for (let k = 0; k < nch; k++) { const d = ab.getChannelData(k); for (let i = 0; i < len; i++) mono[i] += d[i] / nch; }\n        let start = 0; while (start < len && Math.abs(mono[start]) < 0.02) start++;\n        if (start >= len) throw new Error('That sound is silent.');\n        start = Math.max(0, start - Math.round(sr * 0.004));\n        const R = 22050, n = Math.max(1, Math.min(Math.round((len - start) / sr * R), Math.round(maxSec * R)));\n        const pcm = new Int16Array(n), step = sr / R, fade = Math.round(R * 0.03);\n        for (let i = 0; i < n; i++) {\n          const t = start + i * step, i0 = Math.floor(t), fr = t - i0;\n          let v = (mono[i0] || 0) * (1 - fr) + (mono[i0 + 1] || 0) * fr;\n          if (i > n - fade) v *= (n - i) / fade;\n          pcm[i] = Math.max(-32768, Math.min(32767, Math.round(v * 32767)));\n        }\n        const buf = new ArrayBuffer(44 + n * 2), dv = new DataView(buf);\n        const str = function (o, t) { for (let i = 0; i < t.length; i++) dv.setUint8(o + i, t.charCodeAt(i)); };\n        str(0, 'RIFF'); dv.setUint32(4, 36 + n * 2, true); str(8, 'WAVE'); str(12, 'fmt '); dv.setUint32(16, 16, true);\n        dv.setUint16(20, 1, true); dv.setUint16(22, 1, true); dv.setUint32(24, R, true); dv.setUint32(28, R * 2, true);\n        dv.setUint16(32, 2, true); dv.setUint16(34, 16, true); str(36, 'data'); dv.setUint32(40, n * 2, true);\n        new Int16Array(buf, 44).set(pcm);\n        const u8 = new Uint8Array(buf); let bin = '';\n        for (let i = 0; i < u8.length; i += 0x8000) bin += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000));\n        return 'data:audio/wav;base64,' + btoa(bin);\n      }\n      function fxBeep(n) { if (playOwn(fx.sTick)) return; tone(n === 1 ? 988 : 740, n === 1 ? 0.16 : 0.1, 'sine', 0.9); }\n      function fxTick(n) { if (voiceActive()) return; fxBeep(n); }       // the voice says the numbers instead of the beeps\n      function fxPose() { tone(1175, 0.09, 'triangle', 0.7); tone(1568, 0.14, 'triangle', 0.6, 0.08); }\n      function fxShutter() {\n        if (playOwn(fx.sShut)) return;\n        const c = soundOk(); if (!c) return;\n        const t = c.currentTime, len = Math.floor(c.sampleRate * 0.11), buf = c.createBuffer(1, len, c.sampleRate), d = buf.getChannelData(0);\n        for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2.2);\n        [0, 0.075].forEach(function (at, k) {\n          const s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain();\n          s.buffer = buf; f.type = 'bandpass'; f.frequency.value = k ? 1800 : 3200; f.Q.value = 0.9;\n          g.gain.value = (k ? 0.5 : 0.9) * fx.vol;\n          s.connect(f); f.connect(g); g.connect(c.destination);\n          s.start(t + at);\n        });\n        tone(140, 0.07, 'sine', 0.8);\n      }\n      function fxStartChime() { tone(880, 0.1, 'sine', 0.7); tone(1320, 0.16, 'sine', 0.6, 0.09); }\n\n      // ---- Voice countdown: \"Get ready ... Three, Two, One ... Smile!\" ----\n      // The device's own voice (speechSynthesis): no sound files, works offline with the\n      // voices installed on the device. No voice on the device = the beeps are used.\n      const VOICE_WORDS = {\n        en: {\n          ready: 'Get ready!', next: 'Next one!', smile: 'Smile!',\n          n: ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen']\n        },\n        fil: {\n          ready: 'Humanda!', next: 'Susunod!', smile: 'Ngiti!',\n          n: ['', 'Isa', 'Dalawa', 'Tatlo', 'Apat', 'Lima', 'Anim', 'Pito', 'Walo', 'Siyam', 'Sampu', 'Labing-isa', 'Labindalawa', 'Labintatlo', 'Labing-apat', 'Labinlima']\n        }\n      };\n      const VOICE_LEAD = 150;   // ms: speech starts a little early so the word lands on the number\n      function voiceSynth() {\n        try { return window.speechSynthesis && typeof window.SpeechSynthesisUtterance === 'function' ? window.speechSynthesis : null; } catch (e) { return null; }\n      }\n      // Android tablet app: the WebView's own speech is unreliable (often no voices), so the tablet's text-to-speech is used through the app.\n      function voiceNative() {\n        try { const V = window.__PBVoice; return V && typeof V.speak === 'function' && typeof V.voices === 'function' ? V : null; } catch (e) { return null; }\n      }\n      function voiceEngine() { return voiceNative() ? 'native' : voiceSynth() ? 'web' : ''; }\n      function voicesFor(lang) {\n        let all = [];\n        const V = voiceNative();\n        if (V) {\n          try { all = JSON.parse(V.voices(lang === 'fil' ? 'fil' : 'en') || '[]').map(function (v) { return { name: String(v.name), lang: String(v.lang || ''), localService: !!v.local }; }); } catch (e) { }\n        } else {\n          const ss = voiceSynth(); if (!ss) return [];\n          try { all = ss.getVoices() || []; } catch (e) { }\n        }\n        const re = lang === 'fil' ? /^(fil|tl)([-_]|$)/i : /^en([-_]|$)/i;\n        let list = all.filter(function (v) { return re.test(v.lang || ''); });\n        if (navigator.onLine === false) list = list.filter(function (v) { return v.localService; });   // offline: only voices stored on the device\n        return list;\n      }\n      // A readable name for the voice picker (Android voice names look like en-us-x-tpd-local).\n      function voiceLabel(v) {\n        if (voiceNative()) return v.name.replace(/-local$/i, '').replace(/-network$/i, ' (needs internet)');\n        return v.name.replace(/^Microsoft\\s+/i, '');\n      }\n      // Tagalog needs a Filipino voice on the device; without one the English words are used.\n      function voiceLang() { return fx.vLang === 'fil' && voicesFor('fil').length ? 'fil' : 'en'; }\n      function voicePick() {\n        const list = voicesFor(voiceLang());\n        if (!list.length) return null;\n        return list.find(function (v) { return v.name === fx.vName; }) || list.find(function (v) { return v.localService; }) || list[0];\n      }\n      function voiceActive() { return !!(fx.sound && fx.vOn && voiceEngine() && voicePick()); }\n      function voiceStop() {\n        const V = voiceNative();\n        if (V) { try { V.stop(); } catch (e) { } return; }\n        const ss = voiceSynth(); try { if (ss && (ss.speaking || ss.pending)) ss.cancel(); } catch (e) { }\n      }\n      function voiceSay(text) {\n        if (!voiceActive()) return false;\n        const V = voiceNative(), v = voicePick(), vol = fx.vol === 1 ? 1 : fx.vol === 0.35 ? 0.5 : 0.85;\n        if (V) { try { return !!V.speak(text, v.name, vol); } catch (e) { return false; } }      // the app cuts off anything still being said\n        const ss = voiceSynth();\n        try {\n          if (ss.speaking || ss.pending) ss.cancel();     // never let a late word pile up behind the next one\n          if (ss.paused) ss.resume();\n          const u = new SpeechSynthesisUtterance(text);\n          u.voice = v; u.lang = v.lang; u.rate = 1; u.pitch = 1;\n          u.volume = vol;\n          ss.speak(u);\n          return true;\n        } catch (e) { return false; }\n      }\n      function voiceWords() { return VOICE_WORDS[voiceLang()]; }\n      // A number on the screen. True = the voice handles it (spoken, or silent on purpose), so no beep.\n      function voiceNumber(n) {\n        if (!voiceActive()) return false;\n        if (fx.vCount !== 'all' && n > 3) return true;\n        voiceSay(voiceWords().n[n] || String(n));\n        return true;\n      }\n      // \"Get ready!\" as a countdown starts; only when the time before \"Three\" leaves room for it.\n      function voiceReady(index, retake, totalSec) {\n        if (fx.vCount === 'all' || totalSec < 5) return;\n        const w = voiceWords();\n        voiceSay(index > 0 && !retake ? w.next : w.ready);\n      }\n      function voiceSmile() { return voiceSay(voiceWords().smile); }\n      // Some browsers only speak after a tap: a silent word on the first tap opens it.\n      function voicePrime() {\n        if (voiceNative()) return;\n        const ss = voiceSynth(); if (!ss || voicePrime.done) return;\n        voicePrime.done = true;\n        try { const u = new SpeechSynthesisUtterance(' '); u.volume = 0; ss.speak(u); } catch (e) { }\n      }\n      try { const ssv = voiceSynth(); if (ssv && ssv.addEventListener) ssv.addEventListener('voiceschanged', function () { if (typeof refreshFxUI === 'function') refreshFxUI(); }); } catch (e) { }\n\n      // ---- Screen flash ----\n      const screenFlash = document.createElement('div');\n      screenFlash.id = 'screenFlash'; screenFlash.setAttribute('aria-hidden', 'true');\n      document.body.appendChild(screenFlash);\n      function screenFlashOn() {\n        screenFlash.classList.add('on');\n        guestCall('screenflash', true);\n      }\n      function screenFlashOff() {\n        screenFlash.classList.remove('on');\n        guestCall('screenflash', false);\n      }\n\n      // ---- Start without touching ----\n      const hf = { timer: null, prev: null, hist: [], fm: null, fmLoading: null, fmBusy: false, lastFire: 0, smileRun: 0, score: 0, faceSeen: 0, failed: '' };\n      const hfCanvas = document.createElement('canvas');\n      const HF_WAVE = { less: 0.12, normal: 0.07, more: 0.04 };      // share of the picture that must move\n      // mouth width / face width. Measured on real photos: neutral faces ~0.36-0.37,\n      // small smiles ~0.39-0.42, clear smiles 0.44-0.49.\n      const HF_SMILE = { less: 0.46, normal: 0.43, more: 0.40 };\n      function hfMeterOn() {\n        // Setup → Session open: show the live meter so the renter can try it.\n        return fx.hands !== 'off' && !tabSetup.classList.contains('hidden') && curStep === 7;\n      }\n      function hfWanted() {\n        if (fx.hands === 'off' || document.hidden || !streamActive || !video.videoWidth) return false;\n        if (hfMeterOn()) return true;\n        if (document.body.classList.contains('in-session') && readyOverlay.classList.contains('ready-active') && readyOverlay.classList.contains('hands'))\n          return Date.now() - (hf.readyAt || 0) > 1200 && Date.now() - hf.lastFire > 2500;\n        return document.body.classList.contains('in-session') && state === 'idle' && !flowBusy && !(typeof pickOpen !== 'undefined' && pickOpen) &&\n          !readyOverlay.classList.contains('ready-active') && Date.now() - hf.lastFire > 4000;\n      }\n      function hfFire() {\n        hf.lastFire = Date.now(); hf.hist = []; hf.smileRun = 0;\n        if (hfMeterOn()) { hfMeter(true); return; }       // only testing in Setup\n        if (readyOverlay.classList.contains('ready-active')) { if (readyOverlay.classList.contains('hands')) readyStartBtn.click(); return; }   // Get ready: start the countdown\n        fxStartChime();\n        beginGuestFlow(true);\n      }\n      function hfMeter(fired) {\n        const box = document.getElementById('fxMeter'); if (!box) return;\n        box.hidden = !hfMeterOn();\n        if (box.hidden) return;\n        const bar = document.getElementById('fxMeterBar'), txt = document.getElementById('fxMeterTxt'), mark = document.getElementById('fxMeterMark');\n        let pct = 0, thr = 0;\n        if (fx.hands === 'wave') { pct = Math.min(1, hf.score / 0.2); thr = HF_WAVE[fx.sens] / 0.2; }\n        else { pct = Math.max(0, Math.min(1, (hf.score - 0.34) / 0.2)); thr = (HF_SMILE[fx.sens] - 0.34) / 0.2; }\n        bar.style.width = Math.round(pct * 100) + '%';\n        mark.style.left = Math.round(thr * 100) + '%';\n        if (fired) { txt.textContent = fx.hands === 'wave' ? 'Wave seen ✓ This would start a session.' : 'Smile seen ✓ This would start a session.'; box.classList.add('hit'); setTimeout(function () { box.classList.remove('hit'); }, 1500); return; }\n        if (hf.failed) txt.textContent = 'Couldn’t start face detection on this device (' + hf.failed + '). Use Wave instead.';\n        else if (fx.hands === 'smile' && !hf.fm) txt.textContent = 'Getting face detection ready… (about 10 MB, the first time only)';\n        else if (fx.hands === 'smile') txt.textContent = Date.now() - hf.faceSeen < 1500 ? 'Smile at the camera to test it.' : 'No face seen. Stand closer to the camera.';\n        else txt.textContent = 'Wave at the camera to test it.';\n      }\n      function hfLoop() {\n        clearTimeout(hf.timer);\n        const want = hfWanted();\n        hf.timer = setTimeout(hfLoop, fx.hands === 'smile' ? 250 : 120);\n        hfMeter(false);\n        if (!want) { hf.prev = null; hf.hist = []; hf.smileRun = 0; return; }\n        try { fx.hands === 'wave' ? hfWave() : hfSmile(); } catch (e) { console.error('hands-free', e); }\n      }\n      // Wave: how much of the middle of the picture changed since the last look.\n      function hfWave() {\n        const W = 64, H = 48;\n        hfCanvas.width = W; hfCanvas.height = H;\n        const x = hfCanvas.getContext('2d', { willReadFrequently: true });\n        x.drawImage(video, 0, 0, W, H);\n        const d = x.getImageData(0, 0, W, H).data, g = new Uint8Array(W * H);\n        for (let i = 0, j = 0; j < g.length; i += 4, j++) g[j] = (d[i] * 3 + d[i + 1] * 4 + d[i + 2]) >> 3;\n        if (hf.prev) {\n          let moved = 0, n = 0;\n          for (let yy = 4; yy < H - 4; yy++) for (let xx = Math.round(W * 0.15); xx < Math.round(W * 0.85); xx++) {\n            n++; if (Math.abs(g[yy * W + xx] - hf.prev[yy * W + xx]) > 28) moved++;\n          }\n          const share = moved / n;\n          hf.score = share;\n          hf.hist.push(share > HF_WAVE[fx.sens]); if (hf.hist.length > 9) hf.hist.shift();\n          // moving for most of the last second (a wave), not a single bump\n          if (hf.hist.length >= 7 && hf.hist.filter(Boolean).length >= 6) hfFire();\n        }\n        hf.prev = g;\n      }\n      // Smile: mouth width compared with face width, with the mouth corners lifted.\n      function loadFaceMesh() {\n        if (hf.fm) return Promise.resolve(hf.fm);\n        if (hf.fmLoading) return hf.fmLoading;\n        hf.fmLoading = new Promise(function (resolve, reject) {\n          const go = function () {\n            try {\n              const fm = new window.FaceMesh({ locateFile: function (f) { return BG_BASE + 'facemesh/' + f; } });\n              fm.setOptions({ maxNumFaces: 3, refineLandmarks: false, minDetectionConfidence: 0.6, minTrackingConfidence: 0.5, selfieMode: false });\n              fm.onResults(hfOnFaces);\n              fm.initialize().then(function () { hf.fm = fm; resolve(fm); }, reject);\n            } catch (e) { reject(e); }\n          };\n          if (window.FaceMesh) return go();\n          const s = document.createElement('script');\n          s.src = BG_BASE + 'facemesh/face_mesh.js'; s.async = true;\n          s.onload = go; s.onerror = function () { reject(new Error('could not load')); };\n          document.head.appendChild(s);\n        });\n        hf.fmLoading.catch(function (e) { hf.failed = (e && e.message) || 'error'; hf.fmLoading = null; });\n        return hf.fmLoading;\n      }\n      function hfSmile() {\n        if (!hf.fm) { loadFaceMesh().catch(function () { }); return; }\n        if (hf.fmBusy) return;\n        const k = Math.min(1, 480 / Math.max(video.videoWidth, video.videoHeight));\n        hfCanvas.width = Math.round(video.videoWidth * k); hfCanvas.height = Math.round(video.videoHeight * k);\n        hfCanvas.getContext('2d').drawImage(video, 0, 0, hfCanvas.width, hfCanvas.height);\n        hf.fmBusy = true;\n        hf.fm.send({ image: hfCanvas }).catch(function () { }).then(function () { hf.fmBusy = false; });\n      }\n      function smileScore(lm, aspect) {\n        const px = function (p) { return { x: p.x * aspect, y: p.y }; };\n        const L = px(lm[61]), R = px(lm[291]), cl = px(lm[234]), cr = px(lm[454]), up = px(lm[13]), lo = px(lm[14]);\n        const faceW = Math.hypot(cr.x - cl.x, cr.y - cl.y), mouthW = Math.hypot(R.x - L.x, R.y - L.y);\n        if (faceW < 0.12 * aspect) return null;           // too far away: ignore people walking past at the back\n        const lift = ((up.y + lo.y) / 2 - (L.y + R.y) / 2) / faceW;\n        return { width: mouthW / faceW, lift: lift };\n      }\n      function hfOnFaces(res) {\n        const faces = (res && res.multiFaceLandmarks) || [];\n        const aspect = hfCanvas.width / Math.max(1, hfCanvas.height);\n        let best = 0, smiling = false;\n        faces.forEach(function (lm) {\n          const s = smileScore(lm, aspect); if (!s) return;\n          hf.faceSeen = Date.now();\n          best = Math.max(best, s.width);\n          if (s.width >= HF_SMILE[fx.sens] && s.lift > -0.02) smiling = true;\n        });\n        hf.score = best;\n        hf.smileRun = smiling ? hf.smileRun + 1 : 0;\n        if (hf.smileRun >= 3 && hfWanted()) hfFire();      // about ¾ of a second of smiling\n      }\n      hfLoop();\n\n      // ---- Setup UI ----\n      function refreshFxUI() {\n        const f = document.getElementById('fxFlash'); if (!f) return;\n        f.checked = fx.flash;\n        document.getElementById('fxSound').checked = fx.sound;\n        document.getElementById('fxVolRow').style.display = fx.sound ? '' : 'none';\n        document.getElementById('fxOwnRow').style.display = fx.sound ? '' : 'none';\n        document.getElementById('fxVoiceBox').style.display = fx.sound ? '' : 'none';\n        document.getElementById('fxVoice').checked = fx.vOn;\n        document.getElementById('fxVoiceRow').style.display = fx.vOn ? '' : 'none';\n        setSelectValue('fxVLang', fx.vLang); setSelectValue('fxVCount', fx.vCount);\n        try { pillSyncAll(); } catch (e) { }\n        (function () {\n          const sel = document.getElementById('fxVName'), lang = voiceLang(), list = voicesFor(lang), hint = document.getElementById('fxVHint');\n          sel.innerHTML = '';\n          const auto = document.createElement('option'); auto.value = ''; auto.textContent = 'Automatic'; sel.appendChild(auto);\n          list.forEach(function (v) { const o = document.createElement('option'); o.value = v.name; o.textContent = voiceLabel(v); sel.appendChild(o); });\n          sel.value = list.some(function (v) { return v.name === fx.vName; }) ? fx.vName : '';\n          sel.disabled = !list.length;\n          // The tablet's speech engine takes a moment to start: look again for a few seconds before saying there is no voice.\n          if (voiceNative() && !list.length && (refreshFxUI.tries = (refreshFxUI.tries || 0) + 1) < 12) setTimeout(refreshFxUI, 1500);\n          hint.textContent = !voiceEngine() ? 'This device can’t speak, so the booth uses the beeps.'\n            : !list.length && voiceNative() ? 'No voice found on this tablet yet, so the booth uses the beeps. Open the tablet’s Settings → System → Languages → Text-to-speech output, then download the English voice data (Tagalog too, if you want it).'\n              : !list.length ? 'No voice found on this device yet, so the booth uses the beeps. Install an English voice in the device’s speech settings.'\n                : fx.vLang === 'fil' && lang !== 'fil' ? 'This device has no Tagalog voice, so English is used. Add one in the device’s speech settings.'\n                  : fx.vCount === 'all' ? 'Says every number. The “Get ready” is skipped.'\n                    : 'Says “Get ready”, the last three numbers, then “Smile!” just before the photo. Uses the Volume above.';\n        })();\n        document.getElementById('sndShutName').textContent = fx.sShut ? fx.sShut.name : 'Built-in click';\n        document.getElementById('sndTickName').textContent = fx.sTick ? fx.sTick.name : 'Built-in beeps';\n        document.getElementById('sndShutX').hidden = !fx.sShut;\n        document.getElementById('sndTickX').hidden = !fx.sTick;\n        setSelectValue('fxVol', String(fx.vol));\n        setSelectValue('fxHands', fx.hands);\n        setSelectValue('fxSens', fx.sens);\n        document.getElementById('fxSensRow').style.display = fx.hands === 'off' ? 'none' : '';\n        document.getElementById('fxHandsHint').textContent = fx.hands === 'wave'\n          ? 'Guests wave at the camera to start (tapping still works). Someone walking past close to the camera can start it too.'\n          : fx.hands === 'smile' ? 'Guests smile at the camera to start (tapping still works). Works best with faces close to the camera and good light.'\n            : 'Guests tap the screen to start.';\n      }\n      function fxChanged() {\n        refreshFxUI();\n        if (fx.hands === 'smile') loadFaceMesh().catch(function () { });\n        if (typeof scheduleWelcomeRender === 'function') scheduleWelcomeRender();\n        if (typeof scheduleSetupSave === 'function') scheduleSetupSave();\n      }\n      function applyFxSetup(p) { fx = cleanFx(p); refreshFxUI(); prepSounds(); if (fx.hands === 'smile') setTimeout(function () { loadFaceMesh().catch(function () { }); }, 2000); if (typeof scheduleWelcomeRender === 'function') scheduleWelcomeRender(); }\n      document.getElementById('fxFlash').addEventListener('change', function () { fx.flash = this.checked; fxChanged(); });\n      document.getElementById('fxSound').addEventListener('change', function () { fx.sound = this.checked; fxChanged(); if (fx.sound) { unlockAudio(); setTimeout(function () { fxTick(3); }, 60); } });\n      document.getElementById('fxVol').addEventListener('change', function () { fx.vol = Number(this.value) || 0.7; fxChanged(); unlockAudio(); setTimeout(fxShutter, 60); });\n      function voiceTest() {\n        unlockAudio();\n        if (!voiceActive()) { showToast('No voice on this device yet, so the booth uses the beeps.', 4000); return; }\n        const w = voiceWords(), seq = [[0, w.ready], [1400, w.n[3]], [2400, w.n[2]], [3400, w.n[1]], [4400, w.smile]];\n        seq.forEach(function (s) { setTimeout(function () { voiceSay(s[1]); }, 60 + s[0]); });\n      }\n      document.getElementById('fxVoice').addEventListener('change', function () { fx.vOn = this.checked; fxChanged(); if (fx.vOn) { unlockAudio(); setTimeout(function () { voiceSay(voiceWords().ready); }, 80); } });\n      document.getElementById('fxVLang').addEventListener('change', function () { fx.vLang = this.value === 'fil' ? 'fil' : 'en'; fx.vName = ''; fxChanged(); });\n      document.getElementById('fxVCount').addEventListener('change', function () { fx.vCount = this.value === 'all' ? 'all' : '3'; fxChanged(); });\n      document.getElementById('fxVName').addEventListener('change', function () { fx.vName = this.value; fxChanged(); unlockAudio(); setTimeout(function () { voiceSay(voiceWords().ready); }, 80); });\n      document.getElementById('fxVTest').addEventListener('click', voiceTest);\n      document.getElementById('fxHands').addEventListener('change', function () { fx.hands = this.value; fxChanged(); });\n      document.getElementById('fxSens').addEventListener('change', function () { fx.sens = this.value; fxChanged(); });\n      // Upload / remove own sounds\n      let sndTarget = null;\n      const sndFile = document.getElementById('sndFile');\n      document.getElementById('sndShutUp').addEventListener('click', function () { unlockAudio(); sndTarget = 'sShut'; sndFile.click(); });\n      document.getElementById('sndTickUp').addEventListener('click', function () { unlockAudio(); sndTarget = 'sTick'; sndFile.click(); });\n      document.getElementById('sndShutX').addEventListener('click', function () { fx.sShut = null; fxChanged(); unlockAudio(); setTimeout(fxShutter, 60); });\n      document.getElementById('sndTickX').addEventListener('click', function () { fx.sTick = null; fxChanged(); unlockAudio(); setTimeout(function () { fxBeep(2); }, 60); });\n      sndFile.addEventListener('change', async function () {\n        const file = sndFile.files && sndFile.files[0], which = sndTarget; sndFile.value = '';\n        if (!file || !which) return;\n        try {\n          const wav = await soundFileToWav(file, which === 'sShut' ? 2 : 1);\n          const id = await addAsset(wav);\n          fx[which] = { id: id, name: file.name.replace(/\\.[a-z0-9]+$/i, '').slice(0, 60) || 'My sound' };\n          sndBufs[id] = await decodeAudio(audioCtx(), dataUrlBytes(wav));\n          fxChanged();\n          if (!fx.sound) { fx.sound = true; fxChanged(); }\n          setTimeout(function () { if (which === 'sShut') fxShutter(); else fxBeep(2); }, 80);\n          showToast(which === 'sShut' ? 'Your shutter sound is on.' : 'Your countdown beep is on.', 2500);\n        } catch (e) { showToast(e && e.message || 'That sound could not be used.', 5000); }\n      });\n      document.getElementById('fxTestSound').addEventListener('click', function () { unlockAudio(); setTimeout(function () { fxBeep(2); setTimeout(function () { fxBeep(1); }, 400); setTimeout(fxShutter, 800); }, 60); });\n      setTimeout(refreshFxUI, 0);\n\n      // ---- Booth type: Photo booth / Trading card / Certificate ----\n      // The switch at the top of Setup. Card and certificate booths take one photo and ask the\n      // guest for a name (and a title / award) first; everything else (camera, QR, print) is shared.\n      var btSwitchEl = document.getElementById('btSwitch');\n      var btChipsEl = document.getElementById('btStyleChips');\n      var btCertIds = { title: 'btCertTitle', lead: 'btCertLead', msg: 'btCertMsg', signer: 'btCertSigner', role: 'btCertRole' };\n      function btApplyCfg(c) {\n        c = c && typeof c === 'object' ? c : {};\n        var cd = c.card || {}, ce = c.cert || {};\n        var t = function (v, n, d) { return typeof v === 'string' ? v.replace(/[<>]/g, '').slice(0, n) : d; };\n        var tp = function (v, kind) { var f = typeof v === 'string' ? tplById(v) : null; return f && f.t === kind ? v : null; };\n        btCfg = {\n          card: {\n            style: CARD_STYLES[cd.style] ? cd.style : 'fire', stats: cd.stats !== false, tpl: tp(cd.tpl, 'card'), pick: !!cd.pick, builtin: cd.builtin !== false,\n            back: { on: !!(cd.back && cd.back.on), print: !(cd.back && cd.back.print === false) },\n            qs: [0, 1, 2].map(function (i) { return t(Array.isArray(cd.qs) ? cd.qs[i] : '', 30, ''); })\n          },\n          cert: {\n            style: CERT_STYLES[ce.style] ? ce.style : 'gold', title: t(ce.title, 48, 'Certificate of Achievement'), lead: t(ce.lead, 60, 'is proudly presented to'),\n            msg: t(ce.msg, 120, ''), signer: t(ce.signer, 40, ''), role: t(ce.role, 40, ''), askAward: ce.askAward !== false,\n            tpl: tp(ce.tpl, 'cert'), pick: !!ce.pick, builtin: ce.builtin !== false\n          }\n        };\n      }\n      function btRefresh() {\n        qrResults.innerHTML = ''; lastRenderedFolderUrl = null;\n        try { renderComposite(); renderSetupPreview(); } catch (e) { }\n        try { markLayoutThumbsDirty(); } catch (e) { }\n        scheduleSetupSave();\n      }\n      function btBuildChips() {\n        var card = boothType === 'card', set = card ? CARD_STYLES : CERT_STYLES, cc = card ? btCfg.card : btCfg.cert, groups = [], by = {};\n        Object.keys(set).forEach(function (k) { var g = set[k].grp || 'Classic'; if (!by[g]) { by[g] = []; groups.push(g); } by[g].push(k); });\n        btChipsEl.innerHTML = '';\n        groups.forEach(function (g) {\n          var h = document.createElement('p'); h.className = 'bt-chip-g'; h.textContent = g; btChipsEl.appendChild(h);\n          var row = document.createElement('div'); row.className = 'bt-chip-row';\n          by[g].forEach(function (k) {\n            var st = set[k], b = document.createElement('button'), i = document.createElement('i');\n        